INSERT INTO player_evaluations VALUES(1,1,1,'A — 상위 4경기 평균 7.95(rate_v, 풀 내 평점 백분위 91)로 GK 슬롯 확정 주전(obs#110 XI, prescriptions fc26:opt:GK starter). 실측 히트맵은 순수 골라인형(GK 커널 코사인 .96 vs 스위퍼 .63)이고 스위핑은 상황부라는 duties 판정과 일치. 최종 처방은 gk_ballplaying/Build-Up(2026-07-05 숙련도 타이브레이크 확정). ⭐[2026-09-11 FC27 갱신] OVR 85 유지(FC26 동일), DEF만 56→50(−6) 하락. PlayStyles Long Ball Pass·Rush Out·Far Reach+(roster 2026-09-10) — 배급·박스 밖 커버 실측 프로필과 방향 일치. ⚠️ 2026-08-30 첼시 이적 이후이므로 이 AVL(regime 1) 행은 이력 보존용이다.','짧은 빌드업 개시 GK — 압박 아래에서도 풀백·CB 배급이 고정 원칙. 박스 폭 전체의 얕고 넓은 커버, 액션 볼륨 높음(한 경기 74+). 과잉 스위핑 증거 없음. ⭐[FC27 2026-09-10] PlayStyles Long Ball Pass·Rush Out·Far Reach+로 갱신 — 긴 배급(빌드업 개시 실측)과 박스 밖 커버·선방 반경(하이볼 처리 백분위 95)이 게임 특성으로도 확인된다.','빌드업 관여+박스 장악, FC26 OVR 85(스쿼드 최고 GK)·PlayStyles 긴패스·돌진 블로킹. 약점: 오프라인 스위핑은 상시가 아니라 상황부 — 하이라인 배후 광역 커버를 요구하는 체제에는 실측 근거가 없다. ⭐[FC27 2026-09-10 갱신] OVR85(불변)·PAC83·SHO81·PAS82·DRI85·PHY85 그대로에 DEF만 50으로 FC26(56) 대비 −6. GK 실측 태클·인터셉트 0(구조적)과 별개로 게임 내 파생 축만 조정된 것으로 보인다.','Fotmob 프리미어리그 25/26 20지표(2835분)에서 선방률 70.9%(리그 GK 상위 15%)·선방으로 막은 실점 +3.52(상위 8%)·하이볼 처리 48회(상위 5%)로 지역 장악과 선방 효율이 모두 리그 상위다. 발로는 성공한 패스 893회(상위 8%)·패스 정확도 73.7%(상위 21%)·롱볼 정확도 36.0%(상위 23%)에 어시스트 1개(상위 0%, 즉 리그 GK 최상위)까지 있어 빌드업 관여가 실제로 확인된다. 반면 실점 39(백분위 26)와 실책이 실점으로 이어진 3회(하위 5%)는 명확한 마이너스 — 막는 능력은 상위, 사고 빈도는 하위라는 양면이 한 시즌에 공존한다. 표본이 4경기에서 64경기(5506분)로 늘자 평균 평점이 7.95에서 7.06으로 내려앉았고 우리 3팀 풀 백분위도 91에서 66으로 이동했다 — 옛 평가의 ''최상위권'' 서술은 상위 4경기만 본 선별 표본 효과였다. xG·태클 0은 결측이 아니라 GK로서 실제 0이다. ⭐[2026-09-11] FC27(2026-09-10) OVR85·DEF50·PlayStyles 3종 갱신 — 선방률 70.9%·성공한 패스 893회 실측 결론과 방향이 같다.','HIGH — squad rate_v 7.95 실측에 더해 에메리 빌드업 축(manager_profiles buildup)이 GK의 빌드업 참여를 명시적으로 요구 — 임무와 실측 발자국의 정합이 duties에서 HIGH 판정. ⚠️[2026-09-11] 2026-08-30 첼시 이적 이후이므로 이 fit_emery는 빌라 체제 시절 근거의 역사적 기록이며 현재 소속(CHE)과는 무관하다.','HIGH — 알론소의 3-2-5 숏 빌드업(tac-tac-tac 리듬)도 볼 플레잉 GK를 전제하며 마르티네스의 배급 실측이 그대로 이식 가능 (교차 투영 — 실측 아님).','MEDIUM — 고압박·하이라인 체제는 배후 스위핑 GK를 요구하나 실측 발자국은 골라인 고정, 스위핑은 상황부에 그침 (교차 투영 — 실측 아님).','squad_entries GK(rate_v 7.95); prescriptions kind=optimal·role·measured:season(GK); player_duties GK; v_player_profile n=4; player_game_stats FC26(OVR85, 긴패스·돌진 블로킹); obs#14 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 20지표) · v_player_profile n=64(5506분) · v_player_season_stats · prescriptions measured:season:full2526 n=52 rt=6.97 | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR85·DEF50·PlayStyles Long Ball Pass/Rush Out/Far Reach+) vs FC26(roster_date 2026-07-23, OVR85·DEF56)','v_player_profile n=4는 표본 부족이고 rate_v도 ''상위 4경기'' 선별 표본이라 상향 편향 가능. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 64경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다. ⚠️ 2026-09-11: FC27 갱신은 DEF−6 소폭 조정일 뿐 실측 근거 갱신은 아니다 — 표본·판정은 기존과 동일.','2026-09-11','프리미어리그 골키퍼 중 페널티박스 안의 공중볼을 직접 처리해 버리는 적극적인 유형으로 보인다. 하이볼 처리 48회(90분당 1.52회)가 백분위 95, 90분당 기준으로는 100으로 이 모집단 최상위다. 선방률 70.9%가 백분위 85, 선방으로 막은 실점 3.52점이 92로 슛 저지 자체도 상위권이고, 롱볼 정확도 36.0%(77)와 성공한 패스 893회(92)로 배급도 평균 이상이다. 약점은 실수다 — 실책이 실점으로 이어진 경우 3회로 백분위 5, 이 모집단 최하위권이고 총 실점 39골의 백분위도 26에 머문다. 골키퍼는 수집 지표가 20개뿐이라 다른 포지션보다 판단 근거가 얇다는 점은 감안해야 한다. 공중볼 처리와 선방 능력을 믿고 높은 수비라인 뒤를 맡기되, 발밑 판단 실수는 구조적으로 감싸줄 장치가 필요한 프로필이다.');
INSERT INTO player_evaluations VALUES(2,1,2,'A− — 확정 XI RB. FC27(09-10) OVR81 unchanged인데 pac이 75→70(-5)로 뚜렷하게 하락, PlayStyle 「Long Throw」(긴스로우) 유지. 26/27 초반 prescriptions measured(2026-09-06 R4 갱신, n=4, PSG·브라이턴·아스날·헐 4경기 343분)에서 fb_att_wb/Support 0.892·평점6.36으로 직전 회차(n=2, wingback/Balanced 0.959)에서 역할이 이동 — 표본 확대에 따른 변화이며 정본(fc26:opt:RB)은 유지.','윙어 출신 라이트백. FC27 pac 하락(75→70)이 실측 서사(고립 1v1 취약)와 방향이 겹친다 — 프리시즌 바이에른전 루이스 디아스 고립 돌파 실점, 폴란드어 Weszło(2022) 1v1 취약 교차검증. 반면 PlayStyle Long Throw·pas75(+1)는 배급 볼륨 강점과 정합.','v_player_profile 갱신: n=62·4736분·평균평점6.78(08-11 n=53/6.81에서 표본 소폭 확대, 평점 거의 불변). 26/27 아스날전(08-31) 3중 성격 확인 — 팀 내 최고 공격 기여(xG0.15)·아스날 좌우 반전 로테이션 이음새 노출(앙리: 도미노 효과)·스즈키 롱볼 프레스 탈출 지정 러너(Bains: 빌라를 40-50야드 쉽게 전진시킨다). 약점은 pac 하락이 스탯으로 보강된 1v1 고립 취약과 규율 문제(파울·경고 리그 하위권, 기존 기록).','Fotmob PL 25/26 40지표(기존 기록 유지) + v_player_profile 신규(n=62, 4736분, 평균6.78). 26/27 시즌 PL 3경기253분 평점6.28, 슈퍼컵1경기90분6.6 — 초반 폼은 25/26 대비 소폭 낮음(6.83→6.28, 소표본).','HIGH — obs#110 확정 XI RB, C2 비대칭 잔류측. duties 2026-09-01 항목이 여전히 정합(잔류 규율)이나 아스날전 이후 전진 시 이음새 노출 리스크가 새 축으로 추가됐다(D+2 갱신 09-03에서 과잉귀속 정정 — 직접 실점 책임은 린델뢰프).','MEDIUM — 3-4-2-1 윙백의 폭 독점 역할과 전장 우측 커버 실측(.94)은 맞닿으나, 공격 산출(xA 백분위 47)이 폭 공급자 기준으로는 평범 (교차 투영 — 실측 아님).','LOW — 이라올라의 인버티드 RB 성향(프림퐁 실측)과 정반대 — 캐시는 실측상 절대 안쪽으로 들어오지 않는 순수 와이드형 (교차 투영 — 실측 아님).','squad_entries FB(rate_v 7.65); prescriptions optimal·role·measured:season(RB); player_duties RB 2행; v_player_profile n=53; FC26(OVR81, 긴스로우); obs#110·#147 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 40지표) · v_player_profile n=53(4188분) · v_player_season_stats(PL 35경기 34선발 3골) | stat_eval 2026-09-11 갱신: FC27(OVR81 동일, pac75→70 -5·pas74→75 +1)·PlayStyle(Long Throw)·player_game_stats(185cm/74kg) · v_player_profile n=62(4736분, 평균6.78) · prescriptions measured 26/27 R4(n=4, fb_att_wb/Support 0.892, rt6.36) · v_player_season_stats(26/27 PL 3경기 253분 평점6.28)','n=62 충분. pac 하락(-5)은 EA 연례 조정 폭으로는 크다 — 다음 로스터에서 재확인 필요. 1v1 고립 취약 서사와 방향이 겹치나 인과관계 단정은 아니다. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','프리미어리그 풀백 중 공격 관여량이 대단히 많고 대인 수비에서는 자주 뚫리는, 공격 쪽으로 크게 기울어진 프로필이다. 기회 창출 30회(백분위 90), 성공한 크로스 26회(88), 슛 30회(92)와 득점 3골(90)로 측면에서의 최종 산출이 상위권이고, 정확한 롱볼 56회(92)로 긴 전환 패스도 잘 넘긴다. 슛 블록 14회(93)처럼 몸을 던져 막는 행동도 많다. 반면 상대에게 제쳐당한 횟수 35회는 백분위 4로 사실상 최하위이고, 파울 41회(4)·경고 9장(2)으로 반칙에 의존하는 경향이 뚜렷하다. 경합 승률 51.5%(38)와 크로스 정확도 19.8%(44)는 평범하다. 뒤를 덮어줄 수비 조직이 있을 때 전진해 크로스를 공급하는 역할에 쓰고, 빠른 윙어와 1대1로 남기는 배치는 피하는 편이 맞다.');
INSERT INTO player_evaluations VALUES(3,1,3,'S− — RCB 43경기 평균 7.05(rate_v), 시즌 그리드 cb_bpd/Aggressive 코사인 .938(role:season, 2위 Build-Up .865)로 스쿼드에서 가장 강한 역할 실측 정합. 패스 96%로 스쿼드 최고(duties 이벤트 스탯) — BPD 3축 충족으로 cb_bpd 승급. 확정 XI RCB(obs#110). ⭐[2026-09-11 FC27 갱신] roster_date 2026-09-10 행 없음 — 최신 FC27은 2026-08-31 자(OVR84·PAC71·SHO55·DEF86)이고 이후 갱신이 끊겼다. 08-19 £51m 이적설 이후 AVL 로스터에서 빠진 것으로 추정된다(데이터 결손, 확정 근거는 없음).','태클 대신 포지셔닝·요격으로 수비하는 passive-aggressive형. 우측 듀얼·공중볼 앵커이면서 소유 시 볼을 들고 우중앙 미드필드로 스텝업 — 스텝아웃 캐리는 서사가 아니라 실측(duties). ⭐[FC27 최신(2026-08-31)] PAC 75→71(−4)·SHO 53→55(+2)·DEF 85→86(+1), 나머지 불변 — 09-10 신규 갱신은 없다.','스텝아웃 캐리+패스 96%의 볼 플레잉, FC26 OVR 84·PlayStyles 예상+·견제·슬라이딩태클. 약점: 공중볼·크로스 대응(영상 분석, duties) — 게임 공중볼 스탯도 낮아 세트피스 마킹 주의. ⭐[FC27 갱신 결손] 2026-09-10 roster에 콘사 행이 없다 — 최신값은 2026-08-31(OVR84·PAC71·DEF86)이며 이 세션 대상 갱신 데이터가 아니다. 이적 진행(08-19 £51m 보도) 가능성을 명시하되 확정 근거는 없다.','Fotmob 프리미어리그 25/26 41지표(3036분)에서 패스 정확도 95.5%가 리그 센터백 백분위 100(최상위)이고 롱볼 정확도 61.0%(상위 2%)·성공한 패스 2003회(상위 7%)·터치 2439회(상위 10%)로 배급 축이 리그 최고 수준이다. 대인은 경합 승률 67.1%(상위 13%)·슛 블록 29(상위 11%)·상대 진영 볼 탈취 3회(상위 13%)로 강하지만, 공중 경합 승률 57.1%(백분위 43)·태클 22(백분위 41)는 평범해 제공권형 스토퍼가 아니라 위치·차단형임을 보여준다. 얻어낸 파울 40회(상위 6%)에 경고 0장(백분위 100)으로 규율은 최상급이나 퇴장 1회(하위 2%)가 남는다. 출전 중 실점 44(백분위 14)·피xG 48.85(백분위 6)는 개인 지표가 아니라 팀 수비 부하를 반영하는 값이라 감안해서 읽어야 한다. 우리 3팀 풀 실측 48경기 평균 7.05(백분위 61)와 방향이 일치하며, 옛 평가에서 ''표본 0''이라 인용을 접었던 태클·인터셉트 공백이 이번에 메워졌다. ⭐[2026-09-11] FC27 09-10 데이터 결손 — 실측 stat_eval은 기존 25/26 프리미어리그 41지표(패스 정확도 95.5%·롱볼 정확도 61.0%) 그대로 유효, FC27 신규 반영치 없음.','HIGH — role:season .938은 스쿼드 최상위 실측 적합. 에메리 백라인 스텝아웃·볼 플레잉 요구(obs#22 — CB Defender 숙련을 BPD로 기용)와 정확히 일치. ⚠️[2026-09-11] FC27 09-10 갱신 없음 — fit_emery 등급 변경 근거 없음, 기존 HIGH 유지.','HIGH — 알론소는 전 CB cb_bpd/Aggressive를 요구(implementation ①)하며 콘사의 실측 커널이 정확히 그 역할 — 백3 우측 스토퍼로 직이식 가능 (교차 투영 — 실측 아님).','MEDIUM — 하이라인 배후 커버는 pac 75와 요격형 수비(예상+)로 감당 가능하나 전면 맨투맨 전환 체제의 1v1 노출은 실측 검증 없음 (교차 투영 — 실측 아님).','squad_entries CB(rate_v 7.05); prescriptions optimal·role·role:season·measured@dom/@tight(RCB); player_duties RCB 2행; v_player_profile n=48; FC26(OVR84); obs#110·#147 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표) · v_player_profile n=48(4170분) · v_player_season_stats | stat_eval 2026-09-11 갱신 시도: player_game_stats FC27 2026-09-10 행 없음(결손) — 최신 가용치는 roster_date 2026-08-31(OVR84·PAC71·SHO55·DEF86)','n=48로 표본 충분, 실측 신뢰 높음. 태클·인터셉트 지표는 표본 0. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-09-11: FC27 09-10 로스터에 콘사 행이 존재하지 않는다 — 데이터 결손으로 얕게만 갱신했다(이적 진행 가능성 있으나 미확정).','2026-09-11','프리미어리그 센터백 중 공을 잃지 않는 배급형이고, 수비 행동의 빈도 자체는 대단히 낮은 프로필이다. 패스 정확도 95.5%가 백분위 100, 롱볼 정확도 61.0%가 98로 이 모집단 최상위이며 성공한 패스 2003회(93)·터치 2439회(90)로 후방에서 공을 가장 많이 만지는 축에 속한다. 경합 승률 67.1%(87), 슛 블록 29회(89), 얻어낸 파울 40회(94)도 강점이고 경고가 0장이다. 다만 90분당 기준으로 보면 수비적 행동 백분위 1, 걷어내기 9, 태클 7, 공중 경합 승 6으로 단위 시간당 수비 개입이 최하위 수준이다 — 총량 백분위(59·62·41·44)가 높아 보이는 것은 3000분 넘게 뛴 결과다. 출전 중 피xG 백분위 6도 실점 위험이 큰 환경에 있었음을 시사한다. 뒷공간 커버와 1대1 저지를 다른 센터백에게 맡기고 빌드업의 출발점으로 쓰는 배치가 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(4,1,4,'A — 확정 XI LCB(obs#110). FC27(09-10) OVR 81(FC26 80 대비 +1)로 소폭 상승, 26/27 UCL 데뷔전(브뤼헤 원정, 2026-09-08)에서 어시스트 2·키패스 4·빅찬스 창출 1·xA 0.49·평점 7.6(팀 공동 최고)을 기록해 구단 역사상 CL 한 경기 2도움 최초 수비수가 됐다(구단 공식). 다만 26/27 포지션-순수 표본은 아직 3경기·평점 5.74(prescriptions measured, cb_bpd/Aggressive 0.911)로 낮아, 최신 대표 경기 전 소표본과 이후 하이라이트가 공존한다.','좌측 볼 플레잉 CB — 캐리·패스로 좌 하프스페이스 전진. FC27 신규 PlayStyle 「Pinged Pass」(FC26엔 없던 특기, 대각 전환 실측과 정합) 부여. FC27 스탯: pac66(-1)·sho41·pas75·dri69·def83(+1)·phy74(+1), 키191cm·몸무게80kg. 브뤼헤전 실측은 이 프로필을 확장한다 — 11분 선제골에서 자기 진영~박스 앞 40m 무저항 캐리(L''Avenir·Guardian·VoetbalPrimeur 3개 언어 교차확인), 43분은 상대 GK 하이라인을 조건화한 롱 로프트 배후 패스(잭슨 골, FotMob FastBreak 공식 분류).','표본 확대(n=57→65, 3393→3851분)에도 3팀 풀 평균 평점은 6.90→6.84로 큰 변화 없이 유지. 좌측 전진 배급·캐리 관여가 압도적이라는 기존 결론이 브뤼헤전으로 재확인됐고, 신규 축으로 「백라인 지휘·발화」가 추가됐다(UTV: 그가 점점 목소리를 내며 백라인을 이끈다고 평가). 약점은 여전히 pac66·1대1 근접 수비(스페인어 TFA: 가장 빠르지도 기동력 좋지도 않음) — FC27 pac가 오히려 1 더 낮아져 이 약점이 스탯으로도 보강된다.','Fotmob PL 25/26 38지표(1676분) 프로필은 기존과 동일(패스 정확도 89.0% 상위28%·정확한 롱볼 2.85/90 상위20%·공중경합승률 52.1% 하위22%). v_player_profile 갱신(2026-09-10 기준): n=65경기·3851분·평균평점 6.84 — 08-11 기록 n=57/6.90에서 표본이 더 늘며 평점이 소폭 하락, 결론은 불변(발쪽 강점·대인방어 리그 평범).','HIGH — 확정 XI LCB, 빌드업 축 좌측 담당. duties 2026-09-08 항목이 cb_bpd Build-Up 0.887/Aggressive 0.899(Δ0.012, 노이즈 구간)로 정본 유지를 재확인. 26/27 초반 prescriptions measured 행(n=3, cb_bpd/Aggressive 0.911, 평점5.74)은 소표본이라 정본(fc26:opt:LCB)을 대체하지 않는다.','HIGH — 백3 전원 cb_bpd 요구 체제에 좌측 BPD로 직결. 다만 알론소 처방은 Aggressive 포커스라 Build-Up 성향과 미세 긴장 (교차 투영 — 실측 아님).','LOW — pac 67로 하이라인+전면 맨투맨 전환 체제의 배후 공간 리스크가 큼 (교차 투영 — 실측 아님).','squad_entries CB(rate_v 7.35); prescriptions optimal·role·measured:season(LCB); player_duties LCB; v_player_profile n=6; FC26(OVR80, 핑패스); obs#89·#110 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 38지표) · v_player_profile n=57(3393분) · prescriptions measured:season:full2526 n=37 rt=6.86 fit=0.924 | stat_eval 2026-09-11 갱신: FC27(OVR81, +1 vs FC26 80)·PlayStyle(Pinged Pass 신규)·player_game_stats(pac66/sho41/pas75/dri69/def83/phy74, 191cm/80kg) · v_player_profile n=65(3851분) · player_duties 2026-09-08 브뤼헤전(2도움·xA0.49·평점7.6, 구단 CL 최초 수비수 2도움) · prescriptions measured 26/27(n=3, cb_bpd/Aggressive 0.911, rt5.74)','n=65 충분, 표본 확대에도 결론 안정적. 26/27 시즌 초반(n=3)과 브뤼헤전 개별 퍼포먼스 사이 표본 갈등은 시즌 진행에 따라 재확인 필요. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','프리미어리그 센터백 중 출전이 1700분 안쪽이라 90분당 백분위로 읽어야 하는 표본이고, 그 기준으로는 수비 개입 빈도가 낮으나 팀 실점 억제 지표는 좋은 쪽에 있다. 90분당 출전 중 실점 1.02골이 백분위 90, 출전 중 피xG 1.22가 84로 이 선수가 뛸 때 팀이 덜 위험했다. 볼 회수 90분당 4.30회(89), 드리블 성공(82), 상대 진영 볼 탈취(90), 그리고 파울을 거의 하지 않는 점(90분당 0.38회, 86)이 강점이다. 약점은 경합이다 — 공중 경합 승률 52.1%가 백분위 22, 경합 승률 55.7%가 36으로 몸싸움에서 밀리고, 걷어내기(90분당 4)·수비적 행동(4)·인터셉트(7)처럼 직접 막아내는 행동의 빈도가 최하위권이다. 기회 창출 1회(13)로 전방 패스의 산출도 없다. 상대 공격수와 정면으로 부딪히지 않는 위치, 즉 커버 담당 센터백으로 두고 공을 안전하게 돌리는 역할에 쓰는 프로필이다.');
INSERT INTO player_evaluations VALUES(5,1,6,'B+ — 확정 XI LB하나 FC27(09-10) 스탯이 FC26(07-23)과 완전 동일(OVR79·pac87·sho65·pas75·dri81·def73·phy63, PlayStyle Rapid)로 변동 없음. 26/27 초반 v_player_profile n=70·평균평점6.59(08-11 n=60/6.63에서 소폭 추가 하락) — XI 중 최저 산출 축이 유지된다. 브뤼헤전(2026-09-08)에서는 평점5.9(팀 최저)로 저조했고, 그날 커널이 fb_fullback/Balanced 0.849로 잔류측 이동(정본 fb_att_wb/Support 0.717과 Δ0.132) — 같은쪽 헤밍스가 높게 서며 좌우 정본이 반전된 경기.','공격형 레프트백. FC27 스탯이 FC26과 완전 동일해 게임상 프로필 변화는 없다(pac87 최상위, PlayStyle Rapid 유지). 실측은 이중적 프로필을 재확인 — 브뤼헤전 전반 헤밍스와의 침투 조합은 작동했으나(VoetbalPrimeur: 침투하는 헤밍스와 전진하는 이안 마첸) 그날 커널상으로는 잔류측이었다.','prescriptions measured 26/27(R4 갱신, n=4, PSG·브라이턴·아스날·헐)에서 fb_att_wb/Support 0.875·평점6.34·centroid(14.28,47.61)로 정본과 유사한 값 유지. 약점은 여전히 산출 일관성 — v_player_profile n=70/평균6.59로 스쿼드 하위권 지속. 브뤼헤전 9분 옐로카드는 볼 상황이 아니라 항의성이었다(Sporza: 그는 격분했고 그래서 경고를 받았다).','player_game_stats FC27=FC26 동일값 확인(변화 없음, roster 2026-07-23/2026-09-10 공통 OVR79). v_player_profile 갱신: n=70·3173분·평균평점6.59. 26/27 시즌: PL3경기247분평점6.12, UCL1경기90분평점5.9(브뤼헤, 팀최저), 슈퍼컵1경기90분평점7.0.','HIGH — 확정 XI LB, C2 비대칭 전진측(단 홈/지배 임무 한정, 원정 변형 시 Balanced/Defend 처방 기존과 동일). 브뤼헤전 사례가 원정·비지배 국면에서 잔류측으로 이동한다는 기존 duties 경고를 재확인했다.','HIGH — 알론소 좌 윙백은 인선 공백(formation 축)이고 마첸의 하이앤와이드 실측 프로필이 윙백 폭 독점 요구에 부합 (교차 투영 — 실측 아님).','MEDIUM — 고강도 왕복과 pac 87은 부합하나 홈/원정 요동과 낮은 평점 일관성이 고압박 체제의 상시 강도 요구와 긴장 (교차 투영 — 실측 아님).','squad_entries FB(rate_v 6.74); prescriptions optimal·role:season·measured@dom/@tight(LB); player_duties LB; v_player_profile n=45; FC26(OVR79 POT84, 슬라이딩태클·래피드); obs#95·#110·#128 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 40지표) · v_player_profile n=60(2509분) · prescriptions measured:season:full2526 n=21 rt=6.82 fit=0.867 | stat_eval 2026-09-11 갱신: FC27 09-10 확인 — FC26(07-23)과 완전 동일(OVR79, 변화 없음, PlayStyle Rapid) · v_player_profile n=70(3173분, 평균6.59) · prescriptions measured 26/27 R4(n=4, fb_att_wb/Support 0.875, rt6.34) · player_duties 2026-09-08 브뤼헤전(평점5.9 팀최저, 커널 fb_fullback/Balanced 0.849로 잔류측 반전)','n=70 충분, 결론(산출 일관성 낮음)이 표본 확대 후에도 재확인. FC27 스탯 무변화는 확실. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','프리미어리그 풀백 중 상대 박스까지 올라가는 공격형 측면 수비의 모양이고, 소유 국면의 산출이 수비 안정성보다 훨씬 앞선다. 출전이 1600분 안쪽이라 90분당 백분위로 읽으면 상대 박스 터치 3.77회가 백분위 95, 드리블 성공 1.18회가 88, 기회 창출 1.46회가 88, 슛 1.13회가 89로 전진 관여가 상위권이다. 롱볼 정확도 67.6%(96)와 90분당 xA 0.14(87)도 좋다. 약점은 공 관리와 대인 수비다 — 볼 뺏김 90분당 1.29회가 백분위 8, 제쳐당한 횟수 1.35회가 13, 경합 승률 48.8%가 26으로 모두 하위권이고 슛 블록은 11이다. 공격 3선을 지원하는 전진 풀백으로 쓰되, 뒤에 커버할 수비형 미드필더나 안쪽으로 접히는 센터백을 붙여야 하는 프로필이다.');
INSERT INTO player_evaluations VALUES(6,1,7,'B — 백업 CB, 상위 4경기 평균 7.05(rate_v)에 양쪽 CB 커버 가능. 시즌 그리드 cb_bpd/Aggressive .826 >> Build-Up .741로 스텝아웃 뚜렷(prescriptions optimal LCB). obs#14 전 스쿼드 재검증에서 유일하게 처방이 교정된 사례. ⭐[2026-09-11 FC27 갱신] OVR 76→77(+1), DRI 67→68(+1)·PHY 69→71(+2), PAC/SHO/PAS/DEF 불변. PlayStyles 없음(FC26과 동일하게 결측).','양쪽 CB을 모두 커버하는 로테이션 자원. 실측상 스텝아웃 성향의 BPD형 — RCB·LCB·RDM 세 슬롯에 처방 이력. ⭐[FC27 2026-09-10] PHY 71로 상승(+2) — 공중 경합 승률 64.7%(백분위 74) 실측과 방향 일치.','좌우 겸용 유연성과 스텝아웃 빌드업(.826). 약점: pac 50(풀백업 중 최저 수준)·OVR 76 — 하이라인·회복 수비 상황 취약, FC26 PlayStyles 없음. ⭐[FC27 갱신] OVR77(+1)·PHY71(+2)·DRI68(+1), PAC50·SHO51·PAS71·DEF77 불변 — 정확도 강점(패스 정확도 94.2% p98)과 피지컬 축이 함께 소폭 상승.','표본이 5경기에서 66경기(2927분)로 늘자 평균 평점이 6.88에서 6.66(3팀 풀 백분위 22)으로 내려앉았고, 같은 갱신에서 커널 적합도 0.744에서 0.615로 떨어졌다 — 소표본이 실제보다 후하게 보였던 전형이다. Fotmob 프리미어리그 25/26 34지표(944분)에서 살아남는 강점은 정확도뿐이다 — 패스 정확도 94.2%(리그 센터백 상위 2%)·공중 경합 승률 64.7%(상위 26%)·롱볼 정확도 48.1%(상위 24%). 반대로 물량 지표는 거의 전부 리그 하위다 — 경합 승 19(하위 11%)·공중 경합 승 11(하위 11%)·수비적 행동 54(하위 19%)·걷어내기 34(하위 19%)·볼 회수 19(하위 18%)·태클 7(하위 17%). 파울 2회(상위 13%)·경고 0장으로 규율은 좋지만, 이는 개입 자체가 적다는 뜻과 분리되지 않는다. 요약하면 붙으면 이기지만 붙는 횟수가 적은 백업 센터백이다. ⭐[2026-09-11] FC27 PHY 69→71(+2) 갱신 — 공중 경합 승률 64.7%(p74) 실측 강점과 정합. 물량 지표(경합 승 p11·수비적 행동 p19) 하위는 게임 능치로 반영되지 않는 별개 축.','MEDIUM — 로테이션 CB로 처방 정합(.826)은 확인됐으나 XI 밖. 표본 3~5경기라 기능축 근거 약함(prescriptions optimal 주석).','MEDIUM — 백3 체제는 BPD CB 수요가 3장이라 로테이션 가치가 오히려 커질 수 있으나 Aggressive 강도 요구 대비 기동력 의문 (교차 투영 — 실측 아님).','LOW — pac 50으로 하이라인·전면 맨투맨 체제 부적합 (교차 투영 — 실측 아님).','squad_entries CB(rate_v 7.05); prescriptions fc26:opt:LCB/RCB/RDM·optimal·measured:season; v_player_profile n=5; FC26(OVR76); obs#14 (player_duties 행 없음) | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 34지표) · v_player_profile n=66(2927분) · prescriptions measured:season:full2526 n=25 rt=6.64 fit=0.615 | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR77·DRI68·PHY71) vs FC26(roster_date 2026-07-23, OVR76·DRI67·PHY69)','n=5 표본 부족 — 등급 과신 금지. player_duties 미작성 선수. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 66경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다. ⚠️ 2026-09-11: FC27 능치 변화(OVR+1·PHY+2)는 미미 — 표본·판정 기존과 동일.','2026-09-11','프리미어리그 센터백 중 출전이 950분 안쪽인 소표본이고, 34개 지표만 수집된 점을 감안해야 한다. 프로필의 모양은 극단적이다 — 패스 정확도 94.2%가 백분위 98, 롱볼 정확도 48.1%가 76으로 공을 다루는 쪽은 상위권인데, 90분당 수비적 행동은 백분위 0, 경합 승 2, 걷어내기 3, 볼 회수 3, 태클 9로 수비 행동 빈도가 이 모집단 최하위다. 긍정적으로 읽을 부분은 반칙과 위험을 만들지 않는다는 점이다 — 90분당 파울 0.19회(91), 제쳐당함 0.19회(84). 공중 경합 승률 64.7%(74)로 붙었을 때의 승률 자체는 나쁘지 않다. 개입 빈도가 낮은 것은 역할 탓일 수 있으나, 이 숫자만으로는 수비 부담이 큰 경기에 세울 근거가 없고 공을 지배하는 경기의 로테이션 카드로 읽는 것이 안전하다.');
INSERT INTO player_evaluations VALUES(7,1,8,'A− — 피벗 29경기 평균 7.13(rate_v), 확정 XI LDM(obs#110 starter). 처방 dm_holding/Roaming(2026-07-05 확정) — 움직임 dlp .87·기능 볼위닝(태클 3.4·듀얼 6.6 스쿼드 최상위, 창조 최저 xa .04·kp 1.0). 2026-07-21 리옹에서 ACL 재건 수술, 복귀는 3월말~4월 밴드로 26/27 대부분 결장 전망. FC27(09-10) OVR81 유지·SHO 64→68(+4)·PAS 72→74(+2)로 소폭 상승, PlayStyles Slide Tackle·Press Proven·Enforcer·Precision Header 4종 그대로 — 부상 공백에도 게임 평가는 하락하지 않았다.','더블 피벗의 박스투박스·만능 어댑터 — 중앙/좌/우 세 레인 산출이 거의 동일(중앙 7.21/우 7.04/좌 7.05)하고 평점이 파트너 독립적. 공중볼 최강·듀얼 머신, FC27 신체 프로필 192cm/76kg(PAC73·PHY82). 샷맵상 헤더 비중 높아 박스 도착은 대부분 세트피스.','듀얼·공중·스크린+박스 쇄도, FC27 PlayStyles 4종(Slide Tackle·Press Proven·Enforcer·Precision Header) 유지, SHO 64→68·PAS 72→74 상승. 약점: 창조성 최저(xa .04·kp 1.0)에 더해 ACL 재활로 26/27 사실상 결장 — 능치는 안정적이나 가용성 자체가 최대 리스크.','Fotmob 프리미어리그 25/26 38지표(1764분)가 옛 평가의 태클·인터셉트 공백을 메운다 — 태클 48(백분위 63)·인터셉트 25(63)로 중상위, 진짜 상위는 경합이다. 경합 승률 63.9%(상위 2%), 공중 경합 승률 66.2%(10%), 공중 경합 승 45회(15%), 걷어내기 59회(12%), 슛 블록 17회(7%). 창출은 하위 — 기회 창출 7회(17%)·xA 0.70(26%)·어시스트 0. 우리 3팀 풀 실측 38경기 평균 7.05(백분위 61)와 방향 일치. | 2026-09-11 갱신: FC27(roster_date 2026-09-10) OVR81(변화 없음)·PAC73·SHO68(+4 vs FC26 07-23 64)·PAS74(+2 vs 72)·DRI74·DEF81·PHY82, PlayStyles 4종(Slide Tackle·Press Proven·Enforcer·Precision Header) 유지. ACL 재활로 26/27 실측 갱신 없음 — 능치 상승은 EA 정기 업데이트 반영이며 신규 경기력 근거 아님.','HIGH — 확정 XI LDM이고 더블 피벗 dm_holding 분담(implementation ②)의 볼위닝 축. 단 ACL 재활로 최소 3월까지 결장 예상 — 체제 기여는 복귀 시점까지 잠정 보류. FC27 능치가 유지·소폭 상승해 복귀 시 즉시전력 가능성은 남아 있다.','HIGH — 알론소 rest_defense 축이 ''더블피벗 중 한 명 Defend 계열 보험''을 명시적으로 요구 — 오나나의 볼위닝 홀딩 기능이 그 보험 그 자체 (교차 투영 — 실측 아님).','MEDIUM — 듀얼·압박검증은 부합하나 Controlled Lengthy 가속과 창조 최저 기능이 탈취 후 즉시 슛 전환 체제와 부분 긴장 (교차 투영 — 실측 아님).','squad_entries DM(rate_v 7.13); prescriptions optimal·role·role:season(LDM); player_duties LDM·RDM 2행; v_player_profile n=38; FC26(OVR81, PlayStyles 4종); obs#32·#110·#129·#145 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 38지표) · v_player_profile n=38(2649분) · v_player_season_stats(PL 25경기 21선발) | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR81·SHO68·PAS74·PlayStyles 4종) vs FC26(07-23, OVR81·SHO64·PAS72) 비교','n=38 충분. XI LDM은 obs#110(2026-08-11)과 obs#129(고메스 LDM) 간 기록 긴장 존재 — 최신 확정은 obs#110. 2026-09-11 기준 ACL 재활 중이라 26/27 실측 갱신 불가, FC27 게임 스탯만 반영(변화폭 작음, 신뢰도 하락 요인 아님). 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','프리미어리그 미드필더 중 공중과 지상 경합에서 이기는 힘이 압도적이고 창조 쪽은 거의 비어 있는, 순수 파괴형 프로필이다. 경합 승률 63.9%가 백분위 98, 공중 경합 승률 66.2%가 90, 90분당 공중 경합 승 2.30회가 91로 몸싸움 지표가 최상위권이다. 슛 블록 90분당 0.87회(96)와 걷어내기 3.01회(91)로 자기 골문 앞에서 막아내는 행동도 많다. 약점은 최종 패스다 — 기회 창출 7회가 백분위 17(90분당 10), xA 0.70이 26(90분당 16), 어시스트 0개로 하위권이고, 상대 진영에서 공을 끊는 행동(22)이나 볼 회수(16)처럼 전방에서 압박해 되찾는 지표도 낮다. 즉 앞으로 나가 압박하기보다 자기 자리에서 부딪혀 걷어내는 유형이다. 창조를 담당하는 미드필더와 짝지어 후방을 통째로 맡기는 배치가 맞고, 전방 압박의 첨병으로 쓰기에는 근거가 약하다.');
INSERT INTO player_evaluations VALUES(8,1,10,'S — 주장이자 확정 XI RM(obs#110 starter). RM 21경기 7.08에 천장 경기 전부(8.7/8.6/8.5), 피벗우측 7경기 7.87(fit_sim .878 — 자체 실측 최고), CAM .801까지 3슬롯 실측 보유. obs#145에서 외부 영상 분석이 내부 실측(obs#27·#89)을 독립 재현한 ''검증자 사례''. ⭐[2026-09-12 갱신] S 유지(관찰 플래그 1건). 근거: ⑴ 확정 XI RM 지위 불변 — 26/27 공식전 5경기 전부 RAM 선발(슈퍼컵 73분 7.1·1도움 → PL 3경기 82/90/90분 → UCL 90분 7.8·1골, player_matches). ⑵ FC27 09-10판 OVR 83(FC26 출시판·라이브판 81 대비 +2, 스쿼드 내 상위). ⑶ 브뤼헤전 에메리가 실명 호명해 수행 평가(obs#554)·헐 감독 야키로비치가 「right No 8처럼 들어와 중원 과부하」로 독립 증언(obs#539) — 하이브리드 역할의 외부 검증 2건 추가. ⚠️플래그: PL 3경기 평점 6.49/5.76/5.74(평균 6.00, 아스날·헐전 팀 최저) vs UCL 7.8 — 국면(점유 27~39%↔36% 원정 UCL) 차이로 읽고 등급 조정은 보류.','명목 우측이나 움직임은 내부·수직의 하이브리드 — 듀얼 5.75/90 스쿼드 최다, 찬스 창출 최다, 중거리 위협. 샷맵상 헤더 0·평균 17.1m — 박스 스트라이커가 아니라 박스 가장자리 인사이드 포워드형 도착. ⭐[2026-09-12] PlayStyles 궤적(player_game_stats): FC25 출시판(2024-09-13) Long Ball Pass·Press Proven·Relentless → FC26 출시판(2025-09-12) Press Proven·Relentless·Enforcer(Long Ball Pass 탈락, Enforcer 신설) → FC27 09-10판 동일 3종 유지. FC26 라이브(06-30) 트레잇 「부상에 취약함」은 25/26 무릎 결장(01-19~03-11)과 정합. ⚠️Long Ball Pass 탈락은 실측과 어긋난다 — FotMob PL 25/26 정확 롱볼 43회(백분위 94)·롱볼 정확도 60.6%(70)로 여전히 상위. 포지션 표기도 FC25 CM/CDM/RM → FC26 LM/LB/RM/CAM → FC27 RM(09-10판)으로 우측 와이드에 수렴, 실측 RAM 선발과 일치. AcceleRATE Controlled 전 버전 동일.','뱅크 복귀(wm_widemid/Support)와 하프스페이스 런의 겸장, 압박검증·끈기와인내·인포서 PlayStyles. 험지 원정에선 피벗우측 강등이 오히려 평점 상승(7.30). 약점: 피로 누적 시 수행 저하(영상 분석 캐비앗)와 FC26 ''부상에 취약함'' 트레잇, CAM 기용은 부가가치 없음(duties MEDIUM). ⭐[2026-09-12] OVR·6종합 궤적(PAC/SHO/PAS/DRI/DEF/PHY): FC25 출시판 82(68/77/80/82/78/85) → FC26 출시판 81(69/77/78/80/77/83) → FC26 라이브 06-30·07-23판 81(동일) → FC27 09-10판 83(69/80/81/82/78/84). FC27 vs FC26(출시=라이브 동일값) Δ: SHO+3·PAS+3·DRI+2·DEF+1·PHY+1. 세부(attrs): 중거리슛 77→82·크로스 76→82·커브 76→81·침착 77→83·반응력 81→86·시야 79→82·균형 85→88·PK 55→65 상승, 가속·질주 69 유지, 체력 92 유지. FC25→FC26 출시판에서는 짧은패스 83→81·긴패스 83→80·볼컨트롤 83→80·힘 82→79로 하락했던 것이 FC27에서 부분 회복. 강점 갱신: 크로스·중거리 속성 강화가 26/27 우측 크로스 공급(슈퍼컵 1도움·브뤼헤 크로스 7회)과 정합. 약점: 속도 69 정체, 헐전 크로스 0/4·탈취당함 5·빅찬스 실축.','Fotmob 프리미어리그 25/26 41지표(2157분)에서 공격 관여가 폭넓게 상위다 — 기회 창출 41회(리그 동포지션 상위 19%)·기대 도움 3.99(상위 21%)·성공한 크로스 21회(상위 16%)·빅찬스 창출 7회(상위 27%)에 정확한 롱볼 43회(상위 6%)까지 붙는다. 압박·회수 축도 상위 — 상대 진영 볼 탈취 21회(상위 11%)·볼 회수 89회(상위 24%)·수비적 행동 150(상위 24%)·태클 29(상위 29%)로 공수 왕복 프로필이 지표로 확인된다. 얻어낸 파울 48회(상위 8%)는 리그 최상위권으로, 전진 상황에서 상대 반칙을 유도해 팀을 밀어 올린다. 대가는 규율과 소유다 — 파울 31회(하위 11%)·경고 5장(하위 12%)·볼 뺏김 46회(하위 8%). 우리 3팀 풀에서도 실측 44경기 평균 7.01(백분위 59)에 xG 0.212(백분위 64)·키패스 1.38(백분위 73)으로 같은 결론이 나온다. ⭐[2026-09-12] fotmob_detail_stats는 PL 25/26(47지표)이 최신 — 26/27 시즌 지표는 미수집. 25/26 백분위(총량/90분): 얻어낸 파울 48(92/87)·정확 롱볼 43(94/89)·상대진영 볼탈취 21(89/85)·라인브레이킹 패스 82(82/70)·찬스 창출 41(81/73)·xA 3.99(79/68); 하위: 볼뺏김 46(8)·파울 31(11)·경고 5(12)·스프린트 63회(90분당 3)·주행거리(11). 26/27 실측(player_matches·match_player_reports): 슈퍼컵 7.1(키패스 4·1도움) · 브라이턴 6.49(듀얼 7/12 팀 최다) · 아스날 5.76(패스 71%) · 헐 5.74(최종3분의1 이벤트 30 팀1위, 크로스 0/4, xG 0.68 실축) · 브뤼헤 7.8(1골·키패스 4·태클 4·피패스 33 팀 최다, 소유상실 18 팀 최다). v_player_profile n=52 평균 6.97(3553분). v_player_season_stats 26/27: PL 3경기 6.0 · UCL 1경기 7.8 · 슈퍼컵 7.1.','HIGH — fit_sim 실측 .878(DM)·.801(CAM)에 확정 XI RM. 에메리 두 줄 4의 우측 뱅크 복귀 역할(implementation ②)을 정의하는 선수. ⭐[2026-09-12] HIGH 재확인. 소속팀 실측 우선: 26/27 경기별 커널(match_player_prescriptions) 슈퍼컵 wm_winger/Attack .882 → 브라이턴 wm_widemid/Build-Up .852(avg_x 54.6, 10명 국면) → 아스날 wm_wideplm/Attack .613 → 헐 wm_winger/Attack .774 → 브뤼헤 wm_widemid/Support .758(argmax Defend .773, Δ0.015 노이즈 → 정본 유지). 시즌 measured(prescriptions id=418) wm_winger/Attack .801(n=4, 335분). 인게임 A/B(obs#537): RM을 wm_wideplm/Attack→wm_widemid/Support로 바꾸자 맥긴 자기진영 비중 5.9%→38.9%로 뱅크가 섰고 SIM↔T2 그리드 유사도 .97(obs#569) — 정본 wm_widemid/Support가 게임에서 재현 검증됨. 브뤼헤전 그가 복귀형(widemid)이었기에 같은 쪽 완비사카가 전진측이 된 구조적 짝(obs#546).','MEDIUM — 2×10번 하프스페이스 포켓에 인사이드 포워드 도착 성향이 닿으나 알론소 10번은 창조 우선(팔머형) — 맥긴은 듀얼·수직형 (교차 투영 — 실측 아님).','HIGH — 듀얼 최다·압박검증·수직 움직임이 고강도 압박과 측면 압축 체제에 직결 — 단 피로 민감성은 강행군 리스크 (교차 투영 — 실측 아님).','squad_entries CAM/DM/WM 3행(fit_sim .801/.878); prescriptions optimal·role·role:season(RM)·measured:CAM/pivot-right; player_duties RM·pivot-right·CAM·RM(영상) 4행; v_player_profile n=44; FC26(OVR81); obs#110·#145 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표) · v_player_profile n=44(3039분) · v_player_season_stats(PL 30경기 3골 + EL 12경기 3골 1도움) | 2026-09-12 갱신: player_game_stats id=700(FC25 2024-09-13)·701(FC26 2025-09-12)·10/91(FC26 2026-06-30/07-23)·560(FC27 2026-09-10, attrs 포함); fotmob_detail_stats PL 2025/2026 47지표(24/25 40지표 병존); fotmob_traits 2026-08-11; v_player_profile n=52; v_player_season_stats 2026-27; player_matches 26/27 8행; match_player_reports report 1·22·30·31·35; match_player_prescriptions 5행; prescriptions id=418; squad_entries id=11/12/19; player_duties id=14/15/16/25; obs#537·539·546·554·569; player_status id=11(계약 2028-06-30); player_market_values 2026-08-01 €14.25m.','n=44 충분, 3슬롯 실측이 모두 존재해 신뢰 최상급. CAM fit_sim은 n=4 소표본. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-09-12: 26/27 실측은 5경기(PL 3·UCL 1·슈퍼컵 1)로 시즌 판단엔 소표본이며 PL 3경기 중 2경기가 27~39% 점유·10명 국면 등 비정착 조건. FotMob 상세지표는 25/26이 최신(26/27 미수집). FC27 09-10판 PlayStyles는 fut.gg 릴레이(EA 공식 라벨 교차검증 완료)이며 sofifa 1차 소스 대조는 미완. Δ 기준: FC26 출시판(2025-09-12)과 라이브판(2026-06-30)이 동일값이라 이 선수만은 기준 시점 충돌 없음. 06-30·07-23 FC26 행 2건은 값 중복(같은 라이브판). ⚠️player_game_stats 08-18~08-31 FC27 4행은 PlayStyles 미포함 1단계 수집이라 09-10판만 인용.','2026-09-12','프리미어리그 공격형 미드필더·윙어 중 박스 안이 아니라 그 앞에서 일하는 유형이다 — 패스와 압박으로 기여하고 슈팅 지역에는 잘 들어가지 않는다. 얻어낸 파울 48회(백분위 92), 상대 진영 볼 탈취 21회(89), 정확한 롱볼 43회(94), 기회 창출 41회(81), 성공한 크로스 21회(84)가 강점이고 90분당 xA 0.17도 68로 준상위다. 반대로 볼 뺏김 46회가 백분위 8, 파울 31회가 11로 공을 잃고 반칙으로 끊는 빈도가 하위권이다. 90분당으로 보면 상대 박스 터치가 백분위 14, 슛이 13으로 마무리 지역 관여가 사실상 없다 — 총량 백분위(48·54)는 출전 시간이 많아 부풀려진 값이다. 슈팅 부담을 지우지 말고, 중원과 측면 사이에서 전진 패스와 압박을 담당하는 자리에 두는 것이 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(9,1,11,'B− — 다슬롯 백업(RDM·RB). 피벗 21경기 6.62, RB 8선발 704분 6.46(fit_sim .832). 처방 dm_holding/Ball-Winning 벤치(카마라와 동형). FC27(09-10) OVR74 유지, PAC 67→66(-1) 외 SHO53·PAS67·DRI70·DEF72·PHY69 전부 불변, PlayStyle 여전히 0종 — 게임 스탯상으로도 "특징 없는 유틸리티" 판정이 그대로 유지된다.','볼위닝형 유틸리티 — 듀얼 5.8·인터셉트 1.8, 창조 xa .03. 시즌 실측 그리드는 명백히 우측(RDM x=62), CDM/CM/RB 겸업. 26/27 프리시즌·서사(네덜란드어 다국어 수집, obs#229): 유스코치 Boel과 본인 모두 "미드필더가 본 포지션, RB는 최고 포지션 아님"이라 진술 — DM 결손 시 대체 자원 성격이 강화됨.','피벗과 RB를 모두 메우는 커버 폭, POT 81의 성장 여지. 약점: 평균 평점 6.63(백분위 18)·xA 백분위 17 — 산출 전반 하위권, FC27 OVR도 74로 게임 즉전력 낮음(변화 없음). PAC 67→66 미세 하락 외 전 스탯 정체 — 8월 이후 능력치 성장 신호 없음.','두 모집단이 드물게 일치해 양쪽 모두 하위를 가리킨다 — 우리 3팀 풀 실측 63경기 평균 6.64(백분위 20), Fotmob 프리미어리그 25/26 35지표(1047분)에서도 지표 대부분이 리그 하위다. 전진 산출 사실상 없음 — 슛 0개·득점 0·기회 창출 2회(하위 5%)·xA 0.21(7%)·정확한 롱볼 7회(9%)·드리블 성공률 28.6%(7%). 수비도 물량 얇음 — 인터셉트 5회(10%)·수비적 행동 60(12%)·볼 회수 43(19%)·공중 경합 승률 37.5%(16%). 유일한 상위는 패스 정확도 89.7%(17%)와 크로스 정확도 50.0%(6%, 소표본). | 2026-09-11 갱신: FC27(roster_date 2026-09-10) OVR74(변화 없음)·PAC66(-1 vs FC26 07-23 67)·SHO53·PAS67·DRI70·DEF72·PHY69(전부 동일), PlayStyle 0종 유지 — 실측·게임 스탯 모두 정체를 재확인.','MEDIUM — 벤치 처방이 실측으로 정리된 백업. RDM(볼위닝 홀딩)과 RB(fb_wingback/Balanced .832) 두 슬롯 실측 보유가 가치이나, FC27 능치 전면 정체로 즉시전력 승격 가능성은 낮게 유지.','LOW — 박스 미드필드의 극단적 기술 규율 요구(rest_defense 축) 대비 창조·배급 산출이 하위권 (교차 투영 — 실측 아님).','MEDIUM — 젊은 볼위너로 압박 체제 원자재는 되나 실측 근거는 에메리 체제뿐 (교차 투영 — 실측 아님).','squad_entries DM/FB 2행(fit_sim .832); prescriptions optimal(RDM)·measured:season·role:season; v_player_profile n=44; FC26(OVR74 POT81); obs#99·#104 (player_duties 행 없음) | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 35지표) · v_player_profile n=63(2508분) · prescriptions measured:season:full2526 n=10 rt=6.5 fit=0.854 | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR74·PAC66) vs FC26(07-23, OVR74·PAC67) 비교 — 전 스탯 사실상 동일','경기수 n=44이나 슬롯별로 쪼개면 RB 8선발 등 소표본. player_duties 미작성. 2026-09-11 FC27 갱신분은 변화 거의 없어(PAC -1) 기존 등급·서술을 뒤집을 근거 없음. 알론소·이라올라 핏은 교차 투영(실측 아님). 2026-08-11 갱신 caveat(재수집 이전 표본 혼재)은 유효.','2026-09-11','프리미어리그 미드필더 중 1000분 남짓 뛴 소표본이고, 35개 지표에서 뚜렷한 강점을 찾기 어려운 프로필이다. 좋은 축은 짧은 패스의 안정성과 대인 방어다 — 패스 정확도 89.7%가 백분위 83, 크로스 정확도 50.0%가 94, 제쳐당한 횟수 90분당 0.43회가 89로 쉽게 벗겨지지 않는다. 문제는 생산과 개입 양쪽이다. 기회 창출 2회가 백분위 5(90분당 4), xA 0.21이 7(90분당 1), 슛 0회, 어시스트 0개로 공격 산출이 최하위이고, 인터셉트 5회(90분당 5)·수비적 행동 60회(4)로 수비 개입 빈도도 최하위다. 롱볼 정확도 36.8%(9)와 드리블 성공률 28.6%(7)까지 낮아 전진 수단도 마땅치 않다. 리그 무대에서 주전으로 세울 근거가 이 숫자에는 없고, 점유가 확보된 경기의 시간 관리용으로 읽어야 한다.');
INSERT INTO player_evaluations VALUES(10,1,12,'S — 확정 XI RDM(obs#110 starter)이자 3선 배급 주도자(obs#129). 피벗 16경기 7.14(rate_v), 26/27 R4(헐)까지 포지션-순수 4경기 재집계 6.55·342분. 기능축은 dm_holding/Defend로 재확정(2026-08-05, 커널 RDM dm_holding 계열 전수 Defend .703>Roaming .654>Ball-Winning .556). FC27(09-10) OVR84 유지, SHO 55→56(+1)·PAS 77→78(+1)·DRI 79→78(-1)·PHY 80→78(-2), 신규 PlayStyle Block 추가.','우중앙 딥라잉 플레이메이커처럼 움직이는 볼위닝 앵커 — 깊이 앉는 앵커 서사는 탈편향 표본으로 기각(duties). 26/27 UCL 브뤼헤전(2026-09-08) 실측: 패스 36/34(94%, 팀 최다)인데 상대 박스 터치 1·기회창출 0으로 잔류·배급 축이 재확인됐고, 수비액션 x 평균 27.1로 필드 세 번째로 낮아 조앙 고메스(35.8)의 전진을 뒷받침. FC27 신규 PlayStyle Block은 이 잔류형 역할과 정합.','볼위닝+빌드업 겸장(패스량 다수·정확도 높음), FC27 OVR 84로 필드 최고 등급 유지. 약점: 창조 산출 최저(xA 백분위 27), PAC 64로 정적. 2026-08-23 브라이턴전 복귀전에서 지상 듀얼 4/11(36%)로 대인에서 밀린 사례 있음(컨디션 맥락, 단일경기 판단 보류) — 2026-09-08 브뤼헤전 68분서 에메리가 tight라 언급하며 로테이션 관리 시작.','Fotmob 프리미어리그 25/26 38지표(1418분)에서 90분당 경합 승 7.36(상위 7%)·경합 승률 56.9%(20%)로 방향은 서사와 맞고, 공중 경합 승률 64.3%(11%)·공중 경합 승 36회(20%)·90분당 공중 경합 승 2.29(10%)가 확실한 축이다. 배급은 롱볼 정확도 67.4%(12%)·패스 정확도 88.3%(26%), 어시스트 3개(27%)·90분당 얻어낸 파울 1.90(11%). 반면 슛 7개(하위 20%)·xG 0.49(23%)·상대 박스 터치 11회(27%)로 박스 진입은 거의 없음. 우리 3팀 풀 실측 27경기 평균 7.07(백분위 68). | 2026-09-11 갱신: FC27(roster_date 2026-09-10) OVR84(변화 없음)·PAC64·SHO56(+1 vs FC26 07-23 55)·PAS78(+1 vs 77)·DRI78(-1 vs 79)·DEF83·PHY78(-2 vs 80), 신규 PlayStyle Block 추가(FC26 07-23엔 PlayStyle 없음) — Block은 26/27 실측(패스 다수·박스터치 최소)의 잔류형 프로필과 정합.','HIGH — 확정 XI RDM, 더블 피벗 dm_holding/Defend 분담의 핵. 11연승 기간 우측 고정 실측과 26/27 브뤼헤전 남는 쪽 실측(BBC·Bains Analysis 3중 확인)이 체제 기여를 직접 증명. FC27 PHY 소폭 하락(80→78)은 로테이션 관리 필요성과 궤를 같이함.','HIGH — 알론소 카이세도 하강 피벗(dm_dlp/Roaming, 백라인 옆 압박 유인)과 카마라의 dlp형 움직임 실측(.83)이 동형 (교차 투영 — 실측 아님).','MEDIUM — 볼위닝·커버 범위는 부합하나 pac 64·Controlled Lengthy가 수직 전환 최속 체제(1.95m/s)와 긴장 (교차 투영 — 실측 아님).','squad_entries DM(rate_v 7.14); prescriptions optimal·role·role:season(RDM); player_duties LDM·RDM 2행; v_player_profile n=27; FC26(OVR84 POT86, 블로킹); obs#110·#129·#130·#131·#132·#147 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 38지표) · v_player_profile n=27(1768분) · v_player_season_stats(PL 18경기 17선발 1418분) | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR84·SHO56·PAS78·PlayStyle Block) vs FC26(07-23, OVR84·SHO55·PAS77·무PlayStyle) 비교; player_duties 26/27 브뤼헤전(2026-09-08) 추가','n=27 충분하나 듀얼·인터셉트 지표는 표본 1~2경기 — obs#131이 지적한 지표별 표본 불일치 상존. 2026-09-11 FC27 갱신분은 변화폭이 작아(±1~2) 신뢰도에 영향 없음. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','프리미어리그 미드필더 중 경합에 강하고 마무리 지역에는 거의 관여하지 않는, 중원 지키기에 특화된 프로필이다. 출전이 1400분 남짓이라 90분당 백분위로 읽으면 경합 승 7.36회가 백분위 93, 공중 경합 승 2.29회가 90, 공중 경합 승률 64.3%가 89로 몸싸움 지표가 상위권이다. 롱볼 정확도 67.4%(88)와 90분당 얻어낸 파울 1.90회(89)도 좋고, 이 선수가 뛸 때의 90분당 실점 0.95골이 백분위 90이다. 반면 슛 90분당 0.44회가 백분위 11, xG 0.03이 17, 상대 박스 터치 0.70회가 23으로 공격 지역 기여는 최하위권이며 기회 창출(56)은 평범하다. 걷어내기(27)가 낮은 것은 최후방 방어보다 중원 경합에 무게가 실린 역할 때문으로 읽힌다. 앞선 두 명이 창조를 맡는 구조에서 중원 경합을 전담하는 자리에 쓰는 것이 맞다.');
INSERT INTO player_evaluations VALUES(11,1,14,'A− — 확정 XI CAM(obs#110, fc26:opt:LM starter). 좌측 와이드 21경기 6.90에 천장이 압도적(피크 9.4 포레스트 4강·8.5 본머스·8.3 EL 결승 — 전부 좌중앙 실측). CAM fit_sim .672는 n=3 소표본이라 판단 근거로 약함. ''우측 드리프트 10번'' 언론 서사는 실측으로 기각(시즌 우측 선발 2회뿐). FC27(09-10) OVR80은 FC26(78) 대비 +2로 확정 선발 위상과 정합하나, 26/27 CAM 배치 3경기(브라이턴 ST 겸용·아스날·브뤼헤)의 커널 적합이 0.43 이하로 흔들리는 중이라 CAM 슬롯 기하 자체는 재검증 대상이다.','좌편향 자유 플레이메이커 서술은 FC26 시절 기준이고, 26/27 실측(2026-09-08 브뤼헤·2026-09-05 헐 등)은 방향이 다르다 — 「라인 사이 수신, 인필드 이동」 1차 서술이 조사한 어떤 언어에서도 0건이고, Opta/theanalyst·Coaches'' Voice가 공통으로 「박스 도착형」(ghosted in, arriving from deeper positions)을 적는다. FC27 PlayStyles가 Technical로 신규 등록됐고 dri 84(FC26 82 대비 +2)·pas 81(79 대비 +2)로 온볼 수치가 오른 방향이 이 기술형 도착 프로필과 맞는다. 단 hp 38(브뤼헤전)로 표본이 얇아 「포켓 수신형→박스 도착형」 전환을 정본 교정으로 확정하지 않는다.','Fotmob 프리미어리그 25/26 39지표(1759분) 기준 태클·경합 백분위(태클 상위 11%·수비적 행동 상위 15%·볼 회수 상위 18%)는 시즌 데이터라 이번 갱신에서도 유지된다. 신규 반영은 FC27 능력치 상승이다 — sho 78(FC26 77 대비 +1)·pas 81(+2)·dri 84(+2)로 온볼·창조 계열이 고르게 오르고, pac 65(67 대비 −2)·phy 60(67 대비 −7)로 피지컬 계열은 하락했다(roster_date 2026-09-10). 약점은 여전히 드리블 성공률 31.0%(하위 16%)·볼 뺏김 35회(하위 18%) — FC27 dri 상승과 실측 드리블 성공률 저조는 별개 축이며, 볼을 몰고 뚫는 유형이 아니라 도착·마무리형이라는 26/27 관찰과 일치한다.','Fotmob 프리미어리그 25/26 39지표(1759분) 기준은 유지 — 태클 49회(상위 11%)·수비적 행동 197(상위 15%)·슛 49개(상위 22%)·득점 6골(상위 22%), 약점은 드리블 성공률 31.0%(하위 16%)·파울 41회(하위 5%). 신규: FC27(roster_date 2026-09-10) OVR80·PAC65·SHO78·PAS81·DRI84·DEF66·PHY60, PlayStyles=Technical(신규), 신장172cm·72kg. FC26 직전(2026-07-23) 대비 OVR+2·PAS+2·DRI+2·PAC−2·PHY−7 — 창조·기술 계열 강화, 스피드·피지컬 계열 약화가 일관된 방향이다. 우리 3팀 풀 실측 55경기 평균 6.93(백분위 53)·xG 0.316(백분위 82)·키패스 1.93(백분위 80)은 불변.','HIGH — 확정 XI CAM이며 에메리 10번 로밍 담당. 다만 2026-09-08 브뤼헤전 등 26/27 3경기에서 cam_playmaker/Roaming 등 CAM 전 조합 커널 적합이 0.43 이하로 떨어져(헐전 cam_classic10/Attack 0.879과 대비), 「라인 사이 수신형 10번」 처방과 「박스 도착형」 실측 사이 긴장이 새로 발견됐다(2026-09-10 duty 기록). 확정 선발 지위는 유지하되 처방 role 서술은 재검증 필요.','HIGH — 2×10번 하프스페이스 체제의 좌측 포켓에 라인 사이 수신·창조 프로필이 직결 (교차 투영 — 실측 아님).','MEDIUM — 세컨드 스트라이커 압박 실측은 있으나 고강도 왕복의 상시 요구와 리그 일관성 저하가 긴장 (교차 투영 — 실측 아님).','squad_entries CAM/WM 2행(fit_sim .672 n=3); prescriptions optimal(LW)·role·role:LM·measured 다수; player_duties LW/left-10·pivot-left·CAM 3행; v_player_profile n=55; FC26(OVR78); obs#110·#124·#127·#145 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 39지표) · v_player_profile n=55(2988분) · v_player_season_stats(PL 36경기 2골 + EL 15경기 2골 2도움) | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date=2026-09-10, OVR80·PAC65·SHO78·PAS81·DRI84·DEF66·PHY60·PlayStyles=Technical·172cm/72kg) vs FC26(2026-07-23, OVR78) · player_duties 2026-09-08/09/10 브뤼헤 원정 갱신(박스 도착형 서술, CAM 커널 0.43 이하)','n=55 충분. 단 CAM fit_sim은 n=3 표본 부족 — CAM 슬롯 판단엔 쓰지 말 것. 알론소·이라올라 핏은 교차 투영(실측 아님). FC27 OVR 변화(+2)는 시즌 산출 방향과 일치하나, 최신 duty 기록(hp38 소표본)으로 인해 CAM 슬롯 역할 서술은 확정하지 않았다 — 다음 재검증엔 hit_points 45+ 표본 필요.','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 창조보다 압박과 태클로 값을 내는, 모집단에서 드문 수비형 2선 프로필이다. 90분당 수비적 행동 10.08회가 백분위 94, 태클 2.51회가 91, 볼 회수 5.58회가 92, 인터셉트 0.77회가 84로 상위권이고 공중 경합 승(80)까지 좋다. 공격에서는 득점 6골(83)과 헤더 슛(76)이 준상위이고 90분당 얻어낸 파울 2.30회(92)로 전방에서 파울을 유도한다. 약점은 반칙과 볼 소유다 — 파울 41회가 백분위 5(90분당 8), 경고 6장이 7, 드리블 성공률 31.0%가 16, 제쳐당함이 20으로 끊는 방식이 거칠고 공을 몰고 나가는 능력은 없다. 기회 창출(69/61)과 xA(57/37)는 평범해 창조형 10번으로 읽을 근거는 없다. 전방 압박의 강도를 올리는 카드로 쓰고, 공을 잡고 풀어야 하는 자리에는 다른 유형을 두는 편이 맞다.');
INSERT INTO player_evaluations VALUES(12,1,15,'B− — 벤치 인버티드 RW. rate_v 7.33이나 v_player_profile n=3(초기)→48경기(1921분)로 확대되며 평균 평점 6.70(3팀 풀 백분위 24)으로 하락, 상위 서술은 참고 수준으로만 유지된다. ⚠️ FC27 09-10 roster_date 수집에서 이 선수가 누락됐다(수집 목록 결손 확인) — 조회 가능한 최신은 FC27(roster_date=2026-08-22) OVR80으로, FC26(2026-07-23) OVR79 대비 +1이다. 이 08-22 스냅샷을 잠정 근거로 쓴다.','왼발 컷인형 인버티드 우측 와이드. FC27(08-22, 09-10 수집 누락으로 최신 대체) 기준 dri 87(FC26 86 대비 +1)·phy 58(54 대비 +4)로 온볼·피지컬 모두 소폭 상승 — 다만 이 스냅샷에는 PlayStyles·신장·체중 필드가 비어 있어 FC26 수집값(감아차기·트릭스터)을 그대로 참고한다. 드리블 86→87의 미세 상승은 실측 드리블 성공률 55.2%(리그 상위 15%)와 방향이 맞지만, phy 54→58 상승은 실측 수비 관여 최하위권(태클 하위 15%·인터셉트 하위 15%)과는 여전히 괴리된다.','표본이 3경기→48경기(1921분)로 늘며 평균 평점이 7.33→6.70(3팀 풀 백분위 24)으로 하락한 것은 기존 갱신 그대로다. Fotmob 25/26 39지표(873분) 기준 90분당 창출은 상위다 — 기회 창출 2.17/90(상위 10%)·xA 0.20/90(상위 18%)·드리블 성공률 55.2%(상위 15%). 마무리는 붕괴 수준(득점 0, xG 0.58 하위 13%, 유효슛 3개 하위 18%)이고 수비 기여도 최하위권(태클 하위 15%·인터셉트 하위 15%)이다 — 이 부분은 8월 갱신과 동일. ⚠️ FC27 09-10 수집 결손으로 게임 능력치의 최신 변화는 불확실하다 — 08-22 스냅샷(OVR80·dri87·phy58)만 확인되며, 이후 조정 여부는 데이터 없음.','Fotmob 프리미어리그 25/26 39지표(873분) 기준은 8월 갱신 그대로 유지 — 90분당 기회 창출 2.17(상위 10%)·xA 0.20(상위 18%)·드리블 성공률 55.2%(상위 15%), 마무리 붕괴(xG 0.58 하위 13%)·수비 최하위권. ⚠️ FC27(roster_date=2026-09-10) 수집에서 산초는 누락 확인됨 — 조회 가능한 최신은 FC27(2026-08-22) OVR80·PAC79·SHO73·PAS77·DRI87·DEF35·PHY58이며, FC26(2026-07-23) OVR79·PAC79·SHO73·PAS77·DRI86·DEF35·PHY54 대비 OVR+1·DRI+1·PHY+4다. 09-10 수집 목록 결손이므로 이 08-22 값을 잠정 근거로 쓰고, 다음 수집 시 09-10 스냅샷 확보가 필요하다.','MEDIUM — 상위 경기 실측은 좋으나 표본이 48경기로 확대되며 평균이 6.70으로 내려왔고, 뱅크 복귀형 우측(wm_widemid/Support)이 기본인 체제에서 수비 관여 최저 프로필(태클·인터셉트 하위 15%)은 여전히 조건부다. FC27 dri 87·phy 58(08-22 스냅샷) 소폭 상승도 이 구조적 긴장을 해소하지 못한다 — 09-10 최신 데이터 결손으로 판단 변경 근거 없음.','MEDIUM — 하프스페이스 10번 포켓 변환 여지는 있으나 극단적 기술 규율·수비 전환 요구와 def 35의 긴장 (교차 투영 — 실측 아님).','LOW — 고강도 압박·왕복 체제에 수비 스탯 최저 프로필 (교차 투영 — 실측 아님).','squad_entries WM(rate_v 7.33); prescriptions optimal(RW)·measured:season; v_player_profile n=3; FC26(OVR79, 감아차기·트릭스터 — 2026-06-30 수집값); obs#30·#84 (player_duties 행 없음) | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 39지표) · v_player_profile n=48(1921분) · v_player_season_stats(PL 29경기 891분 2도움) | stat_eval 2026-09-11 갱신: player_game_stats FC27 roster_date=2026-09-10 수집에서 player_id=15 누락 확인 — 최신 조회 가능값은 FC27(2026-08-22, OVR80·PAC79·SHO73·PAS77·DRI87·DEF35·PHY58, PlayStyles/height/weight 필드 공란) vs FC26(2026-07-23, OVR79·DRI86·PHY54)','n=3 표본 부족 — 모든 수치 캐비앗, 등급 과신 금지. player_duties 미작성. 알론소·이라올라 핏은 교차 투영(실측 아님). ⚠️ 2026-08-11 갱신: 이 평가는 재수집 이전 표본으로 썼다 — 실측 표본이 48경기로 늘었고(obs#150) 스탯·백분위·시즌 성적은 새 표본을 반영한다. 등급·전술핏 문장은 재검토 대상이다. ⚠️ 2026-09-11 갱신: FC27 09-10 roster 수집에서 이 선수가 빠져 있어(사전 통지된 결손) 게임 스탯은 08-22 스냅샷을 잠정 근거로 썼다 — 실측(n=48) 및 등급 판단에는 영향 없음.','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 873분만 뛴 소표본이므로 90분당 백분위로 읽어야 하고, 그 기준에서는 패스와 드리블로 남을 살리는 유형이 뚜렷하다. 90분당 기회 창출 2.17회가 백분위 90, xA 0.20이 82, 성공한 패스 32.58회가 84, 드리블 성공 1.65회가 78이고 드리블 성공률 55.2%가 85, 롱볼 정확도 66.7%가 85다. 90분당 상대 박스 터치 5.77회(82)로 위험 지역에도 들어간다. 문제는 자기 마무리가 전무하다는 점이다 — 90분당 xG 0.06이 백분위 5, 슛 1.03회가 7, 유효슛이 16이고 득점 0골이다. 수비 기여도 90분당 수비적 행동 5, 경합 승 8, 볼 회수 8로 최하위권이다. 슛을 기대하지 않는 전제에서 마지막 패스를 담당하는 자리에 쓰고, 압박 부담이 큰 측면에는 세우지 않는 편이 맞다.');
INSERT INTO player_evaluations VALUES(13,1,16,'S — 체제의 원톱, 확정 XI(obs#110). ⚠️ FC27(roster_date 2026-09-10) 전체 AVL 수집 목록에서 왓킨스만 누락이 확인되어, 이번 갱신은 FC26 최신값(2026-07-23, OVR82)을 근거로 유지한다. 상위 7경기 평균 8.47(rate_v, 스쿼드 최고), xG 1.007/경기(3팀 풀 백분위 96), Fotmob PL 41지표(2852분)에서 득점 16골(리그 상위 6%)·xG 15.14(상위 8%)로 리그 최상위 볼륨 스트라이커 지위는 이전 갱신(2026-08-11)과 동일하게 유지된다.','뒷공간 런 리그 1위의 박스 상주형(채널 러너에서 진화). 샷맵: 103슛 중 박스 내 84%·6야드 24·헤더 19, xG/슛 0.19 — 순수 박스 도착 프로필. 양발+헤더 마무리, 전방 압박 탈취. FC27 능치 갱신분은 없으나(09-10 수집 누락) FC26 최신(2026-07-23) 기준 pac77·sho82·pas72·dri78·def50·phy80로 직전과 변화 없음.','임무 순응성(시스템에서 가장 게임플랜 순응적인 공격수)과 엘리트 피니시, FC26 칩슛·프리시전 헤딩·끈기와인내. 약점: 창조 안 함(xA 0.03, duties) — Support(링크형) 포커스 부적합 판정, FC26 부상에 취약함 트레잇.','표본이 71경기(4206분)로 늘어난 뒤에도 골 기대치 우위는 그대로다 — 3팀 풀 xG 1.007/경기(백분위 96)이고, Fotmob 프리미어리그 25/26 41지표(2852분)에서 득점 16골(리그 공격수 상위 6%)·xG 15.14(상위 8%)·슛 83개(상위 6%)·유효슛 38개(상위 6%)·상대 박스 터치 177회(상위 4%)로 리그 최상위 볼륨 스트라이커다. 창출·연계도 받쳐준다 — 기회 창출 23회(상위 12%)·드리블 성공 26회(상위 10%)·상대 진영 볼 탈취 16회(상위 12%). 약점은 볼 뺏김·공중 경합 승률 저조. 우리 3팀 풀 평점 백분위는 44에 불과해 리그 득점 상위 6%와 어긋나는데, 이는 강팀 3팀만 모은 좁은 풀과 공격수 평점 체계의 차이로 읽는다. ⚠️ 이번 회차 FC27 스탯은 09-10 AVL 수집 목록에서 왓킨스만 결측되어 반영하지 못했다 — 위 실측 수치는 2026-08-11 갱신분과 동일 소스다.','HIGH — fit_sim 실측 .713(measured:season:full2526, n=37, 평균 6.93, 상위 7경기 8.47)에 확정 XI ST. 에메리 원톱 3중 임무(박스 점유/링크/채널런)의 실측·영상·처방 3축 강정합(obs#145).','MEDIUM — 알론소 9번은 내려오는 false9(st_false9/Build-Up) — 왓킨스는 박스 점유·인비하인드형이라 역할 정의가 어긋남 (교차 투영 — 실측 아님).','HIGH — 뒷공간 런 리그 1위·전방 압박 탈취가 수직 전환+파이널서드 탈취 체제와 직결 (교차 투영 — 실측 아님).','squad_entries ST(rate_v 8.47); prescriptions optimal·role·measured:season(ST); player_duties ST 2행(샷맵 포함); v_player_profile n=56; FC26(OVR82); obs#110·#145 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표) · v_player_profile n=71(4206분) · prescriptions measured:season:full2526 n=37 rt=6.93 fit=0.713 | stat_eval 2026-09-11 갱신: FC27 09-10 roster에 player_id=16 행 없음(AVL 전체 수집 목록에서 결측 확인) — FC26(roster_date 2026-07-23, OVR82·pac77·sho82·pas72·dri78·def50·phy80)이 최신 게임 능치로 유지. Fotmob·v_player_profile·prescriptions 수치는 2026-08-11 갱신분과 동일.','n=71 충분, 3축(실측·영상·처방) 강정합. ⚠️ FC27(2026-09-10) 게임 스탯은 왓킨스 행이 누락되어 대조 불가 — 다음 FC27 수집 때 재확인 필요. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','프리미어리그 공격수 중 슈팅 지역에서의 양과 질이 모두 상위권인 정통 최전방 프로필이다. 슛 83회(백분위 94)·유효슛 38회(94)·득점 16골(94)·xG 15.14(92)·xGOT 15.80(94)이 모두 상위 10% 부근이고, 상대 박스 터치 177회(96)로 위험 지역 점유가 최상위권이다. 연계에서도 기회 창출 23회(88)와 드리블 성공 26회(90)로 공을 지켜 내주는 능력이 좋다. 약점은 공 소유의 안정성과 수비 복귀다 — 볼 뺏김 43회가 백분위 2로 최하위이고, 90분당으로 보면 수비적 행동 4, 걷어내기 10, 볼 회수 16으로 자기 진영 기여가 거의 없다. 공중 경합 승률 38.7%(47)는 평범해 제공권으로 버티는 유형은 아니다. 박스 안 마무리와 앞선 연계를 맡기고 수비 복귀 부담은 지우지 않는 배치가 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(14,1,55,'A− — 합류 확정, obs#110 확정 XI의 CAM(fc26:opt:CAM starter). CAM 적합 .861(cam_halfwinger/Balanced, 대표팀 12경기 7.2), DM .713(클럽 56경기 7.2). FC27(09-10) 신규 수집에서 OVR이 77→80(+3)로 뛰었고 슈팅 71→74·수비 69→70도 함께 올랐다(스피드는 78→71로 하락). 신규 PlayStyle Power Shot이 추가됐다 — 슈팅 능치 상승과 맞물려, 분데스리가 xG 3.85(리그 동포지션 상위 9%)·슛 51개(상위 5%) 실측과 방향이 일치한다.','캐리로 전진하는 박스투박스 — 드리블 돌파보다 운반, 박스 침투 시 공중볼 위협, 중거리 슈팅(영상 종합 가설, obs#142). 수비 기여 실재(태클 1.52·탈취 4.69/90, duties). FC27 갱신에서 dri 83·phy 71로 이전(FC26 dri82·phy71)과 큰 변화 없이 유지, 신규 Power Shot PlayStyle이 중거리 슈팅 서사와 정합.','60경기 전수 실측의 큰 표본과 이중 프로필(10번/8번), FC27 OVR 80(POT86 대비 성장폭 유지)·테크니컬. FC27 슈팅 능치 71→74 상승은 Fotmob PK 제외 xG 상위 9%·유효슛 12개(상위 89%)와 같은 방향이다. 약점: 온더볼 캐리 전진은 그리드 밖이라 미검증, 빌라 실측 0경기, 스피드 하락(78→71)은 대표팀 전방 기용 시 침투 속도 변수로 주시할 값이다.','옛 평가는 xG 0.174가 3팀 풀 백분위 43이라며 ''10번 기준 평범''이라고 썼지만, Fotmob 분데스리가 25/26 42지표(2094분)로 보면 정반대다 — xG 3.85가 리그 동포지션 상위 9%, PK 제외 xG도 상위 9%, 슛 51개 상위 5%, 헤더 슛 11개 상위 6%다. 창출도 함께 상위다 — 기대 도움 5.13(상위 7%)·빅찬스 창출 6회(상위 18%)·상대 박스 터치 80회(상위 6%)·성공한 크로스 11회(상위 23%). 볼 운반과 몸싸움이 이 선수의 진짜 축이다 — 드리블 성공 33회(상위 2%)·경합 승 179회(상위 4%)·경합 승률 58.9%(상위 13%)·얻어낸 파울 78회(리그 백분위 100, 즉 동포지션 1위권). 약점은 볼 관리와 규율이다 — 볼 뺏김 31회(하위 4%)·퇴장 2회(백분위 0)·슛 블록 2회(하위 20%). 우리 3팀 풀 실측 59경기 평균 7.20(백분위 76)과 합치면 좁은 풀에서도 리그 기준으로도 상위인 드문 사례이지만, 분데스리가 실측이라 프리미어리그 강도는 미검증이고 아스톤 빌라 실측은 0경기다. ⚠️ 2026-09-11 FC27(09-10) 대조: OVR 77→80(+3)·sho 71→74(+3)·def 69→70(+1)·pac 78→71(-7), 신규 PlayStyle Power Shot 추가(FC26엔 PlayStyle 미표기). 방향은 분데스리가 실측 강점(슛·xG·경합)과 정합하나, 실측 자체는 이번 회차 재수집되지 않아 위 리그 백분위 수치는 2026-08-11 갱신분 그대로다.','HIGH — fit_sim .861은 실측 기반이며 에메리 자유 10번 슬롯의 cam_halfwinger 처방(implementation ⑤)과 정합. FC27 OVR 상승(+3)·슈팅 상승은 이 판정을 강화하는 방향이나 전방 프로필 자체는 여전히 대표팀 실측(n=12) 근거.','HIGH — 하프윙어 10번 프로필이 2×10번 하프스페이스 체제에 직결, 수비 기여도 rest_defense 리스크 완화 (교차 투영 — 실측 아님).','MEDIUM — 왕복·듀얼 볼륨은 부합하나 전방 압박 트리거 수행은 미검증 (교차 투영 — 실측 아님).','squad_entries CAM/DM 2행(fit_sim .861/.713); prescriptions fc26:opt:CAM(starter)·measured 대회별 7행; player_duties LDM; v_player_profile n=59; FC26(OVR77 POT86, 테크니컬); obs#138·#142·#148 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Bundesliga 2025/2026, 42지표) · v_player_profile n=59(4057분) · v_player_season_stats(분데스 26경기 5골 4도움) | stat_eval 2026-09-11 갱신: FC27(roster_date 2026-09-10, OVR80·pac71·sho74·pas73·dri83·def70·phy71, PlayStyle Power Shot, 183cm/75kg) — FC26(2026-07-23, OVR77·pac78·sho71·pas70·dri82·def69·phy71, PlayStyle 없음) 대비 OVR+3·sho+3·pac-7.','n=59 충분하나 CAM 근거는 대표팀 n=12 축 — 클럽 표본과 프로필이 갈리는 이중성 캐비앗 유지. 빌라 실측 0경기. FC27 능치 상승은 실측 재검증 없이 EA 자체 갱신치라 방향 참고용. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','분데스리가 미드필더 중 공을 몰고 나가 반칙을 얻어내고 직접 슛까지 가는, 전진 지향의 프로필이다. 얻어낸 파울 78회가 백분위 100, 드리블 성공 33회가 98, 경합 승 179회가 96, 경합 승률 58.9%가 87로 상대와 붙어 이겨내는 지표가 최상위권이다. 마무리 관여도 슛 51회(95)·상대 박스 터치 80회(94)·xG 3.85(91)·득점 5골(89)로 상위 10% 부근이고 xA 5.13(93)으로 만들어 주는 쪽까지 상위다. 약점은 공 관리와 규율이다 — 볼 뺏김 31회가 백분위 4, 퇴장 2회가 0으로 최하위이고 슛 블록 2회(20)로 자기 골문 앞 방어 행동은 거의 없다. 패스 정확도 84.5%(56)와 성공한 패스(62)는 평범해 배급을 맡기는 유형은 아니다. 중원 뒤가 아니라 박스 앞까지 밀고 올라가는 전진 미드필더 자리에 두는 것이 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(15,1,56,'A− — 합류 확정 피벗. DM fit_sim .763(dm_dlp/Roaming, 39경기 6.77). 2026-09-08 브뤼헤 원정에서 더블 피벗 분업이 3중 확정(전담 기자·전술 분석 그래픽·실측 일치) — 그가 전진 담당, 카마라가 잔류. 90분·평점 7.6·어시스트 1·박스 내 드리블 돌파로 부엔디아 득점 창출. FC27(09-10) OVR78 유지, PAS 72→74(+2)·PHY 74→76(+2)로 상승, DEF 77→76(-1) 근소 하락, PlayStyle 필드에 값이 비어 나옴(FC26 07-16엔 슬라이딩태클·압박검증 2종 기록 — 09-10 수집 갭 가능성, 실제 삭제로 단정 금지).','볼위닝 destroyer + 박스 침투(6과 절반), 프레스 저항 캐리. 브뤼헤전 실측이 「좁은 공간 탈출 후 전진 패스」·「박스 진입 마무리 관여」를 별개 기능으로 승격시켰다(1874: driving into the box 코멘트). 수비액션 x 평균 35.8로 카마라(27.1)보다 8.7 앞선 전진 위치, 태클 5(팀 최다).','태클 3.0(풀 백분위 87)·듀얼승 6.35(89)·인터셉트 1.02(85)의 수비 삼종 최상위. FC27 PAS·PHY 개선(각 +2)은 브뤼헤전 실측(패스 다수·박스 진입)과 정합. 약점: 창의성 최종 산출은 여전히 낮음(2025/26 xG 백분위 13) — 26/27 브뤼헤 1도움은 표본 1경기, 추세 판단 이름.','Fotmob 프리미어리그 25/26 40지표(2833분)에서 볼 회수 축이 리그 최상위 — 태클 107회(상위 4%)·수비적 행동 388(5%)·볼 회수 194회(5%)·경합 승 226회(2%)·인터셉트 36회(12%). 드리블 성공 43회(2%)·성공률 64.2%(11%). 대가는 파울 69회(백분위 0)·볼 뺏김 55회(1%)·경고 10장(4%) — 개입·실패 빈도 모두 리그 최상위. 25/26은 울버햄튼 실측이라 에메리 체제 검증분 아님. | 2026-09-11 갱신: FC27(roster_date 2026-09-10) OVR78(변화 없음)·PAC54·SHO66·PAS74(+2 vs FC26 07-16 72)·DRI75·DEF76(-1 vs 77)·PHY76(+2 vs 74), PlayStyle 이번 로스터엔 미기재(FC26 07-16 슬라이딩태클;압박검증 2종 대비 갭 — 수집 결측 가능성, 실제 제거로 단정하지 않음). 26/27 브뤼헤전 실측(평점 7.6·어시스트 1)과 PAS·PHY 상승 방향 일치.','HIGH — fit_sim .763 실측에 브뤼헤전으로 전진 축 역할이 실측·서사·기록 3중 확정. 만잠비와의 코사인 .960 중복은 CAM/LDM 분담으로 해소(obs#148).','MEDIUM — rest_defense 보험형 볼위너로는 최적이나 3선 배급·기술 규율 요구 대비 창조 최하위 (교차 투영 — 실측 아님).','HIGH — 프레스 저항 캐리+풀 최상위 태클·듀얼이 고강도 압박·즉시 탈취 체제에 직결 (교차 투영 — 실측 아님).','squad_entries DM(fit_sim .763); prescriptions measured(LDM n=39)·fc26:opt:LDM/RDM; player_duties LDM; v_player_profile n=40; FC26(OVR78 POT83); obs#129·#143·#144·#148 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 40지표) · v_player_profile n=40(3268분) · v_player_season_stats(PL 34경기 2830분) | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR78·PAS74·PHY76, PlayStyle 미기재) vs FC26(07-16, OVR78·PAS72·PHY74·PlayStyle 2종) 비교; player_duties 26/27 브뤼헤전(2026-09-08) 3중 확정 추가','n=40 충분(울버햄튼 25/26 실측 — 에메리 체제 아님, 이적 후 재검증 필요). 2026-09-08 브뤼헤전으로 에메리 체제 첫 실측 표본이 생겼으나 n=1이라 경향 확인 수준. PlayStyle 결측은 09-10 FC27 수집 갭 가능성으로 기록, 확정 판단 보류. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','프리미어리그 미드필더 중 태클과 회수의 양이 최상위이고, 그 대가로 반칙과 볼 손실이 최하위인 극단적 파괴형 프로필이다. 태클 107회가 백분위 96(90분당 90), 경합 승 226회가 98, 볼 회수 194회가 95, 수비적 행동 388회가 95로 끊는 행동의 총량이 상위 5% 안이고 드리블 성공 43회(98)와 드리블 성공률 64.2%(89)로 압박을 받으며 공을 몰고 나가는 능력도 좋다. 얻어낸 파울 49회(93)도 강점이다. 문제는 대가가 크다는 점이다 — 파울 69회가 백분위 0, 볼 뺏김 55회가 1, 제쳐당한 횟수 49회가 1, 경고 10장이 4로 최하위이고 90분당으로 내려도 각각 4·0·10·25로 개선되지 않는다. 창조는 기회 창출(90분당 21)로 사실상 없고 패스 정확도 85.6%(46)도 평범하다. 두 명 이상의 중원 구성에서 공을 끊는 몫만 전담시키고 배급과 최종 패스는 옆의 미드필더에게 맡기는 배치가 맞다.');
INSERT INTO player_evaluations VALUES(16,1,57,'B+ — 합류 확정 CB. fit_sim .883(cb_bpd/Aggressive, 29경기 7.1)으로 실측 적합은 주전급이나 FC27(09-10) OVR68로 게임 즉전력은 여전히 백업 — FC26(07-23) 대비 OVR·PAC·SHO·PAS·DRI·DEF 전부 동일, PHY만 68→69(+1)로 소폭 상승. POT 81 성장형 영입 판정 유지. 2026-08-31 player-collect로 체제 서술 대거 정정 — LASK는 백3(퀴바우어 3-4-1-2), ÖFB컵 결승도 CB 고정으로 DM 겸업설은 반증됨.','공중 지배(191cm)·후방 빌드업 개시·세트피스 골위협, CB 고정(DM 겸업 가설은 2026-08-31 독립소스 5건으로 반증). FC27 능치 사실상 정체(PHY+1 외 불변) — 신체 프로필과 게임 스탯 괴리(pas 53·dri 53)는 여전히 스쿼드 내 최대.','공중볼과 스텝아웃 빌드업 겸장, 듀얼승 4.1(풀 백분위 77)·인터셉트 0.86(77). 약점: FC27도 PAS53·DRI53로 낮은 배급·드리블 능치가 그대로 — 에메리 체제 프리시즌(2026-07-29 레알 소시에다드전)에서 롱볼 위주 습관이 지적된 바(에메리 불만, 본인 사과 제스처)와 정합. 단 같은 경기 1v1 저지(오스카르손) 등 수비 기여도 확인됨.','옛 평가의 "낮은 xG 백분위는 CB 정상" 서술은 Fotmob 오스트리아 분데스리가 25/26 41지표(2271분)로 뒤집힌다 — xG 2.47이 리그 동포지션 상위 3%, 슛 23개(5%), 어시스트 3개(백분위 100). 배급 물량도 상위 — 정확한 롱볼 109회(14%)·패스 정확도 85.3%(28%). 단 공중 경합 승률은 61.4%(65%)로 24/25(76.3%, 15경기 소표본)보다 하락, 인터셉트는 백분위 54로 평범 — "191cm 공중 지배"는 소표본에 기댄 규정이라는 재검토 필요. 우리 3팀 풀 실측 29경기 평균 7.10(백분위 71). | 2026-09-11 갱신: FC27(roster_date 2026-09-10) OVR68(변화 없음)·PAC69·SHO38·PAS53·DRI53·DEF69·PHY69(+1 vs FC26 07-23 68), PlayStyle 0종 유지 — 능치·서사 모두 "성장 대기" 단계임을 재확인.','HIGH — fit_sim .883은 콘사(.938)에 이은 CB 실측 적합 상위이나 즉시 XI 아닌 성장 후 승계 트랙(오스트리아 LASK 실측, 에메리 체제 아님). 2026-08-31 확인된 온더볼 습관 충돌(롱볼 선호 vs 에메리 후방 빌드업 요구)이 체제 적응의 핵심 과제로 부상.','HIGH — cb_bpd/Aggressive 전원 요구 체제와 커널이 정확히 동형 (교차 투영 — 실측 아님).','MEDIUM — 공중·요격형은 유용하나 pac 69와 하이라인 1v1 노출 미검증 (교차 투영 — 실측 아님).','squad_entries CB(fit_sim .883); prescriptions measured(RCB n=29)·fc26:opt:LCB/RCB; player_duties RCB; v_player_profile n=29; FC26(OVR68 POT81); obs#143 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Bundesliga(오스트리아) 2025/2026, 41지표) · v_player_profile n=29(2571분) · v_player_season_stats(오스트리아 분데스 26경기 2골 3도움) | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR68·PHY69) vs FC26(07-23, OVR68·PHY68) 비교; player_duties 2026-08-31 체제 정정(백3 확정·DM겸업 반증·온더볼 충돌) 반영','n=29 충분하나 하위 리그(LASK) 실측 — PL 강도 미검증. FC27 갱신도 변화 미미(PHY+1)해 기존 판단을 뒤집지 않음. 2026-08-31 체제 정정으로 서사 신뢰도는 오히려 상승(5개 독립 소스 교차검증). 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','분데스리가 센터백 중 세트피스 공격 기여가 최상위이고, 수비 지표는 상위권이지만 최상위는 아닌 프로필이다. xG 2.47이 백분위 97, 슛 23회가 95, xGOT 2.56이 92, 헤더 슛 11회가 85로 상대 박스 안 위협이 센터백 기준 최상위권이고 어시스트 3개는 백분위 100이다. 배급도 정확한 롱볼 109회(86)·성공한 패스 1071회(83)로 상위권이며 경합 승률 64.7%(85)로 붙었을 때의 승률도 좋다. 수비 개입은 걷어내기 160회(77)·수비적 행동 240회(75)로 준상위이지만, 90분당으로 내리면 인터셉트가 백분위 14, 공중 경합 승이 32로 떨어져 능동적으로 끊는 빈도는 평범하다. 볼을 뺏기는 빈도(18)와 드리블 성공률 40.0%(29)가 낮아 직접 몰고 나가는 유형은 아니다. 제공권 공격 옵션을 겸하는 센터백으로 쓰기 좋고, 뒷공간을 앞서 끊어야 하는 역할은 다른 인원에게 배분하는 편이 맞다.');
INSERT INTO player_evaluations VALUES(17,1,58,'A− — 합류 확정 윙어. W 슬롯 fit_sim .936(w_winger/Versatile, 첼시 25/26 실측 6경기)·WM .771(wm_winger/Attack, 38경기 6.99). FC27(09-10) 신규 수집에서 OVR 78→77(-1)·피지컬 56→53(-3)로 소폭 하락했고 스피드86·PlayStyle 4종(Finesse Shot·Technical·Quick Step·Acrobatic)은 그대로 유지된다 — def37·phy53의 몸싸움 취약성이 게임 능치에서 한층 뚜렷해졌다.','컷인 후 파포스트 감아차기, 1v1 돌파·볼캐리, 카운터 위협 — 좌 편향(좌측 38경기). PlayStyles는 감아차기·아크로바틱·테크니컬·퀵스텝(FC27에서도 동일 4종 유지, phy만 56→53 하락).','pac 86·Mostly Explosive의 순간 가속과 컷인 슈팅, POT 84. 약점: def 37·phy 53(FC27 갱신, 이전 56)으로 더 낮아져 두 줄 4 뱅크 복귀 임무와의 구조적 긴장(obs#125)이 능치상으로도 심화됐다.','Fotmob 프리미어리그 25/26 40지표(1268분)에서 창출은 리그 상위다 — 90분당 기대 도움 0.261(동포지션 상위 9%)·90분당 기회 창출 2.06(상위 13%)·90분당 빅찬스 창출(상위 16%)·90분당 상대 박스 터치 7.95(상위 7%)·어시스트 4개(상위 25%). 패스 관리도 좋다 — 패스 정확도 87.3%(상위 12%). 문제는 마무리다 — xG 3.45(상위 35%)를 쌓고도 득점은 1골(하위 23%)에 그쳤고 유효슛 7개(백분위 42)·xGOT 1.99(백분위 46)로 슛의 질이 기대치를 밑돈다. 몸싸움과 수비 기여는 하위다 — 공중 경합 승률 18.8%(하위 15%)·드리블 성공률 35.9%(하위 28%)·수비적 행동 70(하위 33%)·걷어내기 6회(하위 21%). 우리 3팀 풀 실측 38경기 평균 6.99(백분위 56)과 큰 충돌은 없으나, 이 표본은 25/26 맨유·첼시 혼합이라 에메리 체제 실측은 0경기다. ⚠️ 2026-09-11 FC27(09-10) 대조: OVR 78→77(-1)·phy 56→53(-3), pac86·PlayStyle 4종은 불변. 실측(fotmob) 재수집은 없어 위 리그 백분위 수치는 2026-08-11 갱신분 그대로다.','HIGH — WM .771 실측 + XI 후보(fc26:opt:LM/RM). 단 .936은 첼시 25/26 출처 실측이라 에메리 체제 근거로는 .771이 1차. FC27 phy 하락(-3)은 두 줄 4 복귀 임무 수행 부담을 다소 키우는 방향이나 판정 자체는 변경하지 않는다.','MEDIUM — 첼시 실측 .936이 있으나 그것은 25/26 전임 체제 기록(규칙 7)이고, 알론소 3-4-2-1엔 순수 윙어 슬롯이 없어 10번 포켓 변환이 전제 (교차 투영 — 실측 아님).','HIGH — 1v1 돌파·카운터 위협·pac 86이 수직 전환 체제의 이상형 — 단 압박 가담량은 미검증 (교차 투영 — 실측 아님).','squad_entries W/WM 2행(fit_sim .936/.771); prescriptions measured(LM n=20)·fc26:opt:LM/RM; player_duties LM; v_player_profile n=38; FC26 2026-07-23(OVR78 POT84, PlayStyles 4종); obs#125·#128·#134·#143 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 40지표) · v_player_profile n=38(2131분) · v_player_season_stats(PL 21경기 1골 4도움) | stat_eval 2026-09-11 갱신: FC27(roster_date 2026-09-10, OVR77·pac86·sho77·pas72·dri79·def37·phy53, PlayStyles 동일 4종, 180cm/72kg) — FC26(2026-07-23, OVR78·phy56) 대비 OVR-1·phy-3.','n=38 충분하나 25/26 맨유·첼시 혼합 실측 — 에메리 체제 실측 0. .936은 첼시 25/26 6경기 소표본. FC27 OVR·phy 소폭 하락은 실측 재검증 없는 EA 자체 갱신치. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 1284분 표본이라 90분당 백분위를 기준으로 읽는다 — 그 기준에서는 박스 안까지 들어가 기회를 만드는 쪽에 값이 몰려 있다. 90분당 상대 박스 터치 7.95회가 백분위 93, xA 0.26이 91, 기회 창출 2.06회가 87, 어시스트가 88, 빅찬스 창출이 84로 창조 지표가 상위권이고 패스 정확도 87.3%(88)로 처리도 안정적이다. 롱볼 정확도 100.0%는 백분위 100이지만 시도가 13회뿐이라 근거로 쓰기 어렵다. 약점은 마무리와 몸싸움이다 — 득점 1골이 백분위 25, 90분당 xGOT가 41로 슛 33회에 비해 결과가 나오지 않았고, 공중 경합 승률 18.8%가 15, 공중 경합 승이 14, 드리블 성공률 35.9%가 28이다. 수비 기여도 90분당 수비적 행동 11, 걷어내기 15로 거의 없다. 마지막 패스와 박스 진입을 맡기는 측면 자리에 쓰되, 득점을 책임지는 위치나 압박 부담이 큰 측면에는 세우지 않는 편이 맞다.');
INSERT INTO player_evaluations VALUES(18,1,59,'C+ — 신규 영입 장기 프로젝트. WM fit_sim .833(wm_widemid/Build-Up, 확장 22경기 6.88). FC27(09-10) 신규 수집에서 OVR은 70으로 FC26과 동일하나, 슈팅 61→65(+4)·패스 64→65(+1)로 소폭 상승하고 스피드 79→76(-3)·피지컬 61→60(-1)은 하락했다. Fotmob이 아직 미수집이라 리그 대조는 불가하나, 슈팅 상승은 duties에 기록된 컷인 슛 개발 방향과 일치한다.','왼발 인버티드 — 우측 시작, 컷인 슛 개발 중, 전환·1v1 위협(영상 종합 가설, 그레미우 감독 메네지스 인터뷰로 obs#147 방향 긴장 해소·wm_widemid 확정, 2026-08-16). FC27 능치는 슈팅 61→65 상승으로 컷인 슛 개발 서사와 정합, 스피드 79→76 하락은 재활 후 컨디션 반영 가능성.','듀얼승 6.14(풀 백분위 87), Serie A 실측(듀얼 승 186회 상위 98%·공중 경합 승 43회 상위 98%·태클 47회 상위 96%)의 나이 대비 경합 능력과 POT 83 성장폭. 약점: OVR 70으로 즉전력 아님, FC27에서도 슈팅65·패스65로 여전히 낮은 편이며 컷인 슛은 개발 중 단계.','이 선수만 Fotmob 상세 스탯이 수집되지 않아 리그 동포지션 백분위 대조가 불가능하다 — 근거는 우리 3팀 풀 실측뿐이므로 다른 선수보다 신뢰 폭을 좁게 잡아야 한다. 실측 22경기 1475분에서 평균 평점 6.88(3팀 풀 백분위 46)로 중위이고, 상위 지표는 경합 승 6.14/경기(백분위 89) 하나뿐이다. 나머지 수비 관여는 태클 1.32(백분위 66)·인터셉트 0.55(백분위 72)로 중상위이나, 창출은 기대 도움 0.047(백분위 35)·키패스 0.41(백분위 36)로 하위다. 시즌 성적도 브라질 세리에 A 20경기 1315분에 1골 1도움으로, 윙어로서의 산출이 아직 성숙하지 않았다. 표본이 그레미우와 빌라에 걸쳐 있어 리그 강도·체제가 모두 이질적이라는 점까지 함께 감안해야 한다. ⚠️ 2026-09-11 FC27(09-10) 대조: OVR 70 유지, sho 61→65(+4)·pas 64→65(+1)·pac 79→76(-3)·phy 61→60(-1). Fotmob 상세 스탯은 여전히 미수집이라 이 리그 대조는 이번에도 불가 — 3팀 풀 실측(22경기 1475분, 평점 6.88)만 근거로 유지된다.','MEDIUM — 커널 .833은 있으나 즉전력 미달. FC27 슈팅 상승(+4)은 긍정적 신호이나 실측 재검증이 없어 판정 변경 근거로는 약하다.','LOW — 10번 포켓·윙백 어느 쪽에도 현 프로필이 닿지 않음 — 개발 단계 (교차 투영 — 실측 아님).','MEDIUM — 전환·1v1 위협과 듀얼 경합력은 수직 체제 원자재 (교차 투영 — 실측 아님).','squad_entries WM(fit_sim .833); prescriptions measured(RM n=15)·fc26:opt:LM/RM; player_duties RM(잠정); v_player_profile n=22; FC26(OVR70 POT83, 인벤티브); obs#147 | stat_eval 2026-08-11 갱신: fotmob_detail_stats 미수집(대조 불가) · v_player_profile n=22(1475분) · v_player_season_stats(브라질 세리에 A 20경기 1골 1도움) | stat_eval 2026-09-11 갱신: FC27(roster_date 2026-09-10, OVR70·pac76·sho65·pas65·dri73·def34·phy60, PlayStyle/신장/체중 미기재) — FC26(2026-07-23, OVR70·pac79·sho61·pas64·dri72·def34·phy61) 대비 sho+4·pac-3.','n=22이나 그레미우(브라질)+빌라 혼합 표본 — 리그 강도·체제 모두 이질. Fotmob 상세 스탯 여전히 미수집. FC27 슈팅 상승은 방향성 참고용이며 실측 검증 없음. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(19,1,60,'C+ 유지 — fit_sim 최저(.643, st_false9/Attack, n=25)에 더해 9월 초 서열이 스쿼드 3옵션(잭슨>마조>아브라함)으로 확정됐다. 1874 기자(Tanswell, 2026-09-02) 증언: 5월부터 이미 매각 대상이었고 훈련 강도 미적응이 에메리 판단의 핵심이며, 입스위치 임대 협상까지 갔다가 본인이 거부하고 잔류(2026-08월 말)했다. 헐전은 벤치, 아스날전 후반 교체 12터치가 최근 실전 전부다. FC27 OVR77은 유지되나 PAC 72(FC26 76 대비 -4)·DRI 72(74 대비 -2)·PHY 72(74 대비 -2)로 하락, PlayStyles는 Enforcer 단일로 좁혀졌다.','타깃형·직선형 9번 — 공중볼과 다이렉트 플레이 국면용. FC27 PlayStyles는 Enforcer만 기록(FC26 최신 행은 PlayStyles 결측이라 직접 비교 불가). 위치 풋프린트(실측)는 하강형에 가깝지만 온볼 이벤트는 박스형인 이중 프로필은 변화 없음.','xG 0.508/경기(풀 백분위 87)의 박스 마무리와 플랜B 공중 옵션. 약점: 연계·드롭 움직임이 에메리 원톱 3중 임무(점유/링크/채널)와 부정합 — fit_sim .643이 이를 수치로 확인, def 36. 9월 기준 추가: 베식타시 임대 복귀 후 반 시즌 19경기 3골(455분)의 저조 산출이 서열 하락의 실질 근거로 붙었다.','이 선수는 총량 백분위와 90분당 백분위가 정반대로 나오는 극단적 사례이므로 90분당으로 읽어야 한다 — Fotmob 프리미어리그 25/26 34지표의 표본이 279분뿐이라 총량은 슛 9개(하위 4%)·터치 75회(하위 6%)·경합 승 10회(하위 8%)처럼 전부 바닥이지만, 90분당으로 환산하면 xG 0.659(리그 공격수 상위 6%)·PK 제외 xG(상위 6%)·xGOT 0.648(상위 10%)·상대 박스 터치 7.10(상위 10%)·기회 창출 1.29(상위 12%)로 뒤집힌다. 우리 3팀 풀 실측 25경기에서도 xG 0.508/경기(백분위 89)로 왓킨스 다음가는 골 기대치를 보인다. 실제 약점은 볼 관여의 질이다 — 패스 정확도 56.8%(리그 하위 4%)·90분당 성공한 패스 8.07(하위 24%)로, 등지고 연결하는 역할은 수치가 받쳐주지 않는다. 공중 경합 승률 45.5%(상위 20%)는 나쁘지 않으나 절대 횟수가 5회뿐이라 타깃형 근거로는 약하다. 시즌 전체로는 쉬페르리그 16경기 7골·컨퍼런스리그 4경기 4골로 하위 강도 대회에서 산출이 몰려 있다. 9월 신규: FC27 신체 능력치 소폭 하락(PAC -4·DRI -2·PHY -2, OVR77 불변)이 ''연계·드롭 움직임 부적합'' 기존 판정과 방향이 같다 — 속도·드리블 저하는 압박·전환 기여를 더 어렵게 한다.','LOW 유지·강화 — obs#19 판정 그대로 기본 시스템 부적합. 실측 fit .643 최저에 더해 훈련 강도 미적응(에메리 판단)·서열 3위·1월 방출 가능성(기자 전망, 확정 아님)까지 겹쳤다. 단 왓킨스·잭슨 로테이션 소진 시 플랜B 자리는 남아있다(09-08 아스날전 후반 교체 출전).','LOW — 알론소 9번은 내려오는 false9(주앙 페드루형) — 아브라함의 st_false9 적합 .643이 낮고 타깃형 성향과 어긋남 (교차 투영 — 실측 아님).','MEDIUM — 직선성·전방 압박(압박검증)은 수직 전환 체제와 부분 부합 (교차 투영 — 실측 아님).','squad_entries ST(fit_sim .643); prescriptions measured(ST n=25)·fc26:opt:ST; v_player_profile n=25; FC26(OVR77, 압박검증·인포서); obs#19·#134 (player_duties 행 없음) | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 34지표 — 표본 279분) · v_player_profile n=25(1878분) · v_player_season_stats(쉬페르리그 16경기 7골 포함) | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR77·PAC72·SHO76·PAS65·DRI72·DEF36·PHY72·PlayStyles Enforcer·194cm/82kg) vs FC26 직전(OVR77·PAC76·SHO76·PAS65·DRI74·DEF36·PHY74, PlayStyles 결측) · player_duties 09-02/09-07 서열·매각시도 서사(1874 Tanswell) · 에메리 08-31 기자회견','n=25이나 25/26 타 클럽(베식타시 임대 등) 혼합 표본 — 에메리 체제 실측 아님. player_duties 미작성이었으나 9월 신규 서사(구단 서열·이적 서사)로 보완됨. 알론소·이라올라 핏은 교차 투영(실측 아님). 서열·이적 시장 서사는 1차 기자 증언(Tanswell, The Athletic)으로 신뢰도 양호. FC27 능력치 하락은 방향만 확인, 원인(부상 회복기 컨디션 vs 실측 반영) 불명.','2026-09-11','프리미어리그 공격수 중 출전이 279분에 불과해 총량 백분위(대부분 한 자릿수)는 무의미하고, 90분당 백분위로만 읽어야 한다. 그 기준에서는 좁은 지역에서 슛 기회를 잡는 쪽의 값이 높다 — 90분당 xG 0.66이 백분위 94, xGOT 0.65가 90, 득점 0.65골이 88, 상대 박스 터치 7.10회가 90이고 기회 창출(88)·xA(90)까지 준상위다. 경합 승률 47.6%(88)와 공중 경합 승률 45.5%(80)로 붙었을 때의 승률도 나쁘지 않다. 약점은 공을 다루는 정확도다 — 패스 정확도 56.8%가 백분위 4로 최하위이고 90분당 터치가 12, 성공한 패스가 24, 드리블 성공이 20으로 연계 참여가 거의 없다. 90분당 출전 중 실점 2.58골(4)도 좋지 않다. 3경기 남짓의 표본이므로 확정적으로 읽을 수 없지만, 연계를 기대하지 않고 박스 안에서만 쓰는 마무리 전문 교체 카드의 모양이다.');
INSERT INTO player_evaluations VALUES(20,2,13,'A — 알론소가 1티어 구단 공식 발언으로 직접 규정한 유일한 선수(obs#59), £117m 영국 기록 영입. 2026-09-11 갱신: 공식전 표본이 0경기(08-11 시점)에서 5경기로 늘었고 전부 고평점이다 — PL 3경기(전 선발, 259분) 평균 7.95(2골1도움: 풀럼 8.65·브라이턴 8.0·아스날 7.2), EFL컵 2경기 평균 6.75(어시스트3, 리즈전 후반 45분 3도움 관여). ''지시 vs 실측'' 충돌(빌라 실측은 좌측 인사이드가 CAM보다 높음)은 이제 알론소 체제 실측으로도 좌측 하프스페이스·좌윙 로테이션이 주 기용임이 확인돼 실측 방향과 알론소 지시가 수렴했다(obs#557·#559·#560).','FC27(roster_date 2026-09-10) OVR84(변화 없음): PAC76(-1 vs FC26 07-23 77)·SHO82(+1 vs81)·PAS82(+1 vs81)·DRI84(-1 vs85)·DEF67(0)·PHY78(0), 188cm/80kg(FC26 187cm, 체중 신규). PlayStyles 갱신 — FC26의 ''단일 클럽 선수''가 빠지고(이적으로 자동 소멸) ''Relentless(끈기와인내)''가 신규 추가, ''낮은 드리븐 슛·예리한패스·테크니컬·인포서''는 유지. 로밍형 중앙 크리에이터였던 프로필이 이제 좌측 하프스페이스에서 롱볼을 몸으로 버텨내는 ''물리형 출구''(Between the Posts, 2026-09-09)로 실측 재정의됐고, Relentless 신규 PlayStyle이 이 체력·몸싸움 축과 정합한다.','특장점: 좌측 인사이드~중앙 10번 겸용의 유연성, 알론소 체제 공식전 5경기 전부 6.3 이상(최저 루턴 EFL컵 6.3, 최고 풀럼 8.65)으로 천장뿐 아니라 바닥도 준수. 하토와 좌측 하프스페이스↔윙 수직 로테이션을 형성해 롱볼을 받아 버티는 물리적 출구 역할을 확보했고(주앙 페드루와 같은 기능 묶음), 아스날 원정 선제골은 세트피스 세컨볼 박스 밖 발리로 마무리(obs#557). 약점: 우측 기용은 여전히 절대 금지 수준(빌라 실측 RM 8선발 평균 6.33, LOW adherence 유지). 아스날전 무실책이 이어진 3v2 뚫림(하토와 함께 상대 우풀백 화이트를 추적하다 공간을 내줌, obs#557 독립 소스 2건)과 경합 0/7(Foot Mercato 단일 매체, 단일경기) — 물리 대결 성향을 올릴 근거로는 쓰지 말 것.','2026-08-11 갱신: fotmob_detail_stats(PL 25/26, 42지표) · v_player_profile n=56(빌라 소속) — 슛·유효슛·박스터치 상위권, 볼 뺏김·경합 승률·패스 정확도 하위권(''많이 관여하고 많이 잃는'' 프로필). 2026-09-11 갱신: match_player_reports·v_player_season_stats로 첼시 공식전 실측 5경기 추가 — PL 3경기(259분) 평균7.95·2골1도움 (풀럼8.65·브라이턴8.0 xA1.01 어시스트1·아스날7.2 골1 xG.076), EFL컵 2경기(113분) 평균6.75·어시스트3(루턴6.3·리즈 후반45분7.2 3도움 관여). season 합계 2026-27 PL 3G 259분 2골1도움 평균7.95, EFL컵 2G 113분 평균6.75. 이 실측은 전부 알론소 체제 공식전이라 팀축 캐비앗이 처음 해소됐다.','HIGH — 유일하게 실측 근거가 있는 감독 핏: 에메리 25/26 체제에서 CAM 평균 7.10·LW 천장 실측을 직접 남겼다. 에메리의 ''자유 로밍 10번''(manager_profiles r1 traits) 원형 인원.','HIGH — 2026-09-11 갱신: 좌측 축(LM wm_wideplm/Attack, 실측 fit_sim 0.8468, n=3, 2026-09-07 재집계) 처방이 알론소 체제 공식전 5경기 전부 고평점(6.3~8.65)으로 재확인됐다. 알론소가 요구한 ''포켓 연결·좌측 출발 유연 2선 공격수''(obs#59) 지시와 실측 기용(좌측 하프스페이스~윙 로테이션) 방향이 일치한다. 단 경합 0/7(단일경기) 등 물리 대결 관련 서사는 실측이 지지하지 않는다.','MEDIUM — (교차 투영 — 실측 아님) 이라올라의 하프윙어 10번 슬롯(r3: 비르츠 cam_halfwinger)에 프로필상 이식 가능하나, 고강도 압박·수직 전환 체계에서의 비소유 기여는 실측 근거가 없다.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·player_duties(r1 3행)·player_game_stats(FC26 2026-06-30)·obs#59·#102·#109 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 42지표) · v_player_profile n=56(빌라 소속) | 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR84·PAC76·SHO82·PAS82·DRI84·PlayStyle Relentless 신규) vs FC26(07-23) 비교; match_player_reports 5경기(풀럼·브라이턴·루턴·아스날·리즈); v_player_season_stats(2026-27 PL 3G·EFL컵2G); player_duties 2026-27 CAM/left pocket 항목(2026-09-08 D+2·2026-09-09 D+3 추가, obs#557·#559·#560)','HIGH(빌라 실측·FC26/FC27 스탯) / HIGH로 상향(알론소 핏 — 공식전 5경기 실측 확보, 이전 MEDIUM에서 상향). 경합 관련 단일 매체(Foot Mercato) 수치는 표본 1경기라 별도 저신뢰로 취급.','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 박스 안까지 직접 들어가 슛으로 마무리하고, 그 대가로 공을 자주 잃는 유형이다. 슛 84회(백분위 97)·유효슛 32회(96)·상대 박스 터치 181회(95)·득점 10골(93)으로 마무리 지역의 양이 최상위권이고, 빅찬스 창출 13회(94)와 상대 진영 볼 탈취 26회(95)로 만들어 주는 쪽과 앞에서 끊는 쪽도 상위다. 얻어낸 파울 49회(94)와 드리블 성공 42회(90)로 공을 몰고 나가 반칙을 유도하는 능력도 좋다. 약점은 공 관리와 경합이다 — 볼 뺏김 80회가 백분위 0, 파울 46회가 3, 경고 7장이 4로 최하위이고 경합 승률 35.7%(11)·패스 정확도 74.6%(17)·크로스 정확도 6.0%(13)도 하위권이다. 3290분을 뛴 표본이라 총량 백분위는 신뢰할 만하지만 90분당으로 내리면 슛(73)·박스 터치(74)로 낮아지므로 많이 뛰어 쌓은 양도 섞여 있다. 실수를 감수하고 박스 진입을 반복시키는 2선 공격 자리에 두는 것이 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(21,2,31,'B — GK 실측(마레스카 체제) 6경기 평균 6.80, gk_goalkeeper/Defend 적합 0.961로 스쿼드 전체 최고 적합치였으나, 2026-09-11 갱신: 알론소 체제 공식 데뷔전(2026-08-25 풀럼 PL)에서 평점 5.67·goals prevented -0.78로 저조했고 Read Chelsea 4/10·복수 매체가 ''GK 교체 필요'' 논거로 인용(3중 정합: 실측·매체 평점·전술 서술). FC27(09-10)에서도 OVR 81→80(-1), 리플렉스류 항목 59→53(-6)로 스쿼드 내 최대 낙폭을 보여 하락 방향이 겹친다.','자기진영 질량 1.00, 중심(51.8,10.8)의 정통 라인 키퍼. FC27(roster_date 2026-09-10) attrs: 다이빙81·핸들링78·킥78·반응력78·반사신경81·포지셔닝79·가속53·질주속도54 (197cm/90kg, 체중 신규). 6대 스탯 OVR80(FC26 81에서 -1)·PAC81(-1)·SHO78(-1)·PAS78(0)·DRI81(-1)·DEF53(-6, 전항목 중 최대 낙폭)·PHY79(-1)로 전항목 하락 또는 유지 — 상승 항목이 하나도 없다. PlayStyle 신규: Footwork·Cross Claimer(FC26엔 PlayStyle 없음).','특장점: GK 커널 적합 0.961(마레스카 체제 그리드)로 처방 확실성은 여전히 높다. 알론소 체제 프리시즌(밀란·소시에다드) 2경기 151분 평균 6.85로 준수했다. 약점: 알론소 체제 공식 데뷔전(2026-08-25 풀럼)은 평점 5.67·goals prevented -0.78로 부진, 실책성 실점 개입 서술 다수(3중 정합). 스위퍼 적합 0.773으로 낮아 알론소식 빌드업 +1 참여 요구 시 검증 안 된 영역이라는 기존 우려가 실전 데뷔 부진으로 더 무겁게 작용한다. FC27 DEF류 -6도 같은 방향.','Fotmob 25/26 PL 33.8경기(GK 20지표, 마레스카·로즈니어 체제) — 하이볼 처리 92백분위·스위퍼 행동 82백분위·정확한 롱볼 87백분위로 박스 밖·공중 관리형 성향, goals prevented +1.70(82백분위). 2026-09-11 갱신: v_player_season_stats·match_player_reports로 알론소 체제 실측 추가 — 프리시즌 3경기(밀란90''6.9·소시에다드61''6.8·유벤투스46''6.0)에 이어 2026-08-25 풀럼 PL 공식 데뷔 평점 5.67(v_player_season_stats 2026-27 PL 1G), goals prevented -0.78. player_game_stats FC27(09-10)은 OVR80·6대 스탯 전항목 하락·유지(DEF류 -6 최대)로 게임 모델도 하락 방향이다. 알론소 체제 공식전 표본은 여전히 1경기뿐이라 서열 판단은 보류.','MEDIUM — (교차 투영 — 실측 아님) 에메리도 GK Defend 처방(r1: ''스위퍼 아님, 참여는 패스 옵션 수준'')이라 요구 프로필이 유사 — 이식 마찰은 작을 것.','MEDIUM→MEDIUM(하향 압력) — 처방은 gk_goalkeeper/Defend 유지(0.961, 마레스카 그리드). 2026-09-11 갱신: 알론소 체제 공식 데뷔전 부진(평점5.67, goals prevented -0.78, 3중 매체·전술 서술 정합)으로 ''새 GK 필요'' 논거가 재확인됐고, FC27 6대 스탯 전항목 하락(DEF류 -6)도 같은 방향이다. 스위퍼 적합 0.773이 낮아 알론소식 빌드업 +1 참여 요구와의 마찰 우려는 유지된다. 표본은 공식전 1경기뿐이라 확정적 결론은 아니다.','LOW~MEDIUM — (교차 투영 — 실측 아님) 하이라인·고압박 체계는 스위퍼형 GK를 선호하는데 산체스의 스위퍼 적합은 0.773으로 낮다.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#44 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 20지표) · v_player_profile n=1 · prescriptions#measured(GK n=6, 6.80) | 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR80·attrs 다이빙81/핸들링78/킥78/반응력78/반사신경81/포지셔닝79, PlayStyle Footwork·Cross Claimer 신규) vs FC26(07-23, OVR81) 비교; v_player_season_stats(2026-27 PL 1G 5.67, Club Friendly 3G); match_player_reports(풀럼 2026-08-25, goals prevented -0.78, Read Chelsea 4/10 인용)','HIGH(그리드 6경기, 마레스카 체제) / LOW→MEDIUM(알론소 체제 — 이벤트 표본 공식전 1경기뿐이나 매체·전술서술·FC27 하락이 동일 방향으로 정합).','2026-09-11','프리미어리그 골키퍼 중 공중볼과 후방 배급에서 값을 내는 유형이고, 골키퍼는 지표가 20개뿐이라 근거가 얇다는 점을 감안해야 한다. 하이볼 처리 42회가 백분위 92, 스위퍼 행동 23회가 82로 골문 밖 처리가 상위권이고, 성공한 패스 871회(87)·정확한 롱볼 199회(87)에 기회 창출 5회와 어시스트 1개(둘 다 100)로 배급에서 실제 산출까지 냈다. 슛 저지는 선방으로 막은 실점 1.70점(82)으로 기대보다 더 막은 편이나 선방률 67.6%는 백분위 62로 평범하다. 약점은 총 실점 47골(18)과 규율이다 — 퇴장 1회(0), 경고 3장(10), PK 선방률 0.0%(21)이고 롱볼 정확도 32.1%(46)도 평범하다. 공중볼 처리와 긴 배급을 활용하는 구조에 맞고, 슛 저지 자체를 믿고 수비 노출을 늘리는 설계에는 맞지 않는다.');
INSERT INTO player_evaluations VALUES(22,2,32,'B — RB 실측(마레스카 체제) 6경기 평균 6.40, fb_att_wb/Support 0.862. 2026-09-11 갱신: 알론소 체제 공식전 6경기에서 RB(1)·RM(1)·RCM(2)·교체(2) 등 포지션이 크게 흔들렸다 — 특히 브라이턴전(RCM 90분)·아스날전(교체 RCM 30분)에서 중앙 미드필더로 기용돼 기존 ''우측 풀백 전용'' 평가와 배치되는 실측이 새로 생겼다(단, 라비아 결장 등 땜빵 성격이 강해 전술적 지지로 단정하기는 이르다). FC27(09-10)에서 SHO가 46→55(+9)로 스쿼드 내 최대 상승폭을 보였다.','균형형 전진 풀백, 중심(81.5,46.3, 마레스카 체제 그리드). FC27(roster_date 2026-09-10) OVR79(변화 없음): PAC82(-2 vs FC26 07-23 84)·SHO55(+9 vs46, 전항목 중 최대 상승)·PAS75(0)·DRI79(+1 vs78)·DEF75(+2 vs73)·PHY73(-1 vs74), 178cm/74kg(체중 신규). PlayStyle 신규: Jockey·Slide Tackle(FC26엔 PlayStyle 없음) — 둘 다 대인 수비 계열로 DEF+2와 방향이 같다. SHO+9는 실측 아직 대응 근거 없음(2026-27 공식전 득점 0).','특장점: 우측 윙백 슬롯의 유일 적임(마레스카 체제 그리드 기준)이자 공수 질량 배분 균형. 2026-09-11 갱신: 알론소 체제에서 실측 다변화가 확인됐다 — 루턴 EFL컵(RB, 67분 7.6, 웰벡 골 어시스트1·키패스2)·풀럼 PL(RM, 76분 6.69)·브라이턴 PL(RCM, 90분 6.4, tool_x 72.6으로 중앙에서도 극단적 우측 편향)·아스날 PL(교체 RCM, 30분 6.9)·리즈 EFL컵(RCM 선발, 45분 6.3). 약점: 본업(RB) 외 기용 시 산출이 들쭉날쭉(RCM 평균 약 6.5권)하고, 중앙 기용은 라비아 결장 등 스쿼드 사정에 따른 임시 배치일 가능성이 커 squad_entries·prescriptions에는 아직 CM 슬롯 행이 없다 — 전술적 정착으로 보기엔 이르다.','player_matches 0행이던 공백을 Fotmob이 메운다 — 25/26 PL 25.2경기, 42지표(마레스카 체제): 배급(패스 성공 87백분위·정확도 82·롱볼 정확도 80)과 회수(볼 회수 82·상대 진영 볼 탈취 87)가 강점, 걷어내기·제쳐당함·공중 경합 승률은 하위. 2026-09-11 갱신: match_player_reports·v_player_season_stats로 알론소 체제 실측 6경기 추가 — 슬롯이 RB/RM/RCM으로 분산돼 단일 포지션 평균을 내기 어렵다(개별: 루턴 RB 7.6, 풀럼 RM 6.69, 브라이턴 RCM 6.4, 아스날 RCM 6.9, 리즈 RCM 6.3). 2026-27 시즌 누계 (v_player_season_stats): PL 3G 196분 평균6.66, EFL컵 2G 112분 평균6.95. player_game_stats FC27은 SHO+9·DEF+2로 상승, PAC-2·PHY-1로 하락 — 혼재된 방향이라 단일 결론을 내리기 어렵다.','MEDIUM — (교차 투영 — 실측 아님) 에메리는 풀백을 한 명씩만 전진(C2). 균형형 프로필이라 전진측·잔류측 어느 쪽도 소화 가능할 것으로 보이나 실측 없음.','MEDIUM~HIGH 유지 — 구조상 유일한 우측 폭 공급자(RB fb_att_wb/Support 0.862, 마레스카 그리드) 평가는 그대로다. 2026-09-11 갱신: 알론소 체제에서 RCM 기용이 반복됐다(2경기 선발 포함)는 사실은 스쿼드 뎁스 활용 가능성을 시사하나, 라비아 결장 등 긴급 대체 성격이 강해 이를 근거로 ''알론소가 그를 미드필더로 본다''고 단정하지는 않는다. 원형(프림퐁형 폭 공급) 산출력은 여전히 미검증.','MEDIUM — (교차 투영 — 실측 아님) 이라올라 우측은 인버티드(프림퐁 fb_inverted 성향 실측)가 기준선 — 귀스토의 인버티드 실측 근거는 없다.','squad_entries(r2)·prescriptions(measured/projected)·obs#46 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 42지표) · v_player_profile 0행 · prescriptions#measured(RB n=6, 6.40) | 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR79·SHO55(+9)·DEF75(+2)·PAC82(-2)·PlayStyle Jockey·Slide Tackle 신규) vs FC26(07-23, OVR79·SHO46) 비교; match_player_reports 6경기(루턴 RB·풀럼 RM·브라이턴 RCM·아스날 RCM·리즈 RCM·소시에다드 교체); v_player_season_stats(2026-27 PL 3G·EFL컵2G)','MEDIUM(그리드 6경기, 마레스카 체제) / 알론소 체제 실측은 6경기로 늘었으나 슬롯이 4종(RB/RM/RCM×2)으로 분산돼 포지션별 표본이 각 1~2경기뿐 — 서열 판단에는 여전히 불충분.','2026-09-11','프리미어리그 풀백 중 공을 앞으로 옮기고 전방에서 끊는 쪽에 강점이 몰린, 소유 지향 측면 수비의 프로필이다. xA 2.99가 백분위 87, 기회 창출 27회가 77, 성공한 패스 1097회가 87, 패스 정확도 86.8%가 82, 롱볼 정확도 49.4%가 80으로 배급 지표가 고르게 상위권이다. 상대 진영 볼 탈취 10회(87)·볼 회수 122회(82)·인터셉트 31회(79)로 높은 위치에서의 회수도 좋고 득점 2골(81)까지 냈다. 약점은 골문 앞 수비와 공중볼이다 — 걷어내기는 90분당 백분위 2, 공중 경합 승은 14, 공중 경합 승률 45.5%는 32이고 제쳐당함(19)도 하위권이다. 퇴장 1회(0)와 내준 PK 1회(4)로 결정적 실수도 있었다. 라인을 올려 압박하고 공을 돌리는 구조에서 전진 풀백으로 쓰기 좋고, 크로스가 많이 오는 박스 안 수비 부담은 다른 선수에게 넘기는 편이 맞다.');
INSERT INTO player_evaluations VALUES(23,2,33,'B+ — RCB cb_bpd/Aggressive 0.943(마레스카 체제 그리드)로 백3 우측 확정 인원이었던 평가에 더해, 2026-09-11 갱신: 알론소 체제 공식전에서 CCB(밀란)·RCB(소시에다드·유벤투스·브라이턴)·LCB(아스날, 90분 7.2)·CB(리즈, 교체)까지 전 슬롯을 소화한 실측이 새로 쌓였다. 특히 아스날 원정 LCB 기용(수비 부하가 집중된 축, 패스 48/92%)은 기존 ''좌측 이동 불가(LCB 0.239~0.424)'' 평가와 배치되는 직접 반증 사례라 이 결론은 재검토가 필요하다(불변규칙 3: 실측 우선).','순수 수비형 CB, 중심(66.5,31.8, 마레스카 체제 그리드). FC27(roster_date 2026-09-10) OVR79(변화 없음): PAC77(0)·SHO41(0)·PAS62(0)·DRI71(0)·DEF80(0)·PHY77(-1 vs FC26 07-23 78)로 PHY만 -1, 나머지 5항목은 변화 없음. PlayStyle 신규: Jockey·Intercept·Aerial Fortress(FC26엔 PlayStyle 없음) — Intercept·Aerial Fortress는 fotmob 실측(인터셉트 90분당 백분위97, 공중 경합 승률 82)과 정확히 겹치는 방향이다.','특장점: 수비 지표가 풀 최상위(fotmob PL 25/26 41지표, 2026-08-14 수집분: 인터셉트 2.086/90 백분위97·수비 행동 10.794/90 백분위84·패스 정확도 92.1% 백분위89·롱볼 정확도 50.0% 백분위82·공중 경합 승률 67.0% 백분위82) — 규모 있는 시즌 표본(41지표, 90분 환산 기준)이라 신뢰도가 높다. 신규 물리 지표(2026-08-21 수집): 라인 브레이킹 패스 150회(백분위63)로 전개 참여도 상위. 약점: 태클 90분당 백분위20, 레드카드 2회(백분위1)로 적극성 대비 규율 리스크가 뚜렷. 2026-09-11 갱신: 좌측 이동 관련 — 아스날 원정에서 실제로 LCB 90분을 소화하고 7.2를 받았다(패스48/92%, 터치74) — 좌측 배치가 불가능하지 않음을 실측이 보여준다. 브라이턴전은 RCB 68분 6.4(클리어7, 패스13/13 100%, 55분 경고 후 68분 교체)로 본업에서도 안정적.','2026-09-11 정정: 기존 평가(08-11)는 ''fotmob_detail_stats 0행''이라 적었으나 재확인 결과 41지표(2026-08-14 수집, PL 25/26)가 이미 존재한다 — 인터셉트·수비행동·패스정확도·롱볼정확도·공중경합승률 상위권(위 strengths 인용)과 태클·레드카드 하위권. 추가로 2026-08-21 수집분(물리 지표 6종)에서 라인 브레이킹 패스 150회(백분위63)·총 이동거리 90분당 3943m(백분위33)·최고속도32.2km/h(백분위32)로 평범한 활동량·속도 프로필이 확인된다. 이 fotmob 데이터는 모두 25/26 마레스카·로즈니어 체제 것이다. 알론소 체제 실측은 match_player_reports로 6경기 확보 — 밀란(CCB 89'' 7.9)·소시에다드(RCB 90'' 7.4)·유벤투스(RCB 66'' 6.8)·브라이턴(RCB 68'' 6.4)·아스날(LCB 90'' 7.2)·리즈(CB 교체14'' 6.7), 알론소 체제 공식전만 보면 4경기 평균 약 6.83. player_matches는 여전히 1경기(89분 7.90)뿐이라 fit_sim 재산출은 하지 않았다.','MEDIUM~HIGH — (교차 투영 — 실측 아님) 에메리 백4의 볼플레잉 CB 요구(r1 buildup)와 cb_bpd 프로필이 일치하나 백4 RCB 실측은 없다.','HIGH 유지, 단 좌측 전용성 캐비앗 추가 — 백3 우측의 확정 인선(RCB cb_bpd/Aggressive 0.943)이라는 기존 결론은 유지하되, 2026-09-11 갱신: 아스날 원정에서 LCB 90분(7.2)을 실제로 소화해 좌측 배치가 불가능하지 않음이 실측으로 확인됐다 — 커널 fit_sim(LCB 0.239~0.424)이 낮게 산출한 것과 실전 기용·성과가 어긋나는 사례로, 백3 좌우 로테이션 유연성을 다시 열어둘 근거가 됐다(squad_entries의 pos_only=RCB 태그는 이 실측 반영 전 값이므로 재검토 필요 — 이번 작업 범위 밖).','MEDIUM~HIGH — (교차 투영 — 실측 아님) 하이라인 커버형 CB 요구 — 순수 수비형 프로필은 맞으나 압박 체계 실측 없음.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#58·#102 | stat_eval 2026-08-11 갱신: fotmob_detail_stats 0행(오기) · v_player_profile n=1 · prescriptions#measured(RCB n=6, 6.47) | 2026-09-11 정정 및 갱신: fotmob_detail_stats 41지표(pulled 2026-08-14, PL 2025/2026) + 물리지표 6종(pulled 2026-08-21) 재확인·인용; player_game_stats FC27(roster_date 2026-09-10, OVR79·PHY77(-1)·PlayStyle Jockey/Intercept/Aerial Fortress 신규) vs FC26(07-23) 비교; match_player_reports 6경기(밀란CCB·소시에다드RCB·유벤투스RCB·브라이턴RCB·아스날LCB·리즈CB)','HIGH(그리드 6경기·슬롯 전수 산출, 마레스카 체제) / MEDIUM(알론소 체제 — 공식전 실측 4경기로 늘었으나 여전히 소표본). 좌측 기용 반증(아스날전)은 단일 경기라 추세 확정은 아니며, 후속 관찰 필요.','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(24,2,34,unistr('B — CCB 슬롯 신설의 근거 인선(obs#102 ②: CCB 0.873 > RCB 0.744 > LCB 0.665, 중심 x 52.7로 정확히 중앙). 중앙 CB를 좌우로 흡수하면 −0.118 손실이라 백3 중앙 배치가 수치로 성립한다. 단 45분+ 표본 3경기로 표본 부족이고, 그리드는 RCB 표기 경기의 것을 CCB에 쓴 것(원 캐비앗). 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.\u000a\u000a[2026-09-11 갱신] 2026-08-09 코모(세리에A)로 완전이적 확정(€30m 고정+€6m 옵션, 5년 계약, 셀온 조항 포함 — Goal.com·ESPN·Chelsea FC 공식 3중 확인) — 26/27 첼시 스쿼드에서 이탈했다. FC27 로스터(2026-08-31)부터 club=''Como''로 반영되고, 최신 2026-09-10 로스터엔 그의 행 자체가 없다(첼시 소속이 아니라 수집 대상에서 제외). 이 행이 정의한 CCB 슬롯 근거(cb_bpd/Aggressive 0.873)는 25/26 첼시 소속 표본에 묶인 이력값으로만 보존하고, 26/27 인선 판단(라크루아 등 후임)에는 쓰지 않는다(player_duties#61 확정).'),unistr('FC26 80/82(CB 최적, 190cm): PAC66 SHO53 PAS69 DRI70 DEF81 PHY78. PlayStyles: 프리시전 헤딩·슬라이딩태클(FC26 실조회값). CB/RB 겸용 등록.\u000a\u000a[2026-09-11] FC27 최신 컬렉션(2026-08-31, club=Como)에서도 OVR80 유지 — PAC65(-1 vs FC26 66)·SHO53·PAS69·DRI69(-1 vs 70)·DEF81·PHY78로 FC26 대비 변동은 미미하다. 2026-09-10 로스터에는 그의 행이 없다(첼시 소속이 아니므로 수집 제외).'),unistr('특장점: 백3 세 슬롯 중 유일하게 중앙 성향(세 CB 전수 산출에서 셋 다 자기 자리 최고 — 그가 빠지면 CCB 슬롯 자체가 흔들린다). 공중·태클형 PlayStyles가 ''강력한 CB'' 축과 정합. 약점: 표본 3경기(표본 부족) — 백3 처방 중 근거가 가장 얇은 축의 하나. PAC 66으로 하이라인 뒷공간 커버는 게임 내 제약.\u000a\u000a[2026-09-11] v_player_season_stats 25/26 시즌 첼시 소속 전 대회 최종 집계: PL 35경기(2782분) 평균 6.94(3골)·UCL 10경기(567분) 평균 6.59·FIFA 클럽월드컵 3경기 7.13·EFL컵 4경기 6.65·FA컵 4경기 7.00 — 이적 전 마지막 풀시즌이 ''주전급 로테이션 CB''였음을 재확인한다. 26/27 이후 기록은 코모 소속이라 이 평가 대상이 아니다.'),'player_matches 0행이던 공백을 Fotmob 25/26 PL 30.9경기(90분 환산, 41지표)가 메운다. 빌드업 지표가 압도적으로 앞선다 — 패스 성공 2124회(96백분위)·정확도 93.0%(94백분위)·터치 2686회(92백분위)·볼 회수 119회(92백분위)로 리그 동포지션 상위 10% 안쪽. 수비 대인은 걷어내기 178회(77백분위)·인터셉트 35회(84백분위)는 좋지만 공중 경합 승률 55.6%(33백분위)·경합 승률 58.5%(43백분위)가 중하위라, 총량은 많고 성공률은 평범한 유형이다. 우리 실측은 그리드 3경기(표본 부족, 평균 6.47)뿐이고 3팀 풀 백분위는 산출 불가였다. 이 시즌 기록은 첼시 소속·마레스카 로즈니어 체제 것이며(참고: 이후 코모 이적 기재), 알론소 체제 스탯이 아니다. | 2026-09-11 갱신: player_duties id=61(2026-08-09 코모 완전이적 확정) · player_game_stats FC27(2026-08-31, club=Como, OVR80 변동 없음) · v_player_season_stats(25/26 전 대회 최종, 첼시 소속 마지막 시즌)','MEDIUM — (교차 투영 — 실측 아님) 백4 체계에서는 CCB 이점이 사라지고 RCB 0.744로 포파나(0.943)에 밀린다.','N/A(이적) — 2026-08-09 코모 완전이적으로 26/27 알론소 스쿼드 평가 대상에서 제외됐다. CCB 처방(cb_bpd/Aggressive 0.873)은 25/26 실측 기준선으로만 보존하며, 후속 인선(예: 라크루아)의 실측은 아직 없다(player_duties#61).','LOW~MEDIUM — (교차 투영 — 실측 아님) FC26 PAC 66은 하이라인·즉시 압박 체계의 뒷공간 노출 지점.','squad_entries(r2)·prescriptions(measured/projected)·player_game_stats(FC26 2026-06-30)·obs#102 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표) · v_player_profile 0행 · prescriptions#measured(RCB n=3) | 2026-09-11 갱신: player_duties#61(2026-08-09 코모 이적 확정, Goal.com·ESPN·Chelsea FC 공식) · player_game_stats FC27(2026-08-31 roster, club=Como, OVR80) · v_player_season_stats(25/26 전 대회, 첼시 소속 마지막 시즌)','MEDIUM(그리드 3경기 — 표본 부족) / HIGH(FC26 스탯) | 2026-09-11 갱신: 이적 확정은 1차 보도 다수 일치로 HIGH. 26/27 CHE 평가 목적상 이 행은 사실상 비활성(historical-only) — 스쿼드 밖.','2026-09-11','프리미어리그 센터백 중 후방에서 공을 가장 많이 만지고 정확도가 높은 배급형이면서, 수비 총량도 상위권에 있는 균형형 프로필이다. 성공한 패스 2124회가 백분위 96, 터치 2686회가 92, 패스 정확도 93.0%가 94로 소유 국면 지표가 최상위권이다. 수비에서는 걷어내기 178회(77)·인터셉트 35회(84)·볼 회수 119회(92)로 개입량이 많고 상대 진영 볼 탈취 5회는 백분위 100이다. 세트피스에서 득점 3골(88)과 xGOT 2.49(86)로 공격 가담의 실효도 있다. 약점은 경합의 질과 긴 패스다 — 공중 경합 승률 55.6%가 백분위 33, 롱볼 정확도 40.0%가 33으로 평범 이하이고 제쳐당함(31)·볼 뺏김(26)도 하위권이며 퇴장 1회(2)가 있다. 짧은 패스로 전개를 담당하는 센터백으로 쓰되, 제공권이 걸린 상황에서는 공중볼이 강한 짝을 옆에 두는 것이 맞다.');
INSERT INTO player_evaluations VALUES(25,2,35,unistr('B — 실측이 포지션 서사를 정정한 사례: ''쿠쿠렐라 후임 LB'' 제안을 실측이 반박(LB 0.717→신커널 0.469)하고 LCB cb_bpd/Aggressive 0.930(신커널 0.850)으로 좌측 CB 프로필이 확정됐다(obs#102 ②: ''하토는 LB가 아니라 좌측 CB'' 반박이 더 강해짐). 6경기 평균 6.52. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.\u000a\u000a[2026-09-11 갱신] 공식전 실측이 축적됐다 — 풀럼(LM 65분 7.08)·브라이턴(LM=좌WB 90분 7.0, 32분 어시스트)·루턴(LB 교체 23분 6.7)·아스날(LWB 60분 7.1, 어시스트) 등 CHE 소속 5경기. squad_entries·prescriptions가 이 표본으로 재산출됐다 — LWB(3-4-2-1) 커널 fb_att_wb/Support 0.7717(45분+ 필터 통과 2경기, 평균 7.05, 150분, 2026-09-07 재집계)로 FB군이 WM(0.6964)·CM(0.4887)을 압도해, 프리시즌 CB 라벨(cb_bpd/Aggressive 0.930)은 정규시즌 실측으로 대체된다 — 그는 좌측 CB가 아니라 좌측 윙백으로 확정 기용된다. 단 동작은 순수 WB가 아니라 하이브리드다: 무공 국면에서 avg_x 38.98(CB 둘과 같은 깊이)까지 내려와 백4를 형성한다(1차 소스 tacticalfootballanalysis, player_duties#62 D+3). 브라이턴·아스날 2경기 연속 어시스트.'),unistr('좌측 볼플레잉 CB, 중심(27.0,35.3), 전방 0.12/자기진영 0.62. obs#58의 ''볼플레잉 CB 2'' 중 한 축. RCB 0.102로 우측 이동 불가. FC26 개인 스탯 DB 미수집.\u000a\u000a[2026-09-11] FC27(2026-09-10) OVR78 유지 — PAC85·SHO42(+1 vs FC26 41)·PAS70·DRI74·DEF76(+1 vs 75)·PHY74(+1 vs 73), 신규 PlayStyle 3종(Pinged Pass·Jockey·Intercept) 추가(FC26엔 PlayStyle 없음) — Jockey·Intercept는 실측된 ''스텝업 요격형''(태클·인터셉트 90분당 백분위 85·87) 프로필과 정합한다.'),unistr('특장점: 백3 좌측의 확정 인선이며 볼플레잉 축. 약점: LB 겸용 불가 판정(0.469)이 좌 윙백 인선 공백(obs#109 ①: 확정 영입 2인이 전부 우측 자원)을 해소하지 못하는 원인 — 그의 전용성이 스쿼드 구조 최약 슬롯을 그대로 남긴다. 이벤트 스탯 평균 6.70(25백분위, 1경기)으로 낮은 편.\u000a\u000a[2026-09-11] 26/27 국면 분리가 실측·서사 양쪽에서 확인된다: 온볼에서는 로저스와 좌 하프스페이스↔윙 수직 로테이션, 무공에서는 백4 형성(하이브리드 5→4, obs#519). 아스날전 결승 빌드업에 세컨볼 헤더로 관여했다(1차 공중 경합 승자는 라크루아 — obs#519 D+2 오기 정정). 매체 평가는 분열 — SI 7점이면서도 「certainly not the long-term solution at wing back」, football.london은 사카 마킹을 호평. 60분 교체는 부진이 아니라 라비아 동시 2장 교체 패키지였다(개인 사유 서술 0건, player_duties#62 D+2).'),'Fotmob 25/26 PL 12.7경기(90분 환산)로 표본 자체가 얇다(39지표). 패스 정확도 92.0%(95백분위)·크로스 정확도 57.1%(95백분위)·드리블 성공률 53.8%(79백분위)로 ''정확도''는 리그 동포지션 최상위인 반면, 총량 지표는 정확한 롱볼 8회(23백분위)·기회 창출 8회(33백분위)·터치 993회(42백분위)로 낮다 — 적게 관여하되 잃지 않는 유형. 수비 쪽은 90분 환산 기준이 훨씬 좋아(태클 2.84 = per90 85백분위, 인터셉트 1.42 = 87백분위, 수비적 행동 7.88 = 80백분위) 합계 백분위(49·49·45)와 어긋나는데, 이는 출전 시간이 짧기 때문이며 per90 쪽이 능력 추정에 적합하다. 우리 3팀 풀에서는 player_matches 1경기(79분 6.70 = 24백분위)와 그리드 6경기 6.52뿐이라 좁은 모집단·소표본이 겹쳤고, 어느 쪽도 알론소 체제(공식전 0경기) 스탯이 아니다. | 2026-09-11 갱신: prescriptions id=481(measured LWB(3-4-2-1), fit_sim .7717, n=2, avg 7.05, 150분, 2026-09-07 재집계) · v_player_season_stats 26/27 누적(PL 3경기 215분 평균7.06 2도움, EFL컵 1경기 23분 6.7, 클럽친선 3경기 212분 6.75) · player_matches CHE 5경기(Fulham·Sociedad·Luton·Brighton·Arsenal) 확인','MEDIUM — (교차 투영 — 실측 아님) 에메리 백4 LCB 볼플레잉 요구와 프로필 일치 — 단 백4 실측 없음.','HIGH(갱신) — 공식전 5경기 실측이 좌측 윙백 기용을 확정한다(fb_att_wb/Support 0.7717, n=2 45분+). 프리시즌 CB 판정(cb_bpd/Aggressive 0.930, 다른 슬롯 축)은 정규시즌 실측으로 대체됐다 — 백3 좌측 CB가 아니라 3-4-2-1 좌 윙백. 무공 시 백4 형성(하이브리드)은 obs#519가 추적 중인 미해결 전술 이슈.','MEDIUM — (교차 투영 — 실측 아님) 좌측 CB 프로필 자체는 이식 가능하나 압박 체계 실측 없음.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#58·#102·#109 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 39지표) · v_player_profile n=1 · prescriptions#measured(LCB, 6.52) | 2026-09-11 갱신: prescriptions id=481(measured LWB, fit_sim .7717, 2026-09-07 재집계) · player_duties season=2026-27 id=62(D+2·D+3 아스날전 추적, 1차 소스 tacticalfootballanalysis·Coaches'' Voice·VoetbalPrimeur) · player_game_stats FC27(2026-09-10, OVR78, PlayStyle 3종 신규) · v_player_season_stats(26/27 PL 3경기 215분 2도움)','HIGH(그리드 6경기·슬롯 전수 산출) / LOW(이벤트 스탯 1경기) | 2026-09-11 갱신: 공식전 5경기·262분 — 45분+ 필터 통과분은 2경기뿐이라 fit_sim 자체는 여전히 소표본. 다만 포지션 판정(WB 채택)은 3중 서사(NL·영어·ES) 교차검증으로 HIGH.','2026-09-11','프리미어리그 풀백 중 1143분 표본이므로 90분당 백분위로 읽는다 — 그 기준에서는 짧은 패스 정확도와 수비 개입량이 함께 높은 유형이다. 패스 정확도 92.0%가 백분위 95, 90분당 성공한 패스 55.17회가 95, 터치 78.26회가 89로 공을 안정적으로 많이 다루고, 90분당 인터셉트 1.42회가 87, 태클 2.84회가 85, 수비적 행동 7.88회가 80으로 수비 빈도도 상위권이다. 크로스 정확도 57.1%(95)는 시도가 7회뿐이라 과대평가 위험이 있다. 약점은 긴 패스와 규율, 최종 산출이다 — 롱볼 정확도 30.8%가 백분위 21, 정확한 롱볼이 13, 경고 7장이 6이고 얻어낸 파울(12)도 최하위권이다. 기회 창출(33)과 xA(29)가 낮아 공격 생산은 기대할 수 없고, 90분당 출전 중 실점 2.13골(8)은 이 선수가 뛴 경기의 실점 환경이 나빴음을 보여준다. 짧은 전개와 수비 가담을 요구하는 자리에 두고, 측면에서 만들어내는 역할은 다른 선수에게 맡기는 편이 맞다.');
INSERT INTO player_evaluations VALUES(26,2,36,unistr('A — 피벗의 실질 기둥. LDM dm_dlp/Roaming 0.941(6경기 평균 7.00, 신커널 불변), 신커널에서 RDM도 0.871로 급등해 양측 겸용이 가능해졌다(obs#102 ⑤ — 단 이동은 순 −0.028로 기각, 우발 대비로만 기록). 핵심 긴장: obs#116이 확정한 기능축 실측(듀얼승 4.6·인터셉트 1.25·볼회수 5.4 전부 피벗 3인 중 1위, 키패스 0.6 최하위)은 그가 명백한 볼위너임을 말하는데, 현 처방은 dm_dlp(창조형)를 유지한다 — 움직임 적합 +0.126을 사고 기능 정합을 포기한 트레이드(지불액 0.246~0.294, 사용자 판단 보류 사항). 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.\u000a\u000a[2026-09-11 갱신] 26/27 공식 출전이 극히 제한적이다 — 밀란(85분 8.2)·소시에다드(76분 7.3)·유벤투스(66분 7.5) 프리시즌 이후, 공식전은 브라이턴전 14분(6.6, 82분 재부상 교체로 시즌 첫 출전이 조기 종료)뿐이다. 아스날전(09-06)·루턴전·리즈전(EFL컵 09-09) 전부 결장했다. 알론소 본인이 「지난주 브라이턴전 투입이 너무 일렀다」고 인정했다(NBC Sports·Sky, 2026-09 D+3 확정 — ReadChelsea: 「브라이턴전 복귀했으나 곧 불편을 느껴 스스로 교체를 요청」). 그의 결장이 엔소 이적과 겹쳐 리스 제임스의 임시 피벗 기용을 낳은 이중 결손의 한 축이다.'),unistr('움직임은 창조형(백라인 옆 하강, obs#44의 ''압박 유인 후 관통'' 정합 — 자기진영 0.40)인데 기능은 볼위너 — ''첼시의 카마라''(obs#116). 중심(47.6,44.5)의 중앙 피벗. FC26 개인 스탯 DB 미수집.\u000a\u000a[2026-09-11] FC27(2026-09-10) OVR86 유지(FC26 88 대비 -2, 07-23 기준) — PAC69·SHO68(+1 vs FC26 67)·PAS77(-1 vs 78)·DRI81·DEF84·PHY82, 신규 PlayStyle 5종(Pinged Pass·Long Ball Pass·Anticipate·Press Proven·Intercept+) 추가(FC26엔 PlayStyle 없음) — Intercept+·Press Proven·Anticipate는 그의 볼위닝 기능축 실측(인터셉트·태클 90분당 백분위 상위권)과 정합한다.'),unistr('특장점: 수비 3지표(듀얼·인터셉트·회수) 피벗 내 전부 1위 + 패스 성공률 90.7%·경기당 66.0회로 볼순환 볼륨도 최고 — 파괴와 순환을 겸한다. 신커널 기준 좌우 피벗 양측 가용. 약점: 창조 산출 최하위(키패스 0.6·xA 0.056) — dm_dlp 처방이 요구하는 창조 축을 기능축 실측이 지지하지 않는다(obs#116 ⑤). 듀얼 4.6은 첼시 3인 내부 비교이지 리그 절대 기준이 아님(카마라 보정값 6.9보다 낮다).\u000a\u000a[2026-09-11] 재부상으로 26/27 강점 서술은 25/26 자료에 크게 의존한다. 공식전 14분 표본만으로는 기능축 재검증이 불가능하다.'),'Fotmob 25/26 PL 31.1경기(90분 환산, 41지표)에서 수비 볼륨이 리그 동포지션 최상단이다 — 인터셉트 59회(100백분위)·태클 87회(90백분위)·수비적 행동 366회(89백분위)·경합 승 172회(89백분위)·볼 회수 177회(86백분위). 배급도 패스 성공 1883회(98백분위)·정확도 91.7%(95백분위)·터치 2496회(95백분위)로 최상위. 약점은 명확히 두 개다: 공중 경합 승률 34.1%(6백분위)로 제공권이 리그 최하위 구간이고, 파울 54회(2백분위)·경고 11장(2백분위)으로 반칙 빈도가 극단적으로 높다. 우리 3팀 풀 실측(9경기 800분 평균 7.08 = 69백분위, 경합승 4.22 = 83백분위, 인터셉트 1.33 = 89백분위)과 방향은 일치하나 순위가 낮게 나오는데, 3팀 풀은 강팀만 모은 59행 모집단이라 리그 전체 동포지션 대비인 Fotmob 쪽이 더 넓다. 이 표본은 전부 25/26 마레스카·로즈니어 체제이며 알론소 체제 스탯이 아니다. | 2026-09-11 갱신: v_player_season_stats 26/27 — PL 1경기 14분(6.6, 82분 부상 교체), 클럽친선 3경기(76·151분 등) 평균 6.8~7.8. 공식전 표본이 14분뿐이라 시즌 실측 판단에는 미달 — 25/26 fotmob 41지표가 여전히 유일한 유의미 표본이다.','HIGH — (교차 투영 — 실측 아님) 에메리 더블 피벗의 볼위닝 축(r1: 오나나·카마라=dm_holding, obs#32의 기능 분화 원칙)에 기능축 프로필이 정확히 대응한다.','MEDIUM(하향, 재부상) — 하강 피벗(dm_dlp/Roaming 0.941)이 알론소 원칙(obs#44)과 정합한다는 판단 자체는 유지하나, 26/27 공식전 표본이 14분(1경기, 그마저 재부상으로 조기 종료)뿐이라 체제 실측이 사실상 없다. 결장 장기화 시 라비아·리스 제임스 임시 조합이 대체 정본으로 굳어질 위험이 있다(2026-09-06 아스날전 리포트 §결원 섹션).','HIGH — (교차 투영 — 실측 아님) 고강도 압박·즉시 탈취 체계에서 볼회수 5.4/경기 프로필은 원형 적합 — 단 실측 없음.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#44·#102·#109·#116 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표) · v_player_profile n=9 · prescriptions#measured(LDM n=6, 7.00) | 2026-09-11 갱신: player_game_stats FC27(2026-09-10, OVR86·PlayStyle 5종 신규) · v_player_season_stats(26/27 PL 1경기 14분) · reports/match-watch/2026-08-30-che-brighton.md(부상 재발 기록) · reports/match-watch/2026-09-06-che-arsenal.md(too early 발언 확정, D+3)','HIGH(움직임 6경기+기능축 8경기 실측) / MEDIUM(알론소 체제 이식 — 공식전 0경기) | 2026-09-11 갱신: 26/27 공식전 표본 1경기 14분 — 판단 근거로 쓰기엔 불충분(descriptive only). 부상 상태·복귀 시점 미확정.','2026-09-11','프리미어리그 미드필더 중 공을 끊는 양과 공을 돌리는 정확도가 동시에 최상위권인, 이 모집단의 표준적 상위 프로필이다. 인터셉트 59회가 백분위 100, 태클 87회가 90, 수비적 행동 366회가 89, 볼 회수 177회가 86으로 회수 지표가 전부 상위권이고 얻어낸 파울 55회도 95다. 소유 쪽에서는 성공한 패스 1883회(98)·패스 정확도 91.7%(95)·터치 2496회(95)로 중원 배급의 축이다. 약점은 반칙과 공중볼이다 — 파울 54회가 백분위 2, 경고 11장이 2, 퇴장 1회가 0으로 규율 지표가 최하위이고 공중 경합 승률 34.1%는 6으로 최하위권이다. 상대 박스 터치(90분당 12)와 기회 창출(31)이 낮아 전진해 마무리를 돕는 역할은 아니다. 중원을 혼자 지키며 배급하는 자리에 쓰되, 세트피스와 제공권은 다른 인원으로 보완해야 하는 프로필이다.');
INSERT INTO player_evaluations VALUES(27,2,37,unistr('A — 실측 6경기 평균 7.28로 첼시 필드 플레이어 최고. 실측 형태는 피벗 라벨보다 좌측 와이드 플레이메이커(LM wm_wideplm/Attack 0.750 > LDM 0.698 > CAM 0.631, 중심 35.3,57.0 좌측 편향). obs#116이 기능축을 확정: 키패스 2.6으로 카이세도의 4배 이상 — 피벗 2인의 기능 분화에서 명백한 창조 축이다. RDM은 0.535로 부적합(''카이세도와 같은 쪽(좌측)을 원한다'' 판정 유지, obs#116 ⑥). 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.\u000a\u000a[2026-09-11 갱신] 2026-09-01 맨체스터 시티로 완전이적 확정 — 이적료 £125m(이삭과 공동 영국 이적 기록 타이), 5년 계약(2031), mancity.com 공식 발표(23:30 UK). 26/27 첼시 스쿼드에서 이탈했다 — 이후 CHE 공식전 명단에 없다(09-06 아스날전부터 결원, transfer_outgoing id=25 CONFIRMED). 첼시 소속 마지막 출전은 2026-08-24 풀럼전(65분 투입 25분, 평점 6.41)으로, 카이세도 컨디션 문제 속 대체 출전이었다 — 「카이세도가 온전했다면 출전하지 않았을 수도 있다」는 서술과 투입 내내 이어진 풀럼 홈 관중의 야유가 복수 매체에 기록됐다(25분 표본+상대 관중 요인으로 수행 평가·이적 등급 판정에는 미채용, player_duties#64 캐비앗 유지).'),unistr('창조형 좌측 성향 미드필더 — 전방 0.49/자기진영 0.21로 피벗 후보 중 가장 전진적. LM 0.750이 로저스(0.700)보다 높아 실측만 보면 LM 칸 1순위(obs#102 ⑥, 격차 0.050). FC26 개인 스탯 DB 미수집(웨스트햄 ''페르난데스''는 동명이인).\u000a\u000a[2026-09-11] 이적으로 CHE FC27 로스터 수집 대상에서 제외됐다 — 첼시 소속으로 확인되는 마지막 FC27 행은 2026-08-31(club=Chelsea, OVR86)이고, 2026-09-10 로스터엔 그의 행이 없다. 향후 갱신은 맨체스터 시티 소속으로 별도 수집이 필요하며 이 프로젝트(CHE 분석) 범위 밖이다.'),unistr('특장점: 창조 지표 풀 최상위 — 키패스 2.63(94백분위)·xA 0.213(83백분위), 평점 7.44(84백분위, player_matches 8경기). 약점: 수비 질량 최소(자기진영 0.21) — 그를 LDM에 두면 좌 윙백 공백 지역의 수비 보호가 사라진다(obs#102 ⑷ 카이세도 이동 기각의 근거). RDM 0.535로 우측 피벗 불가.\u000a\u000a[2026-09-11] 이적 확정으로 이 항목의 강점 서술은 25/26 첼시 소속 표본에 고정된 이력값이다. 26/27 첼시 소속 출전은 풀럼전 25분뿐이라 추가 검증 표본이 없다.'),'Fotmob 25/26 PL 34.7경기(90분 환산, 42지표)에서 창출·득점 양쪽이 동시에 상위 2%다 — 기회 창출 68회(98백분위)·xA 7.25(98백분위)·xG 11.29(98백분위)·xGOT 12.40(98백분위)·득점 10골(93백분위)·유효슛 31회(95백분위). 배급도 패스 성공 1755회(98백분위)·정확한 롱볼 95회(97백분위)·터치 2608회(97백분위)로 최상위이며, 공중 경합 승률 50.0%(90백분위)·헤더 슛 9회(95백분위)로 미드필더치고 제공권까지 갖췄다. 반대로 1대1 캐리는 최하위다 — 드리블 성공률 27.1%(9백분위)·제쳐당함 36회(4백분위)·볼 뺏김 41회(11백분위), 경고 10장(0백분위). 우리 3팀 풀 실측(8경기 718분 평균 7.44 = 85백분위, 키패스 2.63 = 93백분위)과 Fotmob이 드물게 일치하는 사례지만, 두 표본 모두 25/26 마레스카·로즈니어 체제이고 알론소 체제 공식전은 0경기다. | 2026-09-11 갱신: v_player_season_stats 25/26 첼시 소속 전 대회 최종 — PL 36경기(3121분) 평균 7.15(8골 3도움)·UCL 10경기(748분) 평균 6.99(3골 2도움)·EFL컵 5경기·FA컵 4경기 등, 이적 전 마지막 풀시즌 기록. 26/27은 PL 1경기(25분 6.41, 풀럼)뿐이며 2026-09-01 이적 확정 이후 첼시 소속 기록은 없다.','MEDIUM~HIGH — (교차 투영 — 실측 아님) 에메리 더블 피벗의 창조 축(틸레만스=dm_dlp 원형, obs#32)에 기능 프로필이 대응하나 수비 질량이 얇다.','N/A(이적) — 2026-09-01 맨체스터 시티로 완전이적(£125m)이 확정돼 26/27 알론소 스쿼드 평가 대상에서 제외한다. LM wm_wideplm/Attack 0.750 판정은 25/26 첼시 소속 실측 기준선으로만 보존한다.','MEDIUM — (교차 투영 — 실측 아님) 수직 전환 체계의 전진 패스 축으로는 맞으나, 고강도 압박의 비소유 요구 대비 수비 질량(자기진영 0.21)이 최소라는 점이 리스크.','squad_entries(r2)·prescriptions(measured)·v_player_profile·obs#58·#102·#116 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 42지표) · v_player_profile n=8 · prescriptions#measured(LM n=6, 7.28) | 2026-09-11 갱신: transfer_outgoing id=25(CHE→Manchester City, CONFIRMED, 2026-09-01, mancity.com 공식·£125m·5년) · v_player_season_stats(25/26 최종·26/27 1경기) · reports/match-watch/2026-08-24-che-fulham.md(첼시 소속 마지막 출전)','HIGH(움직임 6경기+기능축 8경기 실측) / MEDIUM(알론소 체제 이식 — 공식전 0경기) | 2026-09-11 갱신: 이적 확정은 구단 공식 발표로 HIGH. 26/27 CHE 평가 목적상 이 행은 비활성(historical-only) — 스쿼드 밖, 09-06 이후 CHE 리포트에 결원으로만 등장.','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 창조와 마무리 양쪽에서 최상위권 산출을 낸, 이 모집단에서 가장 강한 프로필 중 하나다. 기회 창출 68회·xA 7.25·xG 11.29·xGOT 12.40이 모두 백분위 98이고 유효슛 31회(95)와 득점 10골(93), PK 제외 xG(97)까지 마무리 지표도 상위 5% 안이다. 배급도 성공한 패스 1755회(98)·정확한 롱볼 95회(97)·터치 2608회(97)로 최상위이고 태클 53회(92)·인터셉트 21회(92)로 수비 개입까지 갖췄다. 약점은 개인 돌파와 규율이다 — 드리블 성공률 27.1%가 백분위 9, 제쳐당한 횟수 36회가 4, 파울 36회가 7, 경고 10장이 0으로 최하위다. 볼 뺏김 41회(11)도 하위권이라 좁은 공간에서 혼자 벗어나는 방식은 맞지 않는다. 공을 받아 앞으로 배급하고 박스 앞에서 때리는 자리, 즉 압박이 덜한 반 칸 뒤에서 경기를 조립하는 역할에 두는 것이 맞다.');
INSERT INTO player_evaluations VALUES(28,2,38,unistr('B — 실측 6경기 평균 6.63, RM wm_winger/Balanced 0.875, 전방 0.59/자기진영 0.20의 터치라인형 윙어. 문제는 선수가 아니라 구조: 알론소 3-4-2-1에는 윙어 슬롯이 아예 없고(obs#61 — 첼시의 구조적 모순은 윙어 과잉), 네투의 실측이 그 모순의 실측 근거로 지목돼 있다. LM 0.316으로 우측 전용. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것.\u000a\u000a[2026-09-11 갱신] 공식전 실측이 우 윙백/우측 전방 기용을 확정했다 — squad_entries·prescriptions 재산출: RWB(3-4-2-1) 커널 fb_att_wb/Support 0.8144(45분+ 필터 통과 2경기, 평균 8.15, 127분, 2026-09-07 재집계)로 FB군이 WM(0.7154)·CM(0.5420)을 압도한다. 브라이턴전(68분 8.1, SofaScore 8.4 — 경기 최고, 골+xG.41+xA.33+키패스2)과 리즈전(EFL컵, 46분 투입 45분 7.7, 60분 결승골)으로 CHE 소속 6경기 중 최고 평점 2회를 기록했다. 다만 수비 부하가 큰 임무다 — 아스날전(D+2·D+3)에서는 무공 시 미드필드 라인까지 올라가 칼라피오리(인버티드 풀백)를 대인 추종하는 임무를 받았고, 이 전진이 아체암퐁을 사실상 단독 우측 풀백으로 고립시켜 팀을 4-4-2로 접히게 하는 연쇄의 시작점이었다(1차 소스 tacticalfootballanalysis·Coaches'' Voice·Sky 캐러거, obs#562·#564). 매체 평가는 분열 — Evening Standard 7 대 football.london 5.'),unistr('터치라인형 우측 윙어(중심 65.4,61.8) — insidefwd 0.847이 근접 차순위라 인사이드 변형 여지는 있음(Δ0.028은 노이즈 구간이라 우열 단정 불가). FC26 개인 스탯 DB 미수집.\u000a\u000a[2026-09-11] FC27(2026-09-10) OVR81(-1 vs FC26 82)·PAC91·SHO76(-1 vs 77)·PAS77·DRI82(-1 vs 83)·DEF40·PHY70 유지, 신규 PlayStyle 3종(Rapid·Quick Step·Low Driven Shot) 추가(FC26엔 PlayStyle 없음) — Rapid·Quick Step은 실측된 전방 캐리 프로필과, Low Driven Shot은 브라이턴전(14분)·리즈전 결승골 유형과 정합한다.'),unistr('특장점: 우측 폭 공급 자체는 확실(적합 0.875). player_matches 1경기 평균 8.20(98백분위)이 눈에 띄나 1경기 값(표본 부족). 약점: 체계 부적합 — 알론소의 폭 담당자는 윙백이라(obs#46) 그의 본 직무 슬롯이 처방에 없다. 팔머(RM 0.845)와 슬롯 경합 시 실측 근거가 밀린다.\u000a\u000a[2026-09-11] 6경기 중 2회 경기 최고 평점(브라이턴 8.1/8.4, 리즈 7.7 결승골)으로 시즌 초반 최고 폼을 보이는 동시에, 아스날전 대인 추종 임무가 수비 조직 붕괴의 시발점으로 지목돼(obs#564) 개인 적합과 무관하게 그 특정 임무 설계가 구조적 리스크로 남는다.'),'Fotmob 25/26 PL 29.4경기(90분 환산, 40지표)는 전형적인 ''공급형 윙어'' 지문이다 — 성공한 크로스 38회(95백분위)·xA 6.83(96백분위)·어시스트 6회(92백분위)·빅찬스 창출 12회(91백분위)·기회 창출 53회(91백분위)·드리블 성공 47회(92백분위). 반면 마무리는 xG 4.61(73백분위)·xGOT 3.83(67백분위)·득점 5골(71백분위)로 한 단계 낮고, 몸싸움은 경합 승률 40.3%(29백분위)·공중 경합 승률 27.3%(30백분위)·제쳐당함 26회(9백분위)로 하위다. 우리 3팀 풀 실측은 player_matches 1경기(59분 평점 8.20 = 97백분위)라 사실상 노이즈이고, 그리드 6경기 평균 6.63이 유일한 실질 근거였다 — 두 백분위의 극단적 괴리는 n=1 탓이다. 이 Fotmob 수치도 25/26 마레스카·로즈니어 체제이며 알론소 체제 스탯이 아니다. | 2026-09-11 갱신: prescriptions id=482(measured RWB(3-4-2-1), fit_sim .8144, n=2, avg 8.15, 127분, 2026-09-07 재집계) · v_player_season_stats 26/27 누적(PL 3경기 163분 평균7.09 1골, EFL컵 2경기 68분 평균7.25 1골, 클럽친선 2경기 59·76분 평균 8.2/7.8)','MEDIUM~HIGH — (교차 투영 — 실측 아님) 에메리 4-2-3-1 Wide의 우측 와이드 슬롯이 존재하나, 그 칸의 처방은 뱅크 복귀형(wm_widemid/Support)이라 전방 0.59/자기진영 0.20의 네투와 질량 방향이 반대다.','HIGH(상향) — 6경기 실측이 우 윙백 기용과 고성과(브라이턴 8.1·리즈 결승골)를 동시에 확인한다(fb_att_wb/Support 0.8144). 단 무공 시 요구되는 대인 추종(칼라피오리 사례)이 수비 조직 붕괴의 원인으로 지목돼(obs#564) — 개인 적합과 별개로 이 특정 임무 설계 자체가 구조적 리스크다. ''윙어라 3-4-2-1에 슬롯이 없다''던 이전 판정은 실측 윙백 전환으로 해소됐다.','MEDIUM~HIGH — (교차 투영 — 실측 아님) 이라올라 체계는 정통 윙어 슬롯이 살아 있는 편(살라 wm_winger/Attack 임시 처방)이라 세 감독 중 직무 보존이 가장 좋다.','squad_entries(r2)·prescriptions(measured)·v_player_profile·obs#46·#61 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 40지표) · v_player_profile n=1 · prescriptions#measured(RM n=6, 6.63) | 2026-09-11 갱신: prescriptions id=482(measured RWB, fit_sim .8144, 2026-09-07 재집계) · player_duties season=2026-27 id=65(D+2·D+3 아스날전 추적) · player_game_stats FC27(2026-09-10, OVR81, PlayStyle 3종 신규) · v_player_season_stats(26/27 PL 3경기 163분 1골)','HIGH(그리드 6경기) / LOW(이벤트 스탯 1경기) | 2026-09-11 갱신: 공식전 6경기로 표본 확대(45분+ 필터 통과 2경기로 fit_sim 산출) — 포지션 판정은 HIGH. 대인 추종 임무의 일반화 가능성(칼라피오리 고유 여부)은 1경기 관찰이라 LOW.','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 측면에서 크로스와 드리블로 기회를 만드는, 전형적인 창조형 윙어 프로필이다. 성공한 크로스 38회가 백분위 95, xA 6.83이 96, 기회 창출 53회가 91, 빅찬스 창출 12회가 91, 어시스트 6개가 92로 남을 살리는 지표가 상위 10% 안이고 드리블 성공 47회(92)로 직접 벗겨내는 능력도 좋다. 패스 정확도 87.3%(89)와 롱볼 정확도 66.7%(85)로 공 처리도 안정적이다. 약점은 수비 기여가 사실상 없다는 점이다 — 90분당 수비적 행동이 백분위 2, 태클이 8, 볼 회수가 13으로 최하위이고 경합 승률 40.3%(29)·제쳐당함(9)도 낮다. 자기 마무리는 xG 4.61(73)·득점 5골(71)로 준상위에 그쳐 결정을 짓기보다 만들어 주는 쪽이다. 뒤를 받쳐줄 수비형 풀백과 짝지어 측면 창조를 전담시키는 배치가 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(29,2,39,'A — 2×10의 우측 축. 실측이 ''CAM 10번'' 라벨을 정정한 대표 사례: 중심(65.0,59.9) 우측 편향, RM wm_wideplm/Attack 0.845 ≫ CAM 0.676, LM 0.152 완전 부적합. 6경기 평균 6.82, 신커널에서도 0.845 불변(obs#102 ①). 로저스와 실측 겹침 0.465로 낮아 좌우 분리 공존이 구조적으로 가능 — 알론소의 ''팔머 병용 플랜''(obs#59)을 실측이 지지한다. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것. [2026-09-11 갱신] 08-24 풀럼전(알론소 첫 공식전) RAM 83분 평점 9.08 — 3골 전개 관여 경기 최우수(player_duties). 알론소 프리시즌 실측(CAM alonso2627, 2경기 161분 평균 6.95, fit_sim cam_playmaker/Build-Up .877)과 공식전 실측이 같은 방향(우측 하프스페이스 창조자)을 가리켜 더 이상 ''체제 실측 아님'' 각주가 필요 없는 첫 사례가 됐다.','우측 포켓 플레이메이커(호프만=우 커넥터 대응, id=8 reference), 전방 0.59/자기진영 0.16으로 수비 질량 최소급. 알론소는 ''10번 근처''로 말했지만 실측 중심 x=65는 우측 편향(projected 캐비앗). FC26 개인 스탯 DB 미수집. FC27(2026-09-10) PlayStyles 7종 확정: Finesse Shot·Incisive Pass·Technical·First Touch·Press Proven·Low Driven Shot·Inventive — 슈팅+패스 이중 창조 프로필과 정합.','특장점: 우측 하프스페이스 전용성이 명확해 처방 확실성이 높다(신커널 불변 7칸 중 하나). 수비 스탯도 1경기 기준 태클 2.0(87백분위)·인터셉트 1.0(85백분위)으로 나쁘지 않음. 약점: LM 0.152 — 좌측 이동 불가라 로저스 부재 시 좌측 커버 불가. 자기진영 질량 0.16으로 비소유 국면 기여는 얇다. FC27 OVR85(FC26 86 대비 -1), PAS85(-1)·DRI85(-1) 소폭 하락하나 SHO83 유지 — 하락폭이 작아 실전 평가(풀럼전 9.08)와 배치되지 않는다.','Fotmob 25/26 PL 21.8경기(90분 환산, 38지표)로 부상 탓에 표본이 짧지만, 슈팅 축은 합계·per90 모두 최상위다 — xG 10.56(94/95백분위)·xGOT 10.06(97/95백분위)·유효슛 25회(92/92백분위)·득점 10골(93/94백분위, PK 5골 포함 100백분위). 압박 기여도 상대 진영 볼 탈취 21회(89백분위)로 높다. 그런데 창출 축은 의외로 평범하다 — 어시스트 1회(22백분위)·빅찬스 창출 3회(46백분위)·기회 창출 24회(62백분위)·xA 2.47(61백분위), 드리블 성공률 32.8%(19백분위)·볼 뺏김 35회(18백분위)까지 더하면 이 시즌의 파머는 ''플레이메이커''보다 ''박스 안 마무리·PK 키커''에 가깝다. 우리 3팀 풀 근거는 player_matches 1경기(85분 7.20)와 그리드 6경기 6.82뿐이라 이 분화를 볼 수 없었고, 두 표본 모두 25/26 마레스카·로즈니어 체제로 알론소 체제 스탯이 아니다. | 2026-09-11 갱신: v_player_profile 표본이 n=1→n=51(3577분)로 확장(2025-26+2026-27 합산) — avg_rating 7.17·xg_pg 0.392·xa_pg 0.109·kp_pg 1.33. v_player_season_stats 2026-27 PL 3경기 평균 7.79(2골 1도움)·EFL Cup 2경기 8.25(2골). prescriptions measured:season:full2526 CAM n=20 rating 7.14. squad_entries CAM(alonso2627) 2경기 161분 평균 6.95, fit_sim cam_playmaker/Build-Up .877(실측 툴x 67.56 — 우측 편향 재확인). player_duties 2026-08-24 풀럼전(알론소 첫 공식전) RAM 83분 평점 9.08 단일경기 최고치.','MEDIUM — (교차 투영 — 실측 아님) 에메리 우측 와이드는 뱅크 복귀형(wm_widemid/Support) 처방이라 파머의 전방 편중(0.59/0.16)과 어긋난다. 자유 로밍 10번 칸이라면 적합하나 그 칸 실측은 없다.','HIGH — 2026-09-11 갱신: 프리시즌 실측(CAM alonso2627 2경기 fit_sim .877)에 이어 공식전 실측(08-24 풀럼전 RAM 83분 평점 9.08, 팀 최우수)까지 같은 결론 — 우측 하프스페이스 창조자로 2×10 우측 확정 인선. 종전 ''체제 실측 0경기'' 각주는 해소됐다(표본은 여전히 프리시즌 2경기+공식전 1경기로 얇으나 방향 일치).','MEDIUM~HIGH — (교차 투영 — 실측 아님) 살라의 우측 인사이드 슬롯(r3 traits)과 형태가 유사 — 단 압박 기여 요구가 미검증.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#59·#102 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 38지표) · v_player_profile n=1 · prescriptions#measured(RM, 6.82) | 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR85·PAS85·DRI85·PlayStyle 7종) vs FC26(07-23, OVR86) 비교; v_player_profile(n=51); v_player_season_stats(2026-27 PL/EFL Cup); squad_entries CAM(alonso2627); prescriptions measured:season:full2526(CAM n=20); player_duties(2026-08-24 풀럼전 RAM)','HIGH(그리드 6경기·신커널 불변) / LOW(이벤트 스탯 1경기) | 2026-09-11: 알론소 체제 표본이 프리시즌 2경기+공식전 1경기로 확장(기존 0경기) — 방향은 일치하나 여전히 소표본. FC27 스탯 변화는 미세(±1).','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 자기 슛으로 값을 내는 마무리 특화 프로필이고, 창조 쪽 산출은 의외로 평범하다. xGOT 10.06이 백분위 97, xG 10.56이 94, 유효슛 25회가 92, 슛 64회가 89, 득점 10골이 93으로 슈팅 지표가 전부 상위권이며 PK 득점 5골은 백분위 100이다 — 다만 PK 제외 xG는 5.83으로 백분위 82로 떨어지므로 마무리 산출 일부는 페널티킥에서 나왔다. 상대 진영 볼 탈취 21회(89)와 인터셉트 15회(80)로 높은 위치의 압박 기여도 좋다. 약점은 남을 살리는 쪽이다 — 어시스트 1개가 백분위 22, 빅찬스 창출이 90분당 28, 크로스 정확도 13.9%가 23이고 기회 창출은 62로 평범하다. 드리블 성공률 32.8%(19)와 볼 뺏김(18)도 낮아 혼자 몰고 들어가는 방식과는 맞지 않는다. 공을 받아 곧바로 때릴 수 있는 위치, 즉 박스 안쪽으로 접히는 자리에 두고 볼 운반과 최종 패스는 다른 인원에게 맡기는 것이 맞다.');
INSERT INTO player_evaluations VALUES(30,2,40,'A− — 서사-실측 일치 사례: ''내려오는 9번''(obs#58) 서술을 실측이 지지한다(ST 0.624 < CAM 0.718 — 하강 성향이 수치로 확인). 6경기 평균 6.92, 처방은 그 성향에 가장 가까운 ST 역할인 st_false9/Build-Up. 구조적 리스크의 당사자: 로저스와 실측 겹침 0.863(전체 최고) — 좌측 10번과 9번이 같은 공간을 쓴다(obs#109 ④: 좌측 과밀+무보호). 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것. [2026-09-11 갱신] 08-24 풀럼전(알론소 첫 공식전) ST 90분 전 경기 소화, 평점 8.47 — 31초 침투와 결승골 홀드업을 동시 수행(player_duties). 알론소 프리시즌 실측(ST alonso2627, 2경기 175분 평균 8.4, fit_sim st_poacher/Support .821)과 공식전이 모두 최상위권 평점으로 일치.','드롭형 9번(보니페이스 대응, id=8 reference: 압박 선봉+링크), 중심(45.1,61.4), 전방 0.61/자기진영 0.18. ST 슬롯 적합 0.624는 스쿼드 처방 10칸 중 최저 — 형태상 순수 9번이 아니기 때문. FC26 개인 스탯 DB 미수집. FC27(2026-09-10) PlayStyles 4종 확정: Chip Shot·First Touch·Press Proven·Acrobatic — 침투+마무리 다양성과 정합, PAC는 79→77(-2)로 소폭 하락.','특장점: 연계·하강 프로필이 알론소 원형(9번=압박 선봉+링크)과 정합하고 평점 산출도 상위(1경기 8.0, 그리드 6경기 6.92). 약점: 처방 적합 0.624가 10칸 중 최저 — 박스 내 고정 9번 산출은 실측 형태 밖. 로저스 겹침 0.863은 알론소 체계의 실질 리스크 지점(projected 명기). FC27 OVR83(FC26 82 대비 +1), SHO83(+1)·PAS74(+1)·DRI84(+1) 전반적 상승(PAC만 -2) — 실전 지표(홀드업+침투 겸장) 상승과 방향 일치.','Fotmob 25/26 PL 29.7경기(90분 환산, 42지표)가 ''내려오는 9번'' 서술을 수치로 확인해 준다 — 경합 승 196회(96백분위)·경합 승률 48.3%(90백분위)·공중 경합 승 74회(80백분위)·얻어낸 파울 56회(100백분위)·얻어낸 PK 3회(100백분위)로 등지고 버티는 축이 최상위이고, 기회 창출 29회(96백분위)·xA 2.00(94백분위)·드리블 성공 40회(100백분위)로 연결 기여까지 동포지션 최상단이다. 마무리도 xG 14.96(90백분위)·15골(92백분위)·xGOT 15.16(90백분위)로 기대치를 맞춘다. 유일하게 낮은 칸은 볼 뺏김 55회(0백분위)로, 받아 내려오는 만큼 잃는 횟수도 리그 최다급이다. 우리 3팀 풀 근거는 player_matches 1경기(85분 2골 평점 8.00)와 그리드 6경기 6.92뿐이었고, Fotmob 표본은 25/26 마레스카·로즈니어 체제라 알론소 체제 스탯이 아니다. | 2026-09-11 갱신: v_player_profile 표본이 n=1→n=74(4802분)로 확장 — avg_rating 7.08·xg_pg 0.54·dw_pg 4.75(경합 관여 최다급). v_player_season_stats 2026-27 PL 3경기 평균 7.76(2골 2도움)·Club Friendly 8.8. prescriptions measured:season:full2526 ST n=37 rating 7.08(fit_sim st_false9/Build-Up .712). squad_entries ST(alonso2627) 2경기 175분 평균 8.4, fit_sim st_poacher/Support .821(실측 툴x 41.41 — 종전 ''내려오는 9번'' 서사와 달리 프리시즌 표본은 포처형 포지셔닝으로도 나타남 — 표본 2경기라 확정은 보류). player_duties 2026-08-24 풀럼전(알론소 첫 공식전) ST 90분 평점 8.47 — ''침투+홀드업 9번'' 서술.','MEDIUM — (교차 투영 — 실측 아님) 에메리 4-2-3-1의 9번은 왓킨스형 압박 선도+뒷공간 침투가 원형 — 하강 연계형과 방향이 다르나 겸용 불가 근거도 없다.','HIGH — 2026-09-11 갱신: 프리시즌 실측(ST alonso2627 fit_sim st_poacher/Support .821)과 공식전 실측(08-24 풀럼전 90분 평점 8.47, 침투+홀드업 겸장)이 모두 상위권 — 종전 ''내려오는 9번'' 서사와 프리시즌 fit_role(st_poacher)이 완전히 일치하지는 않으나(포처=박스 고정 vs 서사=하강), 두 표본 모두 결과(고평점)는 일관. 좌측 과밀(로저스 겹침 .863) 리스크는 08-24 실측으로도 아직 해소 여부 판단 불가(단일 경기).','MEDIUM~HIGH — (교차 투영 — 실측 아님) 파이널서드 탈취→즉시 슛 체계에서 전방 압박 선봉+링크 프로필은 원형 적합 — 실측 없음.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#58·#102 ⑦·#109 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 42지표) · v_player_profile n=1 · prescriptions#measured(ST, 6.92) | 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR83·SHO83·PAS74·DRI84·PlayStyle 4종) vs FC26(07-23, OVR82) 비교; v_player_profile(n=74); v_player_season_stats(2026-27 PL); squad_entries ST(alonso2627); prescriptions measured:season:full2526(ST n=37); player_duties(2026-08-24 풀럼전 ST)','HIGH(그리드 6경기·겹침 산출) / LOW(이벤트 스탯 1경기) | 2026-09-11: 알론소 체제 표본이 프리시즌 2경기+공식전 1경기로 확장(기존 0경기). FC27 스탯은 전반 상승(+1~+1)이나 PAC -2 — 방향 판단에 영향 없음.','2026-09-11','프리미어리그 공격수 중 최전방에서 공을 받아 지키고 연결하는 역할의 지표가 거의 전부 최상위인, 연계형 스트라이커 프로필이다. 성공한 패스 522회·터치 1246회·드리블 성공 40회·얻어낸 파울 56회·얻어낸 PK 3회가 모두 백분위 100이고, 기회 창출 29회(96)·어시스트 5개(96)·xA 2.00(94)으로 만들어 주는 산출도 상위 5%다. 경합 승 196회(96)와 경합 승률 48.3%(90), 공중 경합 승률 48.1%(90)로 몸으로 버티는 능력도 좋고 볼 회수 72회(94)·수비적 행동 138회(94)로 수비 가담까지 한다. 마무리는 득점 15골(92)·xG 14.96(90)으로 상위권이지만 90분당으로 내리면 슛 41·유효슛 47로 떨어져 슈팅 빈도 자체는 평범하다. 약점은 공을 잃는 빈도다 — 볼 뺏김 55회가 백분위 0으로 최하위이고 경고 5장(6)·파울 38회(16)도 낮다. 등을 지고 받아 내려주며 2선을 살리는 최전방 자리에 두는 것이 가장 맞고, 슈팅 횟수를 늘리는 방향의 기용은 근거가 약하다.');
INSERT INTO player_evaluations VALUES(31,2,41,'B+ — 처방 전체의 최약 칸이자 가장 흥미로운 하이브리드. RDM dm_dlp 처방(신커널에서 Roaming 0.772→0.579로 붕괴, Build-Up 0.656으로 포커스만 교체 — obs#102 ③)이나 45분+ 표본 3경기(표본 부족 — ''이 처방의 가장 약한 칸'' 명기). 실측 3경기 평균 7.33은 스쿼드 최고치지만 표본이 이를 뒷받침하지 못한다. 알론소가 트렌트에게 준 ''inverted role'' 지시(obs#57)의 첼시 대응 인원. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것. [2026-09-11 갱신] 08-24 풀럼전(알론소 첫 공식전) RCM 90분 전 경기 소화, 평점 7.01 — 풀럼 중원 우세 속에서도 중앙 연결 유지(player_duties). 프리시즌 실측(CM alonso2627, 소시에다드전 62분 평균 7.4, fit_sim cm_playmaker/Roaming .847)에 이어 공식전에서도 RCM 완주 — 종전 ''RDM 하이브리드'' 처방 대신 3-4-2-1 CM 라인으로 실측 포지션이 굳어지는 흐름.','인버티드 윙백/피벗 하이브리드 — RDM 0.772(구커널) > RB fb_inverted/Attack 0.692, 중심(73.3,52.3). 기능축(obs#116)에서 xA 0.244로 3인 중 최고이나 패스 볼륨 최소(53.1회)·pos가 M/D 혼재라 기능값 자체가 역할 혼재값. FC26 개인 스탯 DB 미수집. FC27(2026-09-10) PlayStyles 7종 확정: Whipped Pass·First Touch·Trickster·Quick Step·Low Driven Shot·Enforcer·Rapid+ — 스탯 자체는 FC26 대비 변화 없음(OVR84 유지, 6대 스탯 전항목 동일).','특장점: xA 0.244(93백분위)로 창조 산출 최상급 + 패스 성공률 94.1%로 정확도 최고 — 우측 전개 축의 근거. 약점: ① 표본 3경기 ② obs#58(1티어)·id=8이 공통 지목한 ''엔소+카이세도'' 피벗에서 이탈한 인선인데 그 이탈이 움직임 적합 +0.126의 구매였음이 뒤늦게 정량화됨(obs#116 ④) ③ 카이세도 RDM 0.871 급등으로 ''유일 적합자'' 서술 폐기(obs#109 ②) — 결장 시 대체는 서나 지위는 상대화됨. FC27 스탯 불변(OVR84, PAC76·SHO71·PAS83·DRI78·DEF83·PHY82 전항목 FC26과 동일) — 게임 데이터는 정체돼 있으나 실전에서는 RDM→CM 포지션 전환이 진행 중이라 카드 스탯이 새 역할(창조·전개)을 아직 반영하지 못한 상태.','Fotmob 25/26 PL 21.8경기(90분 환산, 40지표) — 합계와 per90 백분위가 거의 붙어 있어(예: xA 3.19 = 89/90, 정확한 롱볼 57회 = 93/92, 패스 성공 1178회 = 93/94) 출전 시간이 짧은데도 밀도가 높다는 뜻이다. 강점은 전달과 대인 양쪽: 성공한 크로스 30회(92백분위)·빅찬스 창출 8회(95백분위)·롱볼 정확도 55.3%(88백분위)·공중 경합 승률 66.0%(87백분위)·경합 승률 59.3%(83백분위)·인터셉트 33회(86백분위). 약점은 위치 수비 총량으로, 걷어내기 41회(44백분위)·수비적 행동 128회(54백분위)·상대 박스 터치 16회(37백분위)에 그쳐 침투보다 후방 배급 쪽 무게가 확실하다. 우리 3팀 풀 실측(7경기 592분 평균 7.14 = 75백분위, xA 0.244 = 93백분위)과 방향이 일치하며, 45분+ 그리드는 3경기로 표본 부족이었다. 두 표본 모두 25/26 마레스카·로즈니어 체제로 알론소 체제 스탯이 아니다. | 2026-09-11 갱신: v_player_profile 표본이 n=7→n=70(3892분)로 확장 — avg_rating 7.08·xa_pg 0.108(창조 산출 유지)·tk_pg 1.17. v_player_season_stats 2026-27 PL 3경기 평균 6.77·EFL Cup 2경기 6.6. prescriptions CM(alonso2627, 소시에다드전 단일경기 62분 평균 7.4, fit_sim cm_playmaker/Roaming .847, 좌우 동률 .847=.847 — 주장 완장 착용 LCM 선발). player_duties 2026-08-24 풀럼전 RCM 90분 평점 7.01 — 프리시즌에 이어 공식전도 CM 라인 배치, RDM 하이브리드 서술에서 CM 정착으로 무게중심 이동.','MEDIUM — (교차 투영 — 실측 아님) 에메리 C2(풀백 한 명만 전진)의 전진측 RB로 쓸 수 있는 프로필이나, 에메리 처방의 우측은 잔류형(fb_wingback/Balanced)이라 방향이 어긋난다.','HIGH — 2026-09-11 갱신: 종전 ''체제 실측 가장 얇음'' 평가에서 격상 — 프리시즌 소시에다드전 62분(주장, LCM, fit_sim cm_playmaker/Roaming .847)에 이어 공식전 08-24 풀럼전 RCM 90분 완주(평점 7.01)까지 CM 라인 고정이 두 번 확인됐다. 종전 ''RDM 인버티드'' 서사보다 ''CM 창조·연결'' 실측이 더 강해지는 추세 — 트렌트 대응 인원 서술은 재검토 필요.','HIGH — (교차 투영 — 실측 아님) 이라올라 우측의 인버티드 RB(프림퐁 fb_inverted 실측 성향)와 형태가 가장 직접 대응하는 스쿼드 인원.','squad_entries(r2)·prescriptions(measured/projected)·v_player_profile·obs#57·#102·#109·#116 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 40지표) · v_player_profile n=7 · prescriptions#measured(RDM n=3) | 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR84 불변·PlayStyle 7종 추가 확인) vs FC26(07-23, OVR84) — 스탯 변화 없음; v_player_profile(n=70); v_player_season_stats(2026-27 PL/EFL Cup); prescriptions CM(alonso2627, 소시에다드전); player_duties(2026-08-24 풀럼전 RCM)','MEDIUM(그리드 3경기 — 표본 부족·기능값 역할 혼재) / HIGH(이벤트 7경기) | 2026-09-11: 알론소 체제 표본이 프리시즌 1경기+공식전 1경기로 확장(기존 0경기) — 두 표본 모두 CM 라인이라 방향 일치, 표본 자체는 여전히 얇음(2경기). FC27 스탯은 변화 없어 이 갱신에서 새 근거가 되지 못함.','2026-09-11','프리미어리그 풀백 중 긴 패스와 크로스로 기회를 직접 만드는 배급형 측면 수비이고, 1962분 표본에서 총량과 90분당 백분위가 거의 일치해 신뢰도가 높다. 빅찬스 창출 8회가 백분위 95, 성공한 크로스 30회가 92, xA 3.19가 89, 어시스트 4개가 87로 창조 산출이 상위권이고 정확한 롱볼 57회(93)·롱볼 정확도 55.3%(88)로 긴 전환의 정확도가 좋다. 성공한 패스 1178회(93)·패스 정확도 89.0%(89)·90분당 터치(94)로 공을 다루는 양도 많다. 수비에서는 공중 경합 승률 66.0%(87)와 인터셉트 33회(86)가 강점이다. 약점은 골문 앞 마무리 수비와 박스 진입이다 — 걷어내기가 90분당 백분위 10, 수비적 행동이 31로 자기 진영의 마지막 방어 행동이 적고, 상대 박스 터치는 90분당 13으로 안쪽까지 들어가지는 않는다. 낮은 위치에서 길게 배급하고 크로스를 올리는 역할, 즉 전진하지 않아도 값을 내는 자리에 두는 것이 맞다.');
INSERT INTO player_evaluations VALUES(32,2,42,'B — 실측 3경기(표본 부족) 평균 6.77, RM wm_widemid/Support 0.789. 전방 0.51/자기진영 0.29로 네투보다 복귀 성향이 큰 우측 와이드 — 순수 윙어보다 지원형에 가깝다는 것이 초기 실측의 시사점. 우측은 팔머(0.845)·네투(0.875)와 3파전이라 슬롯 경쟁이 스쿼드에서 가장 치열한 칸. 표본은 CHE 실측 표본은 25/26 마레스카·로즈니어 체제(알론소 체제 공식전 0경기, 첫 경기 8/24 풀럼)의 것. [2026-09-11 갱신] 최대 변화: fotmob_detail_stats에 2025/2026 PL 41지표(2026-08-14 수집) 신규 적재 — 종전 ''0행''에서 실측 백분위 산출이 처음 가능해졌다. 08-24 풀럼전(알론소 첫 공식전)은 후반 7분(RAM, 팔머 교체 투입) 평점 미산출로 표본 가치 낮음.','복귀 성향 우측 와이드(중심 76.1,58.2), winger/Balanced 0.746이 차순위(Δ0.043 — 노이즈 상단이라 우열 단정 보류). FC26 개인 스탯 DB 미수집. 연령·성장 곡선 관련 행도 DB에 없어 잠재력 서술은 하지 않는다. FC27(2026-09-10) PlayStyles 4종 확정: Finesse Shot·Technical·Quick Step·Inventive — 우측 와이드 인사이드형 프로필과 정합. PAC 90→89(-1)로 여전히 스쿼드 최상위 스피드.','특장점: 복귀 질량(자기진영 0.29)이 우측 와이드 3인 중 최대 — 비소유 국면 기여가 필요한 라인업에서 차별점. 약점: 표본 3경기로 모든 판단이 잠정적. 알론소 체계에 윙어 슬롯이 없다는 구조 문제(obs#61)는 네투와 공유. FC27 OVR80(FC26 79 대비 +1), SHO76(+1)·PAS75(+1) 소폭 상승. 신규 확보된 fotmob PL 41지표(2026-08-14 수집)에서 크로스 정확도 31.2%(85백분위)·상대 박스 터치 74회(64백분위)·xG 2.92(58백분위)·얻어낸 PK 1회(81백분위)가 상위권 — 복귀 성향뿐 아니라 박스 근접 침투 관여도 확인된다. 다만 경합 승률 34.9%(9백분위)·공중 경합 승률 17.6%(15백분위)는 하위권으로 피지컬 듀얼은 약점.','이번 Fotmob 수집에서 상세 스탯이 확보되지 않았다(fotmob_detail_stats 0행) — 리그 동포지션 대비 백분위가 존재하지 않는 두 명 중 하나다. player_matches도 0행이라 이벤트 스탯·3팀 풀 백분위 모두 산출 불가이며, 정량 근거는 그리드 실측 3경기 평균 6.77(prescriptions measured, RM wm_widemid/Support)이 전부다. 3경기는 표본 부족 기준(n<6) 아래이므로 이 값 하나로 서열을 매기면 안 된다. 그마저 25/26 마레스카·로즈니어 체제 표본이라 알론소 체제 스탯이 아니다. | 2026-09-11 갱신(핵심): fotmob_detail_stats 2025/2026 Premier League 41지표(2026-08-14 수집, 0행→41행)로 첫 리그 백분위 확보 — 기회 창출 16회(44백분위)·xA 2.2(56백분위)·드리블 성공 29회(77백분위, per90 95백분위)·성공한 크로스 5회(크로스 정확도 85백분위)·xG 2.92(58백분위)·얻어낸 PK 1회(81백분위) vs 인터셉트 4회(32백분위)·태클 11회(27백분위)로 창조·침투는 준수하나 수비 관여는 낮다. 참고용 Palmeiras(Serie A 2025, 이적 전) 41지표도 보유 — 어시스트 3회(68백분위)·기회 창출 24회(71백분위)·성공한 크로스 20회(87백분위)로 CHE 이적 전 창조 지표가 오히려 더 높아 이적 후 출전시간·역할 제약 영향 가능(추정 명기, 확정 아님). v_player_profile n=60(2628분)·avg_rating 6.92. v_player_season_stats 2026-27 PL 2경기 16분(평점 6.5, 표본 미미). prescriptions measured:season:full2526 RAM n=16 rating 7.07(fit_sim wm_wideplm/Attack .793). squad_entries WM(alonso2627) 소시에다드전 단일경기 90분 평균 6.6, fit_sim wm_wideplm/Build-Up .727. player_duties 2026-08-24 풀럼전 RAM 7분(팔머 교체) 평점 미산출 — 평가 불가 표본.','MEDIUM~HIGH — (교차 투영 — 실측 아님) 에메리 우측 와이드 처방이 정확히 wm_widemid/Support(뱅크 복귀형) — 세 감독 처방 중 실측 성향과 역할 라벨이 유일하게 일치한다. 단 실측 자체가 3경기.','MEDIUM — 2026-09-11 갱신: 프리시즌 실측(WM alonso2627, 소시에다드전 90분 fit_sim wm_wideplm/Build-Up .727)은 확보됐으나 공식전(08-24 풀럼전)은 7분·평점 미산출로 판단 근거가 되지 못한다. 2×10 우측은 팔머가 확정 선발이라 출전 경로가 여전히 좁고, 신규 fotmob PL 지표(크로스·박스터치 상위권)는 로테이션 자원으로서의 가치를 뒷받침하나 체제 편입 여부는 미해결.','MEDIUM — (교차 투영 — 실측 아님) 측면 압축·복귀 요구와 복귀 성향은 맞으나 표본이 얇아 판단 보류 수준.','squad_entries(r2)·prescriptions(measured)·obs#61 | stat_eval 2026-08-11 갱신: fotmob_detail_stats 0행 · v_player_profile 0행 · prescriptions#measured(RM n=3, 6.77) | 2026-09-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표, 2026-08-14 수집, 신규 0→41행) + 참고용 Palmeiras(Serie A 2025, 41지표, 이적 전); v_player_profile(n=60); v_player_season_stats(2026-27 PL); squad_entries WM(alonso2627, 소시에다드전); prescriptions measured:season:full2526(RAM n=16); player_duties(2026-08-24 풀럼전 RAM 7분)','LOW~MEDIUM(그리드 3경기 — 표본 부족, 이벤트 스탯 없음) | 2026-09-11: fotmob PL 41지표 신규 확보로 리그 백분위 근거가 처음 생겼다(종전 0행 → 이번 갱신의 핵심 신뢰도 상승 지점). 알론소 체제 표본은 여전히 프리시즌 1경기+공식전 7분으로 얇음.','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(33,3,43,'B+ — Iraola 체제 공식전 3경기(2026-27 PL, 270분) 실측 확보: 뉴캐슬 원정 6.04, 크리스탈 팰리스전 6.1, 입스위치 홈 8.5 — 평균 6.88(v_player_season_stats). prescriptions 신규 행(measured, GK/gk_goalkeeper/Balanced, fit_sim 0.9764, n=3)이 프리시즌 추정치(0.976 Balanced, obs#580 계열)를 그대로 재확인한다 — 포커스가 Defend가 아닌 Balanced로 자리잡았다. 다만 표본 3경기 중 2경기(뉴캐슬·팰리스)는 평범~약점 노출, 1경기(입스위치)만 결정적 선방으로 고평점 — 변동성이 크다. FC27(2026-09-10) OVR87로 FC26(88) 대비 -1, 6대 스탯 중 DEF가 56→50으로 가장 크게 하락했다.','정통 골키퍼형 — 실측 그리드가 골문 근방에 강하게 응집(gk_goalkeeper 0.979 > Balanced 0.969 > sweeper 0.821). ''스위퍼 키퍼'' 서사와 달리 실측 위치 분포는 라인 뒤 잔류형. Δ0.01 수준(Defend vs Balanced)은 EA 노이즈라 포커스 우열은 단정하지 않는다. 2026-27 실전 3경기 누적: 뉴캐슬전(report#23)은 ''골키퍼 역할보다 잔여수비가 우선 교정점''으로 전환 국면 단독 돌파를 허용, 팰리스전(report#28)은 전반 결정적 선방과 별개로 PK를 헌납하고 퀵 스로인 대응에 실패, 입스위치전(report#32)은 평점 8.5로 단일경기 fit gk_goalkeeper/Defend 0.9569를 기록 — 회복탄력성은 있으나 표본 내 편차가 커서 ''항상 안정적''이라 단정하기는 이르다.','역할 커널 정합도가 팀 내 최고(0.979) — 어느 감독 체제에서든 GK 슬롯 배치 리스크가 가장 낮다. 약점: 하이라인 체제에서 요구될 스위핑 반경이 실측상 확인되지 않음(sweeper 0.821). FC26 능력치·PlayStyles 미수집이라 배급 품질은 데이터로 말할 수 없다. FC27 신규 PlayStyles(Far Throw·Deflector·Rush Out+)는 EA가 적극적 스위핑·전진 개입형 카드로 설계했음을 시사하나, 우리 실측 커널(sweeper 0.821 < gk_goalkeeper 0.979)과 08-17 obs#152(마마르다슈빌리 대비 라인 7.2 낮음)는 정반대로 ''라인 뒤 잔류형''을 가리킨다 — 카드 스펙과 실측 행동 간 괴리로 기록한다. 6대 스탯 중 DEF만 56→50(-6)으로 하락폭이 커, FC27 카드는 나이(34세 진입)에 따른 반응속도 저하를 선방 스탯보다 위치선정/스위핑 관련 능력치에 먼저 반영한 것으로 보인다(추정, 미검증).','Fotmob 25/26 PL 26.0경기(90분 환산, GK 18지표)가 기존 공백을 처음으로 메운다. 결과는 방어보다 배급 쪽이 좋다 — 패스 정확도 79.0%(95백분위)·롱볼 정확도 39.4%(85백분위)·실책→실점 0회(100백분위)·경고 1장. 반면 선방률 64.8%(31백분위)·선방 57회(49백분위)·선방으로 막은 실점 −2.70(23백분위)으로, 이 시즌만 놓고 보면 기대 대비 마이너스다(즉 xG 기준으로 막았어야 할 것보다 2.7골 더 허용). 클린시트 8회(69백분위)·실점 31(41백분위)은 리버풀 수비 덕이 큰 팀 종속 지표로 봐야 한다. 우리 자체 실측은 여전히 8/9 모나코 친선 1경기(45분, 평점 6.80)뿐이고 3팀 풀 백분위는 n=1이라 의미가 없다 — 리그 전체 GK 대비인 Fotmob 백분위가 유일한 실질 근거다. | 2026-09-11 갱신: 우리 자체 실측이 친선 1경기에서 Iraola 체제 공식전 3경기(PL, 270분)로 늘었다 — 뉴캐슬 원정 6.04, 크리스탈 팰리스전 6.1, 입스위치 홈 8.5, 평균 6.88(v_player_season_stats 2026-27 PL n=3). prescriptions 신규 행(measured, GK/gk_goalkeeper/Balanced, fit_sim=0.9764, n=3)이 커널 정합을 재확인. FC27(roster_date=2026-09-10)은 OVR87로 FC26(88) 대비 -1, PAC85(-1)·PAS82(-1)·DRI86(-1)·DEF50(-6)·PHY86(-2)로 전 스탯이 소폭~중폭 하락했고 SHO87만 유지 — 하락폭은 DEF에 집중된다. PlayStyles 신규 3종(Far Throw·Deflector·Rush Out+) 확인 — Rush Out+는 적극적 스위핑 개입을 시사하나 실측 커널은 여전히 sweeper 0.821 < gk_goalkeeper 0.979로 반대 방향이다(괴리, 근거 링크: fotmob_detail_stats 재수집 없음 — 09-10 pull은 없었고 08-11/08-21 pull이 마지막).','HIGH — (교차 투영 — 실측 아님) 에메리 빌라 처방이 정확히 GK gk_goalkeeper/Defend(스위퍼 아님, 빌라 실측 0.961)이고 알리송의 실측 최적이 같은 역할·포커스 0.979다. 짧은 빌드업 참여는 ''패스 옵션 수준''이라는 에메리 요구와 잔류형 실측 분포가 정합.','MEDIUM — (교차 투영 — 실측 아님) 알론소는 Short Passing 백3 빌드업에 GK를 후방 수적 우위 요원으로 쓴다. 역할 자체는 무리 없으나 배급 품질을 가릴 FC26 스탯·기능축 실측이 없어 상향 판정 근거 부족.','MEDIUM — ⭐ 2026-09-11 갱신: Iraola 체제 공식전 실측이 0경기에서 3경기(270분, 평균6.88)로 늘었다. prescriptions(measured, fit_sim 0.9764, Balanced)가 프리시즌 추정을 재확인해 ''어느 포커스로 쓰이는지''는 안정적으로 보이나, 3경기 중 2경기에서 잔여수비 판단·퀵 스로인 대응 등 세부 결함이 보고돼(match_player_reports #23·#28) ''하이라인 요구에 부합하는가''는 여전히 확정하기 이르다. 표본 n=3으로 등급은 아직 MEDIUM 유지, HIGH로 올리려면 5경기 이상 추가 표본 필요.','squad_entries(r3) · prescriptions#measured(GK, n=6) · v_player_profile(n=1, 8/9 모나코) · obs#120 · manager_profiles r1/r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 18지표) · v_player_profile n=1(8/9 모나코 친선) · prescriptions#measured(GK n=6, 6.80) | stat_eval/traits/strengths/fit_iraola 2026-09-11 갱신: player_game_stats(FC27, roster_date=2026-09-10, FC26 대비) · v_player_season_stats(2026-27 PL n=3, 270분, 평균6.88) · prescriptions(regime_id=3, kind=measured, GK/Balanced, fit_sim=0.9764, n=3, avg_rating=6.88, minutes=270) · match_player_reports(report_id 23·28·32 — 뉴캐슬/팰리스/입스위치 3경기)','MEDIUM — 이라올라 체제 실측이 공식전 3경기(270분)로 확대돼 이전(0경기)보다 근거는 강해졌으나 표본이 여전히 소수이고 경기별 편차(6.04~8.5)가 커 상한·하한 판정은 유보. FC26→FC27 비교는 확보(둘 다 존재).','2026-09-11','프리미어리그 골키퍼 중 실수를 하지 않고 발밑이 안정적인 반면, 슛 저지 지표는 이 모집단 하위권에 있는 프로필이다. 골키퍼는 수집 지표가 18개뿐이라 판단 근거가 얇다는 점을 먼저 밝힌다. 강점은 실책이 실점으로 이어진 횟수 0회(백분위 100), 패스 정확도 79.0%(95), 롱볼 정확도 39.4%(85)이고 90분당 실점 1.19골도 79로 좋다. 문제는 선방으로 막은 실점이 -2.70으로 기대보다 2.7골을 덜 막았고 백분위 23이라는 점이다 — 선방률 64.8%도 31로 하위권이다. 90분당 선방 횟수(18)가 낮은 것은 팀이 슛을 적게 허용했기 때문으로 읽히지만, 그렇다면 적게 온 슛을 막아내지 못했다는 해석이 남는다. 후방 빌드업의 안정성은 신뢰할 수 있으나, 이 시즌 숫자만 보면 슛 저지 기여는 마이너스로 평가해야 한다.');
INSERT INTO player_evaluations VALUES(34,3,44,'A- — 26/27 PL 3경기 전경기 90분 선발(뉴캐슬 7.1→노팅엄 7.2→입스위치 8.0, 상승세), 팀 첫 승(입스위치 2-0)의 중심. 25/26 시즌 통산 38경기 평균 7.26(Fotmob, v_player_season_stats). LCB cb_bpd/Aggressive 시즌누적 fit 0.911(69경기, prescriptions#measured:season:full2526) · 09-04 입스위치 단일경기 fit 0.8259(match_player_reports). 코나테 이탈이 2026-06-18 레알 마드리드 이적으로 공식 확정(player_duties#45)되며 ''26/27 유일 시니어 CB'' 리스크가 실현 — 자케(89)가 사실상 상시 파트너로 자리잡았다(4경기 연속 선발 페어).','볼 플레잉 + 전진 수비형 LCB(cb_bpd/Aggressive). FC27(2026-09-10 roster) 신규 수집: OVR 88 유지, 6대 스탯 중 PAC 73→70(-3)·드리블 71→70(-1) 하락, SHO/PAS/DEF/PHY(60/72/89/85) 불변. 신장 195→193cm(-2), 체중 92kg 신규 기재. PlayStyles 7종 신규 확정: Pinged Pass·Jockey·Intercept·Anticipate·Bruiser·Precision Header·Aerial Fortress+ — 배급·위치선정·공중전 중심 구성으로 실측(패스량·공중경합 지배)과 정합. FC26 대비 PAC 하락은 만 34세(2026 기준) 스피드 저하를 FC27 스탯이 처음 반영한 신호로 해석 가능하나 표본이 roster 수집 1건뿐이라 단정은 보류.','공중 장악과 빌드업 출구. 09-04 입스위치전 8.0으로 이라올라 체제 첫 승의 중심(match_player_reports). 08-31 노팅엄전은 90분 패스 114/102(89%)·클리어6·인터셉트1로 물량은 여전하나 ESPN이 ''경험을 감안하면 더 나서야 한다''고 비판(6점) — 수비 조직 리더십에 대한 첫 반증 사례. 08-24 뉴캐슬 데뷔전은 7.1·슛2·찬스0으로 무난. 약점: FC27 PAC -3·신장 -2cm 기재가 시사하는 속도 저하 가능성, 그리고 코나테 이탈 확정 이후 대체 불가한 단일장애점 지위가 그대로 유지된다(자케가 파트너이나 백업 부재).','Fotmob 25/26 PL 38경기(90분 환산, 39지표)에서 공중 경합 승 174회(100백분위)·걷어내기 275회(100백분위)·패스 성공 2485회(100백분위)·터치 3261회(100백분위)·득점 6골(100백분위)로 모집단 상단 극점. 태클 22회(41백분위)·볼 회수 87회(69백분위)로 능동적 탈취보다 위치 지우기형. 실점 53(1백분위)은 전 경기 소화의 결과(90분당 백분위는 50)로 해석. 2026-09-11 갱신: fotmob_detail_stats 08-21 추가 수집분(43지표, 6종 신규)에서 라인 브레이킹 패스 346회(96백분위)·최고 속도 33.7km/h(78백분위)로 배급 반경은 여전히 최상위, 신체 지표(총 이동거리 72백분위·스프린트 거리 62백분위·스프린트 횟수 66백분위)는 상위권이나 압도적이진 않아 FC27 PAC -3과 방향이 일치한다. 실측(player_matches)은 26/27 PL 3경기 90분×3(뉴캐슬7.1/노팅엄7.2/입스위치8.0, 평균 7.43) 확보 — 08-11 평가 시점 대비 표본 3경기 순증.','HIGH — (교차 투영 — 실측 아님) 에메리 처방이 양 CB cb_bpd(볼 플레잉)이고 실측 최적이 정확히 cb_bpd. 단 빌라는 ''두 CB 동시 Aggressive는 rest-defense 붕괴''로 기각한 이력(obs#13, obs#120 ⓐ 재인용)이라 포커스는 Build-Up 계열 조정 여지.','HIGH — (교차 투영 — 실측 아님) 알론소 백3는 전 CB cb_bpd/Aggressive + Short Passing(r2 implementation) — 실측 역할·포커스가 그대로 일치. 좌측 CB 실측(LCB 0.896)이라 백3 좌 스토퍼 투영이 자연스럽다.','HIGH(실측 확인) — 08-23 뉴캐슬 원정 duty 기록에 ''좌측 후방 리더''로 명시(player_duties#44, 2026-08-23), 이후 26/27 PL 3경기 전경기 LCB 선발 유지로 체제 편입이 실전으로 검증됐다. 에메리/알론소 투영과 달리 실측 근거다. 다만 08-31 노팅엄전 ESPN 비판(리더십 저하 지적)과 코나테 레알 마드리드 이적 공식 확정(player_duties#45)이 겹치며, 백업 부재 리스크는 이론이 아니라 26/27 스쿼드의 현재 상태다.','squad_entries(r3) · prescriptions#measured(LCB, n=6) · v_player_profile(n=1) · obs#69·#77·#120 · manager_profiles r1/r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 39지표) · v_player_profile n=1(8/9 모나코 친선) · prescriptions#measured(LCB n=6, 7.15) | 2026-09-11 갱신: player_game_stats(FC27 game_version, roster_date 2026-09-10 — ovr88·pac70·height193·weight92·playstyles 7종, FC26 07-23 대비 pac73→70) · player_matches(2026-27 season, PL 3경기: 뉴캐슬 08-23 90분7.1, 노팅엄포레스트 08-31 90분7.2, 입스위치 09-04 90분8.0) · match_player_reports(4건, 08-15~09-06 발행) · squad_entries(08-19 갱신, 프리시즌 2경기 149분 cb_bpd/Aggressive 0.922) · prescriptions(2026-27 kind=measured, n=2, avg7.55, fit0.8648 / kind=measured:season:full2526, n=69, fit0.911) · player_duties(player_id=44 2026-08-23 ''좌측 후방 리더'' / player_id=45 코나테 2026-06-18 레알 마드리드 이적 공식 확정) · fotmob_detail_stats(Premier League 2025/2026, 43지표, pulled 2026-08-21 — 라인브레이킹패스·신체지표 6종 신규)','MEDIUM-HIGH — 26/27 실측 3경기(전경기 90분)로 이라올라 체제 편입 자체는 확인됐다. FC27 신체스탯(PAC/신장 하락)은 roster 1건 수집이라 추세 확정은 아니다. 코나테 이탈은 player_duties 서술로 확정되었으나 squad_entries(lh=OWNED 잔존) 등 일부 테이블에는 아직 미반영된 상태 — 교차 테이블 불일치 잔존.','2026-09-11','프리미어리그 센터백 중 제공권·걷어내기·배급량이 모두 모집단 1위권인, 이 표본에서 가장 극단적으로 강한 프로필이다. 공중 경합 승 174회와 걷어내기 275회, 성공한 패스 2485회, 터치 3261회가 모두 백분위 100이고 경합 승률 73.5%가 98, 공중 경합 승률 74.4%가 93이다. 세트피스 위협도 커서 득점 6골(100)·헤더 슛 23회(98)·xGOT 4.87(98)로 공격 산출까지 최상위다. 약점은 능동적으로 끊는 행동이다 — 태클 22회는 90분당 백분위 6, 인터셉트 28회는 18, 볼 회수는 10으로 단위 시간당 개입이 최하위권이고 총 실점 53골(1)도 낮다. 다만 90분당 출전 중 피xG는 79로, 실점 총량은 3420분을 뛴 결과이지 이 선수가 뛸 때 위험이 컸다는 뜻은 아니다. 공중볼과 배급을 축으로 두고, 앞으로 나가 끊는 역할은 옆의 센터백이나 미드필더에게 배분하는 배치가 맞다.');
INSERT INTO player_evaluations VALUES(35,3,45,'N/A(이적 확정) — 2026-06-18 레알 마드리드 자유이적 공식 완료(player_duties#45, 4년 계약)가 이제 서술이 아니라 확정 사실로 기재됐다. 26/27 리버풀 실측은 0행이며 player_matches에도 26-27시즌 클럽 경기 기록이 전혀 없다(World Cup 국가대표 1경기만 존재). 이 행은 ''26/27 RCB 슬롯의 과거 실측 기준선''으로만 보존.','전진 수비형 볼 플레잉 CB(cb_bpd/Aggressive, 25/26 RCB 기준 0.938). FC27 신규 스탯: player_game_stats에 2026-09-10 roster_date 행이 존재하지 않는다 — LIV 09-10 스쿼드 일괄 수집에서 제외됨. 이는 데이터 공백이 아니라 이적으로 LIV 로스터에서 빠졌다는 정황 증거로 해석한다(FC26 07-23 및 FC27 08-22/08-31 행까지는 존재, 09-10부터 소멸).','(과거 실측 기준) 대인 방어 강점 축 — 경합 승 220회(98백분위)·태클 53회(90백분위)·걷어내기 190회(83백분위). 약점은 파울 33회(6백분위)·경고 7장(10백분위)의 반칙 빈도. 이 강점·약점 평가는 25/26 리버풀 소속 시절 것으로, 26/27 현재는 평가 대상 실효성 자체가 소멸했다.','2026-09-11 갱신: v_player_matches 조회 결과 26/27 시즌 클럽(리버풀) 경기 0건 확인 — 2026-07-18 FIFA 월드컵 국가대표 1경기(45분, 평점 5.5)만 존재하고 그 이후 어떤 경기 기록도 없다. fotmob_detail_stats도 08-21 pulled 기준 여전히 ''2025/2026 Premier League''(리버풀 시절) 데이터만 보유, 26/27 신규 클럽 표본 없음. player_game_stats FC27도 2026-09-10 LIV 로스터 갱신에서 이름이 빠짐. 세 축(player_matches·fotmob·player_game_stats) 모두 독립적으로 ''리버풀 이탈''을 뒷받침한다.','MEDIUM — (교차 투영 — 실측 아님) cb_bpd 요구 자체는 정합이나 빌라의 ''동시 Aggressive 기각''(obs#13) 방침상 포커스 조정 전제. 이적 상태 미확정이라 실전 투영 의미 제한.','HIGH — (교차 투영 — 실측 아님) 알론소 백3 전원 cb_bpd/Aggressive 처방과 역할·포커스 완전 일치. 단 레알 이적이 사실이면 무의미한 투영.','N/A — player_duties(45, 2025-26 RCB 행)에 ''2026-06-18 레알 마드리드 자유이적 완료(4년, 2030까지) — 26/27 리버풀 스쿼드가 아니다''라고 명시적으로 기재되어 있다. 이라올라 체제 적합도 평가 자체가 무의미하며, 이 공백이 26/27 RCB 파트너 선발 과제(자케 89 기용)로 이어졌다.','squad_entries(r3, lh=OWNED — 불일치) · prescriptions#measured(RCB, n=6, 이탈 기재) · obs#69·#77·#120 · manager_profiles r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 42지표) · v_player_profile 0행 · prescriptions#measured(RCB n=6, 6.88) | 2026-09-11 갱신: player_matches(26/27 시즌 클럽 경기 0건, 월드컵 1건만 존재) · player_game_stats(FC27 roster_date 2026-09-10에 미등재 — FC26 07-23·FC27 08-22/08-31까지만 존재) · player_duties(player_id=45, 2026-06-18 레알 마드리드 이적 공식 완료 기재) · fotmob_detail_stats(08-21 pulled, 리버풀 시절 25/26 PL 데이터 그대로, 26/27 신규 표본 없음)','HIGH(이탈 확정) — player_duties 서술·player_matches 공백·player_game_stats 미등재 3개 독립 소스가 모두 일치. 단 squad_entries(lh=OWNED)는 여전히 갱신되지 않아 테이블 간 불일치가 잔존한다는 점은 이전과 동일 — 메인 세션에 squad_entries lh 필드 정정 필요 사항으로 보고.','2026-09-11','프리미어리그 센터백 중 경합에서 이기는 능력이 최상위권이고 반칙 빈도가 그만큼 높은, 정면 대결형 프로필이다. 경합 승 220회가 백분위 98, 경합 승률 69.0%가 91, 공중 경합 승 124회가 96, 공중 경합 승률 71.3%가 90으로 붙었을 때의 양과 질이 모두 상위 10% 안이다. 태클 53회(90)와 볼 회수 117회(89), 얻어낸 파울 41회(97)로 능동적 개입도 많고 성공한 패스 1943회(90)·터치 2638회(91)로 배급량도 충분하다. 약점은 규율이다 — 파울 33회가 백분위 6, 경고 7장이 10, 내준 PK 1회가 4로 최하위권이다. 총 실점 45골(11)은 낮지만 90분당 출전 중 피xG가 86이라, 실점 총량은 3100분 출전의 결과로 보는 편이 타당하다. 상대 공격수와 정면으로 맞붙는 자리에 두는 것이 맞고, 박스 안에서의 무리한 접촉을 줄이는 지시가 함께 필요한 프로필이다.');
INSERT INTO player_evaluations VALUES(36,3,46,'B — 갱신(2026-09-11): FC27에서 PAC−3/PAS+3/DEF+1/Press Proven 신규(OVR 80 유지)로 온볼·수비 기여형 재조정이 확인됐으나, **2026-27 시즌 공식전 출전 기록이 0행**(뉴캐슬·포레스트·입스위치 3경기 연속 미출전, 확인된 것은 프리시즌 친선 3경기뿐)이라는 것이 이번 갱신의 핵심 발견이다. 기존 등급 근거(미드필더의 RB 전용 실측 사례, fb_wingback/Support 0.843, RDM dm_dlp/Roaming 0.800 병립)는 25/26 표본으로 유지하되, 이라올라 체제 초반 기용 서열에서 밀려났을 가능성을 반영해 등급을 B+→B로 하향한다.','인버티드/하이브리드 RB — 풀백 자리에서 중앙 미드필드 지대로 드리프트하는 분포(RB 0.843과 RDM 0.800이 근접 병립). 오버래핑 크로서형이 아니라 안쪽 연결형. 2026-27 시즌 공식전 미출전(교체 후보에서도 배제) 상태 — 인버티드 RB/RDM 겸용 서사는 25/26 표본에 근거하며 이라올라 체제에서 아직 실증되지 않았다.','RB와 RDM 두 슬롯을 한 몸으로 커버하는 위치 다능성 — 인버티드 축 참고 표본으로 지정됨. 약점: 전방 질량이 낮아 공격 기여 상한이 제한적(''트렌트형은 전방 질량이 높아야 함'' — 실측 판정), 정통 윙백 폭 제공 능력 미검증.',unistr('Fotmob 25/26 PL 21.4경기(90분 환산, 41지표)에서 per90 백분위가 합계보다 뚜렷이 높다(터치 93.92 = 98백분위, 패스 성공 70.40 = 96백분위, 볼 회수 6.72 = 95백분위) — 출전 시간은 짧아도 뛰는 동안의 관여 밀도는 리그 동포지션 최상위라는 뜻이다. 세부 강점은 캐리와 배급이다: 드리블 성공 22회(91백분위)·성공률 64.7%(90백분위)·롱볼 정확도 68.1%(91백분위)·패스 정확도 91.6%(93백분위)·상대 박스 터치 51회(86백분위). 약점은 제공권으로, 공중 경합 승률 28.9%(4백분위)·공중 경합 승 11회(28백분위)가 리그 최하위 구간이며 인터셉트 18회(42백분위)·태클 40회(49백분위)로 파괴형은 아니다. 우리 자체 실측은 8/9 모나코 친선 미출전으로 player_matches 0행이라 3팀 풀 백분위는 여전히 산출 불가이고, 정량 근거는 그리드 RB 실측 6경기 평균 7.05(전임 슬롯 체제)뿐이다.\u000a\u000a2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10) vs FC26(2026-07-23) 비교 — OVR 80 동일, PAC 74→71(−3)·PAS 76→79(+3)·DEF 72→73(+1)·DRI 82→81(−1)·PHY 73→72(−1), 신규 PlayStyle ''Press Proven'' 부여(FC26엔 PlayStyles 미기재). SHO 74 불변. 몸무게 75kg 신규 기재(키 185cm 불변). 종합하면 EA는 그를 순간 스피드형에서 패스·수비 기여형으로 근소하게 재조정했다 — 팟몹 실측(온볼 지분 98백분위·공중 4백분위)의 방향과 부합. v_player_season_stats 조회 결과 **2026-27 시즌 공식전(PL 등) 행이 존재하지 않는다** — 있는 것은 ''Club Friendly Games'' n=3(평균 6.43)뿐이다. match_player_reports 대조: 8/16 선덜랜드(46분, 6.5)·렉섬(44분, 6.3)·리즈(44분, 5.2) 3경기 전부 프리시즌 친선 교체 출전이고 좌표·히트맵 미수집(SofaScore 403)이라 판정 보류로 기록돼 있다. 8/23 뉴캐슬·8/29 포레스트·9/4 입스위치 공식전 3경기 연속 미출전(match_player_reports·player_duties 2026-27 시즌 행 모두 부재) — 25/26 시즌 말 리그 선발 14경기·계약 1년 남음·타 클럽 관심(기존 duties#73)이라는 배경과 맞물려, 이라올라 체제 초반 로테이션에서 밀려난 정황이 실측으로 확인된다. v_player_profile 전체 커리어 집계(n=58, 3179분, 평균 6.85)는 25/26 전 대회 포함값이라 현 체제 판단 근거로 쓰지 않는다.'),'MEDIUM-HIGH — (교차 투영 — 실측 아님) 에메리 C2는 RB 잔류형(fb_wingback/Balanced — 캐시 축)을 요구하는데 존스의 실측이 정확히 잔류·연결형 fb_wingback/Support 0.843이다. 낮은 전방 질량이 여기서는 결함이 아니라 요건.','LOW-MEDIUM — (교차 투영 — 실측 아님) 알론소 윙백은 ''크로서가 아니라 득점자''로 폭을 독점(obs#46)하는 전진형 — 존스의 낮은 전방 질량(0.26)과 정면 상충. 반면 하이브리드 RDM(리스 제임스 축, dm_dlp) 투영이라면 RDM 0.800이 근거가 되나 실측은 RB 슬롯 표본.','MEDIUM-LOW — ⚠️ 갱신(2026-09-11): 이라올라 풀백은 낮고 빠른 얼리크로스의 크로서(obs#67)를 요구하는데 존스의 크로스 정확도 21백분위·공중 4백분위는 정면 상충한다는 기존 판정에 더해, **2026-27 공식전 3경기(뉴캐슬·포레스트·입스위치) 연속 미출전**이 실측으로 확인됐다 — 로테이션 밖으로 밀렸을 가능성. 다만 상대 풀백 인버트 시 중앙 미드가 따라 올라가는 맨마킹 체계(obs#68)에서 위치 다능성 자체는 여전히 자산이며, 26/27 RB 슬롯 주인 미정 지위도 서류상 유효하다.','squad_entries(r3) · prescriptions#measured(RB, n=6, ⭐) · obs#67·#68·#120 · manager_profiles r1/r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표) · v_player_profile 0행 · prescriptions#measured(RB n=6, 7.05) | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-09-10) · v_player_season_stats(2026-27 행 부재 확인) · match_player_reports(뉴캐슬·포레스트·입스위치 미출전 확인)','MEDIUM — RB 표본 6경기는 성립하나 전임 체제 것이고, 본직(미드필드) 실측은 이 체제 표본에 없음. | 2026-09-11: 2026-27 공식전 미출전 확인(표본 자체가 0) — 이라올라 체제 실측은 여전히 전무.','2026-09-11','프리미어리그 미드필더 중 단위 시간당 공을 다루는 양이 최상위이고 공중볼에서는 최하위인, 발로 하는 일에 전부 몰린 프로필이다. 1932분 표본에서 90분당 백분위가 총량보다 높게 나오는데, 90분당 터치 93.92회가 백분위 98, 성공한 패스 70.40회가 96, 볼 회수 6.72회가 95로 최상위다. 패스 정확도 91.6%(93)·롱볼 정확도 68.1%(91)·드리블 성공률 64.7%(90)로 정확도와 돌파 성공률이 함께 높고, xG 2.77(90분당 89)과 상대 박스 터치(88)로 전진해 슛까지 만든다. 약점은 공중 경합 승률 28.9%로 백분위 4, 공중 경합 승도 90분당 12라는 점이다. 경합 승률 50.7%(40)와 태클(90분당 35)도 평범해 몸으로 끊는 역할에는 맞지 않는다. 공이 발밑에 오는 중원 자리에 두고 제공권과 파괴는 다른 인원에게 맡기는 것이 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(37,3,47,'B — 갱신(2026-09-11): FC27 PAC−3·PHY−1(OVR 81 유지)에 Whipped Pass·Slide Tackle·Rapid PlayStyles 신규 부여. 핵심 변화는 리버풀 실측 표본이 n=2(6.15)에서 **26/27 공식전 n=3·251분·평균 6.54**로 확장되고 전 경기 선발 고정된 점 — 이라올라 체제 좌측 풀백 1선발이라는 지위가 실측으로 확인됐다. 등급을 B−→B로 상향한다.','전진형 공격 윙백(fb_att_wb/Support 0.799, 차2 fb_wingback/Balanced 0.700). 본머스 시절 프로필은 낮고 빠른 얼리크로스 반복 공급자 — 이라올라의 리허설된 패턴의 실행자였다(obs#67). FC27 PlayStyles Whipped Pass·Slide Tackle·Rapid 부여 — 게임 능치가 실측 문법(얼리크로스+태클)을 그대로 반영.','이라올라 축구를 본머스에서 직접 소화한 스쿼드 유일 자원(obs#76의 본머스 유출 명단 당사자) — 전술 이식의 살아있는 매개. 약점: 리버풀에서의 실측이 2경기뿐이고 그 평균(6.15)도 낮다. 부상 이력(3~5월 결장)이 고주행 체제(총주행 리그 1위 팀 — obs#73)에서 재발 리스크.',unistr('Fotmob 25/26 PL 25.1경기(90분 환산, 40지표)가 n=2짜리 그리드 실측(LB 평균 6.15)의 공백을 메운다. 몸싸움은 좋다 — 경합 승률 59.1%(82백분위)·얻어낸 파울 30회(83백분위)·공중 경합 승 33회(73백분위)·제쳐당함 10회(58백분위/per90 88백분위). 전진 기여는 기회 창출 26회(74백분위)·성공한 크로스 15회(71백분위)·드리블 성공률 54.5%(81백분위)로 중상위인 반면 최종 산출은 xA 0.70(32백분위)·어시스트 1회(38백분위)로 뚝 떨어져, 올라가기는 하되 결정적 패스로 마무리되는 비율이 낮다. 수비 총량도 인터셉트 14회(40백분위)·수비적 행동 134회(57백분위)로 평범하다. 우리 자체 실측은 8/9 모나코 친선 미출전(player_matches 0행)이라 3팀 풀 백분위 산출 불가이며, 이 Fotmob 표본은 리버풀 첫 시즌 기록이다.\u000a\u000a2026-09-11 갱신: player_game_stats FC27(2026-09-10) vs FC26(2026-07-23) — OVR 81 동일, PAC 87→84(−3)·PHY 80→79(−1), SHO/PAS/DRI/DEF(59/75/78/76) 불변. 신규 PlayStyles 3종: Whipped Pass·Slide Tackle·Rapid — 낮고 빠른 크로스(obs#67 본머스 실측 문법)와 태클 강조가 게임 능치로도 반영됐다. 몸무게 71kg 신규 기재. squad_entries·prescriptions 재확인: 리버풀 실측이 8/11 시점 n=2(6.15)에서 **26/27 공식전 3경기(뉴캐슬·포레스트·입스위치) n=3·251분·평균 6.54**로 갱신됐다(prescriptions kind=measured, 2026-09-06 개정, fb_att_wb/Support 0.9339) — 표본 부족 경고는 여전하나(Δ≤.05 노이즈 구간 명기) n=2→3으로 소폭 개선. v_player_season_stats 2026-27: PL 3경기(전 선발) 평균 6.54, Club Friendly 5경기 평균 6.78 — 부상 복귀 후 이라올라 체제에서 즉시 1선발 고정. match_player_reports 3경기 상세: 뉴캐슬(90분 6.32, 엘랑가 역습 허용), 포레스트(71분 6.5, 무뇨스와 연계 미형성 — ESPN 5), 입스위치(90분 6.8, 이라올라 체제 첫 승 — FC26 LB 단일경기 fit 0.8945). 8/16 코모 2차전 친선에서도 좌측 윙백 90분 7.1·크로스 4/1·패스 36/31·fit .864로 이라올라 체제 문법(낮은 크로스 반복 공급)에 정합적.'),'MEDIUM — (교차 투영 — 실측 아님) 에메리 C2 좌측은 전진 담당(LB fb_att_wb/Support — 디뉴 축)이라 역할 문자열은 정확히 일치. 단 리버풀 실측 n=2로 판단 재료 부족.','MEDIUM — (교차 투영 — 실측 아님) 알론소 좌 윙백은 인선 공백 슬롯(r2 formation)이고 요구는 ''폭 독점 + 득점자''(obs#46) — 크로서형인 케르케즈와 득점 요건이 어긋난다. 폭 공급 축만 부분 정합.','HIGH — 갱신(2026-09-11): 26/27 공식전 3경기(뉴캐슬·포레스트·입스위치) 연속 선발·251분으로 이라올라 체제 1선발 LB로 확정됐다(기존 ''리버풀 이식 후 재현은 검증 대상'' 유보 해소 진행 중). 평균 6.54·fb_att_wb/Support 0.9339로 본머스 시절 프로필(크로서형)이 리버풀에서도 유지된다는 정황. 다만 표본 3경기라 Δ≤.05 구간은 여전히 인선 근거로 못 쓴다(prescriptions 명기). 포레스트전 무뇨스와의 좌측 연계 미형성(ESPN 5)은 이식 초기 조율 이슈로 남는다.','squad_entries(r3) · prescriptions#measured(LB, n=2 — 표본 심각 부족) · obs#67·#76 · manager_profiles r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 40지표) · v_player_profile 0행 · prescriptions#measured(LB n=2, 6.15) | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-09-10) · prescriptions(measured LB n=3, 2026-09-06 개정) · match_player_reports(뉴캐슬·포레스트·입스위치·코모2차전) · v_player_season_stats(2026-27 PL n=3)','MEDIUM — 이라올라 핏 근거는 본머스 실측 기반으로 상대적으로 강하나, 리버풀 자체 표본은 n=2로 매우 약함. | 2026-09-11: 리버풀 자체 표본 n=2→3(251분)으로 소폭 개선, 전 경기 선발 고정 확인. 여전히 소표본.','2026-09-11','프리미어리그 풀백 중 뚜렷한 최상위 강점 없이 대부분 준상위에 걸쳐 있는, 균형형이지만 특화가 없는 프로필이다. 좋은 축은 몸싸움과 전진이다 — 경합 승률 59.1%가 백분위 82, 얻어낸 파울 30회가 83, 드리블 성공률 54.5%가 81이고 기회 창출 26회(74)·성공한 크로스 15회(71)·상대 박스 터치 43회(71)로 공격 관여도 준상위다. 득점 2골(81)과 xG 1.59(77)로 직접 마무리에도 가담했다. 약점은 최종 패스의 질과 수비 개입 빈도다 — xA 0.70이 백분위 32(90분당 12)로 크로스가 기회로 연결되는 정도가 낮고, 크로스 정확도 19.0%(40)·롱볼 정확도 34.1%(39)도 평범 이하다. 90분당 기준 태클(24)·수비적 행동(19)·인터셉트(18)가 하위권이라 측면에서 끊어내는 양도 많지 않다. 전진해 크로스를 올리는 역할은 가능하지만 그 결과물의 질은 기대치를 낮춰야 하고, 수비 안정은 중앙 쪽에서 보완해야 하는 프로필이다.');
INSERT INTO player_evaluations VALUES(38,3,48,'B− — 갱신(2026-09-11): FC27 OVR 82→81(−1)·DRI−2·PHY−1, PlayStyles Rapid·Quick Step+ 신규. 리버풀 실측 n=4(6.42)에서 n=2(6.47, 161분)로 갱신됐으나 **입스위치전 결장**이 새로 확인돼 표본이 확대되지 않았다 — 포레스트전 ESPN 팀 최저 평점(수비 국면 노출)까지 겹쳐 기존 ''공격 100/수비 0의 양극단'' 판정이 시즌 초반 실전에서도 유지된다. 등급 B 유지에서 B−로 소폭 하향.','극단적 전진형 우측 자원 — RB 라벨이지만 질량이 윙어 지대에 쏠린다(전방 0.54). regime3 traits 축도 ''인버티드 RB(프림퐁 fb_inverted 성향 실측)''로 기록. 8/9 모나코 친선에서도 RB 75분 소화. FC27 PlayStyles Rapid·Quick Step+ 신규 — 극단적 스피드·가속 특화가 능치로 명문화됐다.','우측에서 RB~RM 대역을 하나로 잇는 공격 전개력 — 살라 이탈 기재 후 우측 공격 질량의 내부 대안이기도 하다. 약점: 자기진영 질량 0.28로 수비 국면 잔류 신뢰도가 실측상 낮음 — 뒷공간 노출형. 표본 4경기로 확정 판단 불가.',unistr('Fotmob 25/26 PL 11.5경기(90분 환산, 39지표)로 대상 중 표본이 가장 짧아 합계/per90 백분위가 크게 갈린다 — 기회 창출 15회(50백분위 vs per90 85백분위)·xA 1.58(52 vs 88)·빅찬스 창출 5회(77 vs 94)·드리블 성공 18회(79 vs 96). per90 기준으로는 리그 최상위 침투형 풀백이며, 상대 박스 터치 69회(89백분위/per90 100백분위)·상대 진영 볼 탈취 9회(81/98백분위)가 그 성격을 못박는다. 반대로 수비는 어느 기준으로도 최하위다 — 수비적 행동 30회(18/1백분위)·태클 11회(19/5백분위)·인터셉트 6회(20/12백분위)·걷어내기 13회(15/0백분위). 우리 자체 실측은 8/9 모나코 친선 1경기(RB 75분, 평점 6.10, 3팀 풀 평점 백분위 0%)와 그리드 4경기 평균 6.42뿐이며 n=1 평점은 서열 근거가 되지 못한다 — 두 백분위의 충돌은 표본 크기 문제로 읽어야 한다.\u000a\u000a2026-09-11 갱신: player_game_stats FC27(2026-09-10) vs FC26(2026-07-23) — OVR 82→81(−1)·DRI 84→82(−2)·PHY 63→62(−1), PAC 94·SHO 62·PAS 74·DEF 72 불변. 신규 PlayStyles: Rapid·Quick Step+ — 속도·가속 특화가 게임 능치로 재확인. 몸무게 65kg 신규 기재. squad_entries·prescriptions 재확인: 리버풀 실측이 8/11 시점 n=4(6.42)에서 **26/27 공식전 2경기(뉴캐슬·포레스트) n=2·161분·평균 6.47**로 갱신(2026-09-06 개정, fb_att_wb/Support 0.9387). ⚠️ 9/4 입스위치전 출전 기록이 없다 — v_player_season_stats 2026-27 PL n=2(starts=2)로 멈춰 있고 match_player_reports에도 입스위치 행이 없다. 기존 duties#75의 ''햄스트링 반복 부상''·''구단이 RB 1선발로 쓰지 않으려 한다''는 서사와 일치하는 결장 패턴으로 읽힌다 — 재발 여부는 명시 확인되지 않아 추정임을 밝힌다. match_player_reports 상세: 뉴캐슬(90분 6.74, 슛1·찬스3), 포레스트(71분 6.2 — ESPN 팀 최저 4/10, 선제골 시 포지션 이탈, fit .911은 좋으나 수비 국면 노출). 8/16 코모 2차전 친선에서 우측 윙백 90분 8.1·어시스트1·빅찬스창출1·fit .856으로 최고 퍼포먼스.'),'LOW-MEDIUM — (교차 투영 — 실측 아님) 에메리 RB는 잔류형(fb_wingback/Balanced, C2 제약 — 풀백은 한 명씩만 전진)이라 프림퐁의 전진 일변 분포와 상충. 우측 와이드(RM)로 쓴다면 뱅크 복귀형(wm_widemid/Support) 요구가 다시 걸림돌.','HIGH — (교차 투영 — 실측 아님) 알론소 윙백은 ''크로서가 아니라 득점자''로 폭을 독점(obs#46) — 전방 질량 0.54의 전진형 윙백은 이 문법의 원형에 가깝다. 레버쿠젠 시절 알론소 아래 뛴 이력도 있으나 본 DB에 그 실측은 없음.','MEDIUM — 갱신(2026-09-11): 26/27 공식전 2경기(뉴캐슬 6.74·포레스트 6.2)에서 fit 0.9387~0.911로 커널 정합은 높지만, 포레스트전 ESPN 팀 최저 평점(선제골 시 포지션 이탈)이 기존 ''수비 결손 노출''(duties#75) 서사를 실전에서 재확인시켰다. **9/4 입스위치전 결장**이 공식 기록·리포트 어디에도 등장하지 않아 — 기존 햄스트링 반복 부상 이력(duties#75)과 겹쳐 재발 가능성을 배제할 수 없으나 사유는 미확인이다. 구단 방침(''프림퐁에게 RB 50경기를 원하지 않는다'' — duties#75)과 결합하면 로테이션 자원 지위가 유지된다.','squad_entries(r3) · prescriptions#measured(RB, n=4 — 표본 부족) · v_player_profile(n=1) · obs#67·#72·#120 · manager_profiles r1/r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 39지표) · v_player_profile n=1(8/9 모나코 친선) · prescriptions#measured(RB n=4, 6.42) | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-09-10) · prescriptions(measured RB n=2, 2026-09-06 개정) · match_player_reports(뉴캐슬·포레스트·코모2차전, 입스위치 행 부재 확인) · v_player_season_stats(2026-27 PL n=2)','MEDIUM — 신·구 커널 값이 유형 서술(전진형)에서는 수렴하나 역할 라벨이 갈렸고(fb_inverted vs fb_att_wb), 표본 4경기. | 2026-09-11: 리버풀 자체 표본 n=4→2(입스위치 결장으로 확대되지 못함). 결장 사유 미확인 — 추정 표기.','2026-09-11','프리미어리그 풀백 중 1035분 표본이라 90분당 백분위로 읽어야 하고, 그 기준에서는 사실상 윙어에 가까운 극단적 공격 편중 프로필이다. 90분당 상대 박스 터치 5.98회가 백분위 100, 드리블 성공 1.56회가 96, 상대 진영 볼 탈취 0.78회가 98, 빅찬스 창출 0.43회가 94, 얻어낸 파울 1.82회가 92로 전진 관여가 최상위다. 수비는 거의 비어 있다 — 90분당 걷어내기가 백분위 0, 수비적 행동이 1, 태클이 5, 인터셉트가 12로 자기 진영 개입이 최하위이고 공중 경합 승률 41.2%(20)·경합 승률 48.3%(24)로 붙었을 때의 승률도 낮다. 긴 패스도 약해 롱볼 정확도 28.0%가 백분위 17이다. 마무리 결과는 없어 득점 0골에 90분당 xGOT 백분위 36에 그친다. 3선이 아니라 공격 3선의 일원으로 취급해 측면 높은 자리에 두고, 그 뒤 공간은 다른 수비 인원이 메우는 전제가 필요한 프로필이다.');
INSERT INTO player_evaluations VALUES(39,3,49,'B− — 갱신(2026-09-11): FC27 OVR 86→85(−1), PAC+3·DRI 일시 하락 후 회복, PlayStyles Intercept·First Touch·Press Proven 신규(캐리·인터셉트 강점과 정합). 핵심 변화는 **26/27 PL 3경기 중 선발 1회(뉴캐슬)뿐이고 이후 2경기는 교체(19분·26분)**라는 점 — 맥알리스터에게 선발 피벗 한 자리를 내준 로테이션 양상이 실측으로 확인됐다. 뉴캐슬전 자체 퍼포먼스(7.38·어시스트1)는 나쁘지 않았으나 D+3 분석이 실점 관여를 지적한 점도 함께 반영해 등급을 B→B−로 하향한다.','박스-투-박스 대칭형 피벗 — 전후방 질량이 정확히 균형(0.38/0.38). ⚠️ obs#120 ⓑ: 피벗 3인(흐라벤베르흐·소보슬라이·맥알리스터)이 전부 dm_dlp/Roaming으로 나와 움직임만으로는 기능 분화가 안 보이며, 리버풀 기능축 실측(appearances·player_match_positions)이 0행이라 이 분화를 가릴 수단이 없다 — 본 평가의 역할 서술은 이 한계 안에서 읽어야 한다. 2026-27 초반 PL 3경기 중 선발 1회(뉴캐슬)뿐 — 포레스트·입스위치는 교체 투입(19분·26분)으로, 맥알리스터에게 선발 피벗 자리를 내준 로테이션 양상.','전천후 커버 범위와 운반 — 대칭 분포가 시사하는 왕복 능력. 친선이지만 KP 2·태클 1·인터셉트 2·어시스트 1의 전방위 기여. 약점: 어느 역할 커널에도 강하게 맞지 않음(최고 0.689) — 특화 부재가 곧 프로필. FC26 스탯 미수집. FC27 신규 PlayStyle Intercept·First Touch·Press Proven이 캐리·인터셉트 강점(팟몹 96/95백분위)과 정합. 약점: 26/27 시즌 선발 빈도 하락(PL 3경기 중 선발 1회) — 로테이션 지위 하락 정황.',unistr('Fotmob 25/26 PL 33.3경기(90분 환산, 38지표)에서 전진 캐리와 차단이 동시에 상위다 — 드리블 성공 32회(96백분위)·인터셉트 48회(95백분위)·유효슛 13회(90백분위)·득점 5골(91백분위)·xGOT 3.09(89백분위)·경합 승 160회(86백분위). 배급 총량도 패스 성공 1653회(94백분위)·터치 2367회(93백분위)로 높다. 단 한 칸이 극단적으로 낮은데 롱볼 정확도 31.5%(5백분위, 정확한 롱볼 23회 = 40백분위)로, 장거리 전환 패스는 리그 미드필더 중 최하위다 — 짧은 전진은 발로 하고 긴 전환은 남에게 맡기는 유형. 우리 자체 실측은 8/9 모나코 친선 1경기(59분 평점 7.30, 인터셉트 2)뿐이고 3팀 풀 백분위(평점 83·인터셉트 91)는 n=1 산물이라 서열 의미가 없으며, 그리드 LDM 6경기 평균 6.77도 전임 체제 표본이다.\u000a\u000a2026-09-11 갱신: player_game_stats FC27(2026-09-10) vs FC26(2026-07-23) — OVR 86→85(−1)·DRI 86→83(−3, 08-31 이후 회복)·SHO 77→76(−1), PAC 76→79(+3)·PAS 81 불변. 신규 PlayStyles 3종: Intercept·First Touch·Press Proven — 인터셉트 강점(팟몹 95백분위)이 게임 능치로 명문화. 몸무게 77kg 신규 기재. prescriptions 재확인: 26/27 공식전 3경기 누적 — 뉴캐슬(78분 선발 LDM, 7.38, 어시스트1) · 포레스트(19분 교체, 6.6, 분 미달로 fit 참고치 .787만 기록) · 입스위치(26분 교체 RDM, 6.6, fit .7536). v_player_season_stats 2026-27 PL: n=3·starts=1(뉴캐슬만 선발, 포레스트·입스위치는 교체) — **25/26 부동의 주전에서 로테이션 자원으로 격하된 정황**이 실측으로 드러난다. 8/23 뉴캐슬전 D+3 Coaches'' Voice 분석(player_duties#169): 빌드업에서 커버섀도 밖 수신은 유효했으나 첫 실점이 중앙 이탈 뒤 차단당한 패스가 직접 원인 — Roaming의 위험 관리가 과제로 명시됐다.'),'MEDIUM — (교차 투영 — 실측 아님) 에메리 더블 피벗 처방은 dm_holding(Roaming/Defend 분담) — 흐라벤베르흐의 차2가 dm_holding/Roaming(0.525)이나 값이 낮아 정합 주장 불가. 대칭형 왕복은 뱅크 복귀 규율과는 무난.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 알론소 하강 피벗(카이세도 dm_dlp/Roaming — r2 implementation)과 역할·포커스 문자열이 일치. 단 박스 미드필드 중앙 볼 상실 리스크(r2 rest_defense)상 기술 규율 요구가 극단적으로 높다는 유보 조건 동반.','MEDIUM — 갱신(2026-09-11): 뉴캐슬 선발 78분·7.38(어시스트1)로 강한 인상을 남겼으나 D+3 분석(Coaches'' Voice)이 중앙 이탈 뒤 실점 관여를 지적했고, 이후 포레스트·입스위치 2경기는 교체(19분·26분)에 그쳐 **맥알리스터가 선발 피벗 한 자리를 가져간 로테이션**이 확인된다. 이라올라의 맨마킹 체계(obs#68·#69)·리그 1위 주행량(obs#73) 요구와 대칭 왕복형 분포 자체는 여전히 방향이 맞으나, 기능축 분화(맥알리스터=슈팅/박스진입, 흐라벤베르흐=캐리/인터셉트 — 08-31 duties 언급)가 선발 서열에 실제로 반영되고 있을 가능성.','squad_entries(r3) · prescriptions#measured(LDM, n=6) · v_player_profile(n=1) · obs#68·#69·#73·#120ⓑ · manager_profiles r1/r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 38지표) · v_player_profile n=1(8/9 모나코 친선) · prescriptions#measured(LDM n=6, 6.77) | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-09-10) · match_player_reports(뉴캐슬·포레스트·입스위치 3경기, 선발 1회 확인) · player_duties#169(Coaches'' Voice D+3) · v_player_season_stats(2026-27 PL n=3 starts=1)','MEDIUM — 실측 6경기는 성립하나 전임 체제 표본 + 기능축 미수집(obs#120ⓑ)으로 역할 분화 판정 불가. | 2026-09-11: 26/27 공식전 3경기 확보(선발1·교체2) — 선발 빈도 하락은 표본 3경기 초반값이라 확정 판단은 유보.','2026-09-11','프리미어리그 미드필더 중 공을 몰고 나가는 능력과 공을 끊는 능력을 함께 갖췄고, 긴 패스만 뚜렷하게 약한 프로필이다. 드리블 성공 32회가 백분위 96, 인터셉트 48회가 95, 성공한 패스 1653회가 94, 터치 2367회가 93으로 소유와 회수 지표가 나란히 상위권이다. 마무리 가담도 유효슛 13회(90)·xGOT 3.09(89)·득점 5골(91)로 상위 10% 부근이다. 약점은 긴 패스다 — 롱볼 정확도 31.5%가 백분위 5로 최하위이고 정확한 롱볼도 90분당 10에 그쳐, 뒤에서 길게 넘기는 전환에는 쓸 수 없다. 볼 뺏김 26회(14)와 파울 38회(17)도 하위권이다. 짧은 패스와 드리블로 압박을 벗어나 전진하는 역할, 즉 중원에서 공을 운반하는 자리에 두고 장거리 전환은 다른 선수에게 맡기는 것이 맞다.');
INSERT INTO player_evaluations VALUES(40,3,50,'B — 갱신(2026-09-11): FC27 OVR 85→84(−1), PAC −5(최대 하락폭)로 스피드 저하가 게임 능치에 반영됐고 Power Shot·Pinged Pass·Block·Game Changer 4종 PlayStyles 신규. 26/27 PL 3경기 중 선발 2회로 흐라벤베르흐 대비 더블 피벗 경쟁 우위가 실측으로 확인됐으나, 포레스트전 duel 6승10패로 대인 수비 약점이 실점으로 직결되는 장면이 재현됐다 — 기존 ''박스 진입·슈팅형, 대인 수비 최하위권'' 판정이 시즌 초반 실전에서도 그대로 유지된다. 등급 B 유지.','딥라잉 플레이메이커 — 커널 정합 0.890은 피벗 중 뚜렷한 최고(흐라벤베르흐 0.689·소보슬라이 0.674와의 Δ0.2는 노이즈 범위 밖). 전방 0.33/자기진영 0.37로 후방 연결 중심. obs#120 ⓑ의 기능축 0행 한계는 동일 적용 — 움직임 커널만으로는 ''무엇을 했는지''(배급/탈압박/수비)를 못 가린다. FC27 PAC −5(5항목 중 최대 하락)로 스피드 저하가 게임 능치에도 반영. 신규 PlayStyles Power Shot·Pinged Pass·Block·Game Changer.','피벗 커널 정합 팀 내 최고(0.890) — dlp 역할 배치 시 구조 리스크가 가장 낮은 미드필더. 약점: 실측 평균 6.64는 피벗 3인 중 최저이고 표본도 5경기 — 정합도와 산출이 어긋나는 표본. 8/9 친선 미출전으로 최신 폼 데이터 없음.',unistr('Fotmob 25/26 PL 29.6경기(90분 환산, 41지표)는 ''슛으로 마감하는 미드필더'' 쪽을 가리킨다 — 슛 52회(96백분위)·xG 3.89(95백분위)·유효슛 12회(89백분위)·상대 박스 터치 65회(98백분위)·헤더 슛 14회(98백분위)·크로스 정확도 45.0%(93백분위). 반면 몸싸움과 볼 간수가 뚜렷한 약점이다: 경합 승률 45.2%(11백분위)·제쳐당함 40회(6백분위)·볼 뺏김 29회(10백분위)·드리블 성공률 40.7%(28백분위). 수비 총량은 태클 53회(68백분위)·인터셉트 21회(56백분위)로 중위권이며 per90으로는 더 내려간다(28·21백분위). 우리 자체 실측은 8/9 모나코 친선 미출전으로 player_matches 0행이라 3팀 풀 백분위 산출 불가이고, 그리드 LDM 5경기 평균 6.64(표본 부족·전임 체제)가 유일한 자체 근거였다.\u000a\u000a2026-09-11 갱신: player_game_stats FC27(2026-09-10) vs FC26(2026-07-23) — OVR 85→84(−1)·PAC 66→61(−5)·PHY 76→74(−2), SHO 82→81(−1)·PAS 84→83(−1)·DEF 77 불변. 신규 PlayStyles 4종: Power Shot·Pinged Pass·Block·Game Changer — 슈팅·중거리 패스·수비 개입이 함께 능치화(팟몹 슈팅 96·크로스 정확도 93백분위와 정합, 반면 경합 승률 11백분위 약점은 그대로). 몸무게 72kg 신규 기재. PAC −5는 5개 항목 중 최대 하락폭 — 25/26 ''반응이 느렸다''(duties#77) 서사와 함께 읽으면 EA도 스피드 저하를 반영한 것으로 보인다. match_player_reports 26/27 3경기: 뉴캐슬(27분 교체 CAM, 6.57) · 포레스트(77분 선발 RDM, 7.2 — 패스59/52·xA .39·듀얼 6승10패·태클3, fit dm_dlp/Roaming .816, 단 Igor Jesus에게 피지컬로 밀려 선제골 직접 원인) · 입스위치(84분 선발 LDM, 6.8, fit .7535). v_player_season_stats 2026-27 PL: n=3·starts=2(포레스트·입스위치 선발, 뉴캐슬 교체) — 흐라벤베르흐(선발 1회)보다 선발 빈도가 높아 **더블 피벗 경쟁에서 우위**를 점한 정황. 포레스트전 duldeul 6승10패(경합 승률 37.5%)는 기존 ''경합 승률 45.2%(11백분위)가 최하위'' 판정을 실전에서도 재확인 — Igor Jesus에게 밀린 장면이 docs/12 obs#69(맨마킹 체계 개인 듀얼 의존)가 역방향으로 처벌받은 사례로 기록됐다.'),'MEDIUM — (교차 투영 — 실측 아님) 에메리 피벗 처방은 dm_holding 계열 — dlp 특화형과 역할 문자열 불일치. 자유 10번(cam_playmaker/Roaming — 부엔디아·맥긴 축) 투영이 대안이나 실측 표본은 DM 슬롯 것.','HIGH — (교차 투영 — 실측 아님) 알론소 하강 피벗 카이세도 처방이 정확히 dm_dlp/Roaming — 역할·포커스 완전 일치에 정합도 0.890. 백라인 옆으로 내려와 압박을 유인하는 빌드업 축의 커널 원형. 단 박스 미드필드의 볼 상실 리스크(r2 rest_defense) 유보 동일.','MEDIUM-HIGH — 갱신(2026-09-11): 26/27 PL 3경기 중 선발 2회(포레스트·입스위치)로 흐라벤베르흐(선발 1회)보다 높은 기용 빈도가 확인돼 기존 ''점유형 딥라잉 배급자 가치 감소'' 우려와 달리 실측 서열에서는 앞선다. 다만 포레스트전 duel 6승10패(37.5%)로 Igor Jesus에게 밀려 실점에 직접 관여한 장면이 기록돼, 이라올라의 맨투맨 락온 압박(obs#68)에서 개인 듀얼 승률 약점(기존 11백분위 판정)이 그대로 리스크로 실현됐다. 전방 질량이 낮다는 기존 유보는 완화됐으나(슈팅·크로스 정확도 강점이 포레스트전 패스량 59회로 재확인), 경합 약점은 여전히 핵심 리스크.','squad_entries(r3) · prescriptions#measured(LDM, n=5 — 표본 부족) · obs#66·#68·#120ⓑ · manager_profiles r1/r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표) · v_player_profile 0행 · prescriptions#measured(LDM n=5, 6.64) | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-09-10) · match_player_reports(뉴캐슬·포레스트·입스위치, 선발 2회 확인) · v_player_season_stats(2026-27 PL n=3 starts=2)','MEDIUM — 커널 값 확정적(0.890), 산출(6.64)과의 괴리 및 기능축 미수집이 유보 사유. | 2026-09-11: 26/27 공식전 3경기 확보(선발2·교체1) — 흐라벤베르흐 대비 선발 우위 확인, 여전히 초반 소표본.','2026-09-11','프리미어리그 미드필더 중 박스 안까지 들어가 슛을 만드는 공격 편중 프로필이고, 대인 수비에서는 이 모집단 최하위권이다. 상대 박스 터치 65회가 백분위 98, 헤더 슛 14회가 98, 슛 52회가 96, xG 3.89가 95로 마무리 지역 지표가 최상위이고 기회 창출 35회(86)·어시스트 4개(85)·크로스 정확도 45.0%(93)로 만들어 주는 쪽도 상위권이다. 약점은 뚜렷하다 — 제쳐당한 횟수 40회가 백분위 6, 경합 승률 45.2%가 11, 볼 뺏김 29회가 10으로 몸싸움과 공 관리가 최하위이고 90분당 수비적 행동(12)·볼 회수(21)로 회수 기여도 낮다. 공중 경합 승률 45.9%(43)는 평범하다. 뒤를 지키는 미드필더를 반드시 붙이고, 박스 진입과 슈팅을 담당하는 전진 미드필더 자리에 두는 배치가 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(41,3,51,'B+ — 26/27 이라올라 체제 공식전 실측 개시(prescriptions#measured, 2026-09-06 R3·R4 갱신): RDM 포지션-순수 3경기(뉴캐슬·노팅엄포레스트·입스위치) 270분 평균 7.52 — LIV 4명 중 최고. 커널 dm_dlp/Roaming 0.5959(프리시즌 전용값 0.744보다 하락, 표본 3경기라 Δ≤.05는 인선 근거로 안 씀). 8/29 노팅엄전 74분 이후 RB로 이동한 임무 전환이 25/26(player_duties id=78 ''미드필더이면서 RB 10경기'')과 정합적으로 재현됐다. FC27(2026-09-10) OVR 86 유지(PAC 81→82, DEF 73→74), 신규 PlayStyles 6종(Power Shot·Dead Ball·Long Ball Pass·Whipped Pass·Technical·Relentless+) 최초 수집 — 세트피스·장거리 배급 자원 서사와 정합.','전진형 하이브리드 겸 유틸리티 피벗 — DM 라벨이 최적이지만 전방 질량 0.49의 박스 침입 성향(신커널 차2 dm_boxcrasher와 정합). 공식전에서는 RDM 기본 배치에 경기 중 RB 전환까지 겸한다(8/29 노팅엄전 74분~ 프림퐁 대체, 케르케즈·프림퐁·각포 3중 교체와 동시). FC27 신규 PlayStyles(Power Shot·Dead Ball·Long Ball Pass·Whipped Pass)가 프리킥·장거리 배급 강점을 능력치 축에서도 확인시킨다.','공식전 표본 확보 — RDM 3경기 평균 7.52로 LIV 4명 중 최고(prescriptions#measured 09-06 갱신). 노팅엄전 90분 완주·터치 117(팀 2위)·패스 성공률 91%로 RB 이동 후에도 관여 유지. FC27 09-10 PAC 82(+1)·DEF 74(+1) 소폭 상승, PlayStyles 6종 신규 확보. 약점: 신·구 커널 값 괴리(구 0.812→신 0.674→공식전 0.5959)가 여전히 좁혀지지 않았고, 공식전 표본 3경기는 확정 판단에 이르다.',unistr('Fotmob 25/26 PL 35.9경기(90분 환산, 41지표)에서 우리 대상 25명 중 100백분위 칸이 가장 많다 — 성공한 크로스 68회(100백분위)·인터셉트 30회(100백분위)·수비적 행동 339회(100백분위)·볼 회수 187회(100백분위)·걷어내기 58회(100백분위)·터치 2996회(100백분위), 여기에 기회 창출 78회(98백분위)·정확한 롱볼 130회(98백분위)·xA 6.81(95백분위)·어시스트 7회(95백분위). 다중 슬롯 순회 실측과 정확히 겹치는 지문으로, 공수 어느 축에서도 총량이 리그 최상단이다. 약점은 대인 유지력과 규율이다 — 제쳐당함 39회(2백분위)·파울 41회(5백분위)·경고 8장(3백분위)·퇴장 1회, 경합 승률 45.8%(67백분위)는 총량 대비 평범하다. 우리 자체 실측은 8/9 모나코 친선 1경기(RDM 76분, 평점 6.60 = 3팀 풀 17백분위)뿐이며 이 17백분위는 Fotmob 리그 백분위와 정면으로 어긋난다 — n=1 대 36경기이므로 후자를 채택한다.\u000a\u000a2026-09-11 갱신: fotmob_detail_stats는 08-21 이후 갱신 없음(26/27 시즌 리그 백분위 아직 미수집, 24/25·25/26만 존재) — 리그 백분위 근거는 위와 동일하다. 대신 prescriptions#measured(RDM, 2026-09-06 R3·R4 갱신)로 공식전 3경기 270분 평균 7.52(LIV 4명 중 최고) 확보, 커널 dm_dlp/Roaming 0.5959. v_player_profile 누적(전 대회·전 시즌 합산) n=74 평균 7.39·xG 0.205/90·xA 0.21/90·키패스 2.36/90·경합승 3.73/90 — 온오프볼 총량형 프로필 유지. FC27(player_game_stats, roster_date 2026-09-10) OVR 86 동일(FC26 대비 PAC 81→82, DEF 73→74), PlayStyles 신규 6종 확인, 키·몸무게(186cm·74kg) 최초 기재.'),'MEDIUM-HIGH — (교차 투영 — 실측 아님) 에메리 자유 10번(cam_playmaker/Roaming) 또는 전진 피벗 투영 모두 가능 — 다능성이 에메리의 상황 프리셋 체계(리드 시 딥블록 등)와 궁합. 단 우측 와이드 기용이라면 뱅크 복귀(wm_widemid/Support) 규율이 전진 편향과 상충.','MEDIUM — (교차 투영 — 실측 아님) 하이브리드 RDM 창조 축(리스 제임스 dm_dlp/Build-Up — r2)과 지대는 겹치나, 소보슬라이의 전방 질량 0.49는 하강 빌드업보다 2×10번 지대에 가깝다 — 어느 쪽에도 완전 정합은 아님.','HIGH — ⭐ 실측 전환 완료(08-11 평가 시점엔 이라올라 공식전 0경기였음). RDM 3경기 270분 평균 7.52로 LIV 4명 중 최고 산출, 커널 dm_dlp/Roaming 0.5959. 8/29 노팅엄전 74분 이후 RB 전환 실측(교체 시각과 좌표 일치)은 이라올라의 유틸리티 활용 문법(obs#68·#69 ''박스 진입 중앙 미드'')과 다능성 요구를 모두 확인한다. 남은 물음표는 신·구 커널 정합값 괴리(0.744→0.5959)와 공식전 표본 3경기의 한계뿐.','squad_entries(r3) · prescriptions#measured(RDM, 다중슬롯 36경기, ⭐) · v_player_profile(n=1) · obs#68·#69·#73·#120 · manager_profiles r1/r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표) · v_player_profile n=1(8/9 모나코 친선) · prescriptions#measured(RDM 다중슬롯 36경기, 7.02) | 2026-09-11 갱신: prescriptions#measured(RDM 공식전 3경기, 2026-09-06 R3·R4) · player_game_stats(FC27 roster_date=2026-09-10) · v_player_profile(누적 n=74) · player_duties(2026-08-23·2026-08-29)','MEDIUM-HIGH → HIGH — 이라올라 공식전 실측 3경기로 격상(08-11 평가 시점엔 0경기). 신·구 커널 값 괴리(0.812→0.674→0.5959)는 여전히 미해소이나, 표본은 팀 내 최대(공식전 3경기 + 누적 74경기).','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 크로스 공급과 수비 가담을 동시에 최상위로 수행하는, 이 모집단에서 매우 이례적인 프로필이다. 성공한 크로스 68회·인터셉트 30회·걷어내기 58회·수비적 행동 339회·볼 회수 187회·터치 2996회가 모두 백분위 100이고 기회 창출 78회(98)·정확한 롱볼 130회(98)·성공한 패스 1919회(98)로 배급량도 최상위다. 창조 산출은 xA 6.81(95)·빅찬스 창출 14회(96)·어시스트 7개(95)로 상위 5% 안에 있다. 약점은 대인 방어와 규율, 자기 마무리다 — 제쳐당한 횟수 39회가 백분위 2, 파울 41회가 5, 경고 8장이 3, 퇴장 1회가 0으로 최하위이고 90분당 상대 박스 터치가 11, xG가 34로 박스 안 위협은 낮다. 슛을 기대하는 자리가 아니라 측면에서 크로스를 공급하며 수비까지 메우는 자리, 특히 오른쪽 측면의 일꾼 역할에 두는 것이 맞다.');
INSERT INTO player_evaluations VALUES(42,3,52,'A− → 조정 — 26/27 이라올라 체제 공식전 실측 개시: CAM 포지션-순수 3경기(뉴캐슬·노팅엄포레스트·입스위치) 242분 평균 6.46(prescriptions#measured 09-06 갱신) — 프리시즌 3경기 7.77보다 하락해 공식전 첫 관문에서는 조정기. 커널은 cam_classic10/Versatile 0.8555로 프리시즌 잠정치(cam_playmaker/Roaming 0.823)보다 오히려 높은 정합 — 역할 자체의 그리드 적합은 개선됐다. FC27(2026-09-10) OVR 86(−1, FC26 87 대비), PAC 77(−3)·SHO 79(−1)·PHY 61(−6) 하락(DEF 54는 불변) — 신체 능력치가 전면 재평가됐다. 신규 PlayStyles(Finesse Shot·Chip Shot·Incisive Pass·Technical·First Touch·Inventive)는 기존 창조 중심 서사와 정합.','하프윙어형 10번에서 공식전 클래식10(Versatile) 커널로 재배치 — cam_classic10/Versatile 0.8555. 뉴캐슬전 중앙 10번 63분 소화, D+3 Coaches Voice 보도: 바깥으로 이동해 상대 수비(Steur)를 끌어내 각포의 중앙 진입 공간을 만드는 연계형 움직임. FC27 신규 PlayStyles(Incisive Pass·First Touch·Inventive·Chip Shot)가 좁은 공간 연결·마무리 다양성 서사와 일치.','공식전 3경기 확보 — 평균 6.46(242분), 커널 정합은 오히려 프리시즌보다 상승(0.8555). 전 대회 누적(v_player_profile n=71, 평균 7.13)은 여전히 리그 상위 창조력(xA 0.215/90, 키패스 2.1/90)을 보인다. 약점: FC27 PAC 77(−3)·PHY 61(−6) 하락, 공식전 3경기 중 최저 5.9(입스위치전)까지 떨어진 편차, 자기진영 질량 0.19의 수비 관여는 여전히 얇다.',unistr('Fotmob 25/26 PL 26.5경기(90분 환산, 41지표)에서 창출은 리그 동포지션 최상위다 — 기회 창출 60회(95백분위)·xA 5.17(89백분위)·상대 박스 터치 161회(93백분위)·터치 1875회(96백분위)·패스 성공 1201회(95백분위)·드리블 성공 39회(85백분위). 슈팅 축도 xG 7.03(85백분위)·xGOT 6.52(84백분위)로 높은데 실제 득점 5골·어시스트 3회(65백분위)로 산출이 기대에 못 미쳐, 첫 시즌 기여는 기대치보다 낮게 끝났다. 명확한 약점은 몸싸움이다 — 공중 경합 승률 14.9%(9백분위)·경합 승률 39.9%(24백분위)·볼 뺏김 36회(17백분위). 우리 자체 실측은 8/9 모나코 친선 1경기(59분 1골, 평점 8.60 = 3팀 풀 98백분위)뿐으로 사실상 근거가 없었고, 그리드 CAM 5경기 평균 7.00도 표본 부족이다.\u000a\u000a2026-09-11 갱신: fotmob_detail_stats 08-21 이후 갱신 없음(26/27 리그 백분위 미수집). prescriptions#measured(CAM, 2026-09-06 R3·R4 갱신)로 공식전 3경기 242분 평균 6.46, 커널 cam_classic10/Versatile 0.8555. v_player_profile 누적(전 대회) n=71 평균 7.13·xG 0.257/90·xA 0.215/90·키패스 2.1/90. FC27(roster_date 2026-09-10) OVR 86(−1, FC26 87 대비), PAC 80→77(−3)·SHO 80→79(−1)·PHY 67→61(−6) 하락(DEF 54는 불변) — 신체 능력치 재평가가 두드러진다. PlayStyles 6종(Finesse Shot·Chip Shot·Incisive Pass·Technical·First Touch·Inventive) 최초 확인, 키·몸무게(177cm·71kg) 기재. ⚠️ squad_entries.rate_note(2026-08-19)에 따르면 프리시즌 3경기(177분)는 이미 이라올라 체제 실측이었다 — 08-11 평가 당시 남은 것은 ''리버풀 25/26 슬롯 체제'' 표본뿐이었으므로, 이번 공식전 3경기가 ''알론소·마레스카 축과 무관한 순수 이라올라 데이터''로는 처음이다.'),'HIGH — (교차 투영 — 실측 아님) 에메리 자유 10번 슬롯(cam_playmaker/Roaming 또는 cam_halfwinger — r1 implementation ⑸에 halfwinger가 만잠비 축으로 명시)과 실측 최적 역할이 일치. 로밍 자유를 주는 문법이 비르츠의 하프스페이스 유동과 정합.','HIGH — (교차 투영이지만 예외적 근거: 레버쿠젠 시절 알론소 본인 체제의 서사 실측 존재) obs#45: 샤카·팔라시오스의 third-man 콤비네이션의 종착지가 비르츠. obs#48: 2×10번 중 ''로머/최종 창조자'' 축이 비르츠로 명시 — 세 감독 핏 중 감독-선수 실제 협업 기록이 있는 유일 조합. 단 첼시 이식 검증 전(r2 confidence MEDIUM)이며 25/26 리버풀 표본은 알론소 것이 아니다.','MEDIUM-HIGH 유지 — 실측 전환됐으나 결과는 혼재. CAM 공식전 3경기 평균 6.46으로 LIV 4명 중 최저권이나, 커널 정합(0.8555)은 오히려 프리시즌보다 개선돼 ''역할 자체는 맞다''는 근거다. 뉴캐슬전 D+3 서술(상대 수비를 끌어내는 폭 이동)은 이라올라의 수직 전환 체제에서 창조 자원으로 기능하고 있음을 보여주나, 결정적 침투 부족(뉴캐슬전 63분 평)이 계속 지적된다. 25/26 £100m 이적 후 적응 지연 서사가 26/27 초반까지 완전히 해소되지 않았다.','squad_entries(r3) · prescriptions#measured(CAM, n=5 — 표본 부족) · v_player_profile(n=1, 8.6) · obs#45·#48·#66 · manager_profiles r1/r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 41지표) · v_player_profile n=1(8/9 모나코 친선) · prescriptions#measured(CAM n=5, 7.00) | 2026-09-11 갱신: prescriptions#measured(CAM 공식전 3경기, 2026-09-06 R3·R4) · player_game_stats(FC27 roster_date=2026-09-10) · v_player_profile(누적 n=71) · player_duties(2026-08-23)','MEDIUM-HIGH 유지 — 공식전 3경기 확보했으나 평점(6.46)이 프리시즌(7.77)보다 낮아 판단이 갈린다. 커널 확정치는 오히려 상승(0.8555). 리버풀 표본 총 6경기(공식전 3 + 친선 3)로 확대됐고, FC27 PAC/PHY 하락은 교차검증되지 않은 단일 소스(EA 공식)다.','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 공을 많이 만지며 기회를 만들고, 몸싸움은 이 모집단 최하위인 전형적인 창조형 프로필이다. 기회 창출 60회가 백분위 95, 성공한 패스 1201회가 95, 터치 1875회가 96, 상대 박스 터치 161회가 93으로 소유와 위험 지역 관여가 상위 5% 부근이다. xA 5.17(89)·xG 7.03(85)·드리블 성공 39회(85)로 만들기와 마무리 기대값이 모두 상위권이고 상대 진영 볼 탈취 21회(89)로 앞에서 끊는 기여도 있다. 약점은 경합이다 — 공중 경합 승률 14.9%가 백분위 9, 경합 승률 39.9%가 24로 최하위권이고 볼 뺏김 36회(17)·제쳐당함(23)도 낮다. 실제 어시스트 3개(65)와 득점 5골(71)은 기대값 백분위보다 낮아 산출이 기대에 못 미친 표본이다. 몸싸움을 요구하지 않는 중앙 2선, 즉 뒤에서 받쳐주는 미드필더 앞의 자유로운 자리에 두는 것이 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(43,3,53,'B− → B+ 상향 — 26/27 공식전 실측이 이전 평가를 뒤집는다. LM 포지션-순수 2경기(8/23 뉴캐슬·9/4 입스위치) 180분 평균 8.11(prescriptions#measured 09-06 갱신), 커널 wm_insidefwd/Balanced 0.8385 — 25/26 ''전 슬롯 0.7 미만''이던 ''어디에도 안 맞는다''는 진단을 공식전 표본이 정면 반박한다. 8/23 뉴캐슬전(90분 1골 평점 8.42)·8/29 노팅엄전(71분 1도움 7.3)·9/4 입스위치전(90분 2도움 7.8) 등 전 공식전 고평점. FC27(2026-09-10) OVR 82(−1, FC26 83 대비), PAC 77(−6) 대폭 하락·SHO 83(+1). 신규 PlayStyles(Finesse Shot·Whipped Pass·Press Proven).','인사이드 포워드형에서 공식전 고성과 좌측 자원으로 격상 — wm_insidefwd/Balanced 0.8385(LM n=2). 뉴캐슬전 ''좌측 득점형 플레이메이커''로 기능(1골·슛6·찬스3), D+3 Coaches Voice 보도: 비르츠·소보슬라이가 벌린 중앙 공간으로 들어가는 움직임이 52분 동점골 관여로 이어졌다. FC27 신규 Press Proven이 전방 압박 관여 서사와 정합.','공식전 4경기(친선 포함) 전부 평점 7.3 이상, 순수 LM 2경기 평균 8.11 — LIV 4명 중 최고 공식전 평균. 골관여 뚜렷(1골 / 1골+1도움 아님 확인: 8/23 1골·8/29 1도움·9/4 2도움, 4경기 누적 2골4도움). FC27 SHO 83(+1)로 마무리 능력치 소폭 상승. 약점: FC27 PAC 77(−6) 대폭 하락 — 침투 속도 자원으로서는 우려 신호. 표본은 여전히 순수 LM 2경기 수준이라 확정엔 이르다.',unistr('Fotmob 25/26 PL 30.5경기(90분 환산, 42지표)에서 슈팅 볼륨과 제공권이 함께 최상위다 — 슛 87회(98백분위)·상대 박스 터치 187회(98백분위)·공중 경합 승 56회(98백분위)·승률 50.9%(95백분위)·헤더 슛 10회(96백분위)·경합 승 162회(92백분위)·xG 8.46(92백분위). 연결도 기회 창출 54회(92백분위)·xA 4.69(83백분위)로 좋다. 낮은 칸은 볼 간수와 규율이다 — 파울 42회(4백분위)·크로스 정확도 12.6%(20백분위)·패스 정확도 78.5%(37백분위), 수비 기여는 총량 76백분위지만 per90으로 보면 13백분위까지 내려간다(수비적 행동 5.01). 우리 자체 실측은 8/9 모나코 친선 1경기(LM 59분, 평점 7.00 = 3팀 풀 58백분위)뿐이라 근거가 사실상 없었고, 그리드 LM 6경기 평균 6.52는 전임 체제 표본이다.\u000a\u000a2026-09-11 갱신: fotmob_detail_stats 08-21 이후 갱신 없음(26/27 백분위 미수집). prescriptions#measured(LM, 2026-09-06 R3·R4 갱신)로 공식전 순수 LM 2경기(8/23 뉴캐슬·9/4 입스위치) 180분 평균 8.11 — LIV 4명 중 최고, 커널 wm_insidefwd/Balanced 0.8385. v_player_profile 누적(전 대회) n=74 평균 7.2·xG 0.273/90(4명 중 최고)·경합승 3.95/90(최고). FC27(roster_date 2026-09-10) OVR 82(−1, FC26 83 대비), PAC 77(−6)·SHO 83(+1)·DRI 81(−2). PlayStyles 3종(Finesse Shot·Whipped Pass·Press Proven) 최초 확인, 키·몸무게(189cm·76kg) 기재.'),'LOW-MEDIUM — (교차 투영 — 실측 아님) 에메리 와이드는 뱅크 복귀 수비 규율(wm_widemid/Support 또는 obs#125 winger/Balanced 사다리)을 요구 — 자기진영 질량 0.13과 정면 상충. 인사이드 포워드 기용(obs#124 문법)이라면 가능하나 그 역할 요구 대비 커널 정합이 0.675로 낮다.','MEDIUM — (교차 투영 — 실측 아님) 2×10번 중 안으로 좁히는 축(로저스 wm_insidefwd — r2 implementation)과 역할 문자열이 일치 — 세 투영 중 문법 정합이 가장 낫다. 단 정합도 절대값(0.675)이 낮아 강한 주장 불가.','MEDIUM → HIGH 상향 — 25/26 ''전 슬롯 0.7 미만'' 진단을 공식전 실측이 뒤집었다. LM 커널 0.8385(n=2)는 LIV 4명 중 최고 정합값이고 평균 평점(8.11)도 최고다. 뉴캐슬전 ''좌측 득점형 플레이메이커'' 기용과 동료를 위해 벌리는 움직임(D+3 서술)이 이라올라의 폭 활용 문법과 부합한다. 다만 자기진영 관여(25/26 기준 0.13)는 낮아 4-4-2 복귀 수비 부담에는 여전히 물음표가 남고, 공식전 표본 2경기의 한계도 있다.','squad_entries(r3) · prescriptions#measured(LM, n=6) · v_player_profile(n=1) · obs#68·#124·#125 · manager_profiles r1/r2/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 42지표) · v_player_profile n=1(8/9 모나코 친선) · prescriptions#measured(LM n=6, 6.52) | 2026-09-11 갱신: prescriptions#measured(LM 공식전 2경기, 2026-09-06 R3·R4) · player_game_stats(FC27 roster_date=2026-09-10) · v_player_profile(누적 n=74) · player_duties(2026-08-23)','MEDIUM → MEDIUM-HIGH — 공식전 2경기(순수 LM) 고평점(8.11)으로 이전 ''전 슬롯 0.7 미만'' 진단이 뒤집혔으나 표본은 여전히 2경기다. FC27 PAC 급락(−6)은 교차검증되지 않은 단일 소스(EA 공식)다.','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 제공권과 박스 안 슈팅량을 동시에 갖춘, 최전방에 가까운 프로필이다. 슛 87회가 백분위 98, 상대 박스 터치 187회가 98, xG 8.46이 92, 헤더 슛 10회가 96으로 마무리 지역의 양이 최상위이고, 공중 경합 승 56회(98)와 공중 경합 승률 50.9%(95)는 이 모집단에서 드문 수준이다. 연계에서도 기회 창출 54회(92)·어시스트 5개(85)·빅찬스 창출 10회(85)로 상위권이다. 약점은 반칙과 패스 정확도다 — 파울 42회가 백분위 4, 패스 정확도 78.5%가 37, 크로스 정확도 12.6%가 20으로 하위권이고 90분당 수비적 행동(13)·볼 회수(12)로 자기 진영 복귀 기여는 거의 없다. 총량 백분위가 높은 지표들도 90분당으로 내리면 다소 떨어지므로 2754분 출전이 값을 부풀린 부분이 있다. 공중볼 타깃과 박스 안 마무리를 함께 요구하는 자리, 즉 최전방이나 그 바로 옆에 두는 것이 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(44,3,54,'A(archival) — 이탈 기재(players.notes: 2026-07-01 FA로 리버풀 계약 조기 해지) 이후 공식 클럽 표본 갱신 없음. 26/27 시즌 player_matches는 이집트 대표팀 월드컵 2경기(7/3·7/7, 평균 7.05)뿐 — 클럽 복귀나 이라올라 체제 실측은 전무. FC27(fut.gg, 2026-08-22 1단계) OVR 91(FC26 89 대비 +2, PAC 89·SHO 88·DRI 90 상승)이지만, 09-10 EA 공식 확정판에는 살라 항목 자체가 없다 — LIV 다른 3명(51·52·53)은 모두 09-10 행이 있는데 살라만 결측이다. 이탈 서사와 정합할 개연성은 있으나 결측=이탈 확정은 아니다(데이터 공백일 뿐).','정통 터치라인 윙어의 침투형(wm_winger/Attack) — obs#100·#120 이중 재현. 자기진영 질량 0.06 최저. 26/27 클럽 실측 갱신 없음(이탈 기재 유지), 이집트 월드컵 2경기(평균 7.05)만 신규 데이터.','우측 뒷공간 침투의 실측 상한 기준선(archetype)으로서 위상은 여전히 유효하다. 신규: 이집트 월드컵 2경기 평균 7.05(120분·90분)로 대표팀 컨디션 유지 정황. FC27 08-22판 OVR 91(+2)로 EA는 능력치 자체는 상향 평가했으나, 09-10 정본에 리버풀 소속 항목이 없어 클럽 연속성 판단이 불가하다. 약점: 여전히 자기진영 0.06 최저, 클럽 복귀 국면 데이터 전무.',unistr('Fotmob 25/26 PL 23.9경기(90분 환산, 42지표)로 출전이 크게 줄었지만 최종 3분의 1 산출은 여전히 상위다 — 상대 박스 터치 187회(98백분위)·슛 68회(89백분위)·xG 8.16(90백분위)·xA 5.31(90백분위)·어시스트 7회(95백분위)·기회 창출 49회(89백분위)·상대 진영 볼 탈취 21회(89백분위). 반면 대인·볼 간수는 리그 윙어 중 최하위 구간으로 내려갔다: 경합 승률 29.9%(2백분위)·드리블 성공률 26.4%(7백분위)·볼 뺏김 50회(6백분위)·패스 정확도 76.9%(24백분위), 수비 복귀도 태클 17회(41백분위)·인터셉트 4회(32백분위)·걷어내기 7회(27백분위)로 낮다. 우리 자체 실측은 8/9 모나코 친선 미출전으로 player_matches 0행이라 3팀 풀 백분위 산출 불가이며, 그리드 RM 5경기 평균 7.56(표본 부족)이 전부였다. 이 42지표는 25/26 리버풀 소속 프리미어리그 기록이며 이후 트라브존스포르 이적이 기재돼 있어, 다음 시즌 모집단은 EPL이 아니게 된다.\u000a\u000a2026-09-11 갱신: fotmob_detail_stats 08-21 이후 갱신 없음(26/27 리그 백분위는 리버풀 소속이 아니므로 애초에 생성 대상이 아니다). player_matches 26/27 시즌은 이집트 월드컵 2경기(7/3 120분 7.3, 7/7 90분 6.8, 평균 7.05)뿐 — 클럽 경기 0행. v_player_profile 누적(전 대회) n=64 평균 7.07·xG 0.388/90(LIV 4명 중 최고)·xA 0.248/90 — 이 값 대부분은 이탈 이전 25/26 리버풀 기록이라 해석에 주의. FC27 08-22(fut.gg 1단계) OVR 91(PAC 89·SHO 88·PAS 86·DRI 90·DEF 45·PHY 76, FC26 대비 OVR+2). 09-10 정본 갱신이 결측(club=''Liverpool''으로 조회해도 09-10 행 없음) — LIV 다른 3명과 달리 PlayStyles·키·몸무게 자료 자체가 없다.'),'MEDIUM(커널 기준 HIGH, 구조 기준 LOW) — (교차 투영 — 실측 아님) obs#100 개정 후 에메리 우측 윙어 브리프의 목표 커널이 정확히 wm_winger — 살라 그리드가 그 브리프의 상한 기준선이다. 그러나 에메리 두 줄 4 뱅크 복귀(obs#125의 winger/Balanced 요구)와 자기진영 0.06은 정면 상충 — ''기준선''이지 ''처방 대상''이 아니다.','LOW-MEDIUM — (교차 투영 — 실측 아님) 알론소 3-4-2-1에는 터치라인 윙어 슬롯이 없다(폭은 윙백 독점 — obs#46). 우측 포켓 10번(팔머 wm_wideplm/Attack 축)은 다른 직무.','LOW-MEDIUM (변동 없음) — 26/27 클럽 실측 갱신 없이 이탈 기재만 유지된다. FC27 09-10 정본 결측이 이탈 서사와 정황상 부합하나 결정적 근거는 아니다(단순 미수집 가능성 배제 못 함). squad_entries(r3) lh=OWNED와의 불일치도 여전히 미해소 — 메인 세션의 소속 상태 확정이 필요하다. 커널 판정(wm_winger/Attack) 자체의 신뢰도는 obs#100·#120 이중 재현으로 견고하나, 이라올라 체제 적합 여부는 여전히 소급 판단만 가능하다.','squad_entries(r3, lh=OWNED — 불일치) · prescriptions#measured(RM, n=5, ⭐⭐, 이탈 기재) · obs#38·#66·#68·#100·#120 · manager_profiles r1/r3 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 42지표) · v_player_profile 0행 · prescriptions#measured(RM n=5, 7.56) | 2026-09-11 갱신: player_matches(26/27 이집트 월드컵 2경기) · player_game_stats(FC27, 08-22판만 존재·09-10 결측 확인) · v_player_profile(누적 n=64) · players.notes(이탈 기재 재확인)','LOW-MEDIUM 유지 — 클럽 실측 갱신 없음(이탈 지속), FC27 09-10 결측이 추가 관찰 사항으로 더해졌다. 대표팀(이집트) 2경기만 신규 데이터.','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 박스 안 점유와 창조·마무리 기대값이 모두 상위 10% 안에 있고, 경합과 수비는 최하위인 극단적으로 분화된 프로필이다. 상대 박스 터치 187회가 백분위 98, 어시스트 7개가 95, xA 5.31이 90, xG 8.16이 90, 슛 68회가 89, 기회 창출 49회가 89로 공격 산출 지표가 고르게 상위권이다. 상대 진영 볼 탈취 21회(89)로 전방에서 끊는 기여도 있다. 약점은 경합 승률 29.9%가 백분위 2, 드리블 성공률 26.4%가 7, 볼 뺏김 50회가 6으로 최하위라는 점이다 — 상대와 붙어 이겨내는 방식이 아니고 공을 자주 잃는다. 90분당 수비적 행동(7)·걷어내기(9)·인터셉트(15)로 자기 진영 기여는 사실상 없다. 수비 부담을 완전히 면제하고 박스 안으로 들어가는 경로를 확보해 주는 자리, 즉 뒤를 풀백과 미드필더가 덮는 오른쪽 공격 자리에 두는 것이 맞다.');
INSERT INTO player_evaluations VALUES(45,1,75,'B+ — 처방 축(더블 피벗 볼위닝) 정면 보강이자 오나나 부상·틸레만스 이탈 공백의 1:1 해법. 역할 정체성 완벽, 슬롯 커널 적합은 중간, 부상 리스크 존재.','볼위닝 앵커(태클·인터셉트·세컨드볼), 190cm 세트피스 빅바디(공중듀얼 62%), 광역 커버로 단독 전환 방어. 온볼 배급 비엘리트, 파울·경고 비용(풀럼 2년 경고 27장).','PL 검증 완료(풀럼 태클 300개 1위 + 토트넘 25/26 중심 기둥 재검증), 에메리 미드블록의 중앙 차단 임무와 기질 일치. 약점: 빌드업 기여 한계(LDM 커널 dm_widehalf/Build-Up .709가 이를 정량화), 네거티브 PS ''부상에 취약함'', 30세(1995년생) 에이징 커브.','우리 실측은 6경기 평균 6.92뿐이고 player_matches에 시즌 전수가 없어, 이 선수는 Fotmob 프리미어리그 25/26 39지표(2197분)가 사실상 유일한 대표본 근거다. 볼 탈취는 리그 최상위다 — 태클 110회(동포지션 상위 2%)·경합 승 193회(상위 6%)·경합 승률 61.7%(상위 7%)·수비적 행동 302(상위 20%)·걷어내기 58회(상위 14%)·공중 경합 승률 58.1%(상위 23%). 세트피스 득점력도 있다 — 득점 5골(상위 9%)·xGOT 4.98(상위 5%)·xG 2.70(상위 16%). 반면 배급은 리그 하위다 — 패스 정확도 82.0%(하위 19%)·롱볼 정확도 41.0%(하위 14%)·기회 창출 8회(하위 20%)·기대 도움 0.66(하위 25%)로, 전진 패스를 담당하는 유형이 아니라 앞선 파트너가 필요하다. 우리 6경기 표본에서는 평범해 보였지만 리그 동포지션 기준 태클은 상위 2%라 두 근거의 결론이 갈리며, 6경기 쪽이 표본이 얇으므로 Fotmob 쪽을 우선한다.','HIGH — 숙련 dm_holding/Ball-Winning이 에메리 더블 피벗 처방과 정확 일치(DB rationale ''기능축 처방과 정확 일치 — 확정''). 슬롯 fit_sim LDM .709(dm_widehalf/Build-Up)·RDM .738(dm_dlp/Roaming) — 커널 지불은 있으나 카마라 부재 시나리오의 보험 가치가 상회.','(교차 투영 — 실측 아님) MEDIUM — 백3 빌드업·윙백 폭 독점 구조(regime 2)에서 싱글/더블 6의 수비 반경은 부합하나, 하프스페이스 2×10번을 받치는 6번에게 요구되는 전진 배급이 그의 최약점.','(교차 투영 — 실측 아님) MEDIUM-HIGH — 고강도 압박·수직 전환(regime 3)에 태클·회수 기질은 부합, 파이널서드 탈취 지향의 전면 맨투맨 전환 시 광역 커버가 자산. 단 탈취 후 즉시 슛/전진 연결의 온볼 속도는 캐비앗.','Total Football Analysis(25/26 토트넘 스카우트 리포트) · BBC Sport · DB transfer_targets#91·92 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Premier League 2025/2026, 39지표) · player_matches 없음 — transfer_targets sample_n=6 avg_rating=6.92(LDM/RDM)','서사 소스(3티어급) + DB 실측 6경기 — 시즌 전수 아님. 이적 구조(임대+옵션 vs 완전 €25~30m) 교착은 DB 08-09 기준.','2026-08-11','프리미어리그 미드필더 중 태클과 경합에서 최상위이고 배급·창조는 최하위권인, 극단적으로 분화된 파괴형 프로필이다. 태클 110회가 백분위 98(90분당도 98), 경합 승 193회가 94, 경합 승률 61.7%가 93으로 공을 끊는 능력이 최상위이고 걷어내기 58회(86)·수비적 행동 302회(80)로 자기 진영 방어량도 많다. 세트피스에서 득점 5골(91)과 xGOT 4.98(95)로 공격 기여가 있는 것도 특징이다. 약점은 공을 앞으로 보내는 일 전부다 — 기회 창출 8회가 백분위 20(90분당 7), xA 0.66이 25(90분당 10), 롱볼 정확도 41.0%가 14, 패스 정확도 82.0%가 19로 하위권이다. 볼 뺏김 30회(7)도 낮아 압박 아래에서 공을 지키는 능력은 떨어진다. 배급을 담당하는 미드필더를 옆에 반드시 두고, 중원 앞의 공을 끊는 몫과 세트피스 위협만 맡기는 배치가 맞다.');
INSERT INTO player_evaluations VALUES(46,1,76,'A- 유지, 근거 갱신 — 08-29 CONFIRMED 첫 팀 등록 이후 실전 배치가 이원적으로 확인됐다. squad_entries 시즌 전수(28경기, 분데스리가 소속 기준) fit .724(st_false9/Attack, 평균 6.92)가 AVL 정본이나, 이적 후 실측 3경기(아스날 st_false9/Build-Up .723 · 헐 st_advanced/Support .632 · 브뤼헤 st_false9/Build-Up .625, pos_class CAM)는 경기 국면에 따라 진자운동한다. 브뤼헤전(2026-09-08) 2골(11분 배후 침투, 22분 등지고 백힐)로 온볼 하강(레이오프)·오프볼 배후 위협의 이중 임무가 모두 득점으로 증명됐다(에메리 회견: ''오늘은 배후 침투를 더 했다''). FC27은 OVR79 유지되나 PAC 82→76(-6)·PHY 78→76(-2)로 하락하고 PlayStyles에서 ''테크니컬''이 빠져 ''낮은 드리븐 슛·게임 체인저'' 2종만 남았다 — 채널 러닝 의존도가 높은 이 선수에게 페이스 하락은 리스크다.','딥존 발동형 9번 — 등지고 레이오프, 파워 스트라이드 가교, 압박 개시·하이 리커버리. 클래식 박스 포처 아님(바이에른 공식 프로필). AVL 3경기 실측은 이 서사를 ''지시된 이중 임무''로 정밀화한다 — 하강 홀드업/백힐(22분 브뤼헤 골 기점)과 최종 배후 러너(11분 브뤼헤 골, 43분 전 경기 골) 둘 다 수행. FC27 PlayStyles는 Low Driven Shot·Game Changer(Technical 소실, FC26 대비).','링크·침투 이중 위협, 수비 기여(백업으로도 콤파니가 공개 옹호·잔류 희망), 분데스 우승 스쿼드 경험. 26/27 초기 3경기(PL 2+CL 1)에서 이미 3골로 마무리 우려를 부분 상쇄(PL 2경기 2골/156분, CL 1경기 1골/81분). 약점: 몸싸움이 여전히 약하다 — 리그 경합 승률 36.7%(하위 28%)가 AVL 실측에서도 재현됐다(브뤼헤전 지상듀얼 3/9·공중 0/2, 볼 상실 12). 서열 상 첼시 복귀 후 적체(조앙 페드로·델랍·웰벡)가 AVL 이적의 배경이었다.','우리 실측은 회차마다 갱신 중이나(09-11 기준 시즌 전수 28경기 6.92), Fotmob 분데스리가 25/26 39지표(1004분)가 여전히 1차 근거다 — 90분당 PK 제외 xG(동포지션 상위 3%)·90분당 유효슛 1.88(상위 5%)·90분당 득점 0.717(상위 10%)·90분당 상대 박스 터치 8.52(백분위 100)로 마무리·박스 침투는 상위권. 패스 정확도 81.6%(상위 10%)·90분당 기회 창출 1.61(상위 11%)로 연계도 양호. 약점은 몸싸움 — 공중 경합 승 7회(하위 16%)·경합 승률 36.7%(하위 28%). 26/27 초기 3경기(PL2+CL1)에서 이미 3골로 ''바이에른 첫 6경기 무득점'' 서사와 다른 방향의 신호가 나왔으며, 브뤼헤전 지상듀얼 3/9·공중 0/2는 몸싸움 약점 재현이다.','HIGH 유지 — CONFIRMED 서명(£65m, avfc.co.uk 2026-08-29) 이후 실측 3경기가 fit_sim을 국면별로 바꾸지만(.723→.632→.625) 시즌 전수 정본(28경기, .724, st_false9/Attack)은 변경 없음(표본 2~3경기는 정본을 덮지 않음 — squad_entries 주석 명시). 왼쪽 배치 가능성(1874 Tanswell: ''잭슨은 왼쪽도 뛸 수 있어 왓킨스와 함께 설 수 있다'')은 로테이션 유연성을 보탠다.','(교차 투영 — 실측 아님) HIGH — 3-4-2-1 원톱은 2×10번을 위해 등지고 내주는 링크형 9번을 요구 — 잭슨의 레이오프·채널 침투 이중성이 구조 요구와 부합.','(교차 투영 — 실측 아님) HIGH — 압박 개시·하이 리커버리 기질이 하이브리드 프레스의 1선 트리거 역할과 정확 부합. 탈취 후 즉시 슛 국면에서 마무리 기복이 유일 감점.','FC Bayern 공식 프로필 · Bavarian Football Works · Goal · DB transfer_targets#123 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Bundesliga 2025/2026, 39지표) · player_matches 없음 — transfer_targets sample_n=6 avg_rating=7.45(ST) | stat_eval 2026-09-11 갱신: squad_entries CONFIRMED 승격(2026-08-29)·measured:season:full2526(28경기 .724)·측정 3경기(아스날/헐/브뤼헤) fit_sim 변동 · player_game_stats FC27(roster_date 2026-09-10, OVR79 유지·PAC82→76·PHY78→76 하락, PlayStyles Low Driven Shot+Game Changer, Technical 소실, 187cm/78kg) · player_duties 브뤼헤전(2026-09-08/09) 이중임무 확정 발언','HIGH — 근거 다중화. 시즌 전수 28경기(분데스리가 소속) 정본 + AVL 실측 3경기(아스날·헐·브뤼헤)가 fit을 흔들지만 표본 부족(경기당 n=1)이라 정본을 덮지 않는다(불변규칙 2). 에메리 이중임무 발언(회견 원문)이 국면별 fit 변동을 설명하는 1차 근거로 확보됐다. AVL 이적 전 서사(바이에른 공식·Goal)는 여전히 유효하나 grid_club 표기 정정 필요성(25/26 실측이 바이에른 소속인데 grid_club=Chelsea로 기록된 결손)이 남아있다.','2026-09-11','분데스리가 공격수 중 1000분 표본이라 90분당 백분위로 읽으며, 그 기준에서는 박스 안에 계속 들어가 슛을 쌓는 마무리형 프로필이다. 90분당 상대 박스 터치 8.52회가 백분위 100, 유효슛 1.88회가 95, PK 제외 xG가 97, xGOT 0.70이 89, 득점 0.72골이 90으로 마무리 지역의 양과 기대값이 모두 최상위권이다. 연계도 90분당 성공한 패스(93)·패스 정확도 81.6%(90)·기회 창출 1.61회(89)로 상위권이라 등지고 받아 내주는 일도 한다. 약점은 몸싸움이다 — 공중 경합 승이 90분당 백분위 5, 경합 승이 11, 경합 승률 36.7%가 28로 최하위권이고 퇴장 1회(0)도 있다. 수비 가담은 90분당 수비적 행동 26, 걷어내기 20으로 낮다. 제공권 타깃이 아니라 박스 안 침투와 마무리를 맡기는 최전방 자리에 두고, 공중볼 경합은 다른 인원으로 해결해야 하는 프로필이다.');
INSERT INTO player_evaluations VALUES(47,1,77,'B — 재능·평점(7.18)·나이(2004년생) 대비 구조 적합이 발목: 해방 윙어 풋프린트인데 빌라 우측은 뱅크 칸. 성사 확률도 셀링클럽 블록으로 4후보 중 최저.','왼발 인버티드 RW — 드리블 Very Strong·공중듀얼 Strong(WhoScored), 오프더볼 성실·전술 성숙(''더 강한 하비 엘리엇''). 크로스·규율(경고 3·퇴장 1) 약점, 통산 64경기 5골로 득점 전환 미완.','양 윙 소화 다재 + 압박 가담 — 뱅크 복귀 임무 학습 가능성은 서사가 지지. 약점: CAM 겸용 주장은 실측 기각(.674), RM 실기용 시 wm_widemid/Support .734 지불, PL 무경험 + 브라질發 적응 리스크, FC26 미존재(게임 재현 불가 — 커스텀 생성 필요).','우리 실측은 6경기 평균 7.18뿐이라, Fotmob 세리에 A 2026 시즌 39지표(1392분)가 대표본 근거다. 돌파와 몸싸움이 리그 최상위다 — 드리블 성공 41회(동포지션 상위 2%)·드리블 성공률 58.6%(상위 19%)·경합 승 110회(상위 2%)·얻어낸 파울 35회(상위 8%)·공중 경합 승률 53.3%(상위 14%). 압박 기여와 슛 볼륨도 상위다 — 태클 26회(상위 5%)·수비적 행동 42(상위 12%)·볼 회수 57회(상위 12%)·슛 33개(상위 12%)·유효슛 13개(상위 12%)·득점 4골(상위 15%). 반대편이 뚜렷하게 나쁘다 — 제쳐당함 26회(리그 하위 1%)·볼 뺏김 27회(하위 3%)·파울 21회(하위 5%)·크로스 정확도 6.7%(하위 15%)·퇴장 1회(하위 1%)로, 무모함과 마무리 전달의 정밀도가 동시에 문제다. 90분당 기준으로는 슛·기회 창출 백분위가 각각 53·43까지 내려가므로, 총량 상위의 상당분이 출전량에서 온다는 점을 함께 읽어야 한다. 브라질 리그 모집단이라 유럽 강도 환산은 미검증이다.','MEDIUM — fit_sim .812(wm_winger/Balanced)는 수치상 4후보 중 2위지만, 에메리 우측이 요구하는 4-4-2 뱅크 복귀(wm_widemid/Support)로 재면 .734로 하락 — DB 판정 ''해방 사이드용 자원, 현 스쿼드 구조와 어긋남'' 유지. 로저스 대체 창조 자원이라는 영입 서사와 실측 풋프린트가 반만 겹친다.','(교차 투영 — 실측 아님) HIGH — 하프스페이스 2×10번 구조가 그의 최적 서식지: 인버티드 컷인 + 좁은 지역 콤비네이션 + CAM 미달이어도 10번 슬롯은 윙백이 폭을 대신 지므로 실측 우측 편향과 충돌이 적다.','(교차 투영 — 실측 아님) MEDIUM-HIGH — 압박 성실성·수직 드리블은 부합하나 이라올라 윙어에게 요구되는 터치라인 고정·크로스 볼륨이 그의 약점(크로스 weak)과 정면 충돌.','Rousing The Kop(2026-02 스카우트 리포트) · WhoScored · FotMob · DB transfer_targets#139 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(Serie A 2026, 39지표) · player_matches 없음 — transfer_targets sample_n=6 avg_rating=7.18(RM)','서사 소스(3티어급) + DB 실측 6경기. 성사 리스크 별도: 팔메이라스 협상 거부·€45m+ 요구·바이아웃 €100m + 리버풀 우선매수권 보도(2026-02, 3티어) — DB 08-09 MEDIUM-HIGH 판정과 병존.','2026-08-11','세리에A 공격형 미드필더·윙어 중 드리블과 경합으로 값을 내고, 공을 잃는 빈도도 그만큼 큰 프로필이다. 드리블 성공 41회가 백분위 98, 경합 승 110회가 98, 얻어낸 파울 35회가 92로 1대1에서 앞서 나가는 지표가 최상위이고 태클 26회(95)·볼 회수 57회(88)·수비적 행동 42회(88)로 수비 가담도 상위권이다. 마무리는 슛 33회(88)·유효슛 13회(88)·득점 4골(85)로 상위권이지만 90분당으로 내리면 각각 53·60·68로 떨어지므로 총량에는 시도의 집중도가 섞여 있다. 약점은 공 관리다 — 제쳐당한 횟수 26회가 백분위 1, 볼 뺏김 27회가 3, 파울 21회가 5, 퇴장 1회가 1로 최하위이고 크로스 정확도 6.7%(15)·롱볼 정확도 41.7%(18)로 배급의 질도 낮다. 좁은 공간에서 몰고 나가 반칙을 얻는 역할에는 맞지만, 최종 패스나 정확한 배급을 요구하는 자리에는 근거가 없다.');
INSERT INTO player_evaluations VALUES(48,1,78,'A- — 4후보 중 구조 적합 최고 CONFIRMED 완료, AVL 확정 LB. FC27(09-10) OVR78(FC26 4-09자 77 대비 +1) — 아틀레티코 소속 시절 대비 소폭 상승, sho60→61·def72→73·phy73→75(+2). PlayStyle이 「에어리얼 포트리스;휩 패스」 2종에서 「Whipped Pass」 단일로 축소 — 공중 강점 태그가 게임상 빠졌다(약점 축과 방향 일치, 아래 참조).','전진형 LB. FC26 PlayStyle Aerial Fortress 소실은 실측 서사와 정합한다 — 다국어 수집(이탈리아어·스페인어)에서 백3 좌측 CB로 시험됐을 때는 공중이 문제였다는 반대 서술이 이미 확인돼 있었다. 잔존 Whipped Pass는 크로스 볼륨·전진 패스 강점(전진패스 8회/90, 풀백80퍼센타일)과 일치.','v_player_profile 갱신 n=66·3765분·평균평점6.69(아틀레티코 전 대회 통합: 라리가37경기1775분6.77·UCL16경기1208분6.66·코파델레이6경기422분6.5). AVL 데뷔는 아직 초기 — 26/27 PL2경기23분(교체 출전, 평점6.52)·친선1경기61분6.5로 표본 극소. 약점: 1대1 방어(경합승률44.2% 하위9%, 기존 기록)와 이제 게임상으로도 공중 특기가 빠진 phy75조차 여전히 6명 중 중위권.','FC27 신규: OVR78·pac78·sho61·pas74·dri71·def73·phy75, 187cm·79kg. FC26 대비(4-09 roster, 아직 AVL 이적 반영 전) OVR+1·sho+1·pas+1·def+1·phy+2 — 전반적 소폭 상승, 피지컬 축이 가장 크게 올랐다. Fotmob 라리가 25/26 41지표(기존 기록: xA3.84 상위8%·크로스29회 상위7%·경합승률44.2% 하위9%)는 유지, v_player_profile은 대회 통합 n=66/평균6.69로 갱신됐다.','HIGH — fit_sim 0.931(n=45, 전수 재수집, 기존 0.949에서 -0.018, 판정 불변) 유지. 디뉴 대체 좌측백으로 CONFIRMED. AVL 실측은 아직 23분뿐이라 아틀레티코 그리드 재측정 필요 경고(prescriptions rationale)가 여전히 유효하다.','(교차 투영 — 실측 아님) HIGH — regime 2의 ''좌 윙백 인선 공백''에 정확히 꽂히는 프로필: 윙백 폭 독점 구조에서 크로스·전진패스형 LWB는 요구 사양 그대로. 가스페리니 3백 이력이 이식성 방증.','(교차 투영 — 실측 아님) MEDIUM — 오버랩 동력은 부합하나 이라올라 풀백에 요구되는 전면 맨투맨 1대1 수비가 그의 지목된 약점 — 측면 압축 구조에서 노출 위험.','Total Football Analysis(25/26 아틀레티코 스카우트 리포트) · Into the Calderon · The Athletic(Tanswell, DB 경유) · DB transfer_targets#141 | stat_eval 2026-08-11 갱신: fotmob_detail_stats(LaLiga 2025/2026, 41지표) · player_matches 없음 — transfer_targets sample_n=6 avg_rating=6.77(LB) | stat_eval 2026-09-11 갱신: FC27(OVR78, +1 vs FC26 4-09자 77)·PlayStyle(Whipped Pass, Aerial Fortress 소실)·player_game_stats(pac78/sho61/pas74/dri71/def73/phy75, 187cm/79kg) · v_player_profile n=66(3765분, 평균6.69, 아틀레티코 전 대회 통합) · v_player_season_stats(26/27 PL 2경기 23분 평점6.52, 친선1경기61분6.5)','표본은 크지만(n=66) 전부 아틀레티코 소속분이고 AVL 실측은 23분뿐 — 빌라 합류 후 그리드 재측정 필요 경고가 여전하다(prescriptions rationale). 알론소·이라올라 핏은 교차 투영(실측 아님, 기존과 동일).','2026-09-11','라리가 풀백 중 크로스로 기회를 만드는 데 특화되고, 개인 돌파와 마무리는 거의 없는 프로필이다. 성공한 크로스 29회가 백분위 93(90분당 97), xA 3.84가 92(90분당 98), 크로스 정확도 33.0%가 84, 기회 창출 25회가 83으로 측면 공급 지표가 상위권이고 롱볼 정확도 55.7%(87)로 긴 패스도 정확하다. 수비에서는 공중 경합 승 26회(82)와 공중 경합 승률 59.1%(80), 볼 회수 98회(70)가 준상위다. 약점은 1대1이다 — 경합 승률 44.2%가 백분위 9, 드리블 성공률 27.8%가 12, 제쳐당한 횟수 24회가 17로 하위권이고 얻어낸 파울 2회(3)로 상대를 끌어당기는 힘도 없다. 마무리는 득점 0골·xG 0.14(23)·슛 5회(33)로 사실상 없다. 안쪽으로 파고들기보다 열린 측면에서 크로스를 올리는 역할, 즉 넓게 서서 공급하는 자리에 두는 것이 이 프로필에 맞다.');
INSERT INTO player_evaluations VALUES(49,1,17,'B — 왼쪽 센터백 슬롯(x=37)에서 cb_bpd/Aggressive 적합 0.935로 이번 8명 중 필드플레이어 최고값이고, 해당 슬롯 17경기 평균 평점 6.74다(prescriptions kind=''measured:season:full2526''). 기존 measured 행의 0.939 대비 Δ−0.003은 EA 노이즈 구간이라 판정은 그대로다. 다만 25/26 전체 40경기 1709분 중 프리미어리그 왼쪽 센터백 선발은 14경기(1202분·평점 6.59)뿐이고 나머지는 짧은 교체·컵대회라, 주전이 아니라 ''적합도는 높은 로테이션 자원''으로 읽어야 한다. obs#152로 뒤늦게 등재된 8명 중 실측 근거가 가장 두꺼운 축이다. ⭐[2026-09-11 FC27 갱신] OVR 78→77(−1), PAC57(−1)·DRI61(−3)·PHY77(+1), SHO/DEF 불변. PlayStyles Bruiser 유지.','196cm 좌발 센터백. 몸싸움과 공중볼로 버티는 전통적 수비수이면서 왼발 배급이 되는 유형이다. FC26 데이터상 특성은 ''브루저''와 ''부상에 취약함'', 개인 특성 태그는 ''공중 지배자''이고 능력치는 헤딩 77·점프 80·힘 85·공격성 86·슬라이딩 태클 80에 비해 가속 49·민첩성 34로 방향 전환이 느리다. 즉 앞으로 나가 부딪치는 것은 강하고 뒤로 돌아 뛰는 상황이 약하다. 유로파리그 왼쪽 센터백 2경기 평점 7.75, 대회 통산 11경기 평점 7.17로 강도가 낮은 경기에서 값이 크게 오른다. ⭐[FC27 2026-09-10] PlayStyles Bruiser 단일 유지, DRI 64→61(−3)로 하락 — 가속49·민첩34 약점(FC26)과 같은 방향의 온볼 기동력 저하.','강점: 패스 정확도 90.0%(리그 동포지션 상위 21%)와 왼발 롱패스로 왼쪽 빌드업의 출발점이 된다. 정확한 롱볼 37회(2.52/90), 성공 패스 842회(90분당 57.3회, 상위 27%)로 볼을 만지는 양 자체가 많다. 공중 경합 40승·승률 59.7%로 세트피스 방어의 축이고, 25/26 유로파리그에서 득점도 1개 있다. 1대1에서 제쳐당한 횟수가 시즌 2회(0.14/90, 상위 11%)로 매우 적다. 약점: 태클 5회(0.34/90)는 리그 센터백 중 하위 10%, 90분 기준으로는 하위 2%로 사실상 최하위다. 인터셉트 11회(하위 27%), 수비 행동 총량 108회(90분 기준 하위 19%)도 낮다 — 미리 끊어내는 유형이 아니라 걷어내고 막는 유형이다. 경합 승률 55.1%(하위 32%)로 지상 몸싸움 효율이 기대만큼은 아니고, 32세에 부상 이력이 게임 데이터에도 특성으로 박혀 있다. ⭐[FC27 갱신] OVR77(−1)·PHY77(+1)로 피지컬은 소폭 상승, DRI61(−3)로 볼운반은 하락 — 몸싸움형 전통 수비수 프로필이 게임 능치로도 강화됐다.','fotmob_detail_stats 2025/2026 프리미어리그 40지표 기준(같은 리그 동포지션 대비). 상위권: 패스 정확도 90.0% 상위 21%, 제쳐당한 횟수 0.14/90 상위 11%, xG 1.37(0.094/90) 90분 기준 상위 16%, 헤더 슛 6회 90분 기준 상위 33%. 중위권: 공중 경합 승률 59.7% 상위 47%, 걷어내기 83회(5.65/90) 중간, 슛 블록 9회 중간. 하위권이 뚜렷하다 — 태클 90분 기준 하위 2%, 수비 행동 총량 90분 기준 하위 19%, 인터셉트 90분 기준 하위 20%, 드리블 성공률 33.3% 하위 18%. ⚠️ 우리 3팀 풀(59명) 백분위와 어긋나는 지점: 우리 풀에서는 경기당 태클 42%·인터셉트 73%로 평범~중상위로 보이지만, 리그 센터백만 놓고 보면 각각 하위 10%·하위 27%다. 풀이 골키퍼·공격수까지 섞인 전 포지션 집합이라 수비 지표가 부풀려 보이는 것이므로, 밍스의 수비 개입 빈도 판단은 리그 백분위 쪽을 채택해야 한다. 반대로 평점은 우리 풀에서 하위 31%인데 이는 컵대회 고평점이 섞인 40경기 평균 6.71 기준이다. 수비수의 낮은 득점 지표는 정상 범위다. ⭐[2026-09-11] FC27 OVR77(−1)·DRI61(−3) 갱신 — 실측 태클 백분위 10·인터셉트 27 등 낮은 개입 빈도와 방향이 같다(온볼 기동력 축 동반 하락).','HIGH — 왼쪽 센터백 슬롯 x=37에서 cb_bpd(볼 플레잉 센터백)/Aggressive 적합 0.935(17경기·평점 6.74) 실측. 에메리 체제의 게임 구현 기준선이 ''짧은 빌드업 + 양 센터백 cb_bpd''(manager_profiles regime 1 implementation ⑴)이므로 처방 역할과 실측 역할이 정확히 겹친다. ⚠️ 단, FC26 roster의 역할 친숙도는 cb_defender 하나뿐이라 게임 안에서 cb_bpd를 주면 친숙도 밖 배치가 된다 — 실측 커널과 게임 내 친숙도가 어긋나는 항목으로 기록해 둔다. 또한 에메리의 기준 수비 라인 52·약팀 상대 67(하이라인)은 가속 49·민첩성 34인 그의 뒷공간 커버와 상충하므로, 하이라인 프리셋에서는 파트너 선택으로 보완해야 한다. ⚠️[2026-09-11] FC27 OVR 소폭 하락(−1)은 등급 변경 근거로 부족 — 기존 HIGH 유지.','MEDIUM — (교차 투영 — 실측 아님) 알론소 체제는 백3 빌드업에 전 센터백 cb_bpd/Aggressive를 주고 ''탁-탁-탁'' 짧은 리듬 패스로 상대 결정을 강요하는 구조다(manager_profiles regime 2 buildup·implementation ⑴). 밍스의 패스 정확도 상위 21%와 왼발 배급은 백3의 왼쪽 센터백에 그대로 맞고, 백3는 좌우 커버가 나뉘어 있어 속도 약점도 백4보다 덜 노출된다. 다만 알론소 구조의 명시된 구조적 약점이 ''중앙 볼 상실 후 직선 역습 취약''(regime 2 rest_defense)이라 되돌아 뛰는 속도가 요구되는데 이 지점이 그의 최대 약점이다.','LOW — (교차 투영 — 실측 아님) 이라올라의 축은 고강도 압박과 수직 전환이고, 존 수비로 시작해 트리거가 걸리면 전면 맨투맨으로 넘어가며 터치라인까지 압축한다(manager_profiles regime 3 pressing). 이 구조는 센터백이 앞으로 튀어나가 미리 끊고 뒷공간을 혼자 감당하는 능력을 요구하는데, 밍스는 태클 90분 기준 하위 2%·인터셉트 하위 20%로 개입 빈도가 낮고 가속 49다. 제쳐당한 횟수가 적다는 강점은 물러서서 버티는 상황의 값이라 이 체제에서는 살리기 어렵다.','squad_entries(regime 1, CB/OWNED, rate 6.74, cb_bpd/Aggressive 0.935) · prescriptions kind=''measured''(LCB x=36 y=34, n=19) 및 ''measured:season:full2526''(LCB x=37, fit 0.935, n=17, 평점 6.74) · v_player_profile(n=40, 1709분, 평점 6.71, 경기당 dw 1.77·tk 0.25·ic 0.42) · 3팀 풀 59명 백분위 SQL 산출 · fotmob_detail_stats 2025/2026 Premier League 40지표(pulled 2026-08-11) · v_player_season_stats(PL 23경기 1323분 6.65 / 유로파 11경기 273분 7.17) · player_matches lineup_pos 분포(LCB PL 14 / LCB EL 2 / RCB 2 / D 21) · player_game_stats FC26 roster 2026-06-30(OVR 78, 32세, €9M) · manager_profiles regime 1·2·3 · observations #152 | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR77·DRI61·PHY77·PlayStyles Bruiser) vs FC26(roster_date 2026-07-23, OVR78·DRI64·PHY76)','MEDIUM-HIGH — 슬롯 적합 표본 17경기·리그 실측 40지표로 8명 중 가장 두껍다. ⚠️ 캐비앗: ⑴ 40경기 중 21경기가 lineup_pos ''D'' 라벨의 짧은 교체·컵 출전이라 v_player_profile 평균 6.71과 슬롯 집계 6.74는 모집단이 다르다. ⑵ 유로파리그 평점 7.17·왼쪽 센터백 2경기 7.75는 상대 강도가 낮은 표본이라 프리미어리그 6.59와 나란히 두면 안 된다. ⑶ 리그 백분위는 프리미어리그 동포지션 기준이고 우리 풀 백분위는 3팀 전 포지션 기준이라 방향이 어긋나는 항목이 있다(태클·인터셉트) — 본문에 명기했다. ⑷ 알론소·이라올라 적합은 manager_profiles 축과의 정성 대조이며 교차 투영 — 실측 아님. ⑸ 실측 커널(cb_bpd)과 FC26 역할 친숙도(cb_defender)가 불일치한다. ⚠️ 2026-09-11: FC27 능치 변화(OVR−1·DRI−3)는 미미 — 표본·판정 기존과 동일. 33세 가용성 리스크는 게임 능치에 반영되지 않는 별개 축.','2026-09-11','프리미어리그 센터백 중 1300분 남짓의 표본이고, 프로필의 모양은 공은 안정적으로 다루지만 능동적 수비 개입이 적은 쪽이다. 강점은 대인 방어에서 벗겨지지 않는 것과 배급이다 — 제쳐당한 횟수 90분당 0.14회가 백분위 89, 패스 정확도 90.0%가 79, 90분당 성공한 패스가 73, 터치가 71이다. 세트피스 위협도 있어 90분당 xG 백분위가 84다. 약점은 태클 5회(90분당 2)와 인터셉트 11회(20), 수비적 행동(19)으로 공을 끊어내는 행동의 빈도가 최하위권이라는 점이다. 90분당 출전 중 피xG 백분위 20으로, 이 선수가 뛸 때 팀이 허용한 슛의 질도 좋지 않았다. 앞으로 나가 끊는 역할이 아니라 자리를 지키며 배급하는 센터백으로 한정해 쓰고, 옆에 능동적으로 커버하는 짝을 붙이는 것이 맞다.');
INSERT INTO player_evaluations VALUES(50,1,18,'B− — 오른쪽 와이드 슬롯(x=85)에서 wm_winger/Balanced 적합 0.782(15경기·1235분·평점 6.76)로 중상 수준이지만 배치 문제라는 기존 판정은 유지된다. FC27(09-10) 신규 수집에서 OVR은 78로 FC26(2026-06-30, OVR78)과 동일하나, 스피드 83→78(-5)·피지컬 78→72(-6)로 하락하고 FC26의 래피드(Rapid) PlayStyle이 FC27에서 사라졌다 — 게임 능치 갱신 방향이 실측(공중 경합·태클 강점, 창조 취약)과 정합적으로, 몸싸움형 강점이 다소 둔화되는 쪽으로 재조정됐다. 이적 논의는 진행 중(transfer_outgoing #15, MEDIUM-HIGH).','188cm에 이번 FC27 갱신 기준 질주 속도 78(FC26 83→FC27 78, -5)·점프91의 큰 체격 측면·중앙 겸용 공격수다. 실측상 최고 산출은 중앙 스트라이커/세컨톱으로 왼쪽 하프스페이스를 자유롭게 드나들 때 나왔다(니스 24/25 중앙 3경기 4골 3도움, 경기당 xG 0.96). 오른쪽에 고정하면 값이 급락한다 — 빌라 우측 14경기에서 xG 0.62→0.17, xA 0.44→0.02로 붕괴(prescriptions measured). FC27 데이터 특성은 래피드 PlayStyle 소실, 역할 친숙도는 인사이드 포워드 계열과 포처.','강점: 측면 자원치고 몸싸움과 공중볼이 압도적이다 — 공중 경합 승률 45.8%로 리그 동포지션 상위 17%(83퍼센타일 재확인), 태클 24회(2.36/90) 상위 11~40%대(재확인 60), 경고·퇴장 0장(백분위 100). 얻어낸 파울도 상위권. 약점: 창출이 거의 없다 — 기회 창출·슛·터치·성공 패스 모두 90분 기준 하위, 볼 뺏김도 하위권. FC27 피지컬 하락(78→72)은 이 몸싸움 강점의 수치적 여유가 줄었음을 시사하나 실측 태클·경합 수치 자체는 아직 유지된다.','fotmob_detail_stats 2025/2026 프리미어리그 39지표 기준. 90분 기준 백분위로 보면 프로필이 극단적으로 갈린다 — 위쪽: 공중 경합 승률 45.8% 상위 17%, 헤더 슛 상위 12%, 태클 2.36/90 상위 11%, 슛 블록 상위 11%, 경합 승 6.78/90 상위 11%, 얻어낸 파울 1.97/90 상위 15%, 수비 행동 8.35/90 상위 21%. 아래쪽: 성공 패스 15.1/90 하위 8%, 슛 1.08/90 하위 8%, 기회 창출 0.49/90 하위 8%, 터치 40.5/90 하위 9%, 볼 뺏김 2.75/90 하위 6%, 정확한 롱볼 하위 3%. 즉 리그 백분위가 그리는 그림은 ''창출하는 윙어''가 아니라 ''싸우고 복귀하는 윙어''다. ⚠️ 우리 풀 백분위와 크게 어긋나는 항목: 우리 3팀 풀에서 경기당 xG 백분위가 90%로 최상위처럼 보이지만, 리그 동포지션 대비 xG는 상위 63%(총량)·상위 60%(90분)에 불과하다. 풀 값의 표본이 xG 기록이 있는 2경기뿐(v_player_profile xg_n=2)이기 때문이며, 이 항목은 리그 백분위를 채택해야 한다. 우리 풀 키패스 백분위 27%는 리그 기회 창출 하위 8%와 방향이 같아 서로 지지한다. ⚠️ 2026-09-11 FC27(09-10) 대조: OVR 78 유지, pac 83→78·phy 78→72 하락, PlayStyle 래피드 소실. 실측(fotmob) 자체는 재수집되지 않아 이 회차엔 변화 없음 — 위 리그 백분위·3팀 풀 수치는 2026-08-11 갱신분 그대로다.','MEDIUM — 오른쪽 와이드 x=85에서 wm_winger/Balanced 0.782 실측(15경기)으로 커널 자체는 무난하나, 에메리 구현의 오른쪽 와이드 요구(wm_widemid/Support, 두 번째 줄 복귀형)와 배치 미스매치로 산출이 붕괴(xG 0.62→0.17). 에메리 구조에서 최적은 10번 자리이나 그 배치의 실측 적합값은 없다. FC27 능치 변화는 이 판정에 영향 없음.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 알론소 구조의 핵심 중 하나가 하프스페이스에 2명의 10번을 두는 것이고(regime 2 philosophy·implementation ⑷), 윙백이 폭을 독점하므로 안쪽 선수는 측면 고정 임무에서 해방된다. 게상이 값을 낸 유일한 프로필이 ''중앙 또는 하프스페이스 자유 드리프트''이므로 구조 방향이 일치한다. 또 백3 뒤에서 앞으로 나가는 9번 대신 내려오는 9번(st_false9)을 쓰는 구성이라 그의 포처 성향과는 다소 어긋난다. ⚠️ 이는 manager_profiles 축과의 정성 대조일 뿐 알론소 체제 실측이 아니며, 25/26 첼시 전술은 알론소의 것이 아니다(불변규칙 7).','MEDIUM — (교차 투영 — 실측 아님) 이라올라 체제는 파이널서드에서 볼을 빼앗아 즉시 슛으로 가는 것이 압박의 목적이다(regime 3 pressing). 게상의 태클·경합 승 90분 상위 11%는 전방 압박 임무의 원료로 쓸 만하다. 그러나 정면으로 걸리는 수치가 있다 — 상대 진영 볼 탈취가 3회(0.295/90)로 90분 기준 하위 11%다. 즉 수비 행동은 많지만 그 위치가 앞이 아니라 자기 진영 오른쪽이다. 압박 후 즉시 마무리라는 요구에도 슛 1.08/90 하위 8%가 걸린다.','squad_entries(regime 1, WM/OWNED, rate 6.76, wm_winger/Balanced 0.782) · prescriptions 5행 — ''measured''(RM x=79 y=58, 빌라 25/26 오른쪽 14경기 통합, 산출 붕괴 서술), ''measured:season:full2526''(RM x=85, fit 0.782, n=15, 1235분, 평점 6.76), ''measured:CP-loan''(CAM x=40 y=62, 팰리스 7경기, 평점 6.77), ''measured:ST''·''measured:RM''(니스 24/25) · v_player_profile(n=62, 2905분, 평점 6.83) · 3팀 풀 59명 백분위 · fotmob_detail_stats 2025/2026 Premier League 39지표 · v_player_season_stats(PL 26경기 933분 6.56 / 유로파 6경기 524분 6.63 / 컨퍼런스 4경기 321분 7.08 / 니스 24-25 Ligue 1 6경기 8.42) · player_matches lineup_pos(RAM PL 5·LAM PL 4·F PL 15 교체) · player_game_stats FC26(OVR 78·POT 83, 24세, €21M, 소속 Crystal Palace 표기) · transfer_outgoing #15 · manager_profiles 1·2·3 · observations #152·#122·#108·#84 | stat_eval 2026-09-11 갱신: FC27(roster_date 2026-09-10, OVR78·pac78·sho76·pas73·dri78·def36·phy72, PlayStyles 없음, 188cm/79kg) 대조 — FC26(2026-06-30, OVR78·pac83·sho76·pas72·dri78·def36·phy78·래피드) 대비 pac -5·phy -6·PlayStyle 소실.','n=62(2905분) 실측은 유지. FC27 게임 능치 하락(pac/phy)은 확인됐으나 실측 스탯 재수집은 이번 회차에 없어 리그 백분위·3팀 풀 수치는 갱신되지 않았다. ⚠️ 이적 불확실성(transfer_outgoing #15) 지속 — 이 평가는 잔류 전제. 알론소·이라올라 핏은 교차 투영(실측 아님).','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 917분 표본이라 90분당 백분위로 읽는다 — 그 기준에서는 공중과 지상 경합에 강하고 공을 다루는 양이 극단적으로 적은 유형이다. 90분당 경합 승 6.78회가 백분위 89, 태클 2.36회가 89, 공중 경합 승 1.08회가 81이고 공중 경합 승률 45.8%가 83, 얻어낸 파울 1.97회가 85로 몸으로 버티는 지표가 상위권이다. 헤더 슛(88)과 슛 블록(89)도 높다. 문제는 소유 국면이다 — 90분당 성공한 패스 15.13회가 백분위 8, 터치 40.48회가 9, 기회 창출 0.49회가 8, 슛 1.08회가 8, 정확한 롱볼이 3으로 공을 만지는 지표 전부가 최하위이고 볼 뺏김도 6이다. 짧은 시간 투입해 몸싸움과 압박으로 경기 리듬을 끊는 용도로는 읽히지만, 공을 맡겨 전개하는 자리에 세울 근거는 없다.');
INSERT INTO player_evaluations VALUES(51,1,19,'B+ — 골키퍼 슬롯(x=50)에서 gk_goalkeeper/Defend 적합 0.961로 8명 중 최고값이고, 해당 슬롯 16경기(1306분) 평균 평점 7.08이다. 에메리 구현 문서가 ''골키퍼는 스위퍼가 아니라 패스 옵션 수준의 참여''라고 못 박으면서 근거로 든 실측값 .961이 바로 이 행이다(manager_profiles regime 1 implementation ⑴). 다만 실제 기용은 컵·유로파 전담이다 — 프리미어리그는 37경기 명단 중 실출전 585분에 그치고 유로파리그 15경기(360분) 평점 8.43이 평균값을 끌어올린다. 즉 ''체제 적합도가 매우 높은 2번 골키퍼''다. ⭐[2026-09-11 FC27 갱신] OVR 78→77(−1), PAC77·SHO74·PAS71·DRI77·DEF44(각 −1~−2 소폭 하락), PlayStyles Footwork 단일 유지.','193cm·34세 네덜란드 골키퍼. FC26 데이터의 특성은 ''긴 스로우'', ''발놀림'', ''디플렉터''이고 역할 친숙도는 볼 플레잉 골키퍼다. 능력치는 위치 선정 79·반사신경 78·다이빙 78·핸들링 75·킥력 72로 고르게 짜여 있고 특별히 튀는 항목이 없다. 리그 실측에서는 발로 하는 부분이 손보다 더 두드러진다 — 패스 정확도와 스위퍼 행동 빈도가 리그 골키퍼 중 최상위권이다. ⭐[FC27 2026-09-10] Footwork PlayStyle 유지, OVR77(−1) — 발밑 안정성 서사(패스 정확도 백분위 90)와 대응.','강점: 발밑이 확실하다. 패스 정확도 76.3%로 리그 골키퍼 중 상위 10%, 90분당 성공 패스 28.3회로 상위 15%, 롱볼 정확도 34.9% 상위 36%다. 짧은 빌드업에 골키퍼를 참여시키는 에메리 구조에서 그대로 쓰이는 값이다. 페널티박스 밖으로 나와 처리하는 행동(스위퍼 역할)이 9회, 90분 기준 상위 5%로 리그 최상위권이고, 하이볼 처리 7회도 90분 기준 상위 23%다. 유로파리그 15경기 평점 8.43은 컵 전담 골키퍼로서의 실적이다. 약점: 선방 수치가 평범하다 — 선방률 65.5%는 하위 36%, 선방으로 막은 실점이 −0.42로 기대 실점 대비 오히려 0.42골 손해다(상위 46%로 리그 중간). 클린시트 1회는 하위 23%. 실책이 실점으로 이어진 사례가 1회 있고 90분 기준 하위 10%다. 34세라 뎁스 자원 이상으로 올리기 어렵고, 프리미어리그 실출전 585분은 판단 근거로 얇다. ⭐[FC27 갱신] OVR 77(FC26 78 대비 −1)·DEF44(−2)로 전반 소폭 하락, PlayStyles Footwork 유지 — 실측 강점(패스 정확도 76.3% p90·스위퍼 행동 p95)과는 무관한 미세 조정.','fotmob_detail_stats 2025/2026 프리미어리그 18지표 기준(골키퍼는 지표 수 자체가 적다). 상위: 패스 정확도 76.3% 상위 10%, 스위퍼 행동 1.385/90 상위 5%, 성공 패스 28.3/90 상위 15%, 하이볼 처리 1.077/90 상위 23%, 롱볼 정확도 34.9% 상위 36%. 중위: 선방 2.92/90 상위 41%, 막은 실점 −0.42 상위 46%. 하위: 선방률 65.5% 하위 36%, 클린시트 하위 23%, 실책→실점 90분 기준 하위 10%, 경고 2장 90분 기준 최하위, 페널티 선방 0/0. ⭐ 판정에 걸리는 어긋남이 하나 있다: 우리 처방은 gk_goalkeeper/Defend, 즉 ''스위퍼가 아니다''인데 리그 백분위에서 스위퍼 행동은 90분 기준 상위 5%로 최상위다. 커널 적합 0.961은 히트맵 분포 형태에서 나온 값이고 스위퍼 백분위는 이벤트 빈도라 측정 대상이 다르지만, 두 근거의 방향이 반대라는 사실은 기록해 둔다 — 다만 그의 프리미어리그 표본이 585분(약 6.5경기)이라 9회라는 절대량 자체가 얇고, 처방 쪽 표본(16경기 1306분)이 더 두껍다. ⚠️ 우리 3팀 풀 백분위(경기당 경합 승 19%·태클 31%)는 골키퍼에게 의미가 없는 항목이므로 해석하지 않는다. 풀 평점 백분위 66%는 8명 중 최고다. ⭐[2026-09-11] FC27 OVR77(−1) 갱신 — 패스 정확도 백분위 90 등 배급 강점은 게임 능치 하락에도 실측상 변함없다.','HIGH — gk_goalkeeper/Defend 적합 0.961(16경기·평점 7.08)로 8명 중 최고 실측값이고, 에메리 구현 문서가 골키퍼 처방의 근거로 직접 인용하는 값이다(regime 1 implementation ⑴: ''GK gk_goalkeeper/Defend — 스위퍼 아님, 실측 .961''). 빌드업 축에서 요구되는 것은 ''수적 우위를 만드는 패스 옵션''인데 그의 패스 정확도 리그 상위 10%가 정확히 그 요구에 맞는다. 실질 역할은 유로파·컵 전담 2번 골키퍼이고 그 범위에서 평점 8.43으로 값을 냈다. ⚠️ FC26 역할 친숙도는 gk_ballplaying으로 잡혀 있어 처방한 gk_goalkeeper와 어긋난다 — 게임 안에서는 친숙도 밖 배치가 된다. ⚠️[2026-09-11] FC27 OVR 소폭 하락(−1)은 등급 재검토를 요할 만큼 크지 않다 — 기존 HIGH 판정 유지.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 알론소 구조는 백3와 더블 피벗으로 후방 7인을 만들어 짧은 리듬 패스를 돌리는 형태이고(regime 2 buildup) 골키퍼는 그 사슬의 한 칸이다. 패스 정확도 리그 상위 10%가 여기에 그대로 쓰인다. 또 중앙 볼 상실 시 직선 역습에 취약하다는 구조적 약점(regime 2 rest_defense)을 고려하면 박스 밖으로 나와 끊는 스위퍼 행동 상위 5%가 보험 역할을 한다. 다만 선방률 하위 36%는 역습을 실제로 맞았을 때의 마지막 방어선으로는 약하다.','MEDIUM — (교차 투영 — 실측 아님) 이라올라는 높은 라인과 수직 전환을 축으로 하고(regime 3 philosophy), 하이라인 뒤 넓은 공간을 골키퍼가 커버해야 한다. 스위퍼 행동 90분 상위 5%·하이볼 처리 상위 23%는 이 요구에 잘 맞는다. 반면 수직 전환의 시발점으로 긴 패스를 정확히 꽂아야 하는데 롱볼 정확도 34.9%(상위 36%)와 정확한 롱볼 30회(하위 26%)는 중간 수준이다. 34세라는 나이도 하이라인 뒤 넓은 커버를 상시 요구하는 체제에서는 감점 요인이다.','squad_entries(regime 1, GK/OWNED, rate 7.08, gk_goalkeeper/Defend 0.961) · prescriptions ''measured''(GK x=51 y=10, n=13) 및 ''measured:season:full2526''(GK x=50, fit 0.961, n=16, 1306분, 평점 7.08) · v_player_profile(n=58, 1370분, 평점 7.05) · 3팀 풀 59명 백분위 · fotmob_detail_stats 2025/2026 Premier League 18지표 · v_player_season_stats(PL 37경기 585분 6.54 / 유로파 15경기 360분 8.43 / EFL컵 1경기 90분 7.5 / FA컵 2경기 136분 6.25) · player_matches lineup_pos 전건 ''G'' · player_game_stats FC26(OVR 78, 34세, €2.4M, 역할 친숙도 gk_ballplaying) · manager_profiles regime 1·2·3 · observations #152 | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR77·DEF44·PlayStyles Footwork) vs FC26(roster_date 2026-07-23, OVR78·DEF46)','MEDIUM-HIGH — 커널 적합 표본은 16경기 1306분으로 충분하고 값(0.961)도 압도적이다. ⚠️ 캐비앗: ⑴ 프리미어리그 실측 표본이 585분(약 6.5경기)뿐이라 fotmob 리그 백분위는 표본이 얇다 — 선방 19회·실점 10골 수준의 절대량에서 산출된 값이므로 선방률 65.5% 같은 비율 지표는 한 경기로도 크게 흔들린다. ⑵ v_player_profile의 58경기·평점 7.05는 미출전 명단 포함 행을 포함한 값이라 실출전 기준과 다르다. ⑶ 유로파리그 평점 8.43(4경기 기록)은 상대 강도가 다른 표본이고 평균을 위로 끌어당긴다 — 프리미어리그 평점 6.54와 나란히 두지 말 것. ⑷ 처방(스위퍼 아님)과 리그 스위퍼 백분위 상위 5%가 방향이 반대다 — 본문에 명기했다. ⑸ 실측 커널(gk_goalkeeper)과 FC26 역할 친숙도(gk_ballplaying)가 불일치한다. ⑹ 알론소·이라올라 적합은 교차 투영 — 실측 아님. ⚠️ 2026-08-11 판정(obs#154): 이 평가가 지적한 ''스위퍼 행동 90분 상위 5% vs 처방 gk_goalkeeper/Defend'' 충돌은 **처방 유지로 해소**됐다 — 해당 백분위는 리그 585분에서 나온 비율값이고 합계 백분위는 41이다. 그리드 커널은 Defend .961 vs sweeper .773(Δ.188, 노이즈 밖). 패스 정확도 백분위 90이 오히려 프로필의 ''패스 옵션 수준 참여''를 확증한다. ⚠️ 2026-09-11: FC27 능치 변화(OVR−1)는 미미 — 표본·판정 기존과 동일.','2026-09-11','프리미어리그 골키퍼 중 585분 남짓만 뛴 소표본이고 골키퍼는 수집 지표가 18개뿐이므로, 결론의 강도는 낮게 잡아야 한다. 90분당 백분위로 읽으면 강점은 골문 밖으로 나오는 플레이와 발밑이다 — 90분당 스위퍼 행동 1.39회가 백분위 95, 하이볼 처리 1.08회가 77, 성공한 패스 28.31회가 85, 패스 정확도 76.3%가 90이다. 반면 슛을 막는 쪽은 평범 이하다 — 선방률 65.5%가 백분위 36이고, 선방으로 막은 실점이 -0.42로 기대보다 덜 막았다. 클린시트 1회(23), PK 선방률 0.0%(21), 90분당 실책이 실점으로 이어진 횟수(10)도 낮다. 나가서 처리하고 후방 빌드업에 가담하는 쪽으로는 쓸 만하지만, 슛 저지 능력이 검증되지 않은 백업 프로필로 읽는 것이 정확하다.');
INSERT INTO player_evaluations VALUES(52,1,21,'B+ — 오른쪽 수비형 미드필더 슬롯(x=62)에서 dm_dlp/Roaming 적합 0.807(17경기·875분·평점 6.91)이고, CAM(x=50)에서 cam_playmaker/Build-Up 0.803으로 스쿼드 1위(2위 맥긴 0.641, 마진 0.162)다. 26/27 LDM 포지션-순수 2경기(아스날·헐, 168분) 집계는 dm_dlp/Roaming 0.823·평균 7.25로 8월 평가보다도 개선됐다. FC27(09-10) OVR77은 FC26과 동일(변동 없음) — PlayStyles가 Power Shot으로 신규 등록돼 기존 traits의 ''파워슛'' 특성 서술이 FC27 데이터로 확증됐다.','189cm·31세 중앙 미드필더. 커널 판정 근거가 평균 위치가 아니라 분포 형태라는 점이 핵심 — dm_dlp/Roaming 커널에 넓고 대칭적인 분포가 잘 담긴다. FC27 PlayStyles=Power Shot이 신규 확인돼, 기존에 ''특성은 파워슛''으로 추정 서술했던 부분이 게임 데이터로 직접 확증됐다. FC27 dri 77(FC26 76 대비 +1)·def 65(64 대비 +1)로 온볼·수비 계열이 소폭 오르고 phy 66(68 대비 −2)로 피지컬은 소폭 하락(roster_date 2026-09-10). 26/27 LDM 실측(2경기·168분·평균 7.25·dm_dlp/Roaming 0.823)이 8월 평가치(0.807·6.91)보다 개선돼 시즌 초반 폼이 상승 곡선이다.','강점: 드리블 성공률 65.0%(리그 동포지션 상위 4%), 롱볼 정확도 73.7%(상위 8%), 패스 정확도 87.7%(상위 11%), 90분당 성공 패스 37.7회(상위 10%). 체격도 좋다 — 공중 경합 승률 46.7%(상위 14%). FC27 능력치는 sho83·pas78·dri77로 큰 변화 없이 유지되며(OVR77 불변), PlayStyles Power Shot이 신규 등록돼 앞서 언급된 파워슛 트레잇을 공식 확증한다. 약점은 여전하다 — 상대 박스 안 터치 18회(하위 9%), 인터셉트 2회(하위 15%), 상대 진영 볼 탈취 3회(하위 13%), 태클 14회(하위 35%) — 앞에서 끊는 선수가 아니다. 31세·가속 52로 뒤로 도는 속도가 없다.','fotmob_detail_stats 2025/2026 프리미어리그 39지표 기준은 유지 — 드리블 성공률 65.0%(상위 4%)·롱볼 정확도 73.7%(상위 8%)·패스 정확도 87.7%(상위 11%). 하위: 상대 박스 터치 1.90/90(하위 9%)·상대 진영 볼 탈취(하위 13%)·인터셉트(하위 15%). 신규: FC27(2026-09-10) OVR77·PAC53·SHO77·PAS78·DRI77·DEF65·PHY66, PlayStyles=Power Shot(신규 등록), 신장186cm·76kg. FC26 직전(2026-07-23) 대비 OVR 불변·DRI+1·DEF+1·PHY−2로 변화 폭이 작다. 26/27 LDM 포지션-순수 2경기(875분→168분 신규 표본) 평균 7.25로 25/26 시즌 평균(6.85)·기존 fit_sim(0.807)보다 폼이 상승했다(dm_dlp/Roaming 0.823).','HIGH — 실측이 두 자리(RDM·CAM)에서 모두 지지하며, 26/27 LDM 포지션-순수 표본(0.823·평균 7.25)이 8월 판정을 재확인·소폭 상회한다. FC27 Power Shot PlayStyles가 기존 파워슛 트레잇 서술을 확증. 에메리 미드블록의 ''탈취 후 전환'' 요구와는 여전히 긴장 — 인터셉트 하위 15%·상대 진영 볼 탈취 하위 13%로 이 축의 기여는 얇다.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 알론소 구조의 더블 피벗은 카이세도가 백라인 옆으로 내려와 상대 압박을 유인하는 dm_dlp/Roaming, 리스 제임스가 창조 축의 dm_dlp/Build-Up이다(regime 2 implementation ⑶). 바클리의 실측 커널이 정확히 dm_dlp이고 최적 포커스도 Roaming과 Build-Up 두 가지라 역할 정의가 겹친다. 패스 정확도 상위 11%·롱볼 정확도 상위 8%는 ''탁-탁-탁'' 짧은 리듬 패스와 백3 뒤 배급 요구에 그대로 맞는다. ⚠️ 걸리는 지점: 이 구조의 명시된 약점이 ''박스 미드필드 중앙에서 볼 상실 시 직선 역습에 취약하고 기술 규율 요구가 극단적으로 높다''(regime 2 rest_defense)는 것이다. 31세·가속 52·인터셉트 하위 15%는 그 보험 역할에 부적합하므로, 두 피벗 중 다른 한 명이 Defend 계열이어야 한다.','LOW — (교차 투영 — 실측 아님) 이라올라의 압박 목적은 파이널서드 탈취(리그 3위) 후 즉시 슛이고 수직성이 극단적이다(초당 1.95m 최속·시퀀스당 2.98패스, regime 3 philosophy·pressing·situational). 바클리는 정면으로 어긋난다 — 상대 진영 볼 탈취 90분 기준 하위 13%, 인터셉트 하위 15%, 상대 박스 터치 하위 9%다. 즉 앞에서 뺏지도 않고 앞으로 들어가지도 않는다. 가속 52·질주 53으로 존 수비에서 전면 맨투맨으로 전환하는 트리거식 수비의 체력·속도 요구도 맞추기 어렵다. 그의 장점(배급 정확도·볼 유지)은 이 체제가 가장 덜 요구하는 항목이다.','squad_entries(regime 1, DM/OWNED, rate 6.91, dm_dlp/Roaming 0.807) · prescriptions 3행 — ''measured''(CM x=50.2 y=53, 6경기, 대역 분해 및 좌우 스왑 로테이션 서술), ''measured:season:full2526''(RDM x=62, fit 0.807, n=17, 875분, 평점 6.91), ''role''(RDM dm_dlp/Roaming 0.836, LDM 0.798, CAM cam_playmaker/Build-Up 0.803 스쿼드 1위, CAM 10개 역할×포커스 전수 열거) · v_player_profile(n=25, 960분, 평점 6.84, 경기당 kp 0.44·dw 2.2·tk 0.64) · 3팀 풀 59명 백분위 · fotmob_detail_stats 2025/2026 Premier League 39지표 · v_player_season_stats(PL 22경기 865분 6.85, 3골 1도움) · player_matches lineup_pos 전건 ''M'' · player_game_stats FC26(OVR 77, 31세, €8.5M, 역할 친숙도 cm_b2b·cam_playmaker) · manager_profiles regime 1·2·3 · observations #152·#134 | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date=2026-09-10, OVR77·PAC53·SHO77·PAS78·DRI77·DEF65·PHY66·PlayStyles=Power Shot·186cm/76kg) vs FC26(2026-07-23, OVR77) — 변화 폭 작음(DRI+1·DEF+1·PHY−2) · prescriptions ''measured|LDM'' 2026-09-06 갱신(2경기·168분·평균 7.25·dm_dlp/Roaming 0.823)','MEDIUM-HIGH — 슬롯 적합 표본 17경기·리그 실측 39지표이고 CAM 마진 0.162는 노이즈 구간(Δ0.02~0.05) 밖이라 판정이 견고하다. ⚠️ 캐비앗: ⑴ SofaScore lineup_pos 라벨이 전건 일반값 ''M''이라 경기별 LDM/RDM/CAM 구분이 불가능하다 — 슬롯 판정은 커널 적합도에 의존하며 라벨 근거가 아니다(prescriptions ''role'' 행 명기). ⑵ 그리드 산출의 원 표본은 6경기이고 시즌 집계는 17경기로 모집단이 다르다. ⑶ 프리시즌 친선은 SofaScore가 선수별 스탯·히트맵을 제공하지 않아(obs#133) ''프리시즌 왼쪽 수비형 미드필더 기용''은 실측으로 직접 확인되지 않는다 — 선발 여부(4/5경기)만 라인업 원천값이다. ⑷ 유출 이력이 있다 — 2026-07-27 리포트에 코번트리와의 협상이 2티어권으로 기록됐으나 transfer_outgoing에는 행이 없고 SofaScore 소속은 Aston Villa다. ⑸ RDM 0.836과 시즌 집계 0.807의 차이는 표본·집계 방식 차이이며 EA 노이즈 구간에 가깝다. ⑹ 알론소·이라올라 적합은 교차 투영 — 실측 아님. FC27 OVR·능력치 변화가 작아(±2 이내) 기존 판정에 실질적 영향 없음. 26/27 LDM 신규 표본(n=2, 168분)은 소표본이나 방향이 8월 판정과 일치해 신뢰를 보강한다.','2026-09-11','프리미어리그 미드필더 중 851분 표본이므로 90분당 백분위로 읽는다 — 그 기준에서는 공을 안정적으로 돌리고 몸싸움도 버티는 중원 유형이다. 90분당 성공한 패스 37.71회가 백분위 90, 패스 정확도 87.7%가 89, 롱볼 정확도 73.7%가 92, 드리블 성공률 65.0%가 96으로 소유 국면 지표가 상위권이다. 공중 경합 승률 46.7%(86)와 헤더 슛(90), 슛 블록(91), 90분당 득점 0.32골(85)도 좋다. 약점은 공을 끊는 위치와 마무리 지역 관여다 — 인터셉트 90분당 0.21회가 백분위 22, 상대 진영 볼 탈취가 13, 상대 박스 터치가 9로 전방 압박과 박스 진입이 거의 없고 기회 창출(34)도 평범하다. 짧은 출전 시간에서 뽑은 수치라 확대 해석은 피해야 한다. 점유를 유지하며 공을 안전하게 순환시키는 역할에 쓰고, 압박의 첨병이나 박스 진입을 기대하는 자리에는 쓰지 않는 편이 맞다.');
INSERT INTO player_evaluations VALUES(53,1,26,'C+ — 오른쪽 와이드 x=85에서 wm_winger/Attack 적합 0.768(9경기·523분·평점 6.46). 우리 3팀 풀 59명 중 평균 평점 백분위 17%로 최하위권. 이적이 진행 중이며 에메리 구상 밖으로 기록돼 있다. FC27(09-10) OVR77은 FC26(78) 대비 −1로 소폭 하락 — PlayStyles가 Quick Step(스피드 드리블 계열)으로 신규 등록됐으나, 실측 드리블 성공률 19.2%(리그 하위 5%)·경합 승률 33.8%(하위 8%)와는 정면으로 어긋난다.','오른쪽·왼쪽 모두 서는 측면 공격수. 실측은 ''올려주는 사람''에 가깝다 — 크로스·기회 창출은 리그 최상위, 스스로 마무리하거나 1대1로 뚫는 값은 리그 바닥. FC27 PlayStyles=Quick Step 신규 등록은 스피드 기반 돌파형 트레잇을 시사하지만, 실측 드리블 성공률(하위 5%)·경합 승률(하위 8%)이 이를 뒷받침하지 않아 게임 능력치와 실측 산출 사이 괴리가 크다. FC27 phy 58(FC26 61 대비 −3)로 피지컬 하락도 확인됐다 — 이적(헐 시티 협상 결렬·목적지 미정) 국면의 몸 상태 반영일 가능성이 있으나 데이터로 직접 확인되지 않는다.','강점: xA 1.46(90분 기준 상위 6%), 기회 창출 12회(2.39/90, 상위 6%), 크로스 정확도 26.3%(상위 27%), 볼 회수 6.17/90(상위 2%). 유로파리그 10경기 1골 1도움 등 컵대회 기여도 있다. 약점: 드리블 성공률 19.2%(하위 5%), 경합 승률 33.8%(하위 8%), 득점 0·유효슛 1회(하위 8%). FC27 sho 73(FC26 74 대비 −1)·phy 58(61 대비 −3)로 하락 방향은 이 약점과 정합적이나, PlayStyles Quick Step(속도형) 신규 등록은 부합하지 않는다 — 능력치·실측 간 불일치를 그대로 기록한다.','fotmob_detail_stats 2025/2026 프리미어리그 40지표(523분) 기준은 유지 — 90분 기준 볼 회수 상위 2%·xA 상위 6%·기회 창출 상위 6%, 드리블 성공률 하위 5%·경합 승률 하위 8%·xG 하위 11~17%. 신규: FC27(roster_date=2026-09-10) OVR77·PAC86·SHO73·PAS73·DRI82·DEF38·PHY58, PlayStyles=Quick Step(신규), 신장178cm·77kg. FC26 직전(2026-07-23) 대비 OVR−1·SHO−1·PHY−3로 소폭 하락. ⚠️ Quick Step(스피드 돌파 계열) PlayStyles와 실측 드리블·경합 최하위권 프로필은 방향이 어긋난다 — 게임 데이터가 최신 경기력 저하를 반영하지 못했을 가능성을 열어두되, 추정하지 않고 불일치로만 기록한다.','LOW — 커널 적합 wm_winger/Attack 0.768은 최악은 아니나 나머지 근거가 전부 반대 방향. FC27 소폭 하락(OVR−1·SHO−1·PHY−3)이 이 판정을 더 약화시키는 방향이다. transfer_outgoing #13(헐 시티 협상 결렬, 목적지 미정)과 에메리 구상 밖 판정은 그대로 — 게임 데이터 갱신이 이적 상황을 바꾸지 않는다.','LOW-MEDIUM — (교차 투영 — 실측 아님) 알론소 구조에서 폭은 윙백이 독점하고(regime 2 implementation ⑵) 안쪽 두 자리는 하프스페이스 10번이다. 즉 순수 측면 크로서를 위한 칸이 없다. 그의 최대 강점인 크로스·기회 창출이 구조적으로 쓰일 자리가 없고, 하프스페이스 10번에게 요구되는 좁은 공간에서의 개인 돌파와 마무리는 드리블 성공률 하위 5%·경합 승률 하위 8%로 정면으로 부족하다. 이 체제의 기술 규율 요구가 극단적으로 높다는 서술(regime 2 rest_defense)도 감점 요인이다.','MEDIUM — (교차 투영 — 실측 아님) 이라올라 체제와는 오히려 접점이 있다. 압박의 목적이 파이널서드 탈취 후 즉시 슛인데(regime 3 pressing) 그의 90분당 볼 회수 6.17회는 리그 상위 2%, 상대 진영 볼 탈취 0.796/90은 90분 기준 상위 24%로 앞에서 뺏는 값이 실제로 있다. 수직 전환에서 빠르게 올려주는 크로스(상위 22~27%)와 xA 상위 6%도 쓰인다. 다만 ''탈취 후 즉시 슛''의 슛 부분이 비어 있다 — 유효슛 하위 8%, 시즌 득점 0이다. 이라올라 체제의 언더독 구조 자체가 26/27 리버풀에서 재현될지가 미검증 과제이기도 하다(regime 3 situational).','squad_entries(regime 1, WM/OWNED, rate 6.46, wm_winger/Attack 0.768, rate_basis full2526) · prescriptions ''measured:season:full2526''(RM x=85, fit 0.768, n=9, 523분, 평점 6.46, lineup_pos=''M'' 필터) · v_player_profile(n=40, 1092분, 평점 6.58, 경기당 xa 0.084·kp 0.5·tk 0.55) · 3팀 풀 59명 백분위(평점 17%) · fotmob_detail_stats 2025/2026 Premier League 40지표 · v_player_season_stats(PL 16경기 466분 6.58 / Serie A 8경기 182분 6.44 / 유로파 10경기 106분 6.77 / 코파 이탈리아 1경기 7.1) · player_matches lineup_pos(F PL 10·M PL 6·F Serie A 8) · transfer_outgoing #13 · manager_profiles regime 1·2·3 · observations #152 | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date=2026-09-10, OVR77·PAC86·SHO73·PAS73·DRI82·DEF38·PHY58·PlayStyles=Quick Step·178cm/77kg) vs FC26(2026-07-23, OVR78) — OVR−1·SHO−1·PHY−3','LOW-MEDIUM — ⚠️⚠️ 이적 진행 중: transfer_outgoing #13(2026-summer, MEDIUM-HIGH, 최신 2026-08-09)에 따르면 헐 시티 완전이적 협상이 주급 £120k 부담 문제로 결렬됐고(Football Insider 2티어 단독, 1티어 교차확인 미완) 목적지가 ''사우디 프로리그 구단 미특정''으로 바뀌었다. 구단 공식 발표는 9일째 0건이며 헐 구단주의 SNS 주장은 근거로 채택하지 않았다. 에메리 구상 밖·아시아 투어 명단 제외·계약 1년 잔여로 이탈 압력이 확정적이다. ⚠️ 표본 캐비앗: ⑴ 슬롯 적합 표본이 9경기 523분으로 8명 중 두 번째로 얇다. ⑵ 25/26이 프리미어리그와 세리에 A(로마 임대)로 쪼개져 있어 리그 수준 보정이 없고, fotmob 백분위는 프리미어리그 523분만의 값이다. ⑶ 90분 기준 백분위와 총량 백분위가 극단적으로 갈리는데 이는 출전 시간의 산물이다 — 밀도 지표를 그대로 주전 산출로 환산하면 과대평가된다. ⑷ player_game_stats에 FC26 행이 없어 게임 능력치·특성·역할 친숙도는 결손이다. ⑸ 우리 풀 xG 백분위(71%)와 리그 xG 백분위(하위 11%)가 반대 방향이다 — 본문에 명기했다. ⑹ 알론소·이라올라 적합은 교차 투영 — 실측 아님. FC27 능력치 소폭 하락(OVR−1 등)은 방향상 실측 부진과 일치하나, 신규 PlayStyles(Quick Step)는 실측 드리블/경합 최하위권과 어긋나 — 게임 데이터를 등급 근거로 추가 채택하지 않았다.','2026-09-11','프리미어리그 공격형 미드필더·윙어 중 출전이 450분 남짓에 불과해 90분당 백분위로만 읽어야 하고, 결론은 잠정적이다. 그 기준의 강점은 마지막 패스와 압박량이다 — 90분당 기회 창출 2.39회가 백분위 94, xA 0.29가 94, 볼 회수 6.17회가 98, 수비적 행동 9.56회가 90이다. 크로스 정확도 26.3%(73)와 성공한 크로스(78)도 준상위다. 반대로 마무리와 1대1은 최하위다 — 90분당 xG 0.10이 백분위 17, xGOT가 8, 유효슛 1회가 8, 득점 0골이고 드리블 성공률 19.2%가 5, 경합 승률 33.8%가 8이다. 패스 정확도 77.0%(25)도 낮아 공을 오래 지키기 어렵다. 450분 표본에서 90분당 수치가 튀는 것을 감안하면, 교체로 들어가 크로스와 압박을 담당하는 제한된 용도 이상으로 확대할 근거는 없다.');
INSERT INTO player_evaluations VALUES(54,1,27,'C (유지) — ⚠️ 판단 보류 지속: fit_sim 미산출(squad_entries 그리드·적합 3경기 표본 미달, fit_role/fit_focus/fit_sim NULL). FC27 09-10 수집에서 누락 확인됐으나, 기존 결손으로 기록됐던 FC26 게임 스탯이 실은 2026-07-23자로 존재한다 — OVR72·pac81·sho44·pas65·dri69·def68·phy67, PlayStyle 없음. 이전 평가의 「player_game_stats FC26 행 없음」 서술을 이 갱신으로 정정한다.','오른쪽 풀백. 실측 히트맵은 여전히 딥(x81.7·y46.6). FC26 신규 확인: pac81이 6명 중 가장 높은 스피드 스탯 — 세르비아어 서사(한 명도 없다, 더 빠른 사람은 없다)와 정확히 정합한다. 반면 def68·phy67은 6명 중 하위권으로, 경합승률26.7%(하위2%) 등 몸싸움 약점 서사와도 일치.','v_player_profile 표본이 n=22→27·375→486분으로 늘었으나 평균평점은 6.47로 동일. 26/27 시즌 친선전 위주 4경기78분(선발1) 평점6.6로 초반 소폭 개선 신호는 있으나 여전히 매우 얇다. 강점(정확도 계열)·약점(경합·수비 개입) 서술은 기존과 동일 — 이번 갱신에서 바뀐 새 실측은 없다.','FC27 09-10 목록에 없음을 재확인(instructions 명시 결손과 일치). FC26(2026-07-23) 신규 확인: OVR72·pac81·sho44·pas65·dri69·def68·phy67 — 이전 평가가 「FC26 행 없음」으로 적었던 것은 오조회였고, 실제로는 존재한다. 이 스탯이 기존 fotmob 프로필(패스 정확도 87.1% 상위15%·롱볼정확도62.5% 상위8% vs 경합승률26.7% 하위2%)과 방향이 일치한다 — pas65는 중간이지만 def68·phy67의 낮은 값이 몸싸움 약세를 뒷받침.','LOW(유지) — 여전히 fit_sim 미산출. FC26 스탯 확인으로 게임 구현 결손 하나는 닫혔으나(⑷번 캐비앗 해소), 나머지 캐비앗(⑴표본 280분·⑵타리그·⑶이탈 사유 미기록·⑸적합 미산출)은 그대로 유효하다.','⚠️ 판단 보류 — (교차 투영 — 실측 아님) 알론소 구조에서 오른쪽 윙백은 fb_att_wb/Support로 폭을 독점하는 공급자다(regime 2 implementation ⑵). 이는 ''전진 빈도 낮은 딥 풀백''이라는 그의 실측 방향과 정반대이고, 상대 박스 터치 하위 5%·슛 0회·xA 하위 6%도 폭 공급자 요구에 미달한다. 다만 크로스 정확도 상위 14%는 접점이 있다. 표본 미달이라 등급을 매기지 않는다.','⚠️ 판단 보류 — (교차 투영 — 실측 아님) 이라올라 체제는 인버티드 풀백(프림퐁 성향)과 고강도 압박·터치라인을 이용한 측면 압축을 축으로 한다(regime 3 traits·pressing). 태클 하위 3%·인터셉트 하위 3%·경합 승률 하위 2%는 이 요구와 정면으로 어긋난다. 표본 미달이라 등급을 매기지 않는다.','squad_entries(regime 1, FB/OWNED, rate_v NULL, rate_basis ''none'', rate_note ''⚠️ RB 그리드 3경기뿐(표본 미달) — 그리드·적합 미산출'', fit_role/fit_focus/fit_sim 전부 NULL) · prescriptions ''measured'' 2026-27(RB x=81.7 y=46.6, 라이프치히 임대 오른쪽 선발 4경기 균등가중 통합, fit_sim 없음) · players.notes(분데스 5경기 3선발 252분 평점 6.3 + DFB포칼 1경기, 12월 집중 출전 후 이탈) · v_player_profile(n=22, 375분, 평점 6.47) · 3팀 풀 59명 백분위(평점 10%) · fotmob_detail_stats 2025/2026 Bundesliga 31지표(280분 기준) · v_player_season_stats(분데스 15경기 3선발 252분 6.30 / DFB포칼 2경기 45분 7.0 / 26-27 친선 12분) · player_matches lineup_pos(RB 분데스 3경기 241분 6.17 · D 라벨 10경기) · player_game_stats FC26 행 없음(결손) · manager_profiles regime 1·2·3 · observations #152 | stat_eval 2026-09-11 갱신: FC27 09-10 수집 목록에 없음 재확인 · FC26(roster 2026-07-23) 신규 확인: OVR72·pac81·sho44·pas65·dri69·def68·phy67(PlayStyle 없음) — 기존 결손 서술 정정 · v_player_profile n=27(486분, 평균6.47) · v_player_season_stats(26/27 친선 위주 4경기 78분 평점6.6)','여전히 LOW — fit_sim 미산출·표본 미달은 불변. 이번 갱신에서 새로 확인된 것은 FC26 게임 스탯 존재(이전 결손 서술 정정)와 v_player_profile 표본 소폭 확대(22→27경기)뿐, 실질 판단을 바꿀 새 실측은 없다. 알론소·이라올라 핏은 비워둔다(추가 근거 없음).','2026-09-11','분데스리가 풀백 중 253분 남짓만 뛴 표본이어서 어떤 결론도 잠정적이며, 31개 지표만 수집됐다. 90분당 백분위 기준의 강점은 공을 안전하게 처리한다는 점이다 — 롱볼 정확도 62.5%가 백분위 92, 패스 정확도 87.1%가 85, 크로스 정확도 33.3%가 86이고 90분당 파울 0.36회(89)로 반칙도 거의 없다. 문제는 경합 전반이다 — 경합 승률 26.7%가 백분위 2, 90분당 경합 승이 2, 태클이 3, 인터셉트가 6, 수비적 행동이 18로 수비 개입의 양과 질 모두 최하위다. 제쳐당함(14)과 볼 뺏김(12)도 하위권이고 슛 0회·어시스트 0개로 공격 산출은 없다. 90분당 출전 중 피xG(86)가 좋아 보이는 것은 표본이 3경기 수준이라는 점을 감안해 읽어야 한다. 현재 숫자로는 경기 막판 수비 인원 보강 정도의 용도만 지지된다.');
INSERT INTO player_evaluations VALUES(55,1,28,'C+ — 오른쪽 와이드 x=85에서 wm_winger/Balanced 적합 0.780(9경기·672분·평점 6.42)로 커널값 자체는 게상(0.782)·베일리(0.768)와 EA 노이즈 구간 안 동률. 25/26 본체 표본이 챔피언십(2부)이라 프리미어리그 수준 검증이 없다. ⚠️ FC27 09-10 roster_date 수집에서 이 선수도 누락 확인됨 — 조회 가능한 최신은 FC27(2026-08-31) OVR72로 FC26(2026-07-23) OVR72와 동일(변동 없음).','등록상 왼쪽 미드필더지만 실측 주력은 오른쪽(웨스트브롬 임대 우측 선발 12경기, 중심 x=75.9). ''공격보다 수비 쪽 값이 더 좋은 측면 자원'' 프로필은 유지. ⚠️ FC27 09-10 수집에서 누락되어 최신 능력치 변화는 확인 불가 — 08-31 스냅샷(OVR72·pac80·def56·phy59)은 FC26(07-23, pac81·def56·phy62) 대비 pac−1·phy−3로 소폭 하락이나, PlayStyles·신장·체중 필드는 두 스냅샷 모두 공란이라 여전히 결손이다.','강점: 챔피언십 동포지션 기준 걷어내기 27회(90분 상위 9%)·슛 블록 4회(상위 13%)·인터셉트 10회(상위 27%)·드리블 성공률 48.4%(상위 24%) — 수비·경합 기여가 강점. 약점: 어시스트 0개(하위 0%), 득점 1골(하위 25%), 크로스 정확도 18.8%(하위 44%) — 결과가 없다. ⚠️ FC27 게임 능력치는 여전히 결손에 가깝다 — 09-10 수집 누락, 08-31 스냅샷도 OVR72로 FC26과 동일하며 PlayStyles·신장·체중 필드는 두 시점 모두 비어 있다. 게임 능력치·특성·역할 친숙도 판단은 여전히 데이터 없음으로 남긴다.','fotmob_detail_stats 2025/2026 챔피언십 41지표(1449분) 기준은 유지 — 걷어내기 1.88/90(상위 9%)·슛 블록(상위 13%)·인터셉트(상위 27%), 어시스트 0(하위 0%)·득점 1골(하위 25%). 이 백분위는 챔피언십 기준이라 다른 5명과 직접 비교 불가(불변). ⚠️ 신규: FC27(roster_date=2026-09-10) 수집에서 player_id=28 누락 확인 — 조회 가능한 최신은 FC27(2026-08-31) OVR72·PAC80·SHO64·PAS68·DRI75·DEF56·PHY59이며, FC26(2026-07-23) OVR72·PAC81·SHO64·PAS68·DRI75·DEF56·PHY62 대비 PAC−1·PHY−3, OVR은 불변이다. PlayStyles·신장·체중 필드는 FC27 08-31·FC26 07-23 두 스냅샷 모두 공란 — 이 결손은 8월 평가 당시와 동일하게 남아 있다.','MEDIUM — 오른쪽 와이드 x=85에서 wm_winger/Balanced 0.780 실측, 챔피언십 실측 프로필(걷어내기 상위 9%·슛 블록 상위 13%·인터셉트 상위 27%, 어시스트 0)이 에메리의 wm_widemid/Support 요구(수비 지원, 공격 산출 비어 있음)와 방향이 맞는다. FC27 능력치는 사실상 변동 없음(OVR72 동일)이라 이 판정에 영향 없음 — 여전히 프리미어리그 수준 검증 부재가 최대 한계.','LOW-MEDIUM — (교차 투영 — 실측 아님) 알론소 구조는 윙백이 폭을 독점하고 안쪽은 하프스페이스 10번 2명이라(regime 2 implementation ⑵⑷) 순수 측면 와이드 미드필더의 칸이 없다. 그의 수비 기여 강점(걷어내기·블록)은 윙백 자리로 옮기면 쓰일 여지가 있고 실제로 챔피언십에서 왼쪽 풀백 1경기 기록이 있으나 표본이 1경기다. 하프스페이스 10번 요구인 창출·마무리는 어시스트 0개·유효슛 하위 25%로 정면 미달이다. 이 체제의 기술 규율 요구가 극단적으로 높다는 점(regime 2 rest_defense)도 2부 리그 검증만 있는 자원에게 불리하다.','MEDIUM — (교차 투영 — 실측 아님) 이라올라 체제는 터치라인을 추가 수비수처럼 쓰는 측면 압축과 존→맨투맨 전환을 요구하고(regime 3 pressing) 측면 자원의 수비 부담이 크다. 그의 걷어내기 상위 9%·인터셉트 상위 27%·공중 경합 승 상위 29%는 이 부담을 감당한다는 신호다. 그러나 압박의 목적인 파이널서드 탈취 후 즉시 슛에서 두 축이 모두 약하다 — 상대 진영 볼 탈취 0.349/90이 90분 기준 하위 21%, 태클 하위 15%로 앞에서 뺏지 못하고, 어시스트 0개·유효슛 하위 25%로 마무리도 없다. 활동량형 측면 자원으로서의 하한선은 맞지만 산출 상한이 보이지 않는다.','squad_entries(regime 1, WM/OWNED, rate 6.42, wm_winger/Balanced 0.780) · prescriptions 3행 — ''measured'' 2026-27(RM/AMR x=75.9 y=55.1, 웨스트브롬 오른쪽 선발 12경기 통합), ''measured:L'' 2026-27(LW/AML x=23.8 y=56.6, 좌측 선발 4경기), ''measured:season:full2526''(RM x=85, fit 0.780, n=9, 672분, 평점 6.42, lineup_pos=''RAM'') · players.notes(26/27 LM 복귀 #19, 이중 임대 경위) · v_player_profile(n=42, 1449분, 평점 6.53) · 3팀 풀 59명 백분위(평점 14%) · fotmob_detail_stats 2025/2026 Championship 41지표 · v_player_season_stats(챔피언십 26경기 14선발 1290분 6.53 / Serie A 12경기 1선발 107분 6.47) · player_matches lineup_pos(RAM 챔피언십 9경기 672분 6.42 · RM 2경기 7.45 · LM 2경기 5.65 · LB 1경기) · player_game_stats FC26 행 없음(결손) · manager_profiles regime 1·2·3 · observations #152·#134·#122 | stat_eval 2026-09-11 갱신: player_game_stats FC27 roster_date=2026-09-10 수집에서 player_id=28 누락 확인 — 최신 조회 가능값은 FC27(2026-08-31, OVR72·PAC80·SHO64·PAS68·DRI75·DEF56·PHY59, PlayStyles/height/weight 공란) vs FC26(2026-07-23, OVR72·PAC81·PHY62) — PAC−1·PHY−3, OVR 불변','LOW-MEDIUM — ⚠️ 리그 수준 캐비앗이 이 평가의 최대 한계다: 25/26 본체 표본이 챔피언십(2부)이고 fotmob 백분위도 챔피언십 동포지션 기준이므로 프리미어리그 수준 보정이 전혀 없다. 세리에 A 12경기는 107분 교체가 전부다. obs#122도 그의 15경기가 임대 표본임을 캐비앗으로 명시한다. ⚠️ 기타: ⑴ 슬롯 적합 표본 9경기 672분으로 얇다. ⑵ 적합값 0.780이 게상 0.782·베일리 0.768과 Δ0.02 이내 — EA 노이즈 구간이라 세 명의 우열 판단 근거로 쓸 수 없다. ⑶ 등록 포지션(LM)과 실측 주력(오른쪽)이 다르고 좌측 표본은 4경기뿐이라 좌우 양용 여부는 미검증이다. ⑷ player_game_stats에 FC26 행이 없어 게임 능력치·역할 친숙도가 결손이다. ⑸ 우리 풀 백분위(하위권)와 챔피언십 리그 백분위(여러 항목 상위 10~30%)의 어긋남은 리그 수준 격차의 산물이다 — 본문에 명기했다. ⑹ 알론소·이라올라 적합은 교차 투영 — 실측 아님. ⚠️ 2026-09-11 갱신: FC27 09-10 수집에서 이 선수도 빠져 있다(15번 산초와 같은 결손 유형) — 08-31 스냅샷 기준으로도 OVR 변동 없고 PlayStyles 등은 여전히 결손이라 게임 능력치 축은 실질적으로 갱신되지 않았다.','2026-09-11','챔피언십 측면 미드필더 중 수비 가담과 세컨드볼 처리가 강점이고 최종 산출은 약한 프로필이다 — 다만 비교 모집단이 프리미어리그가 아니라는 점을 함께 읽어야 한다. 걷어내기 27회(백분위 87)·슛 블록 4회(87)·인터셉트 10회(76)·공중 경합 승 17회(73)로 자기 진영 기여가 상위권이고 헤더 슛(82)도 많다. 공격에서는 성공한 크로스 12회(71)와 드리블 성공률 48.4%(76)가 준상위다. 약점은 결과다 — 득점 1골이 백분위 25, 어시스트 0개, xG(55)와 xA(53), 기회 창출(53)이 모두 평범해 챔피언십 기준에서도 생산이 두드러지지 않는다. 롱볼 정확도 36.4%(27), 패스 정확도 75.8%(43), 90분당 태클(15)도 낮다. 수비 부담을 함께 지는 측면 요원으로는 쓸 수 있으나, 상위 리그에서 창조나 마무리를 맡길 근거는 이 숫자에 없다.');
INSERT INTO player_evaluations VALUES(56,1,61,'C 유지 — 판단 보류 그대로. squad_entries.fit_sim은 여전히 NULL이고 prescriptions 행도 0건이다. 9월 신규: 에메리 08-31 기자회견에서 ''브라이언 마조가 있지만 부상 중''이라 확인돼 현재 결장 중이나, 1874 기자(Tanswell) 증언은 ''전원 건강하면 마조가 (아브라함보다) 서열 위''라고 지목해 부상 회복 시 3순위 스트라이커 중 최상단일 가능성을 시사한다. 실전 표본은 여전히 25/26 리그 앙 174분+U17 예선(커버리지 밖)뿐이다.','최전방 공격수. 25/26 리그 앙에서는 전부 교체로 짧게 뛰었고 lineup_pos는 전건 F다. 조회 가능한 실측만으로 성향을 규정하기 어렵다 — 174분 표본에서 확인되는 것은 공중볼 승률이 나쁘지 않고(3회 시도 중 60%) 그 외 관여 지표가 전반적으로 리그 최하위라는 정도다. FC27에서 첫 게임 스탯 행이 생겼다(FC26엔 행 없음) — OVR65·PAC70·SHO65·PAS50·DRI58·DEF22·PHY74, PlayStyles·신장·체중은 미기재. PAS50·DEF22가 낮아 게임 능력치도 ''연계·수비 관여 약함''이라는 실측 방향과 같은 쪽이다.','강점(전부 극소 표본): 90분 기준으로 보면 유효슛의 질이 나쁘지 않다 — xGOT 0.93(0.533/90)이 90분 기준 상위 23%로, 적은 슛에서 골문 구석으로 가는 슛이 있었다는 뜻이다. 공중 경합 승률 60%(상위 11%)와 걷어내기 90분 기준 상위 18%, 얻어낸 파울 1.72/90 상위 26%도 90분 환산에서는 중상위다. U17 유럽선수권 예선 3경기 2골. 약점: 볼을 다루는 값이 리그 바닥이다 — 패스 정확도 55.6%로 리그 앙 동포지션 하위 2%, 성공 패스 10회(5.7/90)로 하위 2~3%, 터치 41회(23.5/90)로 하위 5%다. 마무리 시도 자체가 거의 없다: 슛 3회(하위 5%), 유효슛 1회(하위 3%), xG 0.35(하위 8%). 게임 스탯상 SHO65·PHY74는 박스 피니셔·몸싸움 잠재력 방향과 정합하나 17세 포텐셜 카드 특성상 해석에 유의.','fotmob_detail_stats 2025/2026 리그 앙 28지표 기준. 표본이 174분(약 1.9경기 분량)이므로 이 백분위 표 전체가 방향 참고용이며 판정 근거가 될 수 없다. 총량 백분위는 거의 전 항목이 하위 10% 안쪽인데 이는 실력이 아니라 출전 시간 162분의 직접적 결과다. 90분 기준으로 환산하면 일부가 올라온다: xGOT 0.533/90 상위 23%, 걷어내기 1.146/90 상위 18%, 얻어낸 파울 1.72/90 상위 26%, 공중 경합 승률 60% 상위 11%. 그러나 패스 정확도 55.6%는 총량·90분 양쪽 모두 하위 2%로 표본이 얇아도 바뀌지 않는 방향이다. FC27 신규(PAC70·SHO65·PAS50·DRI58·DEF22·PHY74)는 표본 부족을 보완하는 근거가 아니라 게임사 스카우팅 추정치이므로 실측 판정에 반영하지 않는다 — 참고용으로만 병기.','판단 보류 — 표본 미달. squad_entries.fit_sim NULL, prescriptions 행 0건이라 에메리 적합을 등급으로 매기지 않는다. 부상 중이라 서열 재검증은 복귀 후 가능(에메리 08-31: ''브라이언 마조가 있지만 부상 중'').','⚠️ 판단 보류 — (교차 투영 — 실측 아님) 알론소 구조의 9번은 내려와서 받는 st_false9/Build-Up이다(regime 2 implementation ⑸). 이는 연계 능력을 최우선으로 요구하는 역할인데 패스 정확도 55.6%(하위 2%)·터치 23.5/90(하위 5%)와 정면으로 어긋난다. 표본 미달이라 등급을 매기지 않는다.','⚠️ 판단 보류 — (교차 투영 — 실측 아님) 이라올라 체제는 파이널서드 탈취 후 즉시 슛이라는 수직 구조이고(regime 3 pressing·situational, 시퀀스당 2.98패스) 최전방의 압박 시발과 침투 반복을 요구한다. 패스가 적게 요구되는 구조라는 점에서는 오히려 접점이 있으나, 수비 행동 2회(하위 5%)로 압박 시발의 근거가 없고 슛 3회(하위 5%)로 마무리 시도도 없다. 표본 미달이라 등급을 매기지 않는다.','squad_entries(regime 1, ST/OWNED, rate_v NULL, rate_basis none, rate_note F 그리드 3경기 199분(표본 미달) — 그리드·적합 미산출. U17 대회는 SofaScore 커버리지 밖(obs#133), fit_role/fit_focus/fit_sim 전부 NULL) · prescriptions 행 0건 · v_player_profile(n=13, 438분, 평점 6.56) · 3팀 풀 59명 백분위(평점 15%) · fotmob_detail_stats 2025/2026 Ligue 1 28지표(174분 기준) · v_player_season_stats(리그 앙 9경기 162분 6.58 / U17 유럽선수권 예선 3경기 216분 2골 / 26-27 친선 1경기 선발 60분 6.5) · player_matches lineup_pos 전건 F · player_game_stats FC26 행 없음(결손) · manager_profiles regime 1·2·3 · observations #152·#133 | stat_eval 2026-09-11 갱신: player_game_stats FC27 최초 행 확보(FC26 행 없음, roster_date 2026-09-10, OVR65·PAC70·SHO65·PAS50·DRI58·DEF22·PHY74, PlayStyles/신장/체중 미기재) · player_duties 09-02 에메리 기자회견(부상 중) · 1874 Tanswell 서열 발언','판단 보류 — 표본 미달. 적합값이 산출되어 있지 않고 prescriptions 행이 0건이므로 에메리 적합을 등급으로 매기지 않는다. 다수의 캐비앗(표본 174분·U17 커버리지 밖·리그1 수준·FC26 게임스탯 결손·풀 xG 백분위 역전)은 08-11 판정과 동일하게 유효하다. 부상으로 실전 검증이 더 늦춰졌다 — 등급은 여전히 실력 판정이 아니라 자료 결손 표시다.','2026-09-11','리그앙 공격수 중 출전이 157분(28개 지표만 수집)에 불과해, 어떤 결론도 참고 수준으로만 읽어야 한다. 90분당 백분위로 보면 강점이라 할 만한 것은 공중 경합 승률 60.0%(백분위 89)와 90분당 걷어내기(82), 얻어낸 파울(74) 정도로, 몸싸움에서 밀리지는 않았다는 신호에 그친다. 반대로 공을 다루는 지표는 전부 최하위다 — 패스 정확도 55.6%가 백분위 2, 90분당 성공한 패스가 2, 터치가 5, xA가 2이고 득점 0골에 90분당 xG 0.20은 15다. 슛 3회(90분당 18)로 마무리 시도 자체가 거의 없었다. 두 경기 분량의 표본에서 나온 숫자이므로, 현재 데이터로는 어떤 역할에 적합한지 판단할 근거가 없다고 보는 것이 정직하다.');
INSERT INTO player_evaluations VALUES(57,1,30,'B → 유지, 근거 확장. PSG 슈퍼컵 90분 단발에서 이제 PL 3경기(브라이턴 90분·아스날 71분·헐 75분)+UCL 브뤼헤 90분까지 성인 공식전 4경기 표본으로 확장됐다. squad_entries 최신 집계(2026-09-06, LM 포지션-순수 3경기 236분, 평균 6.37, wm_widemid/Support fit .566)가 슈퍼컵 단일값(.788)을 보완하는 방향의 신규 정본이며, 헐전 MOTM급(Read Aston Villa 8/10, 팀 유일 유효슛·유일 빅찬스 창출)과 브뤼헤전 CL 데뷔 90분 완주(wm_wideplm/Attack .798로 개선)로 상승세다. FC27 OVR65 유지, PAC 68(FC26 70 대비 -2), SHO51·PAS64·DRI67·DEF61·PHY63은 FC26과 동일.','왼쪽 안쪽 지원형 미드필더 — 명목 LAM보다 낮고 중앙에 서며 압박·회수·짧은 연결로 외곽 풀백을 보조한다는 슈퍼컵 판정과 달리, PL 실측은 오히려 ''좌측 터치라인 고정형 와이드 아웃렛''을 반복 확인한다(브라이턴 avg_y 74.2, 아스날 avg_y 78.3). 원 포지션은 센트럴 미드필더(에메리 본인이 ''엄청난 잠재력을 가진 센트럴 미드필더''로 규정)이며 좌측 배치는 사전 준비된 전술 배치일 뿐이다. 헐전엔 반대로 ''안으로 파고드는'' 기용(Read Aston Villa)으로 유효슛·빅찬스를 만들어 wm_wideplm/wm_winger 대안 검토가 열려 있다.','장점: 90분 가용성 — PSG·브라이턴·브뤼헤 3경기 풀타임 완주. 헐전 팀 유일 유효슛(200분 넘게 이어진 유효슛 가뭄을 끝냄)+팀 유일 빅찬스 창출(평점 6.85, Read Aston Villa 8/10 MOTM). 브뤼헤전 팀 최다 상대 박스 터치(7)와 종료 국면 전술적 파울(UTV: ''tactical maturity'', 실측 파울 6건 팀 최다급). 약점: 마무리 전환력 — 브뤼헤전 빅찬스 미스 2·득점 0, 헐전도 무득점. 평점은 소스 간 큰 편차(브뤼헤전 UTV 8.5 vs astonvillanews 4)로 근거로 쓰지 않는다.','fotmob_detail_stats 행 없음(결손) — SofaScore 이벤트 기반 실측만 존재한다. 수집 누적 11경기 592분 평균 6.67(v_player_profile n=12 수준). PSG전 단일 실측: 90분 6.2, 20/25패스, 1키패스, 2슈팅(1유효), 3/9경합, 1태클, 6회수, 경기 그리드 wm_widemid/Support .788. 09-06 갱신으로 LM 포지션-순수 3경기(236분) 집계가 새로 얹혔다 — 평균 6.37, 툴 중심 (24.38, 52.0), wm_widemid/Support .566(단일경기 .788 대비 하락, 표본 확대에 따른 자연스러운 수렴). FC27(PAC68·나머지 FC26과 동일)은 리그앙 계열 유스 카드 특성상 실측 보정 근거로는 약하다.','MEDIUM-HIGH — 이벤트 원천값과 에메리의 의도된 포지션 발언은 강하지만 공식 성인 표본이 4경기(PL3+CL1)로 여전히 얇고, PL 3경기 중 2경기는 팀이 크게 열세(0-4, 0-1)였다. 브뤼헤전 승리 국면에서 wm_wideplm/Attack .798로 개선된 점은 긍정적 신호다. 에메리가 그를 ''잭슨의 배후 러너''로 명시 지정(2026-09-08 회견: ''George is running, he is running in behind, George is helping so so much to run in behind with Jackson'')하면서도 만잠비·가르나초·음바예 합류 시 이전 가능한 자리라고 밝혀, 확정 역할이 아니라 현재 스쿼드 상태의 임시 배치일 가능성도 열어뒀다.','LOW — 알론소 체제 교차 투영 근거 없음.','LOW — 이라올라 체제 교차 투영 근거 없음.','SofaScore event 16260286; reports/match-watch/2026-08-12-avl-psg-super-cup.md; https://as.com/futbol/internacional/unai-emery-habra-mas-cambios-f202608-n/; https://www.youtube.com/watch?v=cV0xoK0gK3w | stat_eval 2026-09-11 갱신: squad_entries LM measured(3경기, .566, 6.37, 2026-09-06 R4) · player_game_stats FC27(roster_date 2026-09-10, OVR65·PAC68·SHO51·PAS64·DRI67·DEF61·PHY63, PlayStyles/신장/체중 미기재) vs FC26(PAC70, 나머지 동일) · player_duties 브라이턴(08-23)·아스날(08-31)·헐(09-05)·브뤼헤(09-08) 4경기 서사 및 에메리 09-08 회견','HIGH 경기 원천 / MEDIUM-HIGH 역할(기능 축) — 성인 공식전 표본이 1경기에서 4경기로 늘었고 좌측 터치라인 고정 와이드 아웃렛 기능이 PL 2경기 연속 좌표로 일치, 전술 매체 다수가 독립적으로 같은 기능을 지정 임무로 기술했다. fotmob_detail_stats 결손으로 리그 동포지션 백분위 비교는 여전히 불가능하다. PL 표본 2경기가 모두 팀 대패 상황이라 유공 국면 검증은 얇다.','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(58,2,80,'B — 라요의 대량 시즌 표본과 공격형 LB 적합은 확인됐지만 첼시 공식전이 없어 현재 평가는 이전 팀 수행과 알론소 전술 투영을 분리해야 한다. [2026-09-11 갱신] 08-24 풀럼전(알론소 첫 공식전) LM 25분(Hato 교체 투입) 평점 5.98 — 첫 첼시 공식전 실측이나 표본이 짧아(''리드 보호 좌측 윙백'') 역할 판정에는 부족하다. 여전히 라요 시즌 표본(55경기)이 정량 근거의 대부분을 차지한다.','높고 넓게 전진하는 공격형 레프트백. 좌측 폭과 지원을 제공하되 새 팀에서는 하토와의 역할 분담이 미정이다. FC27(2026-09-10) PlayStyles 4종 확정: Whipped Pass·Block·Quick Step·Relentless — Block 추가는 수비 가담 성향과 정합.','강점은 55경기 가용성과 전진 위치 반복. 위험은 라요에서의 역할을 첼시에 그대로 복사할 수 없다는 점이다. FC27 OVR79(FC26 78 대비 +1), PAS74(+2)·DRI75(+1)·PHY77(+1) 전반 소폭 상승, PAC86 유지로 스피드는 스쿼드 상위권 유지.','2025/26 전 대회 55경기 3,519분 평균 6.80, 1골 3도움. 경기당 xG .047, xA .089, 태클 1.33, 인터셉트 .76. 45분+ LB 39경기 fb_att_wb/Support .890. | 2026-09-11 갱신: v_player_profile n=61(3786분)·avg_rating 6.76 — 라요 시즌 표본이 여전히 주축. v_player_season_stats 2026-27 EFL Cup 2경기 180분 평균 7.0(첫 첼시 출전, 완주), Premier League 3경기 73분 평균 6.33(단편 출전). fotmob_detail_stats LaLiga 2025/2026(라요, 이적 전)에서 클린시트 92백분위·슛 블록 93백분위·정확한 롱볼 89백분위로 수비 기여형 풀백 프로필이 확인되나 이는 첼시 실측이 아니다(불변규칙 7 명기). squad_entries FB(full2526, 라요) fit_sim fb_att_wb/Support .89 — 첼시 실측 아직 없음. player_duties 2026-08-24 풀럼전 LM 25분 평점 5.98 — 첫 첼시 공식전 기록이나 표본 부족으로 서술은 ''sample_scope: single-match observation''.','LOW — 에메리 체제 대상 아님.','MEDIUM — 2026-09-11 갱신: 첫 첼시 공식전 실측(08-24 풀럼전 LM 25분, 평점 5.98)이 처음 확보됐으나 25분 교체 출전으로 역할 판정에는 부족하다. 라요 시절 fb_att_wb/Support .89(full2526)는 팀축이 다른 참고치(불변규칙 7)로 유지. EFL Cup 2경기 180분 평균 7.0은 완주 표본이라 다음 갱신에서 핵심 근거가 될 잠재력이 있다.','LOW — 이라올라 체제 대상 아님.','SofaScore player 1010421; https://www.chelseafc.com/en/news/article/pep-chavarria-signs-for-chelsea; reports/transfer-watch/2026-08-13.md | 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR79·PAS74·PlayStyle Block 추가) vs FC26(07-23, OVR78); v_player_profile(n=61); v_player_season_stats(2026-27 EFL Cup/PL); player_duties(2026-08-24 풀럼전 LM 25분)','HIGH 라요 실측 / LOW 첼시 실행 | 2026-09-11: 첼시 공식전 표본이 0→1경기(25분)로 늘었으나 여전히 판정 불가 수준. EFL Cup 2경기(180분 완주, 평균 7.0)가 가장 실질적인 신규 근거.','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(59,3,85,'B+ — 26/27 PL 4경기 출전(20분·13분·서브 → 09-04 입스위치전 90분 선발), 리버풀 공식전 0경기였던 08-13 평가 시점과 달리 이제 공식전 표본이 생겼다. 다만 기용 포지션이 CB가 아니라 ''접히는 RB''로 확정되며(player_duties, 2026-09-04), 애초 squad_entries의 cb_bpd 커널 투영과 실제 기용 사이에 괴리가 발생했다.','전진 스텝아웃·공격적 경합·배급형 수비수. FC27(2026-09-10) 신규: OVR 80(FC26 81에서 -1), PAC/SHO/PAS/DRI 불변(79/54/64/59), DEF 79→78(-1), 신장 188cm·체중 79kg 신규 기재, PlayStyles 4종 확정: Jockey·Slide Tackle·Bruiser·Aerial Fortress. 09-04 입스위치전 실측 포지션은 RB이고 match_player_reports가 이 경기의 커널 적합을 fb_wingback/Balanced 0.8153로 산출 — cb_bpd 계열이 아닌 풀백 커널이 처음으로 실측에 등장했다.','player_duties(2026-09-04) 상세 서술: ''명목 RB이나 감독 지시는 안으로 접혀 백3를 만드는 것 — 크로스·세컨드볼·세트피스 대응이 선발 사유이고 오버랩·최종 3분의 1 창조는 과업이 아니다. 우측 폭은 무뇨스(88)가 홀로 쥐고, 아라우호가 접힌 뒤 비는 공간은 윙어·소보슬러이 복귀 주행으로 메운다.'' 즉 강점은 인버티드 풀백형 수비 안정화이지 측면 전진 크로스가 아니다. 09-04 90분 7.4로 이 역할에서 합격점. 약점은 표본 부족 — 26/27 4경기 중 완주는 1경기뿐(20분·13분 조각 출전 2회, 90분 1회, 09-04 이전 서브 위주)이라 역할 안정성 검증에는 이르다.','2026-09-11 갱신: player_matches 26/27 시즌 4경기 확인 — 08-16 코모 친선 45분(RCB, 7.0), 08-23 뉴캐슬 20분(교체 CB, 6.48), 08-29 노팅엄 13분(교체 CB, 7.0), 09-04 입스위치 90분(선발 RB, 7.4). v_player_profile 통산(바르셀로나+리버풀 합산) n=62·평균 6.9. fotmob_detail_stats는 여전히 25/26 LaLiga(바르셀로나 시절) 42지표만 존재, 리버풀 소속 리그 데이터는 아직 fotmob 상세지표로 축적되지 않았다(표본 부족, player_matches 원자료로만 확인 가능). squad_entries(08-19 갱신)의 cb_bpd/Build-Up 0.839는 여전히 CB 슬롯 기준값이나, 09-04 실전 기용은 RB로 이동해 prescriptions에 아직 반영되지 않은 최신 실측(fit 0.8153, fb_wingback/Balanced)이 더 최신 근거다.','LOW — 에메리 체제 대상 아님.','LOW — 알론소 체제 대상 아님.','MEDIUM-HIGH — (실측 부분 확인, 역할 재해석 필요) 애초 ''RCB 공간 적합''으로 투영했던 것과 달리, 실제 이라올라 기용은 RB 자리에서의 인버티드 수비형이다(player_duties 2026-09-04). 이 자체가 이라올라 백3/백4 혼합 빌드업 구조와 정합하는 실측 근거이나, 슬롯 명칭(CB→RB)이 바뀌었으므로 squad_entries의 CB 슬롯 값을 그대로 fit_iraola 근거로 쓰는 것은 부정확 — 다음 단계는 squad_entries에 RB 슬롯 행 추가 여부 검토가 필요하다(메인 세션 판단 사항으로 남김).','SofaScore player 925097; https://www.liverpoolfc.com/news/liverpool-agree-deal-sign-ronald-araujo-loan; reports/transfer-watch/2026-08-12.md | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-09-10 — ovr80·def78·height188·weight79·playstyles 4종, FC26 대비 ovr81→80) · player_matches(26/27 4경기: 코모45분7.0, 뉴캐슬20분6.48, 노팅엄13분7.0, 입스위치90분7.4) · match_player_reports(4건) · player_duties(player_id=85, 2026-09-04 ''RB이나 접혀 백3'' 상세 서술) · squad_entries(08-19 갱신, cb_bpd/Build-Up 0.839, 프리시즌 1경기 근거) · v_player_profile(통산 n=62 평균6.9)','MEDIUM — 리버풀 공식전 표본이 08-13 평가 당시 0경기에서 4경기(완주 1경기)로 늘었으나 여전히 소표본. 포지션이 CB에서 RB로 실측상 이동해 기존 squad_entries 커널값과 최신 실측 간 정합성 재검토가 필요한 상태.','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(60,3,88,'B+ — 26/27 PL 3경기(뉴캐슬 27분 교체, 노팅엄 90분 선발, 입스위치 64분 선발) 확보. 08-25 재판정으로 주 사이드가 LM에서 RM으로 뒤집혔고(squad_entries obs#328·329), 09-04 입스위치전은 duties·prescriptions 모두 ''RM 선발''로 일치해 좌우 혼선이 실전으로 정리되는 중이다. 다만 08-31 노팅엄전은 ''LM → 71분 우측''으로 경기 중 사이드 전환이 있었다는 점이 여전히 위치 데이터 해석의 변수다.','폭발적 속도·직접 드리블·양측면 소화·복귀 수비를 겸한 와이드 공격수. FC27(2026-09-10) 신규: OVR 79(FC26 78에서 +1), PAC 93→94(+1)·SHO 72→74(+2)·DRI 79→80(+1)·DEF 47→50(+3)로 전 지표 소폭 상승, 신장 173cm·체중 60kg 확정, PlayStyles 4종: Whipped Pass·Rapid·Quick Step·Relentless — 스피드·크로스 특화 구성으로 실측(폭발 드리블·역습 전환)과 정합.','08-31 노팅엄전 90분 7.4·동점골(82분)·xG 0.32·슛4(팀 최다)·드리블 6회 시도로 이라올라 체제 첫 결정적 기여(match_player_reports). wm_wideplm/Attack 단일경기 fit 0.827로 이 경기의 좌측 기준 커널도 확인. 09-04 입스위치전은 RM 선발 64분 6.3으로 다소 평범했으나 fit 0.8254(wm_winger/Attack)로 우측 기준 커널도 실측 재확인됐다. 약점: 08-24 뉴캐슬전 27분 교체(6.67)에서 나타나듯 RM 선발 경쟁이 여전히 열려있고(player_duties ''RM 선발 경쟁을 즉시 개방''), 08-16 더블헤더 1차전은 스탯 자체가 미수집이라 표본 공백이 있다.','Liverpool 공식 프로필 기준 오사수나 34경기 2,766분 7골 5도움(전 소속 실측)은 유지. 2026-09-11 갱신: player_matches 26/27 리버풀 5경기 확인 — 모나코 31분(F, 6.6)·코모 57분(M, 미수집)·코모 17분(F, 6.5)·뉴캐슬 27분(F, 6.67)·노팅엄 90분(M/LAM, 7.4, 골1)·입스위치 64분(M/RAM, 6.3). v_player_season_stats 26/27 PL 3경기 평균 6.79(1골). lineup_pos가 F/M으로 기록되는 등 실측 포지션이 순수 윙어보다 공격형 미드필더(AM)에 가깝게 잡히는 경기가 늘고 있어(08-31 LAM, 09-04 RAM), squad_entries의 wm_winger 커널 라벨과 실측 lineup 사이 미세한 괴리가 관찰된다. fotmob_detail_stats는 여전히 25/26 LaLiga(오사수나) 데이터만 있고 PL 신규 표본은 아직 상세지표로 축적되지 않음.','LOW — 에메리 체제 대상 아님.','LOW — 알론소 체제 대상 아님.','MEDIUM-HIGH(실측 강화) — 09-04 입스위치전 RM 선발과 player_duties(2026-08-23 ''RM'')·prescriptions(fc26:opt:RM, starter=1) 정합으로 우측 주전 편입이 08-13 평가 시점보다 뚜렷해졌다. 08-31 결승골 기여는 이라올라의 수직 전환·와이드 침투 요구와 정합하는 실전 근거. 단 lineup_pos가 종종 M/AM으로 잡히는 점은 순수 와이드 롤이 아니라 하프스페이스 침투를 겸한다는 신호로, fit_role을 wm_winger 단일로 고정하기보다 향후 AM 계열 겸용 여부를 추적할 필요가 있다.','SofaScore player 1145642; https://www.liverpoolfc.com/news/career-path-spain-impact-and-history-maker-get-know-victor-munoz; reports/transfer-watch/2026-08-13.md | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-09-10 — ovr79·pac94·sho74·def50·height173·weight60·playstyles 4종, FC26 대비 ovr78→79) · player_matches(26/27 5경기: 모나코31분6.6, 코모57분/17분6.5, 뉴캐슬27분6.67, 노팅엄90분7.4골1, 입스위치64분6.3) · match_player_reports(6건) · squad_entries(08-24·08-25 갱신 — 주 사이드 LM→RM 재판정, obs#328·329) · prescriptions(measured:side:L fit0.771 n=22 / measured:side:R fit0.834 n=12 / fc26:opt:RM starter=1) · player_duties(player_id=88, 2026-08-23 ''RM'')','MEDIUM — 26/27 실측 5경기로 표본이 늘었으나 완주 경기는 1경기뿐이고 좌우 사이드 판정이 최근 2주 사이 두 차례 뒤집힌 이력(obs#328·329)이 있어 역할 안정성은 아직 변동 중.','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(61,3,89,'A- — 26/27 PL 4경기 전경기 선발(뉴캐슬70분7.04·노팅엄77분8.2팀최고·입스위치90분7.8), 사실상 판 다이크(44)의 상시 RCB 파트너로 자리잡았다. 렌 21경기 표본(우측 14경기 0.903)에 이어 리버풀 공식전 표본까지 확보되며 08-13 평가 대비 근거 밀도가 크게 올라갔다.','공중 지배·침착한 패스·전진 차단을 겸한 볼 플레잉 CB. FC27(2026-09-10) 신규: OVR 77(FC26 76에서 +1), PAS 59→61(+2)·DEF 75→77(+2), PAC/SHO/DRI/PHY 불변(64/38/62/77), 신장 188cm·체중 77kg 확정, PlayStyle 1종: Aerial Fortress — 공중전 특화가 실측(경합 승 다수)과 정합하나 PlayStyle 수가 판 다이크(7종)·아라우호(4종) 대비 1종뿐이라 EA 측 세부 특성 반영이 아직 얕다.','08-31 노팅엄전 77분 8.2(팀 최고 평점)·패스 94/85(90%)·롱볼6/7·지상듀얼 6전6승·공중 3/4·11분 라스트디치 블록으로 결정적 활약(match_player_reports). 09-04 입스위치 승리전도 90분 7.8로 안정. 08-16 코모 데뷔전은 45분 만에 골까지 기록(8.2). 약점: 08-31 8.2 평점이 패스 볼륨에 크게 견인된 값이고, 같은 경기에서 라인을 늦게 올려 상대(Ndoye)를 온사이드로 만든 실책이 병존한다고 리포트가 명시 — ''평점만 볼 것이 아니라'' 는 경고가 기록에 남아있다. 어깨 부상으로 21경기에 그친 렌 시절 표본 부족 우려는 이제 리버풀 4경기 연속 선발로 상당 부분 해소.','렌 2025/26 21경기(우측 14경기 평균 7.08 cb_bpd/Aggressive .903, 좌측 7경기 .850)는 유지. 2026-09-11 갱신: player_matches 26/27 리버풀 4경기 전부 RCB 선발 확인 — 코모 45분(8.2, 데뷔골), 뉴캐슬 70분(7.04), 노팅엄 77분(8.2, 팀 최고), 입스위치 90분(7.8). v_player_profile 통산(렌+리버풀 합산) n=25·평균 7.1·듀얼승 4.56/경기·태클 1.68/경기(포지션 대비 매우 높음)·인터셉트 1.0/경기. squad_entries(08-25 갱신)가 RCB 전용 그리드로 전환(n=9·745분·7.12)했고 prescriptions 09-04 단일경기 fit 0.8796으로 시즌 누적 0.932에 근접 — 커널 정합성이 경기가 쌓일수록 안정적으로 유지되고 있다.','LOW — 에메리 체제 대상 아님.','LOW — 알론소 체제 대상 아님.','HIGH(실측 확인) — 4경기 연속 RCB 선발로 이라올라 체제 주전 편입이 서술이 아니라 실측으로 확정됐다(player_duties 2026-08-23 ''전진형 우측 센터백''). 코나테 이탈(45, 레알 마드리드 확정)이 공백을 남긴 자리를 자케가 사실상 채우며, 판 다이크-자케 페어가 26/27 시즌 초반 주전 CB 조합으로 굳어지는 모양새다. 유일한 유보는 08-31 경기의 라인 관리 실책 사례 — 표본이 더 쌓여야 전진 수비 라인 통솔력을 확정할 수 있다.','SofaScore player 1445625; https://www.liverpoolfc.com/news/jeremy-jacquet-factfile-aerial-dominance-van-dijk-respect-and-lfc-homework; reports/transfer-watch/2026-08-13.md | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-09-10 — ovr77·pas61·def77·height188·weight77·playstyle 1종, FC26 대비 ovr76→77) · player_matches(26/27 4경기 전부 RCB 선발: 코모45분8.2, 뉴캐슬70분7.04, 노팅엄77분8.2, 입스위치90분7.8) · match_player_reports(4건) · squad_entries(08-25 갱신, RCB 전용 그리드 n=9 fit0.827→0.802/0.827 계열) · prescriptions(2026-27 measured n=2 fit0.8621 avg7.42, measured:side:R n=9 fit0.932) · player_duties(player_id=89, 2026-08-23 ''전진형 우측 센터백'') · v_player_profile(통산 n=25 평균7.1)','HIGH — 26/27 리버풀 4경기 전경기 선발로 표본이 8-13 평가 시점(공식전 0경기)보다 크게 강화됐고, 렌 시절 데이터와 리버풀 실측이 방향이 일치(cb_bpd/Aggressive 우세, 공중전 강점)한다.','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(62,1,132,'B+ — 23세·POT 80의 즉시 주전 GK이고 **구조 정합은 높다**(깊은 위치·박스 장악·세트피스 방어가 에메리 요구와 같은 방향). ⛔ 리스크는 하나로 좁혀진다: **슛 질 보정 후 선방 생산이 세리에A 2시즌 연속 음수**이고 마르티네스 대비 약 **4.9골** 열위다. 즉 역할·포커스의 문제가 아니라 **능력치 축의 하락**이다(OVR 74 ↔ 85). ⭐[2026-09-11 FC27 갱신] OVR 74→76(+2) — PAS 71→76(+5)로 최대 상승폭, SHO 72→75(+3)·PAC 73→76(+3)도 동반 상승. PAS 급등 시점이 2026-09-05(헐)~09-08(브뤼헤) 관측된 롱킥 배급·「11번째 필드 플레이어」 서사와 겹친다 — 빌라 첫 실전 3경기가 게임 능치에 반영된 것으로 보인다.','**깊게 서는 박스 장악형 키퍼**다 — 스위퍼가 아니다(4중 근거: 우리 그리드 tool_y 10.06 · Opta 스위퍼 행동 0.60/90 · 이탈리아 매치애널리스트협회 서술 · **EA 역할 숙련 `볼플레잉 키퍼 +`이고 `스위퍼 키퍼`가 아니다**). ⭐ **잡기보다 쳐낸다** — 펀칭 0.72/90으로 마르티네스 0.22/90의 **3.3배**이고, FC26 PlayStyle **디플렉터**(막아낸 슛 방향 통제)가 이 행동과 직접 대응한다. **긴패스** PlayStyle은 롱볼 비중 60.4%와 대응한다. 배급은 **길게 지르는 기점**이다 — 파르마의 저위치 롱볼 시스템에서 1선 압박을 넘기는 역할이고, 압박 아래에서 무리하지 않는다. ⭐ 피치 위에서는 다변이며 수비진을 통솔한다(파소토/가제타 2024-12) — 단 **라커룸에서는 말수가 줄어든다**. AcceleRATE **Controlled Lengthy** · 190cm/91kg **Stocky(185+)** · 오른발. ⭐[FC27 2026-09-10] PlayStyles Cross Claimer·Deflector 유지, PAS 76으로 급등(+5) — 롱킥 배급이 공식 능치로도 확인된다.',unistr('**특장점** ⑴ **박스 안 하이볼 장악이 엘리트**다 — 하이볼 처리 1.45/90(**p88**)이고 24/25는 64회로 **리그 1위(p93)**, 유럽 크로스 캐치 2위였다. 190cm 체격과 점프 73이 뒷받침한다. ⑵ ⭐ **세트피스 방어는 마르티네스보다 낫다** — 25/26 세트피스 PSxG−실점 **−0.54**(선방률 66.7%) ↔ 마르티네스 **−1.72**(57.7%). 마르티네스의 총합 우위는 **오픈플레이 단독 산물**(+4.04)이다. ⑶ 롱볼 정확도 37.9%는 마르티네스 36.0%보다 **높다** — 낮은 패스 정확도(61.9%)는 실력이 아니라 **믹스 선택의 결과**다. ⑷ PK 선방률 33.3%(p81) · 23세 · POT 80. \u000a⛔ **약점** ⑴ ⭐⭐ **슛스토핑이 실질 리스크다** — 선방으로 막은 실점이 24/25 **−0.99** · 25/26 **−1.36**(p24)으로 **세리에A 2시즌 연속 음수**이고 마르티네스는 **+3.52**다. ⚠️ **세이브율은 70.2% ↔ 70.9%로 같아서 보정 전 지표로는 이 격차가 보이지 않는다** — 값싼 지표만 보면 놓치는 종류의 결손이다. ⑵ **짧은 빌드업 실적이 미검증**이다 — 세리에A 패스 정확도 p26·p20이고, 빌라식 짧은 서킬레이션에서의 증거는 **23/24 벨기에 75.8%(p71)가 유일**하다. ⑶ ⚠️ **왼손 3지 개방성 골절 + 주상골 골절**(2025-11-08 밀란전, 그 상태로 10분 더 소화 후 수술) — **캐칭 직결 부위**이고 25/26 표본이 20경기로 줄어든 원인이다. ⑷ 이탈리아어는 입단 초 ''조금만''(2024-12) → 2026-01 유창으로 개선됐으나, 새 언어권에서의 통솔 재현은 미검증이다. ⭐[FC27 갱신] OVR76(+2)·PAS76(+5)·SHO75(+3)·PAC76(+3), DEF56·PHY74·DRI76 불변. 로스터 반영일(2026-09-10)이 브뤼헤전(09-08) 직후라 실전 롱 배급이 게임 능치 상승으로 이어졌을 개연성.'),unistr('**우리 실측(SofaScore 전수)** 그리드 유효 29경기 2602분 · 평점 **7.05** · `gk_goalkeeper/Defend` **fit .975**. ⛔ 이 fit을 우열로 읽지 말 것 — 측정된 GK 5명이 .961~.975(폭 0.014)에 수렴하고 상호 코사인이 ≥0.986이다(obs#220). ⭐ 변별은 평균 위치다: **tool_y 10.06**으로 5명 중 두 번째로 깊고 마르티네스(11.16)보다 **1.10 낮다**. \u000a**Fotmob/Opta 25/26 세리에A(20경기 1800분)** 상위: 하이볼 처리 **p88** · 정확한 롱볼 8.0/90 **p86** · PK 선방률 **p81** · 선방 3.3/90 **p79** · 스위퍼 행동 0.60/90 **p71**. 하위: **선방으로 막은 실점 −1.36 p24** · 패스 정확도 61.9% **p26** · 실책→실점 1회 **p19**. 평점 6.95는 리그 GK 중 **p52**(중위)다. \u000a⭐ **시즌 간 대비가 팀 함수를 드러낸다**(같은 선수가 최고의 통제군이다) — 패스 정확도 **벨기에 75.8%(p71) → 세리에A 63.2%(p20) → 61.9%(p26)**, 선방으로 막은 실점 **벨기에 +4.16(p66) → −0.99 → −1.36**. ⚠️ 배급 하락은 시스템으로 설명되지만 **슛스토핑 하락은 시스템으로 설명되지 않는다** — 피격 질이 높아진 것과 선방 생산이 낮아진 것을 분리할 근거가 없다. 이것이 이 영입의 미해소 질문이다. ⭐[2026-09-11] FC27 PAS +5 급등은 세리에A 시절 패스 정확도 하위권(p26)과 대조적 — 빌라 첫 3경기(아스날·헐·브뤼헤) 롱 배급 실측·서사 축적을 반영한 것으로 읽히나 표본은 여전히 3경기뿐이다.'),'MEDIUM-HIGH — 구조는 맞고 능력치가 깎인다. ⭐ **깊게 서는 것이 여기서는 장점이다** — 에메리 구조는 전진 스위핑을 요구하지 않으므로(obs#154) tool_y 10.06은 부적합이 아니라 **정합 신호**다. 박스 장악(하이볼 p88)과 **세트피스 방어 우위**(−0.54 ↔ 마르티네스 −1.72)도 요구와 같은 방향이다. 처방은 `gk_goalkeeper/Defend`이고 EA 역할 숙련(`볼플레잉 키퍼 +`)도 이를 허용한다. ⛔ 감점은 **오픈플레이 슛스토핑 약 4.9골 열위**와 **짧은 빌드업 미검증**이다. ⚠️ 포커스 `Build-Up` 상향은 근거가 약하다. ⭐[2026-09-11] FC27 PAS 급등(71→76)이 에메리 체제 실측된 「1선 압박 우회 롱킥」 축(2026-09-08 obs)과 정합 — 등급 MEDIUM-HIGH 유지, 상향은 표본(3경기) 부족으로 보류.','(교차 투영 — 실측 아님) MEDIUM — 3-4-2-1의 **후방 점유 빌드업**은 GK를 짧은 서킬레이션의 한 축으로 쓴다. 스즈키의 세리에A 패스 정확도 p26·롱볼 비중 60.4%는 그 요구와 **반대 방향**이고, 총 패스량도 31.4/90으로 적다. ⭐ 다만 **23/24 벨기에 75.8%(p71)** 가 ''점유형 팀에서는 다르게 한다''는 유일한 증거로 남는다 — 능력 문제가 아니라 지시 문제일 가능성.','(교차 투영 — 실측 아님) MEDIUM — 하이브리드 프레스의 **높은 라인은 배후 공간 관리를 GK에게 요구**하는데 그는 자기 박스에 머문다(AIAPC: 배후 공간은 수비수 몫으로 지시된다). ⚠️ **단 LOW로 내리지 않는다** — 평균 위치는 팀 라인 높이에 교란되고(불변규칙 7) 파르마는 잔류권 딥블록이었다. ''스위퍼를 안 한다''가 ''못 한다''의 근거는 아니다. Opta 스위퍼 행동 p71은 오히려 리그 상위다.','obs#220(GK fit 무변별) · obs#222(기능축 실측) · obs#223(서사·4시즌 Opta) · obs#224(세트피스 분리) · obs#225(통솔·다국어) · obs#229(GK 스위퍼 패턴) · obs#234(EA 역할 숙련) | db player_duties id=120 · prescriptions id=362 · transfer_targets id=149 · player_matches 39행(그리드 유효 29) · fotmob_detail_stats 87행(4시즌) · fotmob_traits 6행 · player_game_stats id=30·82 | AIAPC assoanalisti.it(쿠에스타·키부 체제 분석) · Breaking The Lines 2025-02-13 · Sky Sports(Dennis Rudel 인터뷰) · Sportiva 마르코 파소토 2024-12-12 · parmalive 사설 | stat_eval 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR76·PAS76(+5)·SHO75·PAC76) vs FC26(roster_date 2026-07-23, OVR74·PAS71)',unistr('MEDIUM-HIGH. 정량은 강하다 — 우리 실측 전수 29경기 + Opta 4시즌을 메인 세션이 직접 수집·재현했고 게임스탯은 1차 소스를 직접 파싱했다. ⚠️ **regime_id=1은 ''빌라 체제에 넣으면''의 투영이고 실측 체제가 아니다**(불변규칙 7) — 모든 그리드·지표는 **파르마(잔류권 딥블록)** 값이다. `player_duties`는 같은 이유로 regime_id=NULL을 유지했다. 빌라 합류가 CONFIRMED되면 regime_id=1 행을 새로 만들고 이 행은 이적 전 판단으로 보존한다. ⚠️ **서사는 체제가 3개로 쪼개져 있다** — 23/24 신트트라위던 / 24/25 파르마 페키아·키부 / 25/26 파르마 쿠에스타. 섞어 읽으면 결론이 무효다. ⚠️ 25/26 표본 20경기는 **손 골절 이탈(2025-11-08~2026-02-26)** 의 결과다. ⛔ 잔여 결손 ⑴ **세트피스에서의 출동 여부(행동)** — obs#224가 정량화한 것은 결과이고 배치는 2회차 수색에서도 근거 0건이다 ⑵ **수비라인 통솔·오프사이드 트랩 관여** 근거 0건(통솔은 파소토 1건, 2대 전 페키아 체제) ⑶ FBref 403 미해소 — Crosses Stopped % · 박스 밖 수비행동 평균거리 · PSxG/SoT 미확보. ⛔ **콘텐츠팜 경고**: footballkit.lazada.com.ph의 AI 생성 문서가 ''스위퍼 긍정'' 서술의 진원지다 — 재순환 시 출처를 되짚을 것. ⚠️ 딜 상태는 **HIGH(메디컬 08-17 실시 확인, 공식 발표 0건)** 기준이다.\u000a⭐ **[2026-08-18 영입확정 승격]** 이 행의 `regime_id=1`은 이제 ''투영''이 아니라 **소속 체제**다. ⚠️ **그러나 인용한 실측은 여전히 전부 파르마 값이다** — 에메리 체제 표본은 0경기이고, 체제 행 duties(id=121)는 요구역할·사전 정합 판정까지만 채웠다(첫 출전 후 갱신). ⚠️ **양 구단 공식 발표는 여전히 0건이다**(2026-08-18 메인 세션이 avfc.co.uk 뉴스·parmacalcio1913.com/news 직접 파싱해 확인 — 빌라 최신은 FPL 프리뷰·글라드바흐전·일링 볼턴 임대, 파르마 최신은 로메로 영입·온드레이카 임대). ⇒ **DB에 못 박은 CONFIRMED 트리거(`avfc.co.uk 공식 발표`)는 미충족 상태이고, 이 승격은 사용자 지시에 따른 것이다.** 근거 상한: **메디컬 실시 확인**(Romano 1티어 08-17 07:21 UTC) + **개인 조건 5년 계약 합의**(Ornstein 1티어) + **£29.9m/€30m+€5m 구단 간 합의**(Sky UK 1티어 08-16) + **Moretto(2티어) ''완료''**. ⛔ **''here we go''는 이 건에 붙지 않았다** — 일부 매체 헤드라인의 HWG는 태그 전용(轉用)이다(obs#234·transfer-watch 기록). ⚠️ obs#233(오늘 다른 세션)이 **''신호 하나로 등급을 올렸다가 24시간 만에 뒤집힌''** 마르티네스 사례를 남겼다 — 다만 스즈키는 **메디컬 이후** 단계이고 PSG 결렬은 **메디컬 직전**이었다는 점에서 국면이 다르다. ⇒ **공식 발표가 확인되면 이 캐비앗을 해제하고, 반대로 결렬되면 이 행들을 되돌려야 한다.** ⚠️ 2026-09-11: FC27 PAS 급등(+5)은 3경기 표본 위에 얹힌 조정 — 슛스토핑(세리에A 2시즌 연속 선방 생산 음수) 리스크는 게임 능치(SHO/DEF)에 반영되지 않는 별개 축임에 유의.'),'2026-09-11','리그 백분위만 보면 **박스 안에서는 상위권이고 골문 앞에서는 중위권인 키퍼**다. 박스 장악이 프로필의 뼈대다 — 하이볼 처리가 90분당 백분위 **88**(24/25는 리그 1위 **93**)이고 스위퍼 행동 **71**, 선방 수 **79**, PK 선방률 **81**로 공중볼과 박스 진입 처리에서 동포지션 상위다. 배급은 **길게 지르는 유형**이다 — 정확한 롱볼이 **86**인데 패스 정확도는 **26**이다. 두 값이 반대 방향인 것은 실력이 아니라 믹스다(롱볼 비중 60.4%). ⛔ 문제는 **선방의 질**이다 — 선방으로 막은 실점이 **24**이고 값 자체가 **−1.36**(음수)이다. ⚠️ 같은 시즌 세이브율은 **57**이라 **보정 전 지표로는 이 결손이 보이지 않는다** — 이 프로필에서 가장 중요한 한 칸이 가장 눈에 안 띄는 칸이다. 실책→실점 **19** · 패스 정확도 **26** · 선발 백분위 **14**(부상 결장)도 하위다. 평점은 **52**로 정확히 중위다. ⭐ 시즌을 바꿔 보면 **배급은 팀에 따라 달라지지만**(벨기에 패스 정확도 71 → 세리에A 20·26) **슛스토핑은 팀을 바꿔도 회복되지 않았다**(벨기에 66 → 50 → 36). ⇒ 백분위만으로 내릴 판단은 **''박스 장악과 롱 배급을 사는 것이고, 골문 앞 선방 생산은 사는 것이 아니다''** 다.');
INSERT INTO player_evaluations VALUES(63,NULL,190,'B — **깊게 서는 배급형 6번**. 31세·자유계약이고 마지막 2시즌은 콤파니 체제 로테이션(25/26 분데스리가 31경기 25선발 1,954분 평점 7.29)이다. 강점은 볼 유지·전개이고, 약점은 요격과 제공권이다. 「박스투박스 8번」은 **투헬 체제(23/24 6골 9어시)의 서사**이고 현재 표본의 값이 아니다.','깊은 위치에서 받아 배급하고, 기회가 나면 박스까지 전진해 때린다. 콤파니 아래에서 **8번 → 6번**으로 내려섰고(파블로비치에게 6번 경쟁에서 밀린 결과), 그 자리에서 수비·연결 수치가 오르고 득점 관여가 줄었다. AcceleRATE **Lengthy**(가속 72 < 질주 81) — 길게 달리면 빠르지만 첫 3~5m가 느린 유형. 규율은 안정적(퇴장 0).','⭐ 강점 — 패스량·정확도가 동포지션 최상위(성공 패스 1,479 p93 · 정확도 91.4% p94 · 터치 p91)이고 **롱볼 정확도 68.5%(p89)** 가 24/25의 55.3%에서 크게 올랐다. 6번으로 내려와도 공격 관여를 유지한다(xG 4.80 p93 · 슛 35 p87 · 박스 터치 41 p73 · xA 3.81 p83). ⛔ 약점 — **공중볼 승률 37.3%(p16)**로 24/25 53.4%(p70)에서 붕괴했고, 지상 듀얼 48.8%(p34)·**태클 1.34/90(per90 p18)** 로 앞을 막는 능력이 없다. 189cm·힘 87의 외형과 실측이 어긋난다.',NULL,'MEDIUM — 오나나 공백을 메우는 목적에는 **부분적으로만** 맞는다. 볼 유지·후방 전개는 에메리의 짧은 빌드업과 정합하고 롱볼 정확도 p89는 전환 패스의 자산이다. ⛔ 그러나 **오나나가 담당했던 축이 제공권·몸싸움**인데 고레츠카의 실측 공중볼 승률은 37.3%(p16)다 — **같은 자리를 메운다고 같은 일을 하지 않는다.** ⚠️ AcceleRATE Lengthy는 에메리의 전환 수비에서 초기 반응이 불리하다. ⇒ 팔리냐(스크리너)의 대체로 쓰면 어긋나고, **볼 순환의 축**으로 쓰면 맞는다.',NULL,NULL,'fotmob_detail_stats(player 190, Bundesliga 25/26·24/25, 2026-08-22) ; player_game_stats FC26 roster 2026-07-23 (sofifa + fut.gg 카드) ; understat_player_matches(player 335, 57경기) ; player_duties(고레츠카 CDM) ; obs#287 · obs#288 · obs#289 · obs#290 ; transfer_targets id=158','[2026-08-22] MEDIUM. ⛔ **`stat_eval`은 비워 뒀다 — 결손이지 0이 아니다**: SofaScore가 IP 차단돼(obs#290) `player_matches`·`map25`·`fit_sim`이 전부 없다. 즉 이 평가는 **FotMob 축 단독**이고 우리 실측 그리드·커널 적합의 교차검증을 받지 않았다. ⚠️ 슬롯 LDM은 커널 argmax가 아니라 구조 논거(오나나 공백·팔리냐가 LDM·RDM 2행)로 고른 잠정값이다. ⚠️ 서사 축의 결손: 유튜브 실질 미수행 · 전술 블로그 0건 · 콤파니 원기자회견 0건 · 플라망어/프랑스어 미실시. ⚠️ regime_id=NULL — 아직 우리 선수가 아니다(불변규칙 7).','2026-08-22','**FotMob/Opta 백분위만으로 내리는 판단: 「홀딩」이 아니라 「딥라잉 플레이메이커」다.** 같은 표에서 두 축이 정반대로 갈린다 — 배급(패스 p93·정확도 p94·롱볼 정확도 p89)은 최상위, 요격(태클 per90 p18·듀얼 승률 p34·공중볼 승률 p16)은 최하위권이다. 스크리닝형 6번의 프로필이 아니다. ⭐ 여기에 공격 지표(xG p93·슛 p87·박스 터치 p73)가 붙으므로 **깊게 서면서도 전진해 때리는 6번**으로 읽는다. ⚠️ **한 지표는 쓰지 말 것** — FotMob `traits`의 「공중 볼 경합 82」는 승률이 아니라 볼륨/다년 창이다(같은 수집의 승률은 37.3% p16이다, obs#289). ⛔ 이 판단은 **콤파니 단독 체제 2시즌**의 값이고, 통제군(다른 감독)이 없다.');
INSERT INTO player_evaluations VALUES(64,NULL,178,'B — **온볼은 리그와 무관하게 유지되고, 1v1은 리그가 올라가면 무너진다.** 24세·사우샘프턴 주장, 계약 2028(맨시티 바이백·셀온 보유). 같은 클럽에서 챔피언십↔PL을 연속으로 뛴 드문 통제군이 있고, 그 대비가 이 선수의 전부를 말한다.','백3 우측 **braccetto**와 백4 CB를 오간 운반형 센터백. 롱볼 배급이 실질 무기이고(챔십 25/26 롱볼 정확도 48.0% p85 · 23/24 62.3% p96 · 26/27 84.6% p84), 라인을 이탈해 1v1로 요격하는 임무를 받아 왔다. AcceleRATE **Lengthy** · 188cm 73kg의 마른 장신. PlayStyles는 **긴패스·블로킹** — 배급과 차단이지 태클이 아니다.','⭐ 강점 — 온볼이 리그에 독립적이다. 챔십→PL로 올라가도 패스 정확도·롱볼 정확도·기회 창출 백분위가 유지되고 **빅찬스 창출은 오히려 올랐다**(61→85). 수비 개입량 자체는 많다(25/26 클리어 304 p90 · 수비 행동 404 p87). ⛔ 약점 — **1v1과 공중볼**. 듀얼 승률 백분위 49→**19**(60.8%→50.7%), 돌파 허용 0.24→**0.51/90**(2배), 공중볼 승률은 두 리그 모두 낮다(p37→p37). 서사도 5년 간격 두 체제에서 같은 말을 한다 — 「스피드·민첩성 개선 필요」(BTL 2024) · 「1v1 균형 상실·속도 노출」(TFA 2019/20).',NULL,'MEDIUM — 커널 적합은 높다(**AVL RCB `cb_bpd/Aggressive` 0.899**, SofaScore 38경기). ⛔ 그런데 그 0.899는 **챔피언십 배치의 재현값**이고, 붙는 포커스가 하필 `Aggressive`다 — 이 선수의 확정 약점(1v1·속도·PL 파울 p2)이 정확히 그 포커스가 요구하는 것이다. 에메리의 하이라인은 CB의 배후 처리 속도를 전제하는데 그 축이 5년째 같은 지적을 받는다. ⛔ **AVL RB 0.791은 사용 금지** — RB 실전 출전 0건이고 보도가 「콘사에게서 쓴 멀티포지션 유연성이 THB에게는 없다」고 명시한다. ⭐ 제공권 강한 파트너 전제는 필수다.',NULL,NULL,'fotmob_detail_stats(player 178, 4시즌 152지표, 2026-08-21) ; transfer_targets id=153(map25 38경기·fit_sim 0.899) ; player_game_stats FC26·FC27(fut.gg 35속성) ; player_duties(하우드-벨리스 RCB) ; obs#292 · obs#293 ; Breaking The Lines 2024-08-12 · Total Football Analysis 19/20 · Correio da Manhã(이적 요청서 원출처)','[2026-08-22] MEDIUM-HIGH. ⭐ 근거의 강점은 **같은 클럽·인접 시즌·두 리그**라는 통제군이 존재한다는 것이다 — 리그 효과와 선수 능력을 분리해 읽을 수 있는 드문 경우다. ⛔ **`stat_eval`은 비워 뒀다** — `player_matches` 0행이라 우리 실측 경기 스탯 집계가 없다(`map25`는 transfer-watch가 직접 넣은 값이고 경기별 행은 적재되지 않았다). ⚠️ 백분위는 리그별 동포지션 모집단 대비라 리그 간 직접 비교가 아니다 — 절대값이 같은 방향이라 **방향만** 신뢰한다. ⚠️ 미수집: 유튜브 전술 분석 0건 · 유리치의 개별 평가 0건 · CB 파트너 1차 발언 0건 · 에메리 하이라인↔THB 속도를 직접 연결한 분석 0건. ⚠️ regime_id=NULL — 아직 우리 선수가 아니다(불변규칙 7).','2026-08-22','**FotMob/Opta 4시즌 백분위만으로 내리는 판단: 「태클로 못 끊고 파울로 끊는다」**(obs#292). 규율 수치가 그것을 드러낸다 — 23/24 챔십 파울 0.46/90(p39) → **24/25 PL 파울 1.11/90(백분위 2)·옐로 9(p2)** → 25/26 챔십 0.71/90(p18). **퇴장은 4시즌 전부 0**이므로 난폭함이 아니라 **수습 패턴**이다. 같은 창에서 돌파 허용이 2배로 늘고 듀얼 승률 백분위가 49→19로 떨어지므로, 세 지표가 하나로 닫힌다: 먼저 밀리고, 회수하지 못하고, 반칙한다. ⭐ 반대로 온볼 축은 리그가 올라가도 버틴다 ⇒ **빌드업 성분은 채택 가능, 요격 성분은 PL에서 위험하다.** ⚠️ 출전 중 피xG/90 백분위 0·실점 백분위 1은 **개인에게 귀속하지 말 것** — 24/25 사우샘프턴은 PL 최악급 강등팀이다.');
INSERT INTO player_evaluations VALUES(65,1,90,'B — RB 슬롯 fb_att_wb/Support 실측 적합 0.932(25/26 웨스트햄 45분+ 25경기 2,083분, FotMob 평점 6.80·SofaScore 6.59)로 커널상 준수하나, `player_duties` 실측 서사는 그를 ''윙백''이 아니라 ''1v1 대인 봉쇄 전문 RB''로 규정한다(West Ham Zone 2026-02-26: 윙백 배치가 명시적으로 부적합 판정됨). 에메리 체제 공식전 표본은 0(빌라 데뷔 미확인, 08-23 브라이턴전 결장)이라 빌라 축 실측이 전혀 없다. Football Insider(2026-08-15)의 ''백4/백3 CB 전환'' 가설은 에메리 본인의 영입 발표 당일 발언(''콘사 대체 CB가 한 명 더 필요하다'' — 완비사카를 그 CB로 세지 않음)과 긴장 관계라 신뢰도가 낮다. 종합: 라인 뒤 커버 스피드(최고속도 85퍼센타일)를 사는 ''수비 국면 전용 RB 백업''으로 처방하는 것이 실측·서사 모두와 가장 정합한다. ⭐[2026-09-12 갱신] B 유지. 근거: ⑴ 빌라 실측이 처음 생겼다 — 09-08 브뤼헤전(UCL) RB 선발 68분 평점 6.9, 클리어 6·태클 3·인터셉트 1·크로스 4(성공 1)·패스 25/23, 그러나 61분 PK 헌납(실점 2건 모두 우측 기원, obs#547)·68분 교체. 에메리 회견 「he was so, so tired」·「tight」(obs#554). ⑵ 시즌 정본 대비 기능 반전: 경기 커널 fb_att_wb/Support .863(경기 정본 fb_wingback/Balanced .725, Δ0.138 노이즈 밖) — 같은 쪽 맥긴이 복귀형이라 그가 전진측이 됐다(obs#546), 서사(윙백 부적합)와 긴장 재발. ⑶ FC27 09-10판 OVR 78(FC26 출시판 80 대비 −2, FC26 라이브 sofifa 79 대비 −1) 하락. 캐시 결장 시 재선발 유력(obs#615)이나 「수비 국면 전용 백업」 판단 유지.','1v1 대인 봉쇄 전문 풀백 — 태클로 뺏기보다 붙어서 통과를 막는 유형(dribbled_past 0.26/90=92퍼센타일, 인터셉트 1.88/90=95~100퍼센타일). 온더볼은 짧고 안전한 패스 선호, 전진 판단 주저(패스 정확도 76.7%=20퍼센타일). 커버 지향·압박 높이는 낮음. 윙백형 전진 가담(인버티드 하프스페이스 진입)은 어느 소스에도 서술이 없고, West Ham Zone은 오히려 ''윙백이 그의 스킬셋에 안 맞는다''고 명시한다. DR콩고 대표팀(WC 2026 4경기 전 선발)에서도 동일 정체성이 독립 재현됨(드리블 피탈 0회). ⭐[2026-09-12] PlayStyles 궤적: FC25 출시판(2024-09-13) Block·Anticipate·Rapid·Slide Tackle+ → FC26 출시판(2025-09-12) Intercept 추가(5종) → FC26 라이브 06-30 동일 5종 → FC27 09-10판 동일 5종(Block·Intercept·Anticipate·Rapid·Slide Tackle+). 실측 대조: Intercept·Anticipate·Block은 FotMob PL 25/26 인터셉트 40회(93/95백분위)·클리어 94(83/86)·제쳐당함 0.30/90(92)과 강정합. ⚠️Slide Tackle+는 태클 33회(46/14백분위)와 어긋난다 — 그는 태클로 뺏는 선수가 아니라 붙어서 막는 선수(player_duties id=96). Rapid는 최고속도 35.0km/h(85)와 정합하나 스프린트 횟수(26)·주행거리(14)는 하위. FC26 role_familiarity Wingback+ 단일(cmtracker)이 여전히 「윙백 부적합」 서사와 충돌.','PL 25/26 25경기(2,083분) 기준: 인터셉트 1.88/90(90~100퍼센타일), 클리어런스 3.17/90(93~95퍼센타일), 수비 액션 7.36/90(73~97퍼센타일), 크로스 정확도 21~38%(76~90퍼센타일, 단 시도량 자체가 적은 선택적 크로스). FC27 OVR 78(PAC 79·DEF 76·SHO 51). 약점: 공중볼 승률 41.1~47.8%(27~40퍼센타일), 상대 박스 터치 10~19퍼센타일, 듀얼 승률 35~50%(12~35퍼센타일), 스프린트 횟수·주행거리 하위권(14~26퍼센타일, 단 최고속도 35.0km/h=85퍼센타일). ⭐[2026-09-12] OVR·6종합 궤적(PAC/SHO/PAS/DRI/DEF/PHY): FC25 출시판 79(82/51/68/77/77/72) → FC26 출시판 80(80/51/69/77/78/73) → FC26 라이브 06-30 sofifa 79(79/51/69/76/77/73; EA 공식은 80/80/51/69/77/78/73, 3사 6종합 불일치는 산출 공식 차이) → FC27 09-10판 78(79/51/68/73/76/73). FC27 vs FC26 출시판 Δ: OVR−2·DRI−4·DEF−2·PAC−1·PAS−1. FC27 vs FC26 라이브(sofifa) Δ: OVR−1·DRI−3·DEF−1·PAS−1. 세부(FC25→FC26 출시판): 질주 85→80·가속 78→79·헤딩 50→57·반응력 77→79·슬라이딩 88→89·점프 72→75·체력 73→75; FC27 attrs 미수집(obs#364)이라 하락 항목 특정 불가. 강점: 수비 속성(차단 81·슬라이딩 89·수비위치 78)과 속도 유지. 약점: 3버전 연속 SHO 51·중거리 44·긴패스 58 정체, DRI 하락 추세.','FotMob PL 25/26(25경기 2,083분): 평점 6.80, 어시스트 2·골 0, 경고 4·퇴장 0. 시즌 상세지표(24/25·25/26 두 시즌 교차) 상위권 — 인터셉트·클리어런스·수비 액션이 모두 70~100퍼센타일로 안정적. 하위권 — 듀얼 승률(12~35퍼센타일)·공중볼(27~40퍼센타일)·패스 정확도(20~43퍼센타일). 웨스트햄 fullback 대비 특화 트레이트(FotMob traits): 수비적 행동 52퍼센타일·기회 창출 25퍼센타일·터치 12퍼센타일로 ''수비 전용, 볼 관여 최소'' 프로파일이 재확인된다. ⭐[2026-09-12] 최신 FotMob 상세는 PL 25/26(42지표, 웨스트햄) — 26/27 지표 미수집. 백분위(총량/90분): 인터셉트 40(93/95)·제쳐당함 7(73/92)·크로스 정확도 38.1%(90)·클리어 94(83/86)·수비 액션 174(73/75)·최고속도 35.0(85); 하위: 골 0·슛 0(0)·박스 터치 15(33/10)·패스 정확도 76.7%(20)·듀얼 승리 83(49/12)·태클(46/14)·리커버리(52/21)·주행거리(46/14). 26/27 player_matches(AVL): 08-31 아스날 12분 6.29(hp 11) · 09-05 헐 5분 평점 NULL(패스 9/9) · 09-08 브뤼헤 68분 6.9(클리어 6·태클 3·인터셉트 1·듀얼 4/1·크로스 4/1·PK 헌납). 월드컵(COD) 07-01 잉글랜드전 90분 7.6. v_player_profile n=59 평균 6.65(3708분). v_player_season_stats 26/27: PL 2경기 17분 6.29 · UCL 1경기 6.9.','MEDIUM — 실측·듀티 근거. AVL RB 슬롯(x=87) 커널 재현 fb_att_wb/Support 0.932, Δ=0.1042>.05로 위치 채택 확정(2026-08-14). 단 이는 위치 유사도이지 기능 적합이 아니다 — 에메리의 RB(캐시형 윙백 겸 와이드미드)는 전진 폭을 감당해야 하는데, 완비사카는 현 체제(웨스트햄)에서 바로 그 축(윙백)이 명시적으로 부적합 판정을 받았다. Support 지시를 공격 가담 요구로 해석하면 안 된다(상대 박스 터치 10퍼센타일이 뒷받침). 에메리 본인의 완비사카 실명 언급은 빌라 이적 후(08-21~08-31) 전 구간 0건이라 직접 근거는 없음. 종합: ''캐시의 1:1 대체''가 아니라 ''수비 국면 전용 RB 백업''으로 기용될 가능성이 가장 높다. ⭐[2026-09-12] MEDIUM 유지 — 빌라 실측 유효 1경기(브뤼헤 68분, hp 55)가 생겼으나 방향이 갈린다. 지지: 경기 커널 fb_att_wb/Support .863로 시즌 정본 squad_entries(.932)과 같은 역할 — 위치 재현은 빌라 축에서도 성립. 긴장: ⑴ 그 경기 정본 RB 지시는 fb_wingback/Balanced .725였고 그가 전진측이 된 것은 맥긴 복귀형과의 구조적 짝(docs/20 ⑨, obs#546)이며 36% 점유 국면 — 시즌 정본 미변경. ⑵ 실점 2건 우측 기원·PK 헌납·「so tired」(obs#547·554) — 전진 폭 감당 시 수비 국면 비용이 실측됨. 아스날 12분(.823, hp 11)·헐 5분(.786)은 표본 미달. 결론: 「캐시 1:1 대체」 아님, 수비 국면 전용 RB 백업·캐시 결장 시 대체 선발(obs#615) 처방 유지.','LOW-MEDIUM(교차 투영 — 실측 아님). 첼시 소속 표본이 전혀 없다. 알론소 체제는 빌드업 단계 풀백의 하프스페이스 인버트를 요구하는 경우가 많은데, 완비사카의 온더볼 서사(전진 판단 주저·패스 정확도 20퍼센타일)는 이런 요구와 정합이 낮다. 순수 대인 봉쇄 능력만 떼어보면 백업 수비형 RB로는 어느 체제에도 이식 가능하다.','LOW(교차 투영 — 실측 아님). 이라올라 체제의 맨투맨 하이프레스 인계 부담을 감당하려면 커버 지향·전진 압박 참여가 필요한데, 완비사카의 실측 서사는 ''커버 지향·압박 높이 낮음''으로 정반대다. 리버풀 축 표본도 없다.','squad_entries id=128 RB fb_att_wb/Support 0.932; player_game_stats id=483 FC27 OVR78; fotmob_season_stats player 760320(25/26 PL); fotmob_detail_stats(24/25·25/26 두 시즌, per90+percentile); fotmob_traits id=289~294(fullback 비교군); player_duties id=96(웨스트햄 누누 체제·DR콩고 대표팀 실측 서사); prescriptions id=429/430(fb_att_wb/Support 0.932, sample_n=25); player_matches(AVL 08-31 아스널전 12분 출전 포함 다수); player_status id=35(계약 2031-06-30). | 2026-09-12 갱신: player_game_stats id=728(FC25 2024-09-13, attrs)·729(FC26 2025-09-12, attrs)·81(FC26 2026-06-30 cmtracker/sofifa, attrs·role_familiarity)·338/483(FC27 08-22/08-31)·688(FC27 2026-09-10, PlayStyles; attrs 없음); fotmob_detail_stats PL 2025/2026 42지표(24/25 41지표 병존); fotmob_season_stats 25/26; fotmob_traits 2026-08-14; v_player_profile n=59; v_player_season_stats 2026-27; player_matches 26/27 4행(AVL 3행); match_player_reports report 30·31·35; match_player_prescriptions 3행; squad_entries id=128(pos_only RB); prescriptions id=429/430; player_duties id=96; obs#304·364·388·546·547·554·615; player_status id=35(계약 2031-06-30); player_market_values 2026-08-01 €20.04m.','MEDIUM-HIGH — 웨스트햄 시기 실측(25경기)은 두텁고 다국어(영어) 서사도 교차검증됨. 단 ⚠️빌라 체제(에메리) 실측은 0경기다(08-31 아스널전 12분이 유일 — 표본 미달). ⚠️grid_club=West Ham United — 불변규칙 7에 따라 빌라 축 근거로 쓰지 않았다. ⚠️''PL 최고 태클러'' 통설은 맨유 시기 서사이며 현재 실측(태클 14퍼센타일)과 충돌해 기각됨(원장 player_duties에서 이미 처리). ⛔에메리 본인이 완비사카를 실명 지목한 발언은 빌라 이적 후 전 구간 0건. ⚠️ 2026-09-12: 빌라 실측 유효 표본 1경기(브뤼헤, UCL 원정·36% 점유)뿐 — PL 시계열과 분리해 읽어야 하며(report 35 캐비앗) 시즌 판단 불가. 아스날·헐 출전은 hp 11·12·5분으로 그리드 무효. FC27 attrs 미수집(obs#364)이라 6종합 하락의 세부 원인 미특정. FC26 6종합은 sofifa/cmtracker/EA 3사 불일치라 버전 간 Δ는 ±1 오차 내포 — 출시판(fut.gg base)과 라이브판(sofifa)의 −1은 산출 공식 차이일 수 있음. FotMob 상세는 25/26 웨스트햄 축(불변규칙 7). 브뤼헤전 「전진측」은 국면·구조 산물이라 역할 재정의 근거로 쓰지 않았다.','2026-09-12','FotMob 지표만 근거: PL 25/26 25경기(2,083분) 평점 6.80·어시스트 2. 수비 액션 계열(인터셉트·클리어런스·수비적 행동)이 90퍼센타일 이상으로 몰려 있고 공격 관여(기회 창출·터치·상대 박스 터치)는 10~25퍼센타일에 머무는 극단적으로 편향된 프로파일 — FotMob 데이터만 보면 ''순수 수비형 풀백''이라는 결론이 명확하게 선다.');
INSERT INTO player_evaluations VALUES(66,1,86,'C+ — RM 슬롯 wm_widemid/Build-Up 실측 적합 0.878(PSG 25/26 16경기 1,003분, 평점 7.01), 그러나 이것은 빌라 축 표본이 아니라 전부 PSG(루이스 엔리케 체제) 실측이다(불변규칙 7). 18세 유스 자원이며, 1군 선발이 2년 통틀어 10회·2026년 누적 190분·선발 1회로 최근 8개월간 1군 경쟁에서 사실상 탈락한 상태로 이적했다. U19 감독(Camara)·세네갈 대표팀 감독(Thiaw)·PSG 감독(엔리케) 발언이 모두 ''연속성이 필요한 보호 기용 대상''으로 일치해 26/27 즉시 RM 주전으로는 부적합, 장기(2028년경 20세) RM 후보로 처방하는 것이 정합적이다. ⭐[2026-09-12 갱신] C+ 유지. 근거: ⑴ 빌라 공식전 실측 여전히 0 — 26/27 브라이턴·아스날·헐·브뤼헤 4경기 match_player_reports에 행 없음, player_matches AVL 행 0(등번호 19 부여·UCL 명단 상황은 obs#391·476). ⑵ 미출전을 「전술 부적합」으로 적으면 안 된다 — 에메리 브뤼헤전 회견에서 「when they are getting better, Garnacho, Ibra, they can run as well」로 배후 러너 지정 후보로 명시(obs#553), 팬 패널은 「전술 지시 수행 준비도·시스템 숙지」를 실제 차이로 지목(obs#574). ⑶ FC27 09-10판 OVR 76(FC26 출시판 66 대비 +10, FC26 라이브 74 대비 +2)로 게임 내 성장 속도는 최상급이나 DEF 28 고정. ⇒ 장기 RM 후보·즉시 주전 부적합 판단 불변.','정통 터치라인 윙어(orthodox winger) — wide forward가 아니다. 우측 배치 시 바이라인 지향 직선 침투로 풀백을 고립시키고 채널을 공략, 좌측 배치 시 템포 변화·페인트로 패스 레인을 여는 조작형으로 전환. 주발 오른발(우측 배치와 역학적으로 정합). 실측 45분+ 20경기 중 우측 16·중앙 2·좌측 2로 우측 편중이 서사(우60/좌40)보다 더 강함. U19 감독 Camara 원형 정의: ''volume·explosivité·pénétration'' + ''오픈스페이스 투입형''. ⭐[2026-09-12] FC25 행 미수집(2008년생, 출시판 미등재). FC26 출시판(2025-09-13, OVR 66) PlayStyles 공란·AcceleRATE Controlled → FC27 09-10판 Technical·Quick Step, AcceleRATE Explosive(가속 92·민첩 88). 게임은 그를 「가속·드리블형 터치라인 윙어」로 규정 — 실측 프로필(캐리 침투 94백분위·take-on 5.14/90 90백분위, 25/26 리그1)과 방향 일치. 단 ⚠️FotMob directness 1백분위(곡선·페인트형 캐리)와 Quick Step(직선 가속) 사이엔 긴장이 있고, 수비 축(수비 액션 24백분위·듀얼 승률 32)을 반영한 PlayStyle은 없다. 포지션 FC26 RW/RM/LW → FC27 RW 단일, 주발 오른쪽 유지.','PSG 25/26 Ligue1 24경기(997분) 3골 2도움 평점 6.83(FotMob). 캐리 침투 129m/90(94퍼센타일), 프로그레시브 캐리 8.79/90(94퍼센타일), take-on 시도 5.14/90(90퍼센타일)·박스 진입 터치 6.23/90(87퍼센타일), 짧은 패스 정확도 86.5%(87퍼센타일). 약점: take-on 성공률 33.9%(33퍼센타일), 크로스 완성도 12.5%(14퍼센타일, 시도는 많으나 성공은 하위권), 수비 액션 2.08/90(26~37퍼센타일)·듀얼 승률 41.7%(32퍼센타일, 단 시즌 초 28%에서 성장), 신체 175cm/64kg(BMI 20.9)로 PL 윙어 기준 명백한 저체중. ⭐[2026-09-12] OVR·6종합 궤적(PAC/SHO/PAS/DRI/DEF/PHY): FC25 미수집 → FC26 출시판(2025-09-13) 66(77/59/59/70/25/45) → FC26 라이브 07-23판 74·POT 85(89/63/63/78/28/51) → FC27 09-10판 76(90/70/64/80/28/52). FC27 vs FC26 출시판 Δ: OVR+10·PAC+13·SHO+11·DRI+10·PAS+5·DEF+3·PHY+7. FC27 vs FC26 라이브 Δ: OVR+2·SHO+7·DRI+2·PAC+1·PAS+1·PHY+1·DEF 0. 세부(FC26 출시판→FC27): 가속 78→92·질주 77→88·슈팅력 60→84·드리블 70→81·볼컨트롤 66→78·민첩 82→88·반응력 62→74·공격위치 64→75·체력 51→61; 스탠딩 태클 29·슬라이딩 25 불변, 차단 19→24, 힘 42→48. 강점 갱신: 속도·드리블·슈팅력 급등. 약점: 수비 전 속성 20대·체력 61·힘 48은 PL 우측 수비 분담 요구와 계속 충돌.','FotMob Ligue1: 24/25 시즌(12경기 표본, 저분모 주의) 대비 25/26(24경기 997분)에서 뚜렷한 성장 궤적 — 듀얼 승률 28.0%(3퍼센타일)→41.7%(32퍼센타일), 리커버리 2.68(12퍼센타일)→3.70(51퍼센타일), 태클 1.07(12퍼센타일)→1.26(39퍼센타일)로 1시즌 만에 하위 3%에서 하위 32%로 이동. xG 3.28(70퍼센타일)·xA 2.13(65퍼센타일)로 창출력은 상위권이나 xGA on-pitch 1.12/90(81퍼센타일=출전 중 실점 기대값 높음)이 경고 신호. FotMob traits(공격형 미드필더/윙어 비교군): 득점 86퍼센타일·터치 86퍼센타일 vs 수비적 행동 24퍼센타일. ⭐[2026-09-12] 최신 FotMob 상세는 리그1 25/26(39지표, 2026-08-21 수집) — 26/27 지표·빌라 소속 경기 미수집. 25/26 백분위(총량/90분): 터치 802(63/93)·성공 패스 493(70/91)·패스 정확도 86.5%(87)·박스 터치 69(73/87)·드리블 성공 21(72/85)·상대진영 볼탈취 11(64/81)·xG 3.28(70/71)·xA 2.13(65/73); 하위: 크로스 성공 2회(19)·정확도 12.5%(14)·듀얼 승률 41.7%(32)·수비 액션 23(37/26)·xGA on-pitch 1.117/90(81=불리). 26/27 player_matches: 월드컵(SEN) 07-01 47분 6.5, 클럽 친선 08-05 60분 6.4·08-08 90분 7.5·1골(team_code LIV로 적재 — 정합 의심). 09-02 이후 빌라 공식전 평점 없음. v_player_profile n=67 평균 6.91(1745분, 대표팀 혼입).','MEDIUM(빌라 실측 0 — PSG 체제 실측·듀티 서사 기반 판정). squad_entries/prescriptions 재산출 fit_sim 0.878(AVL RM 슬롯 x=85 기준)로 LIV 기준 산출값(0.94, regime_id=3 이력 행)보다 낮다. ⭐tool_x 74.42로 슬롯보다 10.58 안쪽 이탈 — 명단 내 최대 이탈폭이며 ''정통 윙어=터치라인형'' 서사와 정면 충돌(위치는 실측 채택, 불변규칙 3). 에메리 요구(고라인·중앙압박·측면 수비 분담) 중 절반만 부합 — 부합: 전방압박 81퍼센타일·폭유지+컷백 생산(박스터치 87퍼센타일)·구조적 로테이션 소화(패스 정확도 87퍼센타일); 불일치: 수비 복귀·측면 수비 분담(24~32퍼센타일, 최대 리스크)·크로스 완성도(14퍼센타일)·고라인 뒷공간 관리(xGA 81퍼센타일). 엔리케 스스로도 클럽-대표팀 성적 괴리를 인정(''Il a été plus libéré… avec et sans le ballon'', 2025-12-14). 종합: 26/27 즉시 RM 주전 부적합, 육성 자원으로 처방. ⭐[2026-09-12] MEDIUM 유지(빌라 실측 0 — 근거 층위 변화 없음). 시즌 정본 squad_entries id=136·prescriptions id=436/437 wm_widemid/Build-Up .878(grid_club PSG, n=16, 평점 7.01) 그대로. 신규 근거는 감독 발언 층위만: 에메리가 배후 러너 기능(현재 헤밍스 대행)의 지정 후보로 만잠비·가르나초·음바예를 호명(obs#553) — 요구 기능은 「최종 라인 뒤 침투」이며 게임 속성(가속 92·질주 88·Quick Step)이 이를 지지한다. 반면 브뤼헤전 3-2 리드 국면에서 알리송(트랙백 서술)이 대신 투입돼 「수비 복귀 신뢰」가 차별 요인으로 남는다(obs#574). 실측 도착 전까지 wm_widemid/Build-Up 처방·MEDIUM 유지.','LOW(교차 투영 — 실측 아님, 첼시 표본 0). 알론소 체제의 측면 구조(하프스페이스 오버로드·인버티드 풀백 지원)에는 정통 터치라인형보다 인사이드 포워드형이 더 맞는 경향이 있는데, 실측은 음바예를 터치라인형으로 규정한다. 캐리·창출력은 이식 가능하나 수비 복귀(24~32퍼센타일)가 어느 체제든 최대 리스크로 남는다.','LOW(교차 투영 — 실측 아님, 리버풀 표본은 영입 무산 전 이력행 regime_id=3에만 남아있고 fit_sim 0.94는 LIV RM 슬롯 x=77 기준이라 그가 실제로 리버풀에 가지 않았으므로 참고치에 불과). 이라올라의 맨투맨 하이프레스 인계 부담을 감당하기엔 수비 복귀·경합 승률이 하위권(24~32퍼센타일)이라 부적합에 가깝다.','squad_entries id=136 RM wm_widemid/Build-Up 0.878(transfer_targets 승격); player_game_stats id=505 FC27 OVR76; fotmob_season_stats player 1593857(25/26 Ligue1); fotmob_detail_stats(24/25·25/26); fotmob_traits id=325~330(공격형 미드필더/윙어 비교군); player_duties id=98(regime_id 3→1 정정, PSG 실측+다국어 서사: 영어·프랑스어·세네갈어); prescriptions id=436/437(AVL 기준 재산출)·id=356(LIV 기준 이력, 재작성 아님); player_matches(PSG/세네갈 대표팀/월드컵 다수, team_code LIV→PSG 정정 완료); player_status id=79/115(계약 2028-06-30). | 2026-09-12 갱신: player_game_stats id=727(FC26 출시판 2025-09-13, attrs)·554(FC26 2026-07-23)·355/505(FC27 08-22/08-31)·578(FC27 2026-09-10, attrs·PlayStyles); FC25 행 없음; fotmob_detail_stats Ligue 1 2025/2026 39지표(24/25 36지표 병존); fotmob_season_stats 25/26; fotmob_traits 2026-08-21; v_player_profile n=67; v_player_season_stats 2026-27; player_matches 26/27 3행(AVL 0행); match_player_reports 0행; squad_entries id=136; prescriptions id=356/436/437; player_duties id=98; obs#355·356·364·391·553·554·574; player_status id=79/115(계약 2028-06-30); player_market_values 2026-08-01 €28.97m.','MEDIUM — PSG 실측(16경기 1,003분)과 다국어(불어·세네갈어·영어) 서사 교차검증 완료(불변규칙 10 준수). ⚠️시기 혼입 위험: 일부 서사원(Anfield Insights)이 유스·시니어 지표를 분리하지 않아 퍼센타일 기준 시점이 불확정. ⚠️압박·수비 지표는 최초 ''판정 불가''였다가 2026-08-31 회차에서 확보됐으나 결과가 두 갈래(전방압박 상위·수비 복귀 하위)로 갈려 단순화 위험이 있다. ⚠️''빌라 팬층 정당화 서사''로 의심되는 영어권 기사(''pressing intensity considered strongest qualities'')는 실측(수비 액션 24퍼센타일)과 반증되어 채택하지 않음. ⛔에메리 본인의 음바예 관련 발언 0건, PSG 포메이션 특정 불가, 부상 이력 확인 실패. ⚠️거래 배경에 Sawiris-Al Khelaïfi 관계가 스포팅 판단보다 결정적이었다는 서술이 양국에서 반복돼 즉시전력 기대치를 낮춰야 한다. ⚠️ 2026-09-12: 빌라 소속 공식전 표본 0 — 모든 적합 수치는 PSG(루이스 엔리케) 축이다(불변규칙 7). FC25 미수집·FC26 라이브판 attrs 미수집이라 세부 속성 Δ는 「FC26 출시판→FC27」만 산출 가능. FC26 출시판 PlayStyles 공란은 「없음」과 「미수집」 구분 불가(fut.gg base API). FotMob 상세는 25/26이 최신. ⚠️player_matches 26/27 친선 2행(08-05·08-08)이 team_code LIV로 남아 있어 09-01 team_code 정리(obs#373·385)와 충돌 — 재점검 필요. 미출전 사유는 3갈래 병존(obs#553) — 단정하지 않았다.','2026-09-12','FotMob 지표만 근거: Ligue1 25/26 24경기(997분) 3골 2도움 평점 6.83. 창출·침투 지표(xG 70퍼센타일·xA 65퍼센타일·캐리 침투 94퍼센타일)는 20세 이하 윙어로서 상위권이나, 듀얼·수비 지표(수비 액션 26~37퍼센타일·듀얼 승률 32퍼센타일)가 뚜렷한 약점으로 남는다. 시즌 내 성장 궤적(듀얼 승률 3→32퍼센타일)이 FotMob 데이터에서 가장 뚜렷하게 드러나는 신호다.');
INSERT INTO player_evaluations VALUES(67,3,72,'B+ — FC27 OVR 86(스쿼드 최상급 ST)에 걸맞은 개인 능력이나, 이라올라 체제 초기 실측(공식전 2경기 180분, 평균 6.94, fit_sim st_advanced/Versatile 0.764)은 아직 통합 초기 단계다. 뉴캐슬 데뷔전(obs)에서 ''단독 9번 고립''이 관찰됐고(슛 4·득점 0, 연결 터치 제한) 이후 근접 지원 필요성이 지적됐다. 등급은 잠재력 대비 표본 부족·초기 고립 신호를 반영해 A가 아닌 B+로 둔다. ⭐[2026-09-12 갱신] B+ → A- 상향. PL 26/27 3경기 3선발 244분 3골 평점 7.53(v_player_season_stats; 뉴캐슬 6.68·포레스트 7.2·입스위치 8.7). 09-04 입스위치전 xG 0.21에서 2골(6·9분, 학포 어시스트 2; obs#451) — 시즌 3경기 3골로 25/26 PL 리그 총합(3골)과 동률(report 32). 다만 「고립」 신호 지속(report 28: 포레스트전 터치 14, 판정 「고립이다」), 팀 창출 미개선(입스위치전 빅찬스 0). 표본 3경기이므로 A는 유보.','가속형 9번 — FC27 fut.gg 상세(29속성, AcceleRATE Lengthy) 기준 슈팅력91·결정력87·공격 위치선정88이 최상급이나 크로스68·긴 패스60·수비 관련 속성(차단력38·수비 위치선정35)은 순수 피니셔형임을 시사. squad_entries 프리시즌 3경기(188분, 평점 6.57) 실측 툴x 50.58·툴y 69.35는 최전방 중앙 고정을 확인. 커널 최적 st_false9/Attack(fit_sim 0.725, 프리시즌 기준) vs 공식전 재집계 st_advanced/Versatile(0.764) — 표본이 갈수록 ''고정 9번''에서 ''연계 포함 어드밴스드 포워드'' 쪽으로 이동 중. ⭐[2026-09-12] PlayStyles: FC25 출시판(2024-09-10) Finesse Shot·Rapid·Flair·First Touch(4) → FC26 출시판(2025-09-08) Power Shot·Low Driven Shot·Game Changer·Rapid·First Touch·Finesse Shot+(6; Flair 소멸, Finesse Shot+ 승격) → FC27(09-10) Finesse Shot·Power Shot·Rapid·First Touch·Low Driven Shot·Game Changer(6; Finesse Shot+ 강등). AcceleRATE Controlled(FC25) → Lengthy(FC26·FC27). 실측 정합: 입스위치전 xGOT 1.94 vs xG 0.21(obs#451) — 슛 계열 PlayStyles 집중과 「마무리 품질 > 창출」 프로필 일치. 커널 measured st_advanced/Support 0.752(n=3, 09-06)로 Versatile→Support 이동.','결정력·슈팅력·공격 위치선정 최상급(FC27 87/91/88), 헤딩 정확도82로 공중 마무리도 가능. 약점은 크로스·긴 패스 등 배급 관련 속성과 수비 기여(차단력38) — 순수 피니셔로 설계됐다. FotMob 포워드 대비 percentile은 아직 낮다(득점33·기회창출41·공중볼20) — 이는 이적 전 이적설 시즌(뉴캐슬 소속 시절 포함 집계로 추정)의 표본이라 스쿼드 전환 효과가 아직 반영되지 않았을 수 있다. ⭐[2026-09-12] OVR 궤적: FC25 출시(2024-09-10) 85(PAC85 SHO84 PAS73 DRI86 DEF39 PHY74) → FC26 출시(2025-09-08) 88(83/89/73/85/39/76; 출시판 간 +3, SHO+5) → FC26 시즌말(sofifa 2026-07-23) 87(83/88/73/84/39/75) → FC27 예측(2026-09-10) 86(81/87/72/82/39/72; FC26 시즌말 대비 −1, PAC−2·DRI−2·PHY−3). 세부 FC26 출시판→FC27: 결정력 91→87·가속 86→85·질주 80→77·민첩 73→69·드리블 88→85·체력 82→75·힘 79→75 하향, 슈팅력 91·헤딩 82·위치선정 89→88 유지. 강점: 결정력·위치선정·실측 xGOT 초과 마무리. 약점: 배급(긴 패스 60)·수비(차단력 38) 불변, 연계 터치 부족(포레스트전 14).','fotmob_season_stats(2025/26 PL, 14경기 8선발 703분): 3골 1도움, 평균 평점 6.49 — 스쿼드 에이스급 영입치고는 낮은 편인데, 이는 이적 시즌 초반 구간 또는 이적 전 소속 표본이 섞였을 가능성이 있어(source 기록에 소속 전환 시점 명시 없음) 그대로 리버풀 적응도로 읽지 않는다. FotMob 포워드군 percentile(아마도 동일 표본): 득점33·기회창출41·슛시도46·터치27·공중볼20 — 전반적으로 중위권. ⭐[2026-09-12] FotMob 2025/26 PL 상세(14경기 703분): 골 3(xG 2.65), 슛 17(p90 백분위 24), 터치 23.0/90(백분위 2), 듀얼 승률 29.3%(백분위 10), 기회창출 2(백분위 4), 볼 소유 상실 0.90/90(백분위 80) — 관여·연계 지표 최하위권. 2024/25 PL(뉴캐슬): 골 23(백분위 100)·xG 20.42(96)·기회창출 42(96). ⭐ 25/26 급락 시즌은 tenures상 리버풀 소속(22경기 평점 6.45)으로 확인. 09-02 이후: 09-04 입스위치 64분 평점 8.7·2골, 단일 경기 fit st_advanced/Support 0.655(report 32). DB 26/27 PL 3경기 xG 합 2.29·3골. 2026/27 FotMob 시즌·상세 미수집.','MEDIUM-HIGH(교차 투영 — 실측 아님). 에메리는 명확한 타깃형 9번보다 연계·박스 침투를 겸하는 포워드를 선호하는 경향이 있어, 이삭의 결정력·박스 위치선정은 부합하나 배급 속성(크로스68·긴패스60) 부족은 감점 요인.','MEDIUM(교차 투영 — 실측 아님). 알론소 체제의 포지셔널 플레이는 최전방의 폭넓은 연계를 요구하는 경우가 많은데, 이삭의 프로필은 고정 9번에 가까워 완전한 적합보다는 부분 적합으로 본다.','MEDIUM(실측·duties 근거). 프리시즌 st_false9/Attack(0.725)에서 공식전 재집계 st_advanced/Versatile(0.764)로 이동했고, 뉴캐슬 데뷔전은 ''고립'' 문제가 관찰됐다 — 이라올라의 다이내믹한 전방 압박·연계 요구에 완전히 맞물리기 전 초기 조정 단계로 판단한다. 표본이 공식전 2경기(180분)뿐이라 확정적 결론은 이르다. ⭐[2026-09-12] MEDIUM → MEDIUM-HIGH. 리버풀 실측 PL 3경기 244분: measured st_advanced/Support 0.752(prescriptions 428, 09-06 갱신), 단일 경기 fit 포레스트전 0.832(report 28)·입스위치전 0.655(report 32). 3경기 3골로 산출은 확보됐으나 구조 문제 병존 — 포레스트전 「xG 팀 최다=위치선정 정상, 공급 결손」, 입스위치전 팀 xG 열세(0.69–0.75)·빅찬스 0에서 개인 마무리로 승점(obs#451). obs#492 패스 네트워크에서 비르츠–이사크 근접 확인은 「근접 지원」 처방(duties 39)의 초기 실현 신호. 이라올라의 「회수하면 9번에게」 원칙에 산출이 종속돼 있어 HIGH는 유보.','player_game_stats FC27(2026-08-31, fut.gg); fotmob_season_stats(2025/26 PL); fotmob_traits(forwards 6지표); player_duties id=39(뉴캐슬 obs); prescriptions id=428(measured, n=2)·id=454(fc26:opt:ST); squad_entries id=96(프리시즌 3경기); player_status(계약 2031-06-30) | 2026-09-12 갱신: player_game_stats FC25(2024-09-10)·FC26(2025-09-08 출시판, 2026-07-23 라이브)·FC27(2026-08-21/08-22/08-31/09-10); prescriptions 428(2026-09-06)·454; v_player_season_stats 26/27; player_matches 4028·4114·4297; match_player_reports r23·28·32; match_reports 32; fotmob_detail_stats 2024/25·2025/26 PL(2026-08-21); fotmob_traits; player_tenures 2025-26; player_market_values ~2026-08-01(€87.5M); obs#450·451·492','공식전 표본이 2경기 180분으로 매우 얇다 — 초기 통합기 판단이며 시즌 진행에 따라 갱신 필요. fotmob_season_stats의 소속·시기 귀속이 명확히 표기되어 있지 않아 리버풀 이적 이후 전용 지표로 단정하지 않았다. ⚠️ 2026-09-12: 공식전 3경기 244분 — 초기이나 3연속 득점으로 방향 일관. FC27은 출시 전 예측판. FC26 라이브(07-23)·FC27 08-21 행 attrs 미수집. 09-02 평가의 「25/26 FotMob 소속 불명」은 tenures(2025-26 Liverpool 22경기)로 리버풀 시즌임이 확인돼 해소. 2026/27 FotMob 시즌·상세 미수집. 시장가치 06→08월 €103.1M→€87.5M 하락. 09-04 이후 경기(UCL 포함) DB 미수집.','2026-09-12','FotMob 지표만 보면 2025/26 PL 14경기 3골 1도움·평점 6.49로 스쿼드 최고 영입가 대비 초라한 숫자다. 포워드군 percentile도 득점33·기회창출41 등 중위권에 그친다 — 다만 이 지표가 이적 전후 어느 시점 표본인지 DB에 명시가 없어 리버풀 소속 성과로 단정할 수 없다는 한계가 있다.');
INSERT INTO player_evaluations VALUES(68,3,81,'A- (PSG 25/26 실측 기준, 리버풀 실측 0) — PSG에서 29경기 21선발 1750분, 11골 1도움 평점 7.36으로 리그앙 상위 공격형 윙어의 실적을 냈다. FC27 OVR 85(가속92)에 프리시즌 없이 바로 CONFIRMED 이적(2026-08-31 공식 발표, 5년 계약 £106m 고정). 다만 이 평가는 전량 PSG(엔리케 체제) 자료이고 리버풀·이라올라 체제 실측은 아직 0건이다. ⭐[2026-09-12 갱신] A- 유지(단서 강화). 리버풀 첫 실측: 09-04 입스위치 26분 교체(LM, 평점 6.6, 터치 13, xA 0.07, hp 13 그리드 무효; report 32 프랑스 매체 「timides(수줍은) 데뷔」). FC27 OVR 85(2026-09-10 행부터 클럽 Liverpool 반영), 질주 95·가속 89. obs#343: 좌측 fit 0.751이 학포 0.773·무뇨스 0.771보다 낮아 영입은 fit으로 정당화되지 않음(fit=형태 일치도). 등급 근거는 여전히 PSG 25/26(Ligue 1 11골 평점 7.36)이라 A-는 타 팀 실측 등급.','좌측 터치라인 와이드 포워드 — 폭 유지 + 배후·하프스페이스 침투가 1차 임무(PSG 25/26). 드리블은 선택적(성공률 50%, 두에·크바라츠헬리아 대비 낮음)이나 움직임·가속으로 공간을 창출하고, shot-ending carries 2.06/90은 5대리그 유일 2.0 초과(Opta). 좌측 34경기 실측 tool_x 23.3·tool_y 67.8로 ''좌측 폭 유지+전진'' 서사와 정합. 최종 3선 볼 탈취 유럽 5대리그 9위로 압박 지표도 갖춤. ⭐[2026-09-12] PlayStyles: FC25 출시판(2024-09-13) Finesse Shot·Rapid·Flair → FC26 출시판(2025-09-12) Finesse Shot·Game Changer·Rapid(Flair→Game Changer) → FC27(09-10) Finesse Shot·First Touch·Low Driven Shot·Game Changer·Rapid+(Rapid+ 승격, First Touch·Low Driven Shot 추가). AcceleRATE Controlled 3버전 유지. Rapid+·질주 95는 duties 97 「가속으로 공간 창출·shot-ending carries 2.06/90」과 정합; 피니시 PlayStyles 추가는 Ligue 1 25/26 xG 10.83(백분위 96)·박스 터치 8.69/90(98)과 부합. 크로스 PlayStyle 없음 — 크로스 성공률 20%(백분위 29) 정합. obs#455: 이라올라가 양측면 기용 대상으로 바르콜라 직접 열거.','가속92·질주속도(FC27 최상급), 득점력(PSG 89퍼센타일)·기회창출(85퍼센타일) 우수. 약점은 결정적 국면의 성급한 판단과 마무리 정확도(엔리케가 직접 교정 대상으로 지목), 수비적 행동은 43퍼센타일로 평범. ⭐[2026-09-12] OVR 궤적: FC25 출시(2024-09-13) 80(PAC88 SHO74 PAS75 DRI81 DEF34 PHY64) → FC26 출시(2025-09-12) 84(90/77/78/84/39/66; 출시판 간 +4) → FC26 시즌말(sofifa 2026-07-23) 84(92/77/78/84/39/66; PAC+2) → FC27 예측(2026-09-10) 85(92/76/78/84/39/67; 시즌말 대비 +1). 세부 FC26 출시판→FC27: 질주 91→95·가속 88→89·공격 위치선정 84→86·볼컨트롤 84→85 상향, 결정력 80→78·침착 83→79·PK 66→59 하향. 강점: 질주 95(스쿼드 최상급)·xG 생산(Ligue 1 백분위 96)·최종3선 탈취 23(92). 약점: 결정력·침착 하향 추세, 어시스트 1(xA 4.50 대비 저조, 백분위 28), 듀얼 승률 42.6%(36).','fotmob_season_stats(PSG 2025/26): 29경기 21선발 1750분, 11골 1도움, 평점 7.36, 경고 2. FotMob 공격형 미드필더/윙어군 대비 percentile: 득점89·기회창출85·슛시도82·터치59·공중볼49·수비적행동43 — 공격 생산성이 강점, 수비 기여는 평범. ⭐[2026-09-12] FotMob 2025/26 Ligue 1 상세(29경기 1750분): 골 11(백분위 94)·xG 10.83(96)·슛 3.45/90(96)·유효슛 31(98)·박스 터치 169(98)·빅찬스 창출 11(93)·드리블 성공 36(90)·최종3선 탈취 23(92)·태클 30(82); 어시스트 1(28)·크로스 성공률 20%(29)·듀얼 승률 42.6%(36). DB 실측 25/26 전체 69경기 3759분 평점 7.03(Ligue 1 29경기 7.21·UCL 16경기 6.8·WC 4경기 7.4). 09-02 이후 리버풀: 09-04 입스위치 26분 평점 6.6·키패스 1·터치 13(player_matches 4300). 2026/27 FotMob 미수집.','MEDIUM(교차 투영 — 실측 아님). 좌측 폭 유지형 프로필은 에메리의 측면 오버로드 전술과 결이 다르지 않으나, 중앙 플레이메이킹 겸용은 약해 완전 적합으로 보기 어렵다.','MEDIUM-HIGH(교차 투영 — 실측 아님). 알론소 체제가 선호하는 빠르고 직선적인 윙어 프로필과 가속력·배후 침투 성향이 부합할 가능성이 있다.','미확정(리버풀 실측 0). squad_entries 그리드·적합(wm_wideplm/Attack 0.751)은 PSG 25/26(엔리케 체제) 표본을 그대로 이식한 값이며 이라올라 체제 실측이 아니다(confidence에 명기됨). 이라올라가 공개적으로 ''윙어가 필요하다''(2026-07)고 언급했고 압박 실적(최종 3선 탈취 9위)은 이라올라의 전방 압박 요구와 부합할 가능성을 시사하나, 리버풀 소속 실측이 쌓이기 전까지는 가설 수준이다. ⭐[2026-09-12] 미확정 → LOW-MEDIUM(가설, 리버풀 실측 26분). 유일한 리버풀 표본 입스위치전 26분(LM, avg_y 84.1 좌측, hp 13 무효, fit 미산출; report 32). 근거는 여전히 PSG 25/26(엔리케 체제) — wm_wideplm/Attack 0.751(squad_entries 134), duties 97 압박 실적(최종3선 탈취 5대리그 9위). obs#343: 좌측 전용 fit 0.751 < 학포 0.773·무뇨스 0.771. obs#455: 이라올라 09-03 회견 「모든 윙어에게 양쪽을 다 뛰라고 요구」 대상에 바르콜라 명시. 긍정 신호는 압박 지표·감독 발언, 부정 신호는 fit 열위·데뷔 저관여 — 결론은 45분+ 실측 3경기 확보 전까지 유보.','player_game_stats FC27(2026-08-31); fotmob_season_stats(PSG 2025/26); fotmob_traits(AM/wingers 6지표); player_duties id=97(PSG 25/26 서사, ⚠️리버풀 자료 아님); squad_entries id=134(CONFIRMED, PSG 그리드 이식); player_status(계약 2028-06-30, transfer 2026-08-31) | 2026-09-12 갱신: player_game_stats FC25(2024-09-13)·FC26(2025-09-12 출시판, 2026-07-23 라이브)·FC27(2026-08-22/08-31/09-10); fotmob_detail_stats 2025/26 Ligue 1(2026-08-21); fotmob_traits; v_player_profile·v_player_season_stats(25/26·26/27); player_matches 4300; match_player_reports r32; match_reports 32; squad_entries 134; player_duties 97; player_market_values ~2026-08-01(€57.2M, PSG); obs#343·455','⚠️ 불변규칙 7 관련 최대 주의 사례 — duties·squad_entries 근거가 전부 PSG(엔리케 체제) 자료이고 리버풀 이적은 2026-08-31 확정, 이라올라 체제 실측은 0경기다. 여기 적은 fit_iraola는 명확히 가설임을 재확인한다. prescriptions 행 없음(신규 이적으로 최적 스쿼드 재구성 시트에 아직 미반영 가능). ⚠️ 2026-09-12: ⚠️ 불변규칙 7 — 등급·fit 근거 대부분 PSG(엔리케 체제) 자료, 리버풀 실측 26분 1회(그리드 무효). FC27 PlayStyles는 예측판. FC26 라이브(07-23)·FC27 08-22/08-31 행 attrs 미수집(09-10 행만 있음). 시장가치 시계열은 PSG 소속 08-01까지(리버풀 이적 후 값 미수집). 2026/27 FotMob 미수집. prescriptions 행 없음 지속. 09-04 이후 경기(UCL 포함) DB 미수집.','2026-09-12','FotMob 지표 기준 PSG 25/26 최고 생산성 시즌(11골 1도움, 평점 7.36, 득점 89퍼센타일)을 보낸 상승세의 윙어다. 다만 이 지표 전체가 이적 전 소속(PSG) 기준이라 리버풀 이적 후 성과 예측치로 직접 대입할 수는 없다.');
INSERT INTO player_evaluations VALUES(69,3,73,'B — GK 슬롯 실측 rate_v 6.7(프리시즌 4경기 278분)로 스쿼드 내 자리를 잡았으나, 알리송과의 No.1 경쟁이 미해소다(3방 충돌: 마마르다슈빌리 기회설 vs 임대설 vs 알리송 선발). FotMob 2025/26(발렌시아 소속으로 추정, 10경기 868분) 클린시트2·평점6.58로 표본이 제한적이다. ⭐[2026-09-12 갱신] B → B- 하향. PL 26/27 3라운드 GK 선발은 전부 알리송 90분(뉴캐슬 6.04·포레스트 6.1·입스위치 8.5·5세이브, obs#451) — 마마르다슈빌리 공식전 0분으로 No.1 경쟁은 「미해소」가 아니라 백업으로 정리된 상태. FC27 OVR 83(예측판 09-10)은 FC26 시즌말 83 유지이나 FC25 출시 85에서 2년간 −2. 시장가치 2026-06-01 €34.26M → 08-01 €27.75M 하락.','리액티브 샷스토퍼 — 스위퍼형이 아닌 전통형, 골라인 근처에 머무는 성향이 서사·실측 양쪽에서 확인된다. 준통제 비교(모나코전, 각 45분): 마마르다슈빌리 avg_x 8.6 vs 같은 경기 알리송 avg_x 15.8로 마마르다슈빌리가 7.2 더 깊다. 다만 마마르다슈빌리 출전 구간이 2-1→2-3 실점 국면(trail)이라 피격 상황이 라인을 뒤로 밀었을 가능성도 있어 전량을 성향으로 귀속하지 않는다. 박스 장악·크로스 차단은 강점, 배급은 한발·레인지 제한 서사가 있으나 스로 배급은 우수. ⭐[2026-09-12] PlayStyles: FC25 출시판(2024-09-11) Far Throw·Cross Claimer → FC26 출시판(2025-09-12) Far Throw·Footwork·Cross Claimer(Footwork 추가) → FC27(09-10) Far Throw만(Cross Claimer·Footwork 공란 — 예측판 결손 가능). AcceleRATE Lengthy(FC25·FC26). 「스로 배급 우수」(Far Throw 3버전 유지)·「박스 장악·크로스 차단」(Cross Claimer) 서사와 정합. 단 FotMob 하이클레임은 2024/25 LaLiga 33(백분위 86)→2025/26 PL 3(백분위 21), 스위퍼 22(91)→10(p90 79)로 실측 산출은 급감 — 출전 감소(868분) 영향.','FC27 세부(fut.gg): 반사신경83·반응력81·핸들링81·포지셔닝82 상위권, 가속48·질주속도45로 스위핑에 필요한 커버리지는 약점. PK 방어 실적 1/2. FotMob 골키퍼군 percentile: 클린시트15·실점2(낮을수록 실점 적다는 의미면 우수)·스위퍼 액션65·세이브율1(매우 낮음, 표본·팀 상황 영향 가능)·롱볼성공률21. ⭐[2026-09-12] OVR·GK 6종합(DIV/HAN/KIC/REF/SPD/POS): FC25 출시(2024-09-11) 85(86/83/72/85/48/85) → FC26 출시(2025-09-12) 84(84/81/72/84/48/84; 출시판 간 −1 전반 하향) → FC26 시즌말(sofifa 2026-07-23) 83(82/81/72/83/48/82) → FC27 예측(2026-09-10) 83(82/81/75/83/47/82; 시즌말 대비 KIC+3·SPD−1). 세부 FC26 출시판→FC27: 반응력 74→81(+7)·킥 72→75(+3) 상향, 다이빙 84→82·포지셔닝 84→82·반사 84→83 하향. 강점 반사 83·반응 81·핸들링 81. 약점 가속 48·질주 45(하이라인 뒤 커버리지) 3버전 불변. 출시판 OVR 2년 연속 하향(85→84→83).','fotmob_season_stats: 10경기 868분, 클린시트2, 실점18, 평점6.58, PK세이브 1/2. 세이브율 percentile 1은 극단적으로 낮아 팀 실점 상황(발렌시아 시절 추정)과 결부됐을 가능성이 크다 — 개인 기량으로 단순 환산하지 않는다. ⭐[2026-09-12] FotMob 2025/26 PL(10경기 868분) 상세: 세이브 34(p90 백분위 90)·세이브율 65.4%(백분위 33)·goals_prevented −2.65(백분위 26; 기대 대비 실점 많음)·실점 18(1.87/90)·클린시트 2·PK 세이브 1/2(백분위 92)·실책 실점 0·롱볼 성공률 30.3%(백분위 23). 2024/25 LaLiga(발렌시아): 세이브 93(백분위 84)·goals_prevented −1.48·클린시트 8. ⚠️ 09-02 평가의 「발렌시아 소속 추정」은 오류 — 리그명이 Premier League이고 tenures 2025-26 Liverpool(20경기 평점 6.48). 09-02 이후 리버풀 출전 0(match_player_reports 없음). 2026/27 FotMob 미수집.','MEDIUM(교차 투영 — 실측 아님). 에메리는 빌드업 관여도가 높은 GK를 선호하는 경향이 있는데, 마마르다슈빌리의 ''한발·레인지 제한'' 배급 서사는 다소 어긋날 수 있다.','MEDIUM(교차 투영 — 실측 아님). 알론소 체제의 높은 라인·빌드업 요구와 ''골라인 고착'' 성향은 상충 요소가 있다.','MEDIUM-LOW(실측·duties 근거) — 커널 gk_goalkeeper/Defend 0.957(2위 Balanced 0.922, Δ0.035 노이즈 구간이나 서사가 Defend를 독립 지지). ⭐ 핵심 함의: 이라올라는 하이라인을 쓰는데 이 GK는 라인을 비우지 않는 전통형이라 GK 교체가 라인 리스크 변경으로 이어질 수 있다(duties 명시). squad_entries 프리시즌 4경기(278분, 평점6.7) 실측 툴x 50.55·툴y 8.34로 골문 고정 위치 확인. ⭐[2026-09-12] MEDIUM-LOW 유지. 리버풀 실측: 프리시즌 5경기 368분 평점 6.7(v_player_profile; 좌표 유효 4경기 avg_x 7.2~9.3), 공식전 0분. squad_entries gk_goalkeeper/Defend 0.979(4경기 278분). PL GK는 알리송 3/3 선발이고 입스위치전 승점 기여(5세이브·8.5, obs#451)로 서열이 굳어짐. obs#152(알리송보다 7.2 깊은 라인)와 obs#188(이라올라는 GK를 빌드업 기점으로 쓰지 않음)은 상반 함의 — 배급 약점은 감점 요인이 아닐 수 있으나 하이라인 뒤 커버(가속 48·질주 45) 약점은 잔존. 게임 처방은 알리송(Balanced)과 분리(Defend) 유지.','player_game_stats FC27(2026-08-31); fotmob_season_stats; fotmob_traits(keepers 6지표); player_duties id=40(모나코전 통제비교); squad_entries id=90(프리시즌 4경기); player_status(계약 2031-06-30) | 2026-09-12 갱신: player_game_stats FC25(2024-09-11)·FC26(2025-09-12 출시판, 2026-07-23 라이브)·FC27(2026-08-21/08-22/08-31/09-10); fotmob_detail_stats 2024/25 LaLiga·2025/26 PL(2026-08-21); fotmob_traits; player_tenures 2025-26; player_matches 26/27 5경기(친선) + 알리송(43) PL R1~R3; v_player_profile; player_market_values ~2026-08-01; player_status(2026-08-21 계약 2031-06-30); obs#152·188·451','서사 소스가 3티어급(transferhub·premierleague.com·espn·empireofthekop)으로 가설 지위다. No.1 지위 미해소(3방 충돌)로 시즌 내 출전 배분이 유동적이다. FotMob 세이브율 percentile 1은 이례적으로 낮아 원인(팀 상황·표본 소속) 불명확 — 그대로 개인 기량 저평가로 읽지 않는다. ⚠️ 2026-09-12: 공식전 실측 0 — 이라올라 체제 GK 판단은 프리시즌 4경기 좌표(모나코전 준통제 비교 1건)에 의존. FC27 PlayStyles 축소(Cross Claimer·Footwork 공란)는 예측판 결손 가능성 — 출시 후 재확인. GK attrs는 8속성만 수집. FC26 라이브(07-23)·FC27 08-21 행 attrs 미수집. 09-02 「발렌시아 추정」 오류 정정(리버풀 시즌). 2026/27 FotMob 미수집. 09-04 이후 경기(UCL 포함) DB 미수집.','2026-09-12','FotMob 지표만 보면 10경기 868분에 실점18·클린시트2·평점6.58로 눈에 띄는 시즌은 아니었다. 세이브율 percentile 1이 특히 낮게 나오는데 이는 팀 수비 맥락의 영향일 가능성이 있어 개인 기량 지표로 곧이곧대로 해석하기 어렵다.');
INSERT INTO player_evaluations VALUES(70,3,113,'C+ — 26/27 실측 CAM 2선발 포함 4경기 145분에서 평점이 7.1→6.9→6.1→6.0으로 단조 하락했고(뒤 둘은 교체 22·14분 표본 열위 감안), 2026-09-02 기준 CONFIRMED 발렌시아 임대 이적으로 prescriptions의 starter가 해제된 상태다(후임 무뇨스). 즉 26/27 리버풀 1군 축에서는 사실상 제외된 선수로 평가한다.','26/27 실측은 중앙 10번(CAM) — 선덜랜드 46분·렉섬 63분 두 선발 모두 lineup_pos=CAM. 과거 서사(우측·10번·중앙 미드 모두 가능하다는 유틸리티 주장)와 달리 이라올라가 실제로 준 자리는 비르츠의 백업 10번(Opta Analyst 2026-08-12)이다. 좁은 공간의 정교함과 라인 브레이킹 패스가 강점으로 지목되나(TFA 24/25, 슬롯 체제 표본), 7년 전(2019/20) 자료는 정반대 서술(우측 터치라인형)이라 시기 혼입에 주의.','FC27 fut.gg 세부(29속성, AcceleRATE Controlled): 민첩성90·균형감각90·시야78·짧은패스78로 좁은 공간 기술은 우수하나 힘33·점프48·체력51로 피지컬은 약점. FotMob AM/윙어군 percentile: 터치95(최상급)·기회창출6(매우 낮음)·득점39. 볼 소유·터치는 많으나 창출력은 이 표본에서 저조.','fotmob_season_stats(2025/26): 5경기 1선발 110분, 0골 0도움, 평점6.37 — 출전 기회 자체가 제한적이었던 시즌으로 보인다.','MEDIUM(교차 투영 — 실측 아님). 25/26 에메리 빌라 임대 277분 기록이 있으나(duties에 언급) 이는 다른 체제 표본이라 여기서는 근거로 재사용하지 않는다.','LOW-MEDIUM(교차 투영 — 실측 아님). 스피드가 약점으로 지목되는 프로필이라 알론소 체제의 다이내믹한 요구에 완전히 맞물리기 어려울 수 있다.','LOW-MEDIUM(실측·duties 근거). 태도(조기 복귀·개인 훈련, 「eagerness to show himself」)는 감독이 직접 인정했으나 시스템 적합은 열려 있다 — 이라올라는 빠르고 다이내믹한 와이드 선수를 선호하는 경향인데 엘리엇은 스피드가 약점으로 지목된다. 좌표 실측 0(45분+ 조건 미충족)이라 커널 적합 산출 불가, cam_classic10/cam_halfwinger 중 어느 쪽인지도 미확정. 2026-09-02 발렌시아 임대 CONFIRMED로 26/27 리버풀 실전 기회 자체가 사실상 종료됐다.','player_game_stats FC27(2026-08-31); fotmob_season_stats(2025/26); fotmob_traits(AM/wingers 6지표); player_duties id=99(체제 4중 혼입 경고 포함); prescriptions id=453(fc26:opt:RM, 2026-09-02 CONFIRMED 이적으로 starter 해제 갱신); squad_entries id=94(프리시즌 2경기)','⛔ 좌표 실측 0, 체제 4중 혼입(블랙번 임대·슬롯 24/25·에메리 빌라 임대 25/26·이라올라 26/27) 중 셋은 이 평가에서 배제했다. This Is Anfield 403 차단으로 해당 인용은 검색 요약 등급. ⭐ 2026-09-02 발렌시아 임대 CONFIRMED(prescriptions rationale에 기록)로 이 평가 자체의 유효 기간이 짧을 수 있음을 명기한다.','2026-09-02','FotMob 지표 기준 2025/26은 5경기 110분에 그친 제한적 시즌이었고(평점6.37), AM/윙어군 대비 터치는 최상급(95퍼센타일)이나 기회창출은 6퍼센타일로 매우 낮아 볼 소유 대비 생산성 연결이 약했던 것으로 보인다.');
INSERT INTO player_evaluations VALUES(71,3,69,'데이터 부족 + 결정적 제약 — 26/27 취업허가 미달로 리버풀 출전이 애초에 불가능한 상태다(duties confidence에 명기). 프리시즌 실측(4경기 305분, 평점6.62)과 커널 적합(cb_bpd/Aggressive 0.925)은 존재하나 시즌 중 실전 기여를 기대할 수 없는 선수라 등급을 매기지 않는다.','전방지향 센터백 — 198cm 장신, ''전개되기 전에 공격을 차단하는'' 선제형 서사. 공중볼 지배(오픈플레이·세트피스 양방향)와 장신 대비 리커버리 스피드가 강점으로 거론된다. 실측(모나코전 45분 선발, 평점6.7) tool_x 72.4로 RCB 슬롯(x=63)보다 우측 — 우측 CB 배치 서사와 정합, 3-5-2 중앙 CB 주장은 이 표본에서 기각됐다.','FC27 게임스탯(2026-09-01 수집, 6스탯만): OVR59·패스41·드리블41로 매우 낮은 게임 능치 — 유스 등급 반영으로 보인다. attrs 세부 미수집. fotmob_traits 데이터도 0건.','fotmob_season_stats: 12경기 11선발 897분, 1도움, 퇴장1회 — 출전 자체는 있었으나 (아마도 임대·하부팀 표본) 세부 지표 없음. 실측 1경기(모나코전) 기준 태클3·클리어3·패스24중23성공으로 안정적 패스 성공률을 보였다.','LOW-MEDIUM(교차 투영 — 실측 아님). 공중볼 지배·전방지향 차단 성향은 에메리의 라인 관리와 결이 맞을 수 있으나 실측 기반이 아니다.','LOW-MEDIUM(교차 투영 — 실측 아님). Aggressive 포커스(스텝업 요격)는 알론소의 하이라인 요구와 부합할 가능성이 있으나 근거는 가설 수준이다.','MEDIUM(실측·duties 근거, 단 출전 불가 전제 하). cb_bpd/Aggressive 0.803(2위 Build-Up 0.726, Δ0.140으로 노이즈 밖) — ''전방지향·선제 차단'' 서사가 Aggressive 포커스와 정합. 다만 ⛔ 26/27 취업허가 미달로 리버풀 출전이 불가능하다는 별건 제약이 있어(duties 명시), 이 적합도가 실전에 반영될 여지가 없다.','player_game_stats FC27(2026-09-01, 6스탯만, attrs 미수집); fotmob_season_stats; player_duties id=36(모나코전 실측); squad_entries id=92(프리시즌 4경기); ⛔ fotmob_traits 0건','⚠️ 저신뢰 — 전용 필름 분석 0건(서브스택 1건·Tribuna 블로그 1건·구단 팬포럼 인용이 전부). 인용된 인터셉트 수치(6/90 등)는 CB 기준선(~1.5) 대비 비현실적이라 기록에서 배제했다. ⛔ 결정적으로 취업허가 미달로 26/27 리버풀 출전 자체가 불가하다 — 이 평가는 스쿼드 데이터 완결성을 위해 작성하되 실전 가치는 사실상 0에 가깝다.','2026-09-02','FotMob 세부 지표(fotmob_detail_stats·fotmob_traits)가 0건이라 독립적 서술형 평가를 구성할 데이터가 없다. season_stats만 보면 12경기 11선발 897분·퇴장1회로 출전 자체는 있었으나 소속·리그 맥락이 DB에 명확히 표기되어 있지 않다.');
INSERT INTO player_evaluations VALUES(72,3,112,'데이터 다소 부족, 유망주급 — 시니어 공식전 실측은 3경기 180분(평점 7.8/6.3/6.5)뿐이나 선덜랜드전 13분 만의 선제골(클럽 시니어 데뷔골)이 인상적이다. 다만 브리스톨 시티·볼프스부르크가 시즌 임대를 문의 중이라는 상충 사실이 있어 26/27 정규 축으로 모델링하기 이르다.','왼발잡이 우측 인버티드 윙어 — U21 등록 포지션도 RW, 실측 lineup_pos도 선덜랜드·리즈 둘 다 RM으로 일관. 아카데미는 ''창의적·공격적 미드필더''로 규정하며 커티스 존스와 스타일 비교. 선덜랜드전 선제골은 응구모하→엘리엇→모리슨 역습에서 우측→안쪽 컷인→파포스트 마무리로, 서사(인버티드 윙어)를 구체 패턴으로 뒷받침한다.','유스 레벨 득점력 검증됨(25/26 PL2 18경기 14골, 23/24 U18 11골). FotMob AM/윙어군 percentile: 득점98(매우 높음, 표본 극소 주의)·기회창출60·수비적행동3(매우 낮음)·공중볼4. 즉 순수 마무리형·비수비형 프로필.','fotmob_season_stats: 1경기 21분, 평점6.45 — 시니어 공식전 표본이 극히 얇다(1경기). player_duties에 기록된 3경기 180분(프리시즌+데뷔골 포함)이 season_stats보다 최신·포괄적일 수 있어 두 수치가 정확히 일치하지 않는다.','LOW-MEDIUM(교차 투영 — 실측 아님). 인버티드 윙어 프로필 자체는 여러 체제에서 통용되나 근거가 전무해 판단을 보류에 가깝게 둔다.','LOW-MEDIUM(교차 투영 — 실측 아님). 근거 부족.','MEDIUM(실측·duties 근거, 단 불확실성 큼). 실측·클럽 등록·본인 발언이 전부 ''우측 인버티드''로 일치하고(「우측 옵션이 좀 부족하다는 걸 모두 안다」 본인 인용), 살라 이탈로 비어 있는 우측 후보로 언급된다. 좌표 실측 0이라 커널 적합 산출은 불가(game_role_implication 보류 수준). ⚠️ 임대 문의가 진행 중이라 26/27 가용성 자체가 불확실 — 감독 발언은 매체 해석뿐이고 직접 인용은 확보되지 않았다.','fotmob_season_stats; fotmob_traits(AM/wingers 6지표); player_duties id=105(선덜랜드 데뷔골 서사); squad_entries id=95(프리시즌 3경기, wm_winger/Attack 0.706); ⛔ player_game_stats(FC26/27) 0건','MEDIUM — 전술 블로그 전용 리포트 0건(TFA·BTL 미커버), 감독 직접 발언 0건. 신장 표기 불일치(SofaScore 170 vs Wikipedia 180), 국적 표기 혼동 위험(잉글랜드 태생 북아일랜드 대표)을 교차 확인했다고 duties에 명시됨. ⚠️ 임대 문의 진행 중이라 26/27 정규 전력 여부가 유동적이다.','2026-09-02','FotMob 지표 자체는 표본 극소(시니어 1경기 21분)라 독립적 결론을 내리기 어렵다. AM/윙어군 percentile상 득점98은 눈에 띄나 표본 크기를 감안하면 통계적 노이즈일 가능성이 크다.');
INSERT INTO player_evaluations VALUES(73,3,70,'B- — 오버래핑 레프트백으로 프리시즌 3경기(149분, 평점6.57)에서 자리를 잡았고 커널 적합 fb_wingback/Balanced(0.836)이 서사(오버랩·크로스·측면 과부하)와 방향이 일치한다. 다만 26/27 잔류 여부에 소스 충돌(4~6월 잔류 → 8월 이탈설)이 있었고, FotMob 2025/26 시즌 출전은 18경기 중 6선발·637분으로 백업 롤에 머물렀다. ⭐[2026-09-12 갱신] B- 유지. PL 26/27 3라운드 중 공식전 출전은 08-29 포레스트전 교체 19분 1회(평점 6.9, 어시스트 1)뿐이고 LB 선발은 3경기 모두 케르케즈(90·71·90분) — 백업 지위 확정. FC27 OVR 76(2026-09-10 예측판)은 FC26 시즌말(2026-07-23) 77 대비 −1. 시장가치 2026-06-01 €12.28M(로마) → 08-01 €9.95M 하락, 계약 2027-06-30.','오버래핑 레프트백 — ''넓고 높게'' 서며 오버랩·언더랩 모두 가능, 인버트하지 않는다는 서사. 이라올라 체제 풀백 브리프도 인버트가 아니라 오버랩(윙어+풀백 측면 과부하, 풀백 전진 오버랩). 실측(모나코전 59분, 평점6.2) tool_x 19.6으로 ''넓게''는 확인되나 avg_x 42.1(중간 높이)로 같은 경기 프림퐁(우, 53.4)보다 낮아 ''높게''는 이 표본에서 확인되지 않는다. ⭐[2026-09-12] PlayStyles: FC25 출시판(2024-09-13) Rapid 1개 → FC26 출시판(2025-09-12) 공란 → FC27(09-10) 공란. AcceleRATE Controlled(FC25·FC26 출시판). 크로스 81은 FC25·FC26 출시판 동일 — 「엘리트 크로스」 서사와 게임 속성은 정합하나 실측(모나코전 키패스 0, FotMob 2025/26 Serie A 크로스 성공률 16.3%·백분위 8)과의 충돌은 지속. 공격성 80·스탠딩 태클 76→77·헤딩 55→66(FC25→FC26 출시판).','FC27 게임스탯(6스탯만, attrs 미수집): OVR76·수비74·패스73로 균형형 풀백. 엘리트 크로스가 핵심 무기로 서사에서 지목되나 실측 표본(모나코전)에서는 키패스 0으로 확인되지 않았다. FotMob 풀백군 percentile: 기회창출77·득점78(높음)·수비적행동26·공중볼20(낮음) — 공격 가담 위주, 공중전은 약점. ⭐[2026-09-12] OVR 궤적: FC25 출시(2024-09-13) 77(PAC80 SHO57 PAS74 DRI75 DEF73 PHY78) → FC26 출시(2025-09-12) 77(78/57/75/75/74/72; 출시판 간 PAC−2·PHY−6·DEF+1) → FC26 시즌말(sofifa 2026-07-23) 77(78/57/75/75/75/72) → FC27 출시 예측(fut.gg 2026-09-10) 76(78/56/73/73/74/72; FC26 시즌말 대비 OVR−1·PAS−2·DRI−2·DEF−1). 세부 FC25→FC26 출시판: 체력 77→69·힘 77→69 하향, 헤딩 55→66 상향. FC26 라이브(07-23)·FC27 행은 attrs 미수집. 강점: 크로스 81·공격성 80. 약점: 피지컬 종합 하향세, 공중볼(FotMob 풀백군 백분위 20).','fotmob_season_stats(2025/26): 18경기 6선발 637분, 평점6.43, 경고1 — 시즌 내내 백업으로 활용된 수치. 선발 비중이 낮아(6/18) 주전 경쟁에서 밀린 시즌으로 보인다. ⭐[2026-09-12] FotMob 2025/26 Serie A(로마, 18경기 637분) 상세: 기회창출 4(p90 백분위 23)·크로스 성공 7(성공률 16.3%, 백분위 8)·xA 0.42·듀얼 승률 47.6%(백분위 26)·수비 액션 5.51/90(p90 백분위 57). 2024/25 PL(리버풀): 크로스 성공 14(p90 백분위 93)·xA 2.32(p90 95)·기회창출 16(p90 91) — 로마 시즌에 공격 산출 급락. 09-02 이후: 09-04 입스위치전 결장(match_player_reports 없음). DB 26/27 실측 6경기 279분 평점 6.62(v_player_profile). 2026/27 FotMob 시즌·상세 미수집.','MEDIUM(교차 투영 — 실측 아님). 오버래핑형 풀백은 에메리의 측면 활용과 결이 맞을 수 있으나 근거는 없다.','MEDIUM(교차 투영 — 실측 아님). 근거 없음.','MEDIUM(실측·duties 근거, 단 노이즈 구간). fb_wingback/Balanced 0.741(2위 fb_fullback/Balanced 0.727, Δ0.013 노이즈 구간)이나 서사가 wingback을 지지해 커널 선택과 방향이 일치한다는 판단. ''높게'' 서는 정도는 실측이 부분 반박(중간 높이)하므로 Attack 계열로의 상향 근거는 없다. 정량 근거가 2019/20 올림피아코스 자료로 6년 낡았고, 로마 25/26 감독 평가(''다재다능하지 않다'')와 TFA의 오버랩·언더랩 겸용 주장이 상충한다. ⭐[2026-09-12] MEDIUM 유지. 리버풀 실측: PL 08-29 포레스트전 19분 교체(평점 6.9, 패스 13/13, 어시스트 1, 참고 fit 0.921 — 분 미달로 집계 제외, report 28). 공식전 3라운드 LB 선발은 전부 케르케즈. squad_entries fb_wingback/Balanced 0.836(프리시즌 3경기 149분). obs#409: 포레스트전 70:50 케르케즈→치미카스 교체는 프림퐁→흐라벤베르흐와 함께 소보슬러이 RB 이동을 동반한 3중 교체의 일부. obs#492에서 케르케즈 오버랩→학포 인사이드 좌측 구조가 확인됐으므로 오버래핑형 치미카스는 역할상 대체 가능하나 실측 19분뿐이라 상향 근거 없음.','player_game_stats FC27(2026-08-31, 6스탯만); fotmob_season_stats(2025/26); fotmob_traits(fullbacks 6지표); player_duties id=37(모나코전 실측); squad_entries id=91(프리시즌 3경기); player_status(계약 2027-06-30) | 2026-09-12 갱신: player_game_stats FC25(2024-09-13)·FC26(2025-09-12 출시판, 2026-07-23 라이브)·FC27(2026-08-22/08-31/09-10); fotmob_detail_stats 2024/2025 PL·2025/2026 Serie A(2026-08-21); fotmob_traits; player_matches 26/27 6경기; match_player_reports r3·8·9·10·19·28; v_player_profile; player_market_values ~2026-08-01; player_status(2026-08-21); obs#409·#492','서사 소스 3티어급(TFA·팀 사이트 등) — 가설 지위. 정량 근거 6년 낡음, 26/27 잔류 여부 소스 충돌(단 실측상 08-09 출전 확인으로 현재 스쿼드 내 존재는 확정). ⚠️ 2026-09-12: 26/27 공식전 표본 19분 1회(fit 산출 불가). FC26 라이브(07-23)·FC27 3행 attrs·PlayStyles 미수집 — PlayStyles 변화(Rapid 소멸)는 FC25→FC26 출시판 사이만 확인되고 FC27 공란은 결손일 수 있음. FC27은 출시 전 예측판(rating-predictions). 2026/27 FotMob 시즌·상세 미수집. 09-04 입스위치전 이후 경기(UCL 포함) DB 미수집.','2026-09-12','FotMob 지표 기준 2025/26은 18경기 중 6선발에 그친 백업 시즌이었다(평점6.43). 풀백군 대비 공격 기여(기회창출77·득점78)는 상위권이나 수비적 행동(26퍼센타일)·공중볼(20퍼센타일)은 약점으로 확인된다.');
INSERT INTO player_evaluations VALUES(74,3,114,'B — 프리시즌+PL 개막전 5경기(260분)에서 좌우 양측면을 소화했고, 유일한 공식전 표본(2026-08-23 뉴캐슬 PL 개막전, 우측 선발 63분)을 포함해 우측 3경기(170분, 평점6.86)가 주 사이드로 채택됐다(squad_entries). FC27 OVR 75(Δ+7, fut.gg 상승폭 최대급)로 게임 평가도 상승세다. 다만 압박·수비 임무 서술이 어느 소스에도 없어(이라올라 체제 1차 자격요건 공백) 완전한 체제 적합 판단은 이르다. ⭐[2026-09-12 갱신] B → B- 하향. PL 26/27: R1 뉴캐슬 RM 선발 63분(6.37) 후 무뇨스와 직접 교체(obs#317), 무뇨스가 27분 만에 PK 유도(obs#308)로 RM 경쟁 열위; R2 포레스트 교체 19분(6.5); R3 입스위치 결장. FotMob 2026/27 PL 2경기 1선발 82분 평점 6.24. 게임 평가는 반대로 상승 — FC27 OVR 75(FC26 출시 68 대비 +7, FC26 시즌말 72 대비 +3). 시장가치 2026-06-01 €29.84M → 09-01 €21.76M 하락.','좌측이 본거지인 직진형 와이드 어태커, 이라올라가 양측면 소화를 육성 방침으로 검증 중. 실측: 좌측 선발 2경기(선덜랜드·리즈, 프리시즌) 평점6.2·6.5, 우측(렉섬 교체+코모+뉴캐슬 PL개막전 선발) 3경기 평점 최고 7.2 포함 평균6.86. 최고 평점(렉섬전 7.2)이 유일한 우측 배치였고 결승골(75분)도 그 경기에서 나왔으나 표본 1경기·교체 출전 교란이 있어 ''우측이 더 낫다''로 단정하지 않는다. ⭐[2026-09-12] PlayStyles: FC25 해당 버전 카드 없음(결손) → FC26 출시판(2025-09-12) Technical·Quick Step → FC27(09-10) Trickster·Quick Step(Technical→Trickster). AcceleRATE Explosive(FC26·FC27). Quick Step·Explosive·가속 92는 실측 최고속도 33.2km/h(26/27 PL 백분위 58)·드리블 성공률 69.8%(25/26 백분위 100)와 정합; Trickster는 1v1 고립형 드리블 볼륨 서사(duties 107)와 부합. 반면 이라올라 1차 요건인 압박은 FotMob 수비 액션 25/26 백분위 13·26/27 백분위 2, 게임 차단력 36·공격성 39로 게임·실측 모두 약점.','FC27 fut.gg 세부(29속성, AcceleRATE Explosive): 가속92·질주속도89 최상급, 민첩성87·균형감각88·드리블80 우수. 헤딩정확도38·차단력36·공격성39로 피지컬 대결·수비 관련은 약점. FotMob AM/윙어군 percentile: 기회창출82·터치77 상위권, 공중볼2·수비적행동5로 최하위권 — 순수 스피드형 어태커 프로필. ⭐[2026-09-12] OVR 궤적: FC25 카드 없음(결손, 2008년생) → FC26 출시(2025-09-12) 68(PAC90 SHO64 PAS59 DRI72 DEF35 PHY53) → FC26 시즌말(sofifa 2026-07-23) 72(90/66/64/77/35/53; POT 88) → FC27 예측(2026-09-10) 75(90/71/68/79/37/49; 시즌말 대비 +3, FC26 출시 대비 +7). 세부 FC26 출시판→FC27: 공격 위치선정 64→76·드리블 71→80·짧은 패스 57→69·크로스 64→72·결정력 65→72·침착 71→76 상향; 힘 54→44·점프 61→56 하향. 강점: 가속 92·질주 89·균형 88·민첩 87. 약점: 힘 44·헤딩 38·차단력 36 — 피지컬 대결·수비 관여 최저.','fotmob_season_stats(2025/26): 19경기 5선발 551분, 2골 1도움, 평점6.67 — U16 잉글랜드 대표에서는 드리블 12.91/90(성공률64%)로 압도적 1v1 고립형 볼륨을 기록(Wyscout 10.98/90 대비도 높음), 다만 이는 대표팀 레벨 지표라 클럽 레벨과 직접 비교하지 않는다. ⭐[2026-09-12] FotMob 2026/27 PL(2026-09-12 수집, 2경기 1선발 82분): 평점 6.24, 슛 1, 터치 42.8/90(백분위 27), 드리블 성공 2(p90 백분위 82), 수비 액션 3(백분위 2), 최고속도 33.2km/h(58). 2025/26 PL(19경기 551분): 드리블 성공 30(p90 100)·성공률 69.8%(100)·기회창출 16(p90 95)·슛 16(p90 84)·수비 액션 30(13). 09-02 이후: 09-04 입스위치전 출전 없음(match_player_reports 없음). DB 26/27 실측 7경기 309분 평점 6.65(v_player_profile), PL 2경기 82분 6.44.','MEDIUM(교차 투영 — 실측 아님). 직선적 침투형 와이드 플레이어는 에메리의 측면 활용에 맞을 여지가 있으나 근거 없음.','MEDIUM-HIGH(교차 투영 — 실측 아님). 빠르고 다이내믹한 와이드 선수를 선호하는 체제라면 가속력·질주속도 최상급 프로필이 부합할 가능성.','MEDIUM(실측·duties 근거, 단 압박 축 공백). wm_winger/Attack 커널 적합 — 좌측(x=26) 0.837(n=2, 90분) vs 우측(x=77) 0.812(n=3, 170분). ⭐ 주 사이드를 우측으로 채택한 근거는 ⑴유일한 공식전 표본이 우측(뉴캐슬 PL개막전 선발) ⑵분량도 우측이 큼(170분 vs 90분) — 둘 다 같은 방향을 가리켜 확정. 다만 ⛔ 이라올라 체제 1차 자격요건인 압박 가담 서술이 어느 소스에도 없어(duties 명시) 시스템 적합의 핵심 축 하나가 공백 상태다. ⭐[2026-09-12] MEDIUM → MEDIUM-LOW. 리버풀 실측: PL R1 뉴캐슬 RM 선발 63분(6.37, 슛 1·찬스 0, report 23) → 무뇨스와 직접 교체(obs#317), 무뇨스 PK 유도(obs#308); R2 포레스트 좌측 교체 19분(6.5, 참고 fit 0.750, 분 미달); R3 입스위치 결장. obs#330: 무뇨스 주 사이드가 RM으로 재판정돼 RM 선발 경쟁 열위. squad_entries wm_winger/Attack 0.812(우측 3경기 170분, prescriptions 408). 이라올라 양측면 원칙(obs#455)에 직접 열거된 점은 긍정. 압박 축 공백(duties 107)은 FotMob 26/27 수비 액션 백분위 2로 수치상 확인.','player_game_stats FC27(2026-08-31); fotmob_season_stats(2025/26); fotmob_traits(AM/wingers 6지표); player_duties id=107(육성/컨텍스트)·id=171(뉴캐슬 실측); prescriptions id=407(measured:side:L)·id=408(measured:side:R, starter=1); squad_entries id=129(우측 채택, 5경기) | 2026-09-12 갱신: player_game_stats FC26(2025-09-12 출시판, 2026-07-23 라이브)·FC27(2026-08-21/08-22/08-31/09-10) — FC25 카드 없음; fotmob_season_stats·fotmob_detail_stats 2025/26·2026/27 PL(2026-08-21·09-12); fotmob_traits; prescriptions 407·408; squad_entries 129; player_matches 26/27 7경기; match_player_reports r23·28; player_market_values ~2026-09-01(€21.8M); player_status(2026-09-12 계약 2028-06-30); obs#308·317·330·455','MEDIUM — 좌우 표본이 각각 얇다(좌 n=2·90분, 우 n=3·170분 중 프리시즌 2경기 포함). BTL·TFA 리포트는 25/26 슬롯 체제·U18/U21 자료라 이라올라 축 근거로 직접 쓰지 않음(불변규칙 7). 주발 확인 실패로 방향성 주장에 주의가 필요. ⚠️ 2026-09-12: PL 표본 2경기 82분(1선발) — 26/27 백분위는 82분 기준이라 변동 큼. FC25 결손으로 3버전 궤적 불가(FC26 출시→FC27 2점). FC27 예측판. FC26 라이브(07-23)·FC27 08-21 행 attrs 미수집. 시장가치 06→09월 하락은 출전 감소와 동행. 압박 임무 서사 여전히 0건. 09-04 이후 경기(UCL 포함) DB 미수집.','2026-09-12','FotMob 지표 기준 2025/26은 19경기 중 5선발에 그쳤으나(551분) 2골 1도움·평점6.67로 나쁘지 않은 임팩트를 남겼다. AM/윙어군 대비 기회창출(82퍼센타일)·터치(77퍼센타일)는 상위권인 반면 수비적행동(5퍼센타일)·공중볼(2퍼센타일)은 최하위권으로, 순수 공격 특화형 프로필임이 뚜렷하다.');
INSERT INTO player_evaluations VALUES(75,3,116,'B — 이번 LIV 9명 중 감독 직접 발언·실측·매체가 셋 다 같은 방향을 가리키는 유일한 사례(duties adherence HIGH). 프리시즌 3경기(135분, 평점7.1)로 스쿼드 최상급 실측 평점을 기록했고 fc26:opt:RDM 최적 스쿼드 시트에 선발(starter=1)로 반영됐다(fit_sim 0.888). 다만 좌표 실측이 없어 커널 적합의 최종 확정은 유보 상태다. ⭐[2026-09-12 갱신] B 유지(조건부). PL 26/27 3라운드 중 2회 교체 출전(08-29 포레스트 13분 6.7·09-04 입스위치 12분 6.6) — 로테이션 멤버로는 기용되나 선발 0. FotMob 2026/27 PL 2경기 19분 평점 6.36. FC27 OVR 67(FC26 시즌말 65 대비 +2, FC25 출시 61부터 매 버전 상승). 프리시즌 평점 7.1(squad_entries)의 근거는 유지되나 공식전 유효 좌표 표본은 여전히 0. 시장가치 2026-07-01 €9.92M → 09-01 €7.17M 하락.','6번/8번 하이브리드 피벗 — 본인 규정 그대로 렉섬전 RDM 선발·리즈전 LDM 선발로 좌우 피벗을 모두 소화. 이라올라가 요구한 추가 임무는 ''볼 상실 후에도 10번·9번·배후 볼을 시야에 두는 것''(본인 인용). 프리시즌 전체 파이널서드 침투 패스 23회로 팀 1위, 동시에 태클·인터셉트·리커버리 등 수비 산출도 병존(리즈전 수비 기여 팀 3위) — 배급형이면서 수비 기여가 같이 나오는 유형. ⭐[2026-09-12] PlayStyles: FC25 출시판(2024-09-14) 공란 → FC26 출시판(2025-09-12) 공란 → FC27(09-10) 공란 — 3버전 모두 0(실제 0인지 결손인지 미구분). AcceleRATE Controlled(FC25·FC26). 세부 궤적은 서사와 정합: 긴 패스 62→65·짧은 패스 65→68·시야 60→64(FC25→FC26 출시판), FC27 6종합 DEF 60(FC26 시즌말 53 대비 +7)·PHY 58(+5)로 「배급+수비 산출 병존」(duties 104) 방향으로 게임 평가 이동. FotMob 26/27 상세 미수집이라 실측 백분위 대조는 25/26 traits(기회창출 73·수비 액션 14)만 가능.','FC27 게임스탯(6스탯만): OVR67(Δ+3)·수비60·패스66로 낮은 편이나 유스 등급 반영으로 보인다. FotMob 미드필더군 percentile: 기회창출73·슛시도70·터치62 상위권, 공중볼8·수비적행동14로 피지컬 대결은 약점. ⭐[2026-09-12] OVR 궤적: FC25 출시(2024-09-14) 61(PAC67 SHO52 PAS58 DRI67 DEF50 PHY51) → FC26 출시(2025-09-12) 64(67/54/61/69/52/52; 출시판 간 +3) → FC26 시즌말(sofifa 2026-07-23) 65(67/57/62/69/53/53; POT 84) → FC27 예측(2026-09-10) 67(67/57/66/70/60/58; 시즌말 대비 +2, PAS+4·DEF+7·PHY+5). 세부 FC25→FC26 출시판: 커브 44→55·중거리 46→52·스탠딩 태클 52→56·긴 패스 62→65. FC26 라이브·FC27 attrs 미수집. 강점: 매 버전 상승(61→64→65→67), FC27 수비·피지컬 종합 급등. 약점: 페이스 67 정체, OVR 67은 스쿼드 최하위권.','fotmob_season_stats: 6경기 0선발 21분 — 시니어 출전은 극소이며, 위 duties 실적(파이널서드 패스 23회 등)은 U21/프리시즌 표본으로 season_stats와 별개다. ⭐[2026-09-12] FotMob 2026/27 PL(2026-09-12 수집): 2경기 0선발 19분 평점 6.36. 2025/26 PL 6경기 21분(시니어 표본 무의미). fotmob_detail_stats 0행(미수집). DB 26/27 실측 8경기 297분 평점 6.84(v_player_profile; 친선 6 + PL 교체 2). 09-02 이후: 09-04 입스위치 12분 교체 RDM 6.6(맥알리스터 대체, hp 5 그리드 무효, report 32); 08-29 포레스트 13분 6.7·패스 20/18·태클 2(참고 fit 0.581, 분 미달, report 28).','MEDIUM(교차 투영 — 실측 아님). 배급+압박 겸용 6번/8번 하이브리드는 에메리 체제의 중원 구조에도 통용될 수 있는 범용 프로필이나 근거는 없다.','MEDIUM(교차 투영 — 실측 아님). 근거 없음.','MEDIUM-HIGH(실측·duties 근거, 단 좌표 실측 0). dm_dlp/Roaming 0.888(squad_entries·fc26:opt 공통) — 프리시즌 3경기 135분 평균평점 7.1로 스쿼드 최상급. 감독 1차 발언 확보가 결정적 근거: 「볼을 아주 잘 다루고 매우 침착하며 상황을 잘 읽는다... 점프 타이밍이 매우 좋다」(2026-07-29 LFCTV). 다만 좌표 실측이 없어(45분+ 조건 미충족) 커널 적합은 시사 수준이며 확정 아님. 반대 근거도 존재(「PL 38경기를 선발로 뛸 준비는 되지 않았다」). ⭐[2026-09-12] MEDIUM-HIGH → MEDIUM(하향, 실측 근거 약화). 리버풀 실측: PL 3라운드 중 2회 교체(13분·12분, 합 25분) — 유효 좌표 표본(45분+·hp15+) 여전히 0. 참고 fit 포레스트전 0.581(report 28)은 squad_entries dm_dlp/Roaming 0.888(프리시즌 3경기 135분 평점 7.1)과 괴리 크나 분 미달이라 결론 아님. fc26:opt:RDM starter=1(prescriptions 452)은 커널 총합 최적화 산출로 실제 선발 서열과 다름. 감독 1차 발언(duties 104)은 유효하나 반대 근거 「PL 38경기 선발 준비 안 됨」이 초반 기용 패턴(교체 전용)과 정합.','player_game_stats FC27(2026-08-31, 6스탯만); fotmob_season_stats; fotmob_traits(midfielders 6지표); player_duties id=104(감독 1차 발언 포함); prescriptions id=452(fc26:opt:RDM, starter=1); squad_entries id=93(프리시즌 3경기); player_status(계약 2030-06-30) | 2026-09-12 갱신: player_game_stats FC25(2024-09-14)·FC26(2025-09-12 출시판, 2026-07-23 라이브)·FC27(2026-08-22/08-31/09-10); fotmob_season_stats 2025/26·2026/27 PL(2026-08-21·09-12); fotmob_traits; prescriptions 452; squad_entries 93; player_matches 26/27 8경기; match_player_reports r3·20·28·32; v_player_profile; player_market_values ~2026-09-01; player_status(2026-09-12 계약 2030-06-30); player_duties 104','HIGH-MEDIUM(감독 1차 발언 확보가 결정적, duties 자체 평가). 전용 전술 블로그 스카우트 리포트 0건(TFA·BTL·Scouted Football 미커버), 전용 유튜브 분석 0건. 팀 1위 지표(파이널서드 패스23)는 This Is Anfield 집계인데 본문 403이라 검색 요약 경유 2차 등급. ⚠️ 2026-09-12: 공식전 25분(교체 2회, 그리드 무효) — 커널 적합 확정 불가 지속. fotmob_detail_stats 미수집(백분위 대조 불가). FC26 라이브·FC27 attrs 미수집 — 세부 변화는 FC25→FC26 출시판 사이만. PlayStyles 3버전 공란은 실제 0인지 미수집인지 예측판에서 구분 불가. FC27 예측판. 09-04 이후 경기(UCL 포함) DB 미수집.','2026-09-12','FotMob 시니어 지표는 6경기 21분으로 사실상 무의미한 표본이다. 다만 미드필더군 percentile(기회창출73·슛시도70)은 제한된 출전 시간 내에서도 준수한 기록을 보였음을 시사한다.');
INSERT INTO player_evaluations VALUES(76,4,148,'A — 26/27 라리가 4경기(360분) 실측 평점 6.85로 09-02 갱신 시점(3경기 평균 7.3)보다 표본이 늘며 소폭 하락(R3 입스위치·R4 아틀레틱 클럽 반영, fit_sim 0.9478). FC27(09-10 EA 공식) ovr 88으로 FC26과 동일 — 스쿼드 최고 GK 지위 유지. 백5 뒤 최종 차단자 역할은 그대로.','빌드업 +1로 내려오지 않는 전통형 시메오네 GK(알론소 GK와 정반대 축) — 09-02 판단 유지. FC27 신규: PlayStyles Far Throw·Far Reach·Rush Out+ 3종 확정(FC26은 미등록이었음) — 롱킥·긴 스로인·적극적 커버 반경이 EA 공식 특성으로 인정됨, 09-02 traits의 "롱빌드업 배급 가능" 서술과 정합.','25/26 클린시트 11(87%ile)·세이브율 70.8%(62%ile)·에러로 실점 0(100%ile). FC26 ovr 88·sho 90(반사). 약점: 26/27 R1 세이브 1회뿐이라 표본이 얇고 하이클레임 56%ile로 평범.','25/26 라리가 시즌 지표(fotmob_detail_stats, 08-21 pull 그대로 — 09-02 이후 신규 pull 없음): 클린시트 87%ile·세이브율 62%ile·롱볼 정확 85%ile 불변. 26/27 표본 확대: v_player_profile n=4(360분) 평균 6.85, prescriptions(kind=measured) fit_sim 0.9478·avg_rating 6.85·sample_n=4(2026-09-06 R3·R4 갱신분 반영) — 09-02 시점 n=3·avg 7.3에서 갱신.','MEDIUM — 에메리 GK는 백5 뒤 커버 범위·스위퍼 역할을 중시하는데 오블락의 스위퍼 클리어런스는 46%ile로 평범. 반사 능력은 최상급이라 순수 슈팅 저지력은 fit(교차 투영, 실측 아님).','LOW — 알론소 체제는 GK의 짧은 빌드업 개시자(+1) 역할을 요구하는데 오블락 duties는 ''내려오지 않는다''로 정반대축 — 구조적으로 어긋난다(교차 투영, 실측 아님).','MEDIUM — 이라올라는 하이라인 뒤 스위퍼 GK를 원하는데 오블락은 전통형에 가깝다. 반사 능력으로 일부 상쇄되나 라인 뒤 커버는 약점(교차 투영, 실측 아님).','player_duties(GK, 2026-27); prescriptions kind=measured(fit_sim 0.97, n=3, avg 7.3) 및 kind=measured:laliga-r1(fit_sim 0.943); squad_entries GK(fit_sim 0.943); fotmob_detail_stats 25/26·26/27; fotmob_traits keepers 6종; player_market_values 26-08 12.4M€ | 2026-09-11 갱신: player_game_stats(FC27, roster_date 2026-09-10, ovr 88·playstyles Far Throw/Far Reach/Rush Out+·weight 87kg 신규); prescriptions(kind=measured, id=409, n=4, avg 6.85, fit_sim 0.9478, 2026-09-06 R3·R4 갱신); v_player_profile n=4(360분); fotmob_detail_stats는 08-21 pull 그대로(신규 pull 없음)','26/27 표본 4경기(360분)로 09-02(3경기) 대비 확대됐으나 여전히 얇다. FC27 ovr은 FC26과 동일(88)이라 게임 능치 변화 없음 — playstyles만 신규 확정. fotmob_detail_stats는 갱신되지 않아 시즌 percentile은 09-02와 동일 근거.','2026-09-11','FotMob 지표만 보면 25/26 시즌 클린시트 87%ile·에러 0(100%ile)로 안정적 최종수문장이나 세이브율(62%ile)·하이클레임(56%ile)은 리그 GK 평균 수준. 26/27 데이터는 1경기뿐이라 트렌드 판단은 이르다.');
INSERT INTO player_evaluations VALUES(77,4,149,'C — 16세 유스 CB/RB. 09-02 이후 신규 실측·FC27 스탯 전무 — R1 45분 교체(평점 6.05) 출전이 여전히 전부다. FC27 player_game_stats(roster_date 2026-09-10)에 이 선수 행 자체가 없다(1군 로스터 미등재로 추정).','09-02 판단과 동일 — 백3 좌측 담당(Opta 라벨 RB, 실측 툴x 84.8은 우측). 신규 서사·player_duties 관찰 없음.','패스 정확도 100%(13/13, 소량 표본)지만 터치 24회로 관여가 극히 적었다. 파울 4회로 침착성 부족 신호.','FotMob 26/27 단 1경기(45분) 지표 불변(fotmob_detail_stats 08-21 pull 그대로, 신규 pull 없음): 듀얼 승률 33.3%(7%ile)·수비 액션 3회(3%ile). v_player_profile·prescriptions 모두 n=1(45분)로 09-02와 동일 — R2 이후 출전 기록 없음.','판단 근거 부족 — 데이터 최소(45분 1경기).','판단 근거 부족 — 데이터 최소(45분 1경기).','판단 근거 부족 — 데이터 최소(45분 1경기).','player_duties(RB, 2026-27 R1); fotmob_season_stats/detail_stats 26/27 1경기; prescriptions measured:laliga-r1(fit_sim 0.917); squad_entries FB | 2026-09-11 갱신 확인: player_game_stats에 FC27(roster_date 2026-09-10) 행 없음(1군 미등재 추정); v_player_profile·prescriptions(measured:laliga-r1) n=1 불변; player_duties 신규 행 없음 — 09-02 이후 데이터 증분 없음','16세 유스 선수, 45분 1경기가 전부인 표본은 09-02와 변화 없음. FC27 게임 스탯 미등록. 데이터 부족 — 지어내지 않음.','2026-09-11','FotMob 단일 경기 지표만 존재. 듀얼 승률·수비 액션 모두 하위권이나 경고 후 하프타임 교체(카드 관리성)라 경기력만으로 평가하기 어렵다.');
INSERT INTO player_evaluations VALUES(78,4,150,'B+ — 09-02 판단 유지. 26/27 R1 90분·평점 7.56, 클럽 공식전 2경기 평균 6.58(fit_sim 0.929, cb_bpd/Aggressive, n=2) — 09-06 R3·R4 갱신에도 표본·수치 변화 없음(이 두 경기에 포지션-순수 조건 미충족 경기 포함 추정). FC27(09-10 EA 공식) ovr 81로 FC26과 동일치 유지.','09-02 판단 불변 — 백3 중앙 rest-defense 조율축. FC27 신규: PlayStyles Aerial Fortress 확정(FC26 미등록) — 25/26 공중볼 승률 67.1%(83%ile) 실측과 정합. AcceleRATE Lengthy 유지.','25/26 시즌 공중볼 승률 67.1%(83%ile)·파울 유도(77%ile)로 안정적 CB. 약점: 25/26 롱볼 정확도 26%ile로 배급 다양성 부족.','FotMob 25/26 라리가 지표 불변(08-21 pull 그대로): 인터셉트 56%ile·듀얼 승률 84%ile·공중볼 83%ile. 26/27 표본은 여전히 n=2(166분) — 09-02 이후 증분 없음.','HIGH — 에메리 백라인은 조율축 CB를 원하는데 르노르망의 라인 스윙 축 역할이 정확히 부합. 공중볼·수비 지표 강점도 일치(교차 투영, 실측 아님).','MEDIUM — 알론소 CB는 빌드업 배급력을 더 요구하는데 롱볼 정확 26%ile로 다소 부족(교차 투영, 실측 아님).','MEDIUM — 이라올라 하이라인엔 스피드가 중요한데 르노르망 pac 66은 평범(교차 투영, 실측 아님).','player_duties(RCB); prescriptions measured(fit_sim 0.929, n=2, avg 6.58); fotmob_detail_stats 25/26·26/27; fotmob_traits CB 6종; player_market_values 26-08 24.4M€ | 2026-09-11 갱신: player_game_stats(FC27, roster_date 2026-09-10, ovr 81·playstyles Aerial Fortress 신규·accelerate Lengthy·weight 80kg); prescriptions(kind=measured, id=410) n=2·avg 6.58 09-02와 동일 확인; fotmob_detail_stats 신규 pull 없음','표본 2경기(166분)로 09-02 이후 변화 없음. FC27 ovr 81도 FC26 대비 변동 없어(fut.gg 표기 Δ-2는 FC26 출시판 대비이며 우리 FC26 시즌말판과는 동일치) 게임 능치 실질 변화는 playstyles 확정뿐이다.','2026-09-11','FotMob만 보면 안정적 수비형 CB 원형 — 수비 액션·듀얼은 강하나 볼 관여(터치 23%ile)와 롱볼 다양성은 낮다.');
INSERT INTO player_evaluations VALUES(79,4,151,'A- — 백3 우측이자 전진 배급의 주 출구. 09-06 R3·R4 갱신으로 표본이 3경기→4경기(360분)로 늘며 평균 평점이 7.62→7.34로 소폭 하락(fit_sim 0.893→0.8875, cb_bpd/Aggressive). R1 90분 평점 8.66(팀 최고)·어시스트 1은 불변. FC27(09-10 EA 공식) ovr 83으로 FC26과 동일.','09-02 판단 유지 — 빌드업 축 CB, 전진 패스·크로스필드 배급의 핵심 출구. FC27 신규: PlayStyles Long Ball Pass·Jockey·Anticipate 3종 확정(FC26 미등록) — Long Ball Pass는 09-02 "롱볼 정확도 70%(87%ile)" 실측과, Anticipate는 인터셉트 지표와 정합.','R1 정확패스 91(100%ile)·롱볼 정확도 70%(87%ile)·xA 0.21(93%ile). 25/26 시즌 chances created 94%ile·빅찬스 창출 97%ile로 CB치고 이례적 창조성. 약점: 25/26 dribbled past 5%ile·dispossessed 4%ile로 볼 뺏김 있고 공중볼 14%ile로 약함.','FotMob 25/26 라리가 지표 불변(08-21 pull 그대로): chances created 94%ile·assists 92%ile·수비 액션 16%ile. 26/27 v_player_profile·prescriptions(kind=measured, id=411)이 n=3→n=4(360분), avg_rating 7.62→7.34, fit_sim 0.893→0.8875로 갱신 — 09-06 R3(입스위치)·R4(아틀레틱) 반영분.','MEDIUM — 에메리는 빌드업 배급형 CB를 선호하나 수비 견고성도 요구하는데(교차 투영, 실측 아님) 한츠코의 수비 액션 16%ile은 우려 요소다.','HIGH — 알론소 체제는 CB의 전진 배급·라인브레이킹 패스를 핵심 축으로 쓰는데(교차 투영, 실측 아님) 한츠코의 창조성·전진성이 정확히 부합한다.','MEDIUM — 하이라인 뒤 커버 스피드가 필요한데 한츠코 pac 77은 준수하나 공중볼 약점(14%ile)이 걸림(교차 투영, 실측 아님).','player_duties(LCB); prescriptions measured(fit_sim 0.893, n=3, avg 7.62); fotmob_detail_stats 25/26·26/27; fotmob_traits CB; player_market_values 26-08 32.5M€ | 2026-09-11 갱신: player_game_stats(FC27, roster_date 2026-09-10, ovr 83·playstyles Long Ball Pass/Jockey/Anticipate 신규·accelerate Lengthy·weight 82kg); prescriptions(kind=measured, id=411, n=4, avg 7.34, fit_sim 0.8875, 2026-09-06 R3·R4 갱신 — 09-02 시점 n=3·avg 7.62에서 변경); v_player_profile n=4(360분)','표본 4경기(360분)로 09-02(3경기) 대비 확대. 평점 하락(7.62→7.34)은 표본 확대에 따른 자연스러운 평균 회귀로 판단되며 R1 단일경기 임팩트(8.66·어시스트)가 과대 반영됐던 것을 R3·R4가 조정한 것으로 해석한다. 단일 시즌 상승 추세일 수 있어 장기 표본 필요(09-02 판단 유지).','2026-09-11','FotMob 지표만으로도 ''창조적 CB'' 프로필이 뚜렷 — chances created·assists 90%ile 이상인 반면 defensive actions·aerials는 하위권으로 뚜렷한 트레이드오프.');
INSERT INTO player_evaluations VALUES(80,4,152,'C+ — 09-02 판단 유지. R1 57분 교체 평점 6.13 이후 신규 실측 없음. FC27(09-10 EA 공식) player_game_stats에서 club이 처음으로 "Atlético de Madrid"로 등록(FC26 최신판까지는 라요 바예카노 임대 표기였음) — 임대 복귀·1군 등록이 게임 데이터에 반영된 것으로 보인다. ovr 70으로 FC26(라요 소속판)과 동일치.','09-02 판단 유지 — 폭 담당 + 수비 복귀형 윙어. FC27에서 best_pos이 ST/LM/CAM(라요 시절)에서 LW로 재분류됨. FC27 상세 8속성·playstyles는 이 선수 행에 미수집(attrs·playstyles NULL) — fut.gg 상세 페이지 결손으로 추정.','R1 상대 박스 터치 6(100%ile)·xG 0.07이나 듀얼 승률 12.5%(0%ile)로 수비 기여는 약하다. [09-11 확인] FC27 club 필드가 Atlético de Madrid로 갱신되어 임대 종료·1군 등록 시점이 게임 데이터로 교차확인됨. 실측 강약점 서술(R1 상대 박스 터치 6·듀얼 승률 12.5%)은 09-02와 동일 — 신규 경기 표본 없음.','FotMob 25/26 라리가 지표 불변(08-21 pull 그대로, 팀 축은 임대처 라요 바예카노 소속 기록으로 추정 — 09-02와 동일 미확인 상태): 슈팅 20%ile·찬스 창출 11%ile. 26/27 v_player_profile·prescriptions 모두 n=1(57분)로 R1 이후 증분 없음.','판단 근거 부족 — 데이터 얇음.','판단 근거 부족 — 데이터 얇음.','판단 근거 부족 — 데이터 얇음.','player_duties(RM); fotmob_detail_stats 25/26·26/27; prescriptions measured:laliga-r1(fit_sim 0.853); player_market_values 26-08 0.87M€(스쿼드 최저) | 2026-09-11 갱신: player_game_stats(FC27, roster_date 2026-09-10, ovr 70·club=Atlético de Madrid로 갱신·best_pos LW·weight 74kg) — FC26 최신판(라요 임대 표기) 대비 소속 갱신 확인; fotmob_detail_stats·prescriptions·v_player_profile은 09-02 이후 증분 없음(n=1 불변)','시장가치 87만 유로로 스쿼드 최저(09-02 판단 유지). FC27에서 소속이 ATM으로 정정된 점 외 신규 실측 없음. 1경기 57분이 26/27 실측 전부.','2026-09-11','FotMob만으로는 드리블 개인기는 있으나 수비 기여·전체 관여도가 뚜렷이 낮은 로테이션급 윙어.');
INSERT INTO player_evaluations VALUES(81,4,153,'C+ — 63 ovr(FC27 2026-09-10, FC26 62 대비 +1) 젊은 백업 LB. 26/27 라리가 표본은 여전히 R1 90분 1경기뿐(평점 7.51) — 09-02 이후 추가 출전 없음. fit_sim 0.968(fb_att_wb/Support)로 슬롯 적합도는 매우 높다.','백5 우측 윙백 — 폭 담당 + 전진 지원. FC27(09-10) 기준 부여 PlayStyle 없음(FC26도 동일).','R1 터치 88·정확패스 47·회수 8로 관여량 많았음. 다만 듀얼 6승 7패로 1대1은 아직 불안정. fotmob_detail_stats 26/27 percentile: 볼 리커버리 86%ile·정확한 패스 82%ile은 상위권이나 정확한 롱볼 9%ile·듀얼 승률 27%ile은 하위권.','26/27 R1 단일 경기(90분) 실측이 전부 — 09-02 이후 추가 경기 없음(v_player_profile n=1 유지). FC27(2026-09-10) OVR63(PAC65·SHO34·PAS52·DRI53·DEF62·PHY63)로 FC26(62, 07-23) 대비 소폭 상승(+1), PlayStyle 미부여는 동일.','판단 근거 부족 — 데이터 최소(1경기).','판단 근거 부족 — 데이터 최소(1경기).','판단 근거 부족 — 데이터 최소(1경기).','player_duties(LB); prescriptions fc26:opt:LB 및 measured:laliga-r1(fit_sim 0.968); squad_entries FB || 2026-09-11 갱신: player_game_stats FC27(2026-09-10, OVR63) · v_player_profile/v_player_season_stats(변동 없음, n=1) · fotmob_detail_stats 26/27(28지표, 변동 없음)','63 ovr 백업/유스급, 시장가치 데이터 없음. 1경기 표본으로 등급 상향은 이르다. 2026-09-11 갱신: 09-02 이후 추가 표본 없음 — 표본 크기 불변(n=1), 신뢰도 재확인만 완료.','2026-09-11','FotMob 지표는 R1 1경기뿐 — 정확패스 47·회수 8로 관여도는 나쁘지 않았으나 후속 표본 필요.');
INSERT INTO player_evaluations VALUES(82,4,154,'B- — CM 71 ovr(FC27 09-10, FC26과 동일). 26/27 표본이 3경기 114분으로 확대(v_player_profile n=3), 평균 평점 6.69로 R1 단독(7.08)보다 하락 — 이후 경기서 부진했음을 시사. fit_sim 0.639(cm_b2b/Ball-Winning)로 슬롯 적합은 여전히 중간.','도식상 좌측 미드필더이나 실측은 중앙(툴x 35.3)에 가까웠다. 드리블 지향형 8번(25/26 드리블 성공 77%ile). FC27(09-10) PAC69(FC26 68 대비 +1)·PHY66(FC26 67 대비 −1)로 스피드 소폭 상승·피지컬 소폭 하락, PlayStyle은 FC26·FC27 모두 미부여.','25/26 xA 1.11·찬스 창출 15(54%ile)·드리블 20회(77%ile)로 준수한 연계·전진 드리블. 26/27 3경기 누적 fotmob: 슛 100%ile(4.74/90)·xG 90%ile(0.354/90)·상대 박스 터치 93%ile로 공격 침투는 여전히 강하다. 다만 터치 19%ile·정확한 패스 21%ile·듀얼 승률 21%ile로 볼 관여·수비 기여는 하위권 — 표본이 늘며 약점이 더 뚜렷해졌다.','FotMob 25/26 라리가(30+지표, 유지) + 26/27(29지표, 09-02 이후 3경기 누적으로 갱신): 평균 평점 6.69, xG 0.354/90·xA 0.121/90로 공격 생산성은 유지되나 패스 정확도 90.9%(71%ile)에 비해 터치량(53.7/90, 19%ile)은 낮아 경기 관여 자체가 제한적이다.','MEDIUM — 에메리 중원은 볼 운반형 8번을 활용하나 수비 기여(28%ile)가 약해 리스크(교차 투영, 실측 아님).','MEDIUM — 알론소는 창조적 8번에게 전진 드리블을 허용하는 편이라 부합 가능성 있음(교차 투영, 실측 아님).','LOW — 이라올라는 높은 강도의 볼 회수를 요구하는데 듀얼 승률 16%ile은 우려(교차 투영, 실측 아님).','player_duties(RCM); fotmob_detail_stats 25/26·26/27; prescriptions measured:laliga-r1(fit_sim 0.639); player_market_values 26-08 14.7M€ || 2026-09-11 갱신: v_player_profile/v_player_season_stats(n=3, 114분, 평점 6.69) · fotmob_detail_stats 26/27(29지표, 3경기 누적) · player_game_stats FC27(2026-09-10, OVR71 유지·PAC+1·PHY-1)','25/26 시즌 표본의 소속 클럽이 DB상 명시되지 않아(팀 축 혼동 방지 차원에서) 해석에 유의. 26/27은 57분 1경기뿐. 2026-09-11 갱신: 26/27 표본이 1→3경기(114분)로 확대돼 신뢰도가 다소 개선됐으나 여전히 소표본(선발 2회뿐)이다.','2026-09-11','FotMob 지표는 공격 생산성(슈팅·xG·드리블) 위주로 강점이 나타나고 수비 기여는 하위권 — 전형적 박스투박스보다는 인사이드 드리블러형.');
INSERT INTO player_evaluations VALUES(83,4,155,'A- — CM 83 ovr(FC27 09-10, FC26과 동일). 26/27 표본이 4경기 294분으로 확대(v_player_profile n=4), 평균 평점 7.39(어시스트 1)로 R1 단독(7.96)보다는 낮으나 여전히 상위권. fit_sim 0.846(cm_playmaker/Roaming)로 fc26:opt 슬롯 배정도 동일. FC27 신규 PlayStyle 4종(Pinged Pass·Tiki Taka·Press Proven·Relentless) 부여(FC26엔 PlayStyle 없음) — 볼위닝+배급 겸용 기능축 실측과 정합적이다.','중앙 봉쇄와 회수 후 전환의 첫 연결. 인터셉트 3(88%ile)·정확패스 51(79%ile). squad_entries에 RDM 위치 측정치도 별도 존재: 2경기(45분+ 필터, 8/29 세비야·9/05 아틀레틱) 평균 7.35/180분, dm_dlp/Roaming 0.775 — 다만 표본 2경기·Δ≤.05로 인선 근거로는 아직 부족(DB 경고 명시).','25/26 시즌 recoveries 85%ile·interceptions 88%ile·dribbles 92%ile로 볼 회수와 전진 드리블을 겸비. 26/27(4경기 누적) fotmob: 공중 경합 승률 100%ile·빅찬스 창출 100%ile·인터셉트 88%ile·볼 리커버리 81%ile·드리블 성공률 79%ile로 R1 단독 때 이상의 종합 상위권을 유지한다. 약점은 기회 창출 43%ile·볼 탈취당함 24%ile(하위권 유지).','FotMob 25/26 라리가 41지표(유지) + 26/27 29지표(09-02 이후 4경기 누적으로 갱신): duels won% 66.7%(79%ile)·big chances created 100%ile(26/27 기준)로 만능형 8번 프로필이 표본 확대 후에도 유지된다. FC27(09-10) OVR83 유지, PAC80(FC26 82 대비 −2).','HIGH — 에메리 체제의 볼 위닝+연결형 8번 요구에 정확히 부합(교차 투영, 실측 아님) — 회수 후 즉시 전진 패스 패턴.','HIGH — 알론소 중원도 볼 회수 후 빠른 재전개를 원함(교차 투영, 실측 아님).','HIGH — 이라올라의 높은 강도 압박·회수 요구에도 부합(교차 투영, 실측 아님).','player_duties(LCM); prescriptions fc26:opt:LCM 및 measured:laliga-r1(fit_sim 0.846); fotmob_detail_stats 25/26·26/27; fotmob_traits; player_market_values 26-08 46.2M€ || 2026-09-11 갱신: v_player_profile/v_player_season_stats(n=4, 294분, 평점 7.39, 어시스트 1) · fotmob_detail_stats 26/27(29지표, 4경기 누적) · player_game_stats FC27(2026-09-10, OVR83 유지·PlayStyle 4종 신규) · squad_entries measured(RDM, dm_dlp/Roaming 0.775, n=2)','표본 1경기(90분) 26/27 — 25/26 시즌 데이터로 보강했으나 소속팀 확인 필요. 2026-09-11 갱신: 표본 26/27 4경기(294분)로 R1 단독 대비 확대. RDM 측정 fit_sim은 n=2로 인선 근거 미달(DB 명시 경고).','2026-09-11','FotMob만 보면 25/26 시즌 recoveries·interceptions·dribbles 모두 80%ile대 이상인 만능형 8번 — 스쿼드 내 최상위 미드필더 프로필 중 하나.');
INSERT INTO player_evaluations VALUES(84,4,156,'B+ — CM 81 ovr(FC27 09-10, FC26과 동일), 34세 베테랑. 26/27 표본이 4경기 193분으로 확대(v_player_profile n=4), 평균 평점 7.11로 R1 단독(7.35)보다 소폭 하락했으나 여전히 안정적. fit_sim 0.834(dm_dlp/Roaming). FC27 신규 PlayStyle 3종(Long Ball Pass·Tiki Taka·Relentless) 부여(FC26엔 PlayStyle 없음) — 롱볼 배급 특화 실측과 정합.','빌드업 개시·롱볼 배급 특화(25/26 accurate long balls 99%ile, 26/27도 정확한 롱볼 100%ile 유지). 피지컬 저하 신호는 아직 뚜렷하지 않음(FC27 PAC50, FC26 49 대비 +1).','25/26 시즌 touches 96%ile·pass accuracy 94%ile·accurate long balls 99%ile로 여전히 리그 최상위 배급력. 26/27(4경기 누적) 정확한 롱볼 100%ile·터치 83%ile·롱볼 정확도 79%ile로 표본 확대 후에도 배급 상위권 유지. 약점: aerial duels 13%ile(25/26), 26/27 듀얼 승률 43%ile·수비 액션 29%ile로 몸싸움·수비 기여는 여전히 약함.','FotMob 25/26 라리가 40지표(유지) + 26/27 25지표(09-02 이후 4경기 누적으로 갱신): 정확한 롱볼 100%ile(26/27)로 배급형 CDM 프로필 일관. FC27(09-10) OVR81 유지, PAS84(FC26 83 대비 +1).','MEDIUM — 에메리 딥라잉 플레이메이커 요구에 배급력은 부합하나 34세 스피드 저하가 하이템포 국면에서 리스크(교차 투영, 실측 아님).','HIGH — 알론소 체제의 빌드업 개시 CDM(짧은 패스+정확한 진행)에 정확히 부합하는 프로필(교차 투영, 실측 아님).','LOW — 이라올라의 높은 라인·전방 압박 강도는 코케의 스피드 열세와 상충(교차 투영, 실측 아님).','player_duties(CDM); prescriptions fc26:opt:CDM 및 measured:laliga-r1(fit_sim 0.834); fotmob_detail_stats 25/26·26/27; fotmob_traits; player_market_values 26-08 2.77M€(계약 2027 만료 임박 반영) || 2026-09-11 갱신: v_player_profile/v_player_season_stats(n=4, 193분, 평점 7.11) · fotmob_detail_stats 26/27(25지표, 4경기 누적) · player_game_stats FC27(2026-09-10, OVR81 유지·PAS+1·PlayStyle 3종 신규)','34세 — 표본은 견고하나 노쇠화 곡선을 감안해야 한다. 2026-09-11 갱신: 26/27 표본이 1→4경기(193분)로 확대돼 신뢰도 개선, 배급력 지표는 표본 확대 후에도 일관되게 상위권.','2026-09-11','FotMob 지표는 리그 최상위 배급력(패스 정확도·롱볼·회수)을 뚜렷이 보여주나 공중볼(13%ile)과 스피드 의존 지표는 하위권.');
INSERT INTO player_evaluations VALUES(85,4,157,'C — LM 69 ovr(FC27, FC26 데이터 없음 — FC27 신규 등재 선수). 26/27 표본이 3경기 113분으로 확대(v_player_profile n=3), 평균 평점 6.46(R1 단독 6.58과 유사)이나 히트포인트 경고가 DB에 여전히 남아있어 표본 얇음은 지속. 찬스 창출은 3경기 누적으로도 86%ile 유지되나 관여량(터치 2%ile) 자체가 여전히 매우 적다.','도식상 우측 미드필더로 채널 수비+역습 출구 역할. 09-02 이후 서술 변화 없음(player_duties 최신 관찰일 2026-08-19 그대로).','3경기 누적 기준 fotmob 26/27: 크로스 정확도 100%ile·성공한 크로스 93%ile·기회 창출 86%ile·xA 76%ile로 결정적 순간 생산성은 상위권 유지. 그러나 터치 2%ile·정확한 패스 2%ile·패스 정확도 7%ile로 볼 관여·기본 패싱은 최하위권 — R1 단독 때 지적된 ''기본기 편차''가 표본 확대 후에도 그대로 확인된다.','2023/24 세군다(LaLiga2) 참고자료는 유지. 26/27 ATM 실측은 3경기 113분으로 확대(09-02 시점 1경기 57분 대비)됐으나 여전히 소표본. FC27(09-10) OVR69·PAC78·DEF31 — FC26 데이터가 없어 시즌 대비 변화는 확인 불가(FC27 신규 등재).','판단 근거 부족 — 데이터 최소, 유스급.','판단 근거 부족 — 데이터 최소, 유스급.','판단 근거 부족 — 데이터 최소, 유스급.','player_duties(LM, 히트포인트 18 경고); fotmob_detail_stats 26/27·2023/24 LaLiga2; prescriptions measured:laliga-r1(fit_sim 0.772); player_market_values 26-08 0.47M€ || 2026-09-11 갱신: v_player_profile/v_player_season_stats(n=3, 113분, 평점 6.46) · fotmob_detail_stats 26/27(23지표, 3경기 누적) · player_game_stats FC27(2026-08-22~09-10, OVR69 변동 없음, FC26 행 없음 확인)','히트포인트 18로 위치 추정 자체가 불안정하다고 DB에 명시. 유스/로테이션급으로 얕은 등급 유지. 2026-09-11 갱신: 표본이 1→3경기(113분)로 늘었으나 경기당 관여도(터치 25.3/90)가 낮아 여전히 신뢰 구간 밖.','2026-09-11','FotMob 26/27 표본이 너무 얇아(57분) 신뢰 가능한 결론 도출 불가. 2023/24 세군다 자료는 다른 리그 수준이라 참고용이다.');
INSERT INTO player_evaluations VALUES(86,4,158,'B — ST 83 ovr(FC27 09-10 동일, FC26 대비 DRI 85→84 소폭 하락, 신규 PlayStyle 4종: First Touch·Quick Step·Low Driven Shot·Game Changer 추가). 라벨은 ST이나 실측은 LM/좌측 윙에 고정된다 — measured 슬롯 LM 3경기(08-23 비야레알·08-29 세비야·09-05 아틀레틱) 평균 6.97/203분, fit wm_insidefwd/Attack 0.7141(prescriptions id=475). 26/27 누적 4경기 293분 평균 6.92로 R1 단일평가(6.77)보다 개선됐으나, 09-05 아틀레틱전은 좌측 고립으로 급락(실측 ay80.4·터치27·듀얼0/6·Into the Calderón 평점 2, obs#495 — 3개 언어권 수렴).','false9 성향(연계형 움직임, chances created 85%ile)과 R1 「단독 9번」 서술(id=136)이 최초 관측이었으나, 09-05 아틀레틱전(id=206)은 좌측 윙 완전 고립 — 「함께 플레이할 사람과 연계할 파트너가 필요하다」는 3개 언어권(영어·스페인어·한국어) 공통 진단이다. 좌우 비대칭 구조(우측 편중) 문제이지 개인 폼 문제가 아니라고 obs#495가 명시.','25/26 chances created 85%ile·pass accuracy 91%ile로 연계 능력 최상위(포워드치고 이례적). 약점: aerials won 7%ile·duels won 21%ile로 몸싸움 최하위권 — 09-05전 듀얼 0/6으로 재현됐다. 좌측 단독 배치로는 강점이 발현되지 않는다 — 연계 파트너 동반 배치가 전제조건(obs#495).','FC27(2026-09-10) OVR83 — FC26(83) 대비 DRI만 85→84로 미세 하락, 신규 PlayStyle 4종 추가. 26/27 시즌: LaLiga 4경기 293분 평균 6.92(1골). measured LM 슬롯 3경기 평균 6.97/203분, 툴 중심(23.32,64.54). FotMob 25/26 30+지표: goals 38%ile·xG 43%ile 평범, chances created 최상위(기존 내용 유지).','MEDIUM — 에메리는 압박 기준점+연계형 9번을 활용 가능하나 duels 21%ile은 리스크(교차 투영, 실측 아님).','HIGH — 알론소 체제의 연계형·false9 지향과 chances created 강점이 부합(교차 투영, 실측 아님).','MEDIUM — 이라올라 트랜지션 축구에 스피드(pac 86)는 부합하나 피지컬 듀얼 약점(15%ile)이 우려(교차 투영, 실측 아님).','player_duties(ST); prescriptions fc26:opt:ST 및 measured:laliga-r1(fit_sim 0.699); fotmob_detail_stats 25/26·26/27; fotmob_traits; player_market_values 26-08 32.5M€ | 2026-09-11 갱신: player_game_stats FC27(2026-09-10, OVR83·PlayStyle 4종 신규) · v_player_season_stats(26/27 LaLiga 4경기 293분 평점 6.92) · prescriptions id=475(measured LM 3경기 6.97/203분, fit wm_insidefwd/Attack 0.7141) · player_duties id=206(09-05 아틀레틱 좌측고립, obs#495, Into the Calderón·ESPN·Atlético Stats 3소스) · player_market_values(team_name이 2026-02-01부터 Atletico Madrid로 전환 확인)','25/26 시즌 데이터의 소속팀이 DB club 필드에 명시 안 됨 — 이전 클럽 자료 혼입 가능성 유의(불변규칙 7 관련 주의). | 2026-09-11 갱신: 26/27 표본 1경기→4경기(293분)로 확대, LM measured 3경기는 여전히 Δ≤.05 인선 근거로는 미흡(squad_entries 주석). 기존 「소속팀 미상」 캐비앗은 player_market_values로 해소 — team_name이 2026-02-01부터 이미 Atletico Madrid라 25/26 LaLiga 표본은 겨울이적 이후 ATM 소속 구간이며, 이는 이번 여름 이적시장 신규영입이 아니라 26/27 시즌 개막 전 이미 8개월 가까이 ATM 소속이었음을 뜻한다(과제 가정과 배치 — 실측 우선 원칙에 따라 채택).','2026-09-11','FotMob만 보면 ''득점보다 연계'' 프로필이 뚜렷 — chances created 85%ile인 반면 aerials·duels는 최하위권.');
INSERT INTO player_evaluations VALUES(87,4,159,'B+ — RB/다중포지션 85 ovr(FC27 09-10 갱신, FC26 대비 OVR·6대 스탯 변동 없음 — pac91·sho79·pas80·dri82·def79·phy83). 26/27 표본이 R1 단독(45분)에서 포지션-순수 RB 3경기·201분(R2 입스위치·R3 세비야·R4 아틀레틱)으로 확장됐다 — 평균 평점 6.87, 커널 적합 fb_wingback/Balanced 0.912(prescriptions id=476, 09-06 갱신)로 R1 단독값(fb_att_wb/Support 0.891)보다 소폭 상승. 09-05 아틀레틱전은 한 경기에 CB·RB·WB·ST·RW 5개 포지션을 소화한 다중롤 사례로 시메오네가 직접 언급한 두 선수 중 하나였다(player_duties).','공수 겸장형 풀백/윙백이자 경기 중 포지션 전환에 강한 다중 롤 자원 — 25/26 goals 73%ile·chances created 44%ile에 더해 26/27 R2~R4 표본에서도 우측 과부하의 존 이탈 축으로 기능(전술 분석 「Marcos Llorente saliendo de zona」).','25/26 xA 91%ile·big chances created 96%ile·assists 90%ile로 팀 내 최상위 창조성 — FC27 신규 PlayStyles(Power Shot, Whipped Pass, Rapid, Quick Step, Relentless+)가 이 창조성·주력 프로필과 일치한다. 약점: 26/27 4경기 누적(225분)에서 duels won% 5%ile·defensive actions 5%ile로 몸싸움·수비 관여가 여전히 약하나, pass accuracy 91%ile·long ball accuracy 100%ile로 배급은 최상위.','FC27(09-10) 카드: OVR85·6대 스탯 FC26과 동일, PlayStyles 5종 신규 공개(FC26엔 비공개). 실측: v_player_profile n=4(225분) 평균 평점 6.85, xa_pg 0.023·kp_pg 0.75·dw_pg 2.25·tk_pg 1.25. FotMob 26/27 LaLiga 소표본에서는 pass accuracy 93.9%(91%ile)·long ball 100% 정확이나 duels won 25%(5%ile)로 몸싸움 고전 지속. 25/26 30+지표(풍부한 표본)는 xG 91%ile·xGOT 93%ile·touches in opposition box 97%ile로 여전히 풀백치고 최전방급 공격 생산성.','HIGH — 에메리의 인버티드/공격형 풀백 활용과 요렌테의 공격 생산성이 정확히 부합(교차 투영, 실측 아님).','HIGH — 알론소 체제의 전진형 풀백 요구에도 부합(교차 투영, 실측 아님).','HIGH — 이라올라의 하이템포 측면 오버래핑에도 스피드(pac 91)와 생산성이 부합(교차 투영, 실측 아님).','player_duties(RB); prescriptions measured:laliga-r1(fit_sim 0.891); fotmob_detail_stats 25/26·26/27; fotmob_traits fullbacks; player_market_values 26-08 15.0M€ | 2026-09-11 갱신: player_game_stats(FC27, roster_date 2026-09-10) OVR·PlayStyles·키/몸무게; v_player_profile n=4(225분); v_player_season_stats(LaLiga 2026-27, 4경기); fotmob_detail_stats 26/27 LaLiga(소표본); prescriptions id=476(R2~R4 누적, fit_sim 0.912); player_duties(09-05 아틀레틱, 다중포지션)','26/27 표본이 1경기(45분)→4경기(225분)로 확장돼 신뢰도가 소폭 개선됐으나 여전히 시즌 초반. FC27 스탯 카드는 OVR·6대 스탯 변동 없어 게임 능치 축은 안정적. 25/26 풍부한 시즌 데이터가 신뢰도를 계속 보강한다.','2026-09-11','FotMob 지표만으로 스쿼드 내 최상위 ''공격형 풀백'' — xG·xA·박스 터치가 전방 자원급으로 이례적이다.');
INSERT INTO player_evaluations VALUES(88,4,160,'A- — LM/공격형 83 ovr(FC27 09-10, FC26 82→83 소폭 상승). 26/27 표본이 R1 단독(33분, LM)에서 확장돼 R3·R4에서는 false 9(LST)로 기용된 표본이 별도 집계됐다 — 2경기·161분 평균 평점 7.95(prescriptions id=477, fit_sim 0.563 st_false9/Attack). LM 슬롯(fc26:opt:LM starter=1)은 여전히 최적 스쿼드 배정.','좌측에서 안쪽으로 들어오는 인사이드형 윙어이자 false 9 겸용 자원으로 역할이 확장됐다 — 25/26 chances created 96%ile·big chances created 100%ile의 창조력이 최전방 기용에서도 xG excl. penalty 74%ile·xGOT 95%ile(26/27 소표본)로 이어진다.','25/26 successful crosses 96%ile·xA 98%ile로 리그 최상위 어시스트 자원. 26/27(4경기 239분) 골 3·도움 1, xg_pg 0.161·xa_pg 0.172·kp_pg 2.5로 생산성 유지. 약점: duels won 15%ile(25/26)·26/27 소표본에서도 duels won% 10%ile·touches 14%ile로 피지컬 대결·볼 관여 빈도는 약함.','FC27(09-10): OVR 82→83, pas83·dri82 유지, playstyles 신규 공개(Dead Ball, Incisive Pass, Tiki Taka, Technical, First Touch, Inventive)로 기술형 프로필이 명문화됐다. 실측: v_player_profile n=4(239분) 평균 평점 7.35. false9 기용(LST, R3·R4 2경기 161분) 평균 평점 7.95로 LM(0.825)보다 표본은 작으나 평점이 더 높다 — fit_sim은 st_false9/Attack 0.563으로 슬롯 적합 자체는 LM보다 낮아 포지션과 실측 성과가 괴리된 사례.','HIGH — 에메리의 인사이드 윙어+창조성 요구에 정확히 부합(교차 투영, 실측 아님).','HIGH — 알론소 체제의 좌측 하프스페이스 창조자 역할과 부합(교차 투영, 실측 아님).','MEDIUM — 이라올라의 높은 강도 압박 회수는 요구 대비 duels 15%ile이 우려(교차 투영, 실측 아님).','player_duties(LM); prescriptions fc26:opt:LM 및 measured:laliga-r1(fit_sim 0.825, 좌우 재정정 이력 있음); fotmob_detail_stats 25/26·26/27; fotmob_traits; player_market_values 26-08 36.9M€ | 2026-09-11 갱신: player_game_stats(FC27, 2026-09-10) OVR83·PlayStyles; v_player_profile n=4(239분); v_player_season_stats(LaLiga 26/27, 골3·도움1); fotmob_detail_stats 26/27 LaLiga; prescriptions id=477(measured LST false9, R3·R4)·id=461(fc26:opt:LM starter)','LM 표본은 4경기 239분으로 확장돼 신뢰도가 개선됐으나 false9 표본(2경기 161분)은 여전히 얕다 — 두 포지션 값을 병기하고 단일 결론으로 뭉개지 않는다.','2026-09-11','FotMob만 보면 스쿼드 최상위 창조형 윙어 — xA·chances created·big chances created 전부 90%ile 이상.');
INSERT INTO player_evaluations VALUES(89,4,161,'B- — RM 82 ovr(FC27 09-10, FC26과 OVR 동일). 26/27 표본이 R1 단독(33분, 좌측 넓은 레인)에서 R3~R4까지 확장돼 포지션-순수 RM 3경기·239분 평균 평점 6.53(prescriptions id=478, wm_winger/Balanced 0.8078)으로 재산출됐다. ⚠️ 09-05 아틀레틱전(선발·우측)은 2실점의 기점이 된 볼 로스트와 「활성화 부족」 비판이 명시적으로 기록됐다(player_duties, Atlético Stats 인용).','우측 침투형 윙어. 폭 유지(우측 과부하 성립)는 수행하나 전환 국면 활성화가 부여 기준에 미달한다는 평가가 반복된다 — 09-05 경기 「no puedes tener esa falta de activación」(그런 활성화 부족을 보일 수는 없다) 인용.','25/26 shots 88%ile·recoveries 82%ile로 공수 양면 기여했으나, 26/27 4경기(272분) 누적에서는 pass accuracy 5%ile·recoveries 5%ile로 관여 정확도가 낮다(aerials won 100%ile·duels won% 79%ile은 소표본 강점). 약점: 09-05 경기 현지 매체가 「공격에서 가장 약한 고리」·「당장 선발에서 빼지 않으면」 수준의 강한 비판을 제기했다(Atlético Stats 인용, player_duties).','FC27(09-10): OVR 82 유지, dri 82→80 소폭 하락·def 56→57 소폭 상승, playstyles 신규 공개(Rapid, Quick Step, Relentless+). 실측: v_player_profile n=4(272분) 평균 평점 6.55, goals1·assists1, dw_pg 4.75·tk_pg 2.0으로 몸싸움·수비 관여는 활발하나 kp_pg 1.0·pass accuracy 70.8%(5%ile, 09-05 경기)로 배급 정확도가 낮다.','MEDIUM — 에메리의 조직적 윙어 요구엔 패스 정확도가 다소 부족(교차 투영, 실측 아님).','MEDIUM — 알론소는 정교한 볼 관리를 원하는데 이 부분이 약점(교차 투영, 실측 아님).','HIGH — 이라올라의 하이템포 침투·역습 스타일에 xG 97%ile 침투력이 정확히 부합(교차 투영, 실측 아님).','player_duties(RM); fotmob_detail_stats 25/26·26/27; fotmob_traits; player_market_values 확인 안 됨(값 없음) | 2026-09-11 갱신: player_game_stats(FC27, 2026-09-10); v_player_profile n=4(272분); v_player_season_stats(LaLiga 26/27); fotmob_detail_stats 26/27 LaLiga; prescriptions id=478(measured RM 누적, wm_winger/Balanced 0.8078); player_duties(09-05 아틀레틱, 비판적 매체 인용 2건)','26/27 표본 4경기 272분으로 확장. 다만 09-05 경기는 현지 매체의 강한 비판(교체·기용 재검토 요구)이 실려 있어 향후 출전 시간 변동 가능성을 신뢰도 판단에 반영한다.','2026-09-11','FotMob 25/26 지표는 침투형 공격 생산성이 강점(xG 97%ile)이나 26/27 초반 표본(33분)은 패스 정확도가 낮아 팀 내 서열 상승을 아직 뒷받침하지 못한다.');
INSERT INTO player_evaluations VALUES(90,4,162,'A- — RW/CM 80 ovr(FC27 09-10 OVR 동일, 신규 PlayStyle 6종: Finesse Shot·Dead Ball·Long Ball Pass·Whipped Pass·Technical·Inventive — 창조형 프로필과 정합). 26/27 누적 4경기 230분 평균 7.07(1골1도움)로 R1 단일 표본(33분)보다 근거가 넓어졌다. measured RST 슬롯 2경기(세비야·아틀레틱) 평균 6.75/131분, fit st_false9/Build-Up 0.6326(prescriptions id=479) — 명목 ST 라벨과 달리 실질은 우측 인사이드/하강형이다. 09-05 아틀레틱전은 3분 결승 골에도 불구, 39분 경고 이후 하강해 ATM 이적 후 최저 평점(SofaScore 6.4/FotMob 6.7, obs#513 — 5소스·4개 언어권 수렴).','좌측 하프스페이스 침투+마무리(R1, id=140)로 시작했으나, 09-05전(id=205)은 반대편 — 우측 최종 3분의 1에서 폭 유지/중앙 좁히기를 오가는 인사이드 자원으로 관측됐다(「no tiene una referencia clara」— 명확한 위치 기준점 없음). 09-09 안필드 선발 여부도 소스 간 상충(obs#515) — 좌우 모두 소화 가능한 유동적 자원으로 잠정 정리한다.','R1 듀얼 4승1패(80%)로 몸싸움에서도 우위. 09-05전 드리블 성공률 100%, 유리 베르치체를 급정지 컷으로 벗겨낸 후 득점(5소스 일치) — 전반은 「Looked lively throughout」로 고평가. 약점: 경고 이후 집중력 저하 패턴이 2개 독립소스로 확정(obs#513), 59분 교체 아웃 후 「안쪽에 절대적으로 아무것도 없었다」는 평.','FC27(2026-09-10) OVR80 — FC26 대비 OVR 동일(PAC 72↔73 미세 변동), 신규 PlayStyle 6종 추가. 26/27 시즌: LaLiga 4경기 230분 평균 7.07(1골1도움). measured RST 2경기 평균 6.75/131분, 툴 중심(74.16,56.37).','판단 근거 부족 — 데이터 최소(1경기 33분).','판단 근거 부족 — 데이터 최소(1경기 33분).','판단 근거 부족 — 데이터 최소(1경기 33분).','player_duties(RCM); squad_entries CM(fit_sim 0.661); player_market_values 26-08 24.9M€ | 2026-09-11 갱신: player_game_stats FC27(2026-09-10, OVR80·PlayStyle 6종 신규) · v_player_season_stats(26/27 LaLiga 4경기 230분 평점 7.07, 1G1A) · prescriptions id=479(measured RST 2경기 6.75/131분, fit st_false9/Build-Up 0.6326) · player_duties id=205(09-05 아틀레틱 우측인사이드·경고분기점, obs#513, 4개 언어권 소스) · player_market_values(PSG→Atletico Madrid 전환이 2026-08-01부로 확인 — 이번 여름 이적시장 신규영입 맞음)','결승골 임팩트는 크지만 33분 단일 표본 — 등급은 임팩트 반영해 A-로 주되 성급한 상향은 경계한다. | 2026-09-11 갱신: 표본이 33분(R1 단일)→230분(4경기)으로 확대돼 근거가 개선됐으나, 39분 경고 이후 하강 패턴의 반복성은 아직 1경기 관측뿐이라 확정할 수 없다. 등급 A-는 유지하되 좌/우 위치 유동성으로 슬롯 고정 판단은 보류한다.','2026-09-11','FotMob 26/27 지표는 1경기뿐이나 짧은 시간 내 고효율(슈팅 3·태클 3·결승골)을 기록했다.');
INSERT INTO player_evaluations VALUES(91,4,163,'B+ — DM 83 ovr(FC27 09-10, FC26과 동일). 26/27 표본이 R1 단독(12분)에서 포지션-순수 LDM 3경기·234분(R2~R4)으로 크게 확장 — 평균 평점 7.0, 커널 적합 dm_dlp/Roaming 0.878(prescriptions id=412)으로 R1 단독값(0.602)보다 대폭 상승해 코케의 배급 역할 계승이 실측으로 뒷받침된다. ⚠️ 09-05 아틀레틱전은 전반 「스펙타큘러」·MVP 후보 평가와 후반 「사라졌다」는 평가가 공존하는 전후반 분리 사례(player_duties).','코케의 중앙 배급 역할을 이어받는 딥라잉 미드필더 — 피탈 직후 활성화(카운터프레싱 트리거)가 핵심 값으로 명시된다(「activación tras pérdida es muy buena」).','26/27 4경기(246분) dw_pg 4.75·tk_pg 2.0·ic_pg 1.5로 수비 관여가 왕성. 약점: 09-05 경기 후반 소멸(「ha desaparecido」)과 기술적 실수로 인한 피탈 1건(Proyecto Hadi 지목)이 기록됨 — 팀 전체 붕괴 국면과 분리되지 않는다는 단서 포함.','FC27(09-10): OVR83·6대 스탯 FC26과 완전 동일, playstyles 신규 공개(Jockey, Block, Anticipate, Relentless+). 실측: v_player_profile n=4(246분) 평균 평점 6.81, xa_pg 0.073. ⚠️ 26/27 LaLiga 세부 percentile 지표(fotmob_detail_stats)는 아직 미수집 — 현재 보유한 상세지표는 이전 소속(Liga Portugal 25/26) 30+ 지표뿐이라 팀·리그 이적 간 비교에는 참고용으로만 쓴다.','판단 근거 부족 — 데이터 최소(12분).','판단 근거 부족 — 데이터 최소(12분).','판단 근거 부족 — 데이터 최소(12분).','player_duties(CDM); squad_entries DM(fit_sim 0.602); player_market_values 26-08 35.8M€(이적 평가치 반영 가능성) | 2026-09-11 갱신: player_game_stats(FC27, 2026-09-10); v_player_profile n=4(246분); v_player_season_stats(LaLiga 26/27); prescriptions id=412(measured LDM 누적, R2~R4, dm_dlp/Roaming 0.878); player_duties(09-05 아틀레틱, 전후반 분리 평가)','26/27 표본이 12분→246분(4경기)으로 크게 확장돼 신뢰도가 개선됐다. 다만 26/27 LaLiga 세부 percentile 지표는 여전히 결손이라 stat_eval의 percentile 근거는 이전 리그(Liga Portugal) 자료에 의존한다 — 팀·리그 교차 시 confidence를 낮춰 취급.','2026-09-11','FotMob 26/27 지표는 12분 표본뿐이라 결론 도출 불가.');
INSERT INTO player_evaluations VALUES(92,4,164,'C(백업 GK 확정) — 82 ovr(FC27 09-10, FC26 80 대비 +2 — PAC80·SHO82(+4)·PAS73·DRI83·DEF46·PHY81, 191cm/93kg 신규 기록). squad_entries(regime=4) GK 슬롯 sort_order 비교: 오블락(player 148) 10위 vs 무소 90위로 오블락의 명백한 2옵션이다. 26/27 공식전 실측은 여전히 0경기(무출전 지속).','⛔ 역할 서술 없음 — DB duties에 관찰 근거 0으로 명시(변화 없음). 09-11 기준 오블락 백업 지위가 squad_entries sort_order로 재확인됐다.','판단 불가 — 실측 없음(변화 없음). FC27 SHO 78→82(+4) 상승은 게임 능치 갱신일 뿐 경기력 실측이 아니다.','25/26 시즌 8경기(720분) 평점 6.81(변화 없음, 소속팀 여전히 명시 안 됨 — squad_entries 주석은 레알 소시에다드 임대 14경기를 별도 언급). FC27(09-10) OVR82로 FC26(80) 대비 +2, SHO가 78→82로 가장 크게 뛰었다. 26/27 실측·서사 신규 없음.','판단 근거 부족 — 데이터 최소.','판단 근거 부족 — 데이터 최소.','판단 근거 부족 — 데이터 최소.','player_duties(GK, 미출전 명시); fotmob_season_stats 25/26; squad_entries GK(fit_sim 0.966, rate_basis=measured이나 rate_v 공란); player_market_values 26-09 2.03M€ | 2026-09-11 갱신: player_game_stats FC27(2026-09-10, OVR82 — FC26 대비 +2, SHO+4) · squad_entries(regime=4) GK sort_order 비교(오블락 10 vs 무소 90) · v_player_season_stats/player_duties/fotmob_detail_stats 26/27 신규 관찰 0건(09-02 이후 변화 없음)','26/27 실측 0. squad_entries의 fit_sim 0.966은 포지션 슬롯 매칭값일 뿐 경기력 실측이 아니다. | 2026-09-11 갱신: 26/27 실측 0경기 지속 — 백업 GK 지위 확정 외에 갱신할 근거가 없다. FC27 스탯 점프(SHO+4)는 실측과 무관한 게임 밸런싱으로 취급한다.','2026-09-11','FotMob 25/26 지표(8경기)는 있으나 소속 클럽 불명확 — ATM 백업으로서의 실측은 아직 없다.');
INSERT INTO player_evaluations VALUES(93,4,165,'C+ — CB 83 ovr(⚠️ FC27 09-10 로스터 갱신에 히메네스 행 자체가 없다 — 최신 FC27 스냅샷은 08-22의 83 ovr다, FC26 대비 PAC 71→73·DEF 84→85 소폭 변동 외 동일). 26/27 R1 미출전, J3(세비야전) 72분 교체 투입 약 20분(Opta 평점 6.37)이 여전히 26/27 체제 유일한 실측이며 09-02 이후 신규 관찰 없음 — DB는 ''역할을 서술할 수 없다''는 판정을 유지한다.','⛔ 역할 서술 불가(터치 14회로 위치 추정 불안정, DB 명시). 09-02 이후 변화 없음.','판단 근거 부족(변화 없음).','25/26 시즌 16경기 1177분 평점 6.9(소속팀 미상, 변화 없음). 26/27 실측은 20분 카메오뿐. FC27(08-22) OVR83 스냅샷이 마지막 기록 — 09-10 로스터 수집에서 이 선수 행이 누락됐다(수집 결손).','판단 근거 부족 — 데이터 최소.','판단 근거 부족 — 데이터 최소.','판단 근거 부족 — 데이터 최소.','player_duties(LCB, 2건 — R1 미출전 + J3 카메오); fotmob_season_stats 25/26; player_market_values 26-08 10.3M€ | 2026-09-11 갱신: player_game_stats 조회 결과 FC27 roster_date=2026-09-10 행 없음(수집 결손 확인, 최신은 08-22) · v_player_season_stats/player_duties/fotmob_detail_stats 26/27 신규 관찰 0건','DB가 명시적으로 ''역할 서술 불가''라 판정했다. 부상 이력 등 서사 자료는 이번 synthesis 범위(DB 내부)에서 확인 안 됨. | 2026-09-11 갱신: DB가 명시적으로 「역할 서술 불가」로 판정한 상태 유지. FC27 09-10 로스터에 이 선수 데이터가 빠져 있어 FC26→FC27 스탯 비교 자체가 08-22 스냅샷에 의존한다 — 다음 수집 세션에서 09-10 로스터 재확인 필요.','2026-09-11','FotMob 지표는 25/26 시즌 16경기(1177분) 평점 6.9로 로테이션급 출전량이나 26/27 데이터는 20분 카메오뿐이다.');
INSERT INTO player_evaluations VALUES(94,4,166,'B — RB/CB 81 ovr(FC27 09-10, FC26 80 대비 +1 — PAC79·SHO56·PAS71·DRI74·DEF81·PHY82, 190cm/82kg, 신규 PlayStyle 5종: Block·Anticipate·Bruiser·Relentless·Aerial Fortress — 수비형 라인에 정합). squad_entries FB(fit fb_falseback/Defend 0.811) 외에 prescriptions measured RCB 2경기(세비야·아틀레틱, 2026-09-06 갱신) 평균 6.45/180분, 중심(65.35,32.32), 커널 fit cb_bpd/Aggressive 0.9191 — 우측풀백뿐 아니라 우측 센터백으로도 고적합이 확인된 멀티포지션 자원이다.','false-back 성향 풀백(인버티드 움직임, fit_role fb_falseback) — 변화 없음. RCB 배치 시에는 cb_bpd(빌드업형 센터백) 적합이 0.9191로 매우 높게 나와 하이라인 수비+빌드업 양쪽에 쓸 수 있는 자원임이 추가 확인됐다.','25/26 시즌 19경기 확립. fotmob_detail_stats(25/26 LaLiga, 40지표) 재확인 결과 — 듀얼 승률 100%ile(71.3%)·공중경합 승률 98%ile(77.6%)·공중경합 승 83%ile(59회)·xGOT 80%ile·드리블 성공률 74%ile(80%)로 수비 몸싸움·제공권이 매우 강하다(⚠️ 기존 stat_eval의 「percentile 지표 0건」 서술은 갱신 누락이었다 — 정정). 약점: 롱볼 정확도 21%ile(38.1%)로 장거리 배급은 약하다.','fotmob_season_stats(25/26: 19경기 1382분 1G1A 평점 7.17, 변화 없음) + fotmob_detail_stats(25/26 LaLiga 40지표, 신규 반영) — 듀얼승률 71.3%(100%ile)·공중경합승률 77.6%(98%ile)·xGOT 0.094/90(80%ile)·드리블성공률 80%(74%ile)·인터셉트 1.302/90(56%ile). FC27(09-10) OVR81(FC26 80 대비 +1). prescriptions measured RCB 2경기 평균 6.45/180분(2026-09-06 갱신).','판단 근거 부족 — 상세 지표 결손, 시즌 요약만 존재.','판단 근거 부족 — 상세 지표 결손.','판단 근거 부족 — 상세 지표 결손.','squad_entries FB(rate_v 7.35, rate_basis=measured2, fit_sim 0.811); fotmob_season_stats 25/26; player_market_values 26-08 22.1M€ | 2026-09-11 갱신: player_game_stats FC27(2026-09-10, OVR81·PlayStyle 5종 신규) · fotmob_detail_stats(25/26 LaLiga 40지표 — 기존 「0건」 서술 정정) · prescriptions id=480(measured RCB 2경기 6.45/180분, fit cb_bpd/Aggressive 0.9191, 2026-09-06 match-watch 갱신) · v_player_season_stats/player_duties 26/27 신규 관찰 없음(R1 미출전 지속)','26/27 R1 미출전으로 duties는 결손 처리됨. rate_v 7.35의 산출 표본(measured2) 세부 경기는 이번 조회 범위에서 확인 안 됨. | 2026-09-11 갱신: fotmob_detail_stats 40지표 확인 완료로 세부 강약점 근거가 크게 보강됐다(HIGH). 26/27 실측은 여전히 R1 미출전이며 RB·RCB 양쪽 커널 적합이 확인됐으나 26/27 공식전 표본은 0이라 실전 검증은 남아 있다.','2026-09-11','FotMob 상세지표(fotmob_detail_stats)가 0건이라 percentile 기반 평가 불가 — 시즌 요약(평점 7.17)만 근거로 삼는다.');
INSERT INTO player_evaluations VALUES(95,4,167,'A- — LB 85 ovr. 확정 주전 — 스쿼드 유일의 정통 LB로 대체 옵션이 없다(2소스 독립 확인). 26/27 라리가 3경기 전부 90분 선발(비야레알·세비야·아틀레틱), 평균 평점 6.5(v_player_profile n=3). squad_entries 실측 갱신(2026-09-01) rate_v 6.55·fit_sim 0.877, prescriptions measured 갱신(2026-09-06, n=3) fit_sim 0.8978(fb_att_wb/Support) — 스쿼드 내 최상위권 측정 적합. 다만 최근 09-05 아틀레틱전은 2개 독립 소스가 부진으로 지목(Into the Calderón 평점 2, Atlético Stats ''경기 최악의 선수'') — 역할·프로필 불일치 의문이 처음 제기됐다.','명목 좌측 풀백이나 실질은 매우 넓게 벌려 받는 크로스 공급원 — 아틀레티코 좌측 진행의 유일한 출구(player_duties id=202, obs#494·#511). FC27 신규 PlayStyles(Finesse Shot·Whipped Pass·First Touch·Inventive·Dead Ball+)가 크로스·데드볼 지향성과 일치.','폭 넓은 위치에서 크로스 공급, 시메오네 체제 유일 정통 LB로 입지 확고(루제리·훌리오 디아스 방출, 다니 마르티네스 1부 무경험 — 대체 부재). 다만 09-05전 크로스 성공 0·빅찬스 0로, 크로스 지향 배급이 최전방 마무리 자원과 짝을 이루지 못하면 무의미하다는 게임구현 시사점이 도출됐다("¿para qué te sirve un gran centrador si no hay un gran rematador?"). 약점: 압박 시 피탈 다수(Atlético Stats 16회, 다수가 역습 유발 패스).','26/27 ATM 3경기 270분 평균 6.5(xg_pg 0.039, xa_pg 0.049, tk_pg 3.0 — v_player_profile). 이전 분데스리가 25/26 29경기 8G8A 평점 7.68(타팀 축, 참고용 — 불변규칙7). FC27(2026-09-10) vs FC26: ovr 동일 85, pac 72→73, def 74→72, phy 66→65 소폭 하락, PlayStyles 5종 신규 확인.','판단 근거 부족 — ATM 실측 결손, 타 리그 자료만 존재.','판단 근거 부족 — ATM 실측 결손.','판단 근거 부족 — ATM 실측 결손.','squad_entries FB(rate_v 6.55, measured2, fit_sim 0.877); fotmob_season_stats 분데스리가 25/26(팀 축 주의 — 이적 전 클럽 자료); player_market_values 26-08 21.2M€ | 2026-09-11 갱신: player_matches(26/27 라리가 3경기: 08-23 비야레알 6.6·08-29 세비야 6.5·09-05 아틀레틱 6.4, 전부 90분 선발); v_player_profile n=3; squad_entries(rate_v 6.55·fit_sim 0.877, 2026-09-01 갱신); prescriptions(measured, n=3, fit_sim 0.8978, 2026-09-06 갱신); player_duties id=202(obs#494·#511, Into the Calderón 2026-09-06·Atlético Stats 자막전사); player_game_stats FC27(2026-09-10, playstyles 5종)','표본 3경기(270분)로 시즌 초기이나 90분 풀타임 3연속으로 확립된 주전. 09-05 관찰은 2개 독립 소스(Into the Calderón·Atlético Stats)가 결론은 일치하나 귀책 메커니즘은 갈림(⚠️ Atlético Stats는 auto-caption). 09-09 안필드전 선발 제외 + 한츠코 좌측 이동이 2소스로 예상됨(obs#515) — 다음 경기가 판별점.','2026-09-11','FotMob 지표는 이적 전 분데스리가 시즌뿐 — 풀백으로서 8골8도움은 유럽 최상위권 생산성이나 ATM 체제 실측과는 분리해서 봐야 한다.');
INSERT INTO player_evaluations VALUES(96,4,168,'C+ — CM/DM 80 ovr(FC27 09-10, FC26과 동일). 26/27 출전이 2경기 26분으로 소폭 늘었으나(v_player_profile n=2, 평점 6.7) 선발은 0회 — 여전히 로테이션 밖. squad_entries fit_sim 0.876(dm_dlp/Roaming)은 유지.','⛔ 역할 서술 없음(DB 명시) — 추정 슬롯 CDM, 09-02 이후에도 실측 갱신 없음(player_duties 최신 관찰일 2026-08-19 그대로).','판단 근거 부족 — 26/27 fotmob_detail_stats 자체가 아직 미수집(26분 표본으로 상세지표 산출 안 됨). 25/26 시즌(38지표) 참고 시 태클 65%ile·인터셉트 63%ile·수비 액션 65%ile로 수비 기여는 중상위였으나 이는 ATM 합류 이전(타 소속) 표본일 가능성이 있어 ATM 실측으로 단정하지 않는다.','26/27: 2경기 26분(선발 0), 평점 6.7 — 골·어시스트 0. FC27(2026-09-10) OVR80(PAC74·SHO67·PAS75·DRI77·DEF79·PHY78, FC26과 완전 동일) — FC27 신규 PlayStyle 2종(Intercept·Bruiser) 부여(FC26엔 PlayStyle 없음).','판단 근거 부족 — 데이터 최소.','판단 근거 부족 — 데이터 최소.','판단 근거 부족 — 데이터 최소.','player_duties(CDM, 미출전 명시); fotmob_season_stats 26/27·25/26; squad_entries DM(fit_sim 0.876); player_market_values 26-09 16.4M€ || 2026-09-11 갱신: v_player_profile/v_player_season_stats(n=2, 26분, 평점 6.7, 09-02 시점 5분 대비 증가) · player_game_stats FC27(2026-09-10, OVR80 유지·PlayStyle 2종 신규) · fotmob_detail_stats 25/26(38지표, 26/27 없음 재확인)','실측 사실상 0(5분). 데이터 지어내지 않음. 2026-09-11 갱신: 09-02 대비 출전 5분→26분으로 소폭 늘었으나 여전히 상세지표 산출 불가한 수준.','2026-09-11','FotMob 지표는 5분 출전이 전부라 결론 도출 불가.');
INSERT INTO player_evaluations VALUES(97,4,169,'데이터 없음 — 스쿼드 등재만 확인, 2026-09-02 이후 변동 없음. 2025/26 프리메라 페데라시온 그룹2 기록(0경기 0분, 골 2 표기 — 데이터 이상치로 추정)만 있고 실측·FotMob·서사·게임스탯(FC26·FC27 모두 player_game_stats에 행 없음) 전부 결손.','결손.','결손.','결손. player_game_stats에 FC26·FC27 모두 이 선수의 카드 행이 없다(FC27 신규 수집에서도 미포함).','판단 근거 부족 — 데이터 없음.','판단 근거 부족 — 데이터 없음.','판단 근거 부족 — 데이터 없음.','player_duties(RCM, 미출전 명시); fotmob_season_stats 프리메라 페데라시온; player_market_values 26-09 0.39M€ | 2026-09-11 확인: player_game_stats에 FC26·FC27 모두 행 없음(카드 미발행); fotmob_detail_stats 0건; v_player_profile·v_player_season_stats 0건; player_duties·squad_entries·prescriptions 09-02 이후 갱신 없음','유스팀 선수 — 09-02 이후 신규 데이터 전무. 데이터 지어내지 않는다는 원칙을 유지한다.','2026-09-11','결손.');
INSERT INTO player_evaluations VALUES(98,4,170,'C — ST 63 ovr 유스(FC27 로스터 자체가 미수집 — FC26 07-23 행만 존재, 09-10 FC27 스냅샷에 이 선수 없음). 25/26 시즌 라리가 2경기 48분 1골(평점 6.88), 프리메라 페데라시온 5골로 유스 대회 득점력은 확인되나 1군 표본은 여전히 극히 얇다. 09-02 이후 신규 실측·서사·게임스탯 전무.','⛔ 역할 서술 없음(DB 명시) — 추정 슬롯 LM. 09-02 이후 변동 없음.','프리메라 페데라시온 5골로 유스 레벨 득점력은 확인되나 1군 검증은 안 됨. 09-02 이후 신규 근거 없음.','라리가 25/26: 2경기 48분 1골 평점 6.88(상세지표 없음). ⚠️ FC27 player_game_stats 행 자체가 없다(2026-08~09 로스터 3회 스냅샷 모두 미수록) — EA FC27에 이 선수가 반영되지 않았을 가능성.','판단 근거 부족 — 데이터 최소, 유스급.','판단 근거 부족 — 데이터 최소, 유스급.','판단 근거 부족 — 데이터 최소, 유스급.','player_duties(LM, 미출전 명시); fotmob_season_stats 25/26 라리가·프리메라 페데라시온 | 2026-09-11 갱신 확인: player_matches·fotmob_detail_stats·squad_entries(regime 4)·player_duties·player_game_stats(FC27) 전부 09-02 시점과 동일 — 신규 데이터 0건.','유스급 — 시장가치 데이터 없음. 09-02 이후 전 축에서 갱신 확인했으나 신규 데이터가 전혀 없어 이전 판단을 그대로 유지한다. 데이터 지어내지 않음.','2026-09-11','1군 표본 48분뿐 — 결론 도출 불가.');
INSERT INTO player_evaluations VALUES(99,4,172,'A — ST 86 ovr, 스쿼드 최고가 자산(2026-09-01 84.0M€, 08-01 93.3M€ 대비 하락 추세). 26/27 라리가 2경기(비야레알 24분 6.5·아틀레틱 31분 6.6) 전부 교체 출전 — 확정 선발은 아직 아니다. squad_entries fit_sim 0.679(st_false9/Build-Up, 레알 마드리드 실측 승계 — 팀 축 주의).','fotmob_detail_stats(25/26 라리가, 레알 마드리드, 41지표)로 처음 구체화됨 — 창조형 지표가 압도적: 성공한 크로스 percentile_per90 96, xA 96, 기회창출 94, 빅찬스창출 93, 정확한 롱볼 88. 반면 순수 피니셔 지표는 중위(골 49, xG 46, 슛 47) — false9/딥리잉 빌드업형 프로필이 데이터로 확인되며 기존 slot 배정(st_false9/Build-Up, fit_sim 0.679)과 정합적.','위 창조 지표 종합 — 딥 빌드업 연계·찬스 메이킹에서 리그 최상위권. 약점: 공중경합 승률 9th percentile(20.8%), 드리블 돌파 허용 18th percentile — 피지컬 듀얼에서 약함. 압박 강도도 중위(공격3선 볼획득 63, 파울획득 28).','26/27 ATM 2경기 55분 평균 6.55(xg_pg 0.138, xa_pg 0.027, kp_pg 1.0 — v_player_profile n=2), 매우 작은 표본. 25/26 레알 마드리드 시즌(41지표): 골8·어시4(위 percentile). FC27(2026-09-10) vs FC26: ovr 동일 86, phy 78→77 소폭 하락, PlayStyles 신규 확인(Finesse Shot·Incisive Pass·Press Proven·Low Driven Shot·Dead Ball+).','판단 근거 부족 — 상세지표 결손, 시즌 요약만 존재.','판단 근거 부족 — 상세지표 결손.','판단 근거 부족 — 상세지표 결손.','player_duties(ST, R1 명단 미포함 명시); fotmob_season_stats 26/27·25/26; squad_entries ST(fit_sim 0.679); player_market_values 26-09 84.0M€ | 2026-09-11 갱신: player_matches(26/27 라리가 2경기: 08-23 비야레알 24분 6.5·09-05 아틀레틱 31분 6.6, 둘 다 교체); v_player_profile n=2; fotmob_detail_stats(2025/2026 LaLiga Real Madrid 41지표, 팀 축 주의 — 이적 전 자료); player_market_values 2026-09-01 84.0M€; player_game_stats FC27(2026-09-10, playstyles 5종)','ATM 실측은 2경기 55분(둘 다 교체 출전)으로 여전히 얇다 — 선발 여부 미확정. fotmob_detail_stats(레알 마드리드 25/26, n=41지표)는 표본은 충분하나 팀 축이 달라(불변규칙7) ATM 적합의 직접 근거로 쓰지 않고 ''선수 소질'' 참고로만 반영. 알바레스·쇠를로트·데이비드 3명이 ST 2자리 경쟁 구도 유지(duties id=149, 09-02 이후 관찰 갱신 없음).','2026-09-11','FotMob 상세지표 결손 — 시즌 요약(1경기 24분 평점 6.1)만 확인되며 결론 도출에는 부족하다.');
INSERT INTO player_evaluations VALUES(100,4,173,'B+ — ST 83 ovr(FC27 09-10 기준, FC27 초반 82와 소폭 진동). 9월 근육부상으로 결장 지속(player_status 최신 확인 2026-09-02, 복귀시점 미확정 ''September 2026'' — 이후 신규 확인 없음). 26/27 ATM 실측 여전히 0경기. fotmob_detail_stats(25/26 비야레알, 41지표)로 처음 구체화된 지표: 공중경합 압도적(승률 58.4% percentile 97, 헤더슛 32회 94, 공중경합승 94회 93) — 전형적 타겟맨 프로필이 데이터로 확인됨.','기존 ''전통형 타겟맨 성향 추정(상세지표 결손으로 확정 불가)'' → 이번 fotmob_detail_stats로 확정: 공중전 지배력 최상위, 지상 연계·패스는 약함(패스정확도 68%, 하위 28%). FC27 신규 PlayStyles(Power Shot·Enforcer·Game Changer·Precision Header)도 타겟맨 성향과 일치.','골 13/35경기(25/26 비야레알, xG 10.16 percentile 68), 공중경합 지표 최상위권 — 상대 최종 수비라인을 직접 위협하는 정통 타겟맨. 약점: 패스 정확도·기회창출(percentile 16) 낮음 — 볼 배급형이 아닌 순수 피니셔.','25/26 비야레알 35경기 1981분 13골 평점 6.79 + fotmob_detail_stats 41지표(위). 26/27은 부상으로 실측 0 유지.','판단 근거 부족 — 상세지표 결손 + 현재 부상.','판단 근거 부족 — 상세지표 결손 + 현재 부상.','판단 근거 부족 — 상세지표 결손 + 현재 부상.','player_duties(ST, R1 명단 미포함 명시); fotmob_season_stats 25/26; player_status(injury, Muscle injury, 2026-09); squad_entries ST(fit_sim 0.701); player_market_values 26-09 16.3M€ | 2026-09-11 갱신: fotmob_detail_stats(2025/2026 LaLiga Villarreal 41지표); player_status(injury, 마지막 pulled 2026-09-02 — 그 이후 신규 확인 없음); player_game_stats FC27(2026-09-10, playstyles 4종)','부상으로 26/27 ATM 실측 0 지속(마지막 확인 2026-09-02, 복귀시점 미확정) — 단기 가용성 낮음. fotmob_detail_stats(비야레알 25/26, n=41지표)는 표본 충분하나 팀 축이 달라(불변규칙7) ATM 실측이 아니라 ''선수 소질'' 참고로만 반영.','2026-09-11','FotMob 상세지표 결손 — 시즌 요약(13골/35경기)만으로 준수한 백업 스트라이커로 판단되나 세부 성향은 확인 불가.');
INSERT INTO player_evaluations VALUES(101,4,174,'B+ — CB 82 ovr. 26/27 ATM 데뷔(09-05 아틀레틱전, 59분 교체 투입·31분 출전, 평점 6.7/Into the Calderón 4) — ''실측 0'' 상태를 벗어났다. squad_entries fit_sim 0.879(cb_bpd/Aggressive, 토트넘 25/26 실측 승계 — 팀 축 주의), prescriptions fc26:opt:RCB 동일값(커널 최적 배정, 실측 아님).','데뷔전(player_duties id=204)에서 초반 전진 스루패스 2회로 온더볼 기여 즉시 입증(''espectacular'' — 훌리안에게 준 스루패스 포함). 다만 이후 수행 저하(''muy pachorresco'')·대인방어 소극성(니코 윌리엄스 상대 과도한 거리, ''se protegió en exceso'')·3실점 국면 템포 지연(''temporiza mucho'') 지적 — 기대(더 저돌적일 것, ''como un animal'')와 실제 사이 괴리가 2소스로 명시됨.','fotmob_detail_stats(25/26 프리미어리그, 토트넘, 45지표)로 CB치고 이례적 공격 기여 재확인 — 골 4(percentile 96), 빅찬스창출 4(92/97), xA 1.26(84/96), 태클 58(94/98), 공중경합승률 71.6%(91). 약점: 파울 32(하위 6%)·옐로카드 9(하위 2%)·레드카드 2(하위 2%) — 징계 리스크가 뚜렷한 공격적 CB.','26/27 ATM 1경기 31분 평점 6.7(v_player_profile n=1, xg_pg 0.176, xa_pg 0.022). 25/26 프리미어리그 23경기 1872분 4골1도움 평점 7.06 + 위 45지표. FC27(2026-09-10) 게임스탯: ovr 82 유지, pac 66→64·dri 65→64 소폭 하락, PlayStyles 신규(Pinged Pass·Slide Tackle·Bruiser·Aerial Fortress·Precision Header)가 공중전·피지컬 특성과 일치.','판단 근거 부족 — ATM 실측 0, 상세지표 결손. 다만 프리미어리그 검증 자체는 긍정적 신호.','판단 근거 부족 — 동일 사유.','판단 근거 부족 — 동일 사유.','player_duties(RCB, R1 명단 미포함 명시); fotmob_season_stats 프리미어리그 25/26; prescriptions fc26:opt:RCB(fit_sim 0.879); squad_entries CB(rate_basis=measured:club(25/26 TOT)); player_market_values 26-08 46.7M€(team_name이 Tottenham Hotspur로 남아있음 — 갱신 지연 가능) | 2026-09-11 갱신: player_matches(26/27 라리가 09-05 아틀레틱 31분 6.7, 교체 투입); v_player_profile n=1; player_duties id=204(2026-09-05 데뷔 관찰, Atlético Stats 자막전사·Into the Calderón·Libertad Digital); fotmob_detail_stats(2025/2026 Premier League Tottenham 45지표); player_game_stats FC27(2026-09-10, playstyles 5종)','데뷔 31분 단일 표본 — 시즌 슬롯 확정에는 이르다. 3실점 귀책이 3소스(카르도소·그리말도·로메로)로 분산돼 단일 귀책하지 않음. fotmob_detail_stats(토트넘 25/26)는 팀 축이 달라(불변규칙7) 선수 소질 참고로만 사용, ATM 적합 직접 근거 아님. 09-09 안필드전 센터백 선발이 2소스로 예상됨(obs#515) — 다음 경기가 풀타임 표본의 첫 기회.','2026-09-11','FotMob 상세지표 결손 — 프리미어리그 시즌 요약(4골/23경기, 평점 7.06)만으로 정상급 CB임은 확인되나 ATM 체제 적응은 미검증.');
INSERT INTO player_evaluations VALUES(102,4,175,'C+ — AM/CM. FC27(roster 2026-09-10) OVR77(FC26 대비 동일, PAC72/DRI79로 -2 소폭 하락). 26/27 R1 명단 여전히 미포함, 09-01 기준 부상 의심(Physical discomfort/doubtful) 유지. 25/26 27경기 3골(평점 6.66) 표본에 상세지표 40건(2026-08-21 수집, 직전 평가 09-02에서 누락)을 반영하면 크로스·롱볼·드리블 성공률 상위 87~91%ile의 기술형 좌측 하프스페이스 자원으로 구체화된다. 시장가치 1.32M€(08-01 1.10M€ 대비 소폭 반등)로 스쿼드 하위권은 유지.','⛔ 26/27 역할 서술 여전히 없음(R1 명단 미포함, 슬롯은 FotMob positionIdsDesc 추정). squad_entries fit_role cm_halfwinger/Support(fit_sim 0.775, rate_basis=measured)로 하프스페이스 서포트형 배정. fotmob_detail_stats(25/26 LaLiga)로 보면 크로스 정확도 91%ile·롱볼 정확도 90%ile·드리블 성공률 90%ile·패스 정확도 87%ile — 기술적 배급형이나 상대 박스 터치 32%ile·xA 44%ile·xG 44%ile로 침투·창조 기여는 낮다.','25/26 LaLiga 상세지표(40건, 2026-08-21 수집): 크로스 정확도 30.4%(91%ile)·성공한 크로스 17회(73%ile)·롱볼 정확도 74.2%(90%ile, 정확한 롱볼 23회 68%ile)·드리블 성공률 57.1%(90%ile, 드리블 20회 62%ile)·패스 정확도 88.1%(87%ile, 정확한 패스 580회 74%ile)·공중 경합 승률 50%(80%ile)·태클 27회(68%ile). 좌측/하프스페이스에서 배급과 크로스로 기여하는 기술형 베테랑.','동일 표본 기준 약점: 어시스트 1회(23%ile)·xA 1.51(44%ile)·xG 1.93(44%ile)·빅찬스 창출 1회(19%ile)·상대 박스 터치 25회(32%ile)로 창조력·침투는 낮음. 규율·볼관리도 하위권 — 옐로카드 4장(13%ile)·볼 탈취당함 33회(14%ile)·클리어런스 2회(11%ile). FC27(roster_date 2026-09-10): OVR77·PAC72·SHO74·PAS78·DRI79·DEF67·PHY61(FC26 대비 PAC/DRI -2, 나머지 동일).','판단 근거 부족 — 상세지표 결손.','판단 근거 부족 — 상세지표 결손.','판단 근거 부족 — 상세지표 결손.','player_duties(CM, R1 명단 미포함 명시); fotmob_season_stats 25/26; player_status(injury, Physical discomfort, doubtful); squad_entries CM(fit_sim 0.775); player_market_values 26-09 1.32M€ | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-08-22/08-31/09-10 3스냅샷 확인, OVR 76→77→77) · fotmob_detail_stats(2025/2026 LaLiga, 40지표, pulled 2026-08-21 — 직전 평가(09-02)에서 누락됐던 테이블을 반영) · player_status·player_market_values 재확인(시장가치 1.10M€→1.32M€, 부상 상태 doubtful 유지) · player_duties·squad_entries 재확인(변화 없음, R1 명단 미포함 유지)','fotmob_detail_stats 40지표는 25/26 시즌 전체(27경기 1259분) 기준으로 표본은 준수하나 포지션 대비 백분위라 팀 전술 맥락은 제거된 값이다. 26/27 R1 실측은 여전히 0. FC27 스탯은 EA 공식 3개 스냅샷 교차 일치(OVR 안정). 서사 자료는 이번 갱신에서 추가 수집하지 않음(docs/30 다국어 절차 미착수 상태 유지).','2026-09-11','FotMob 상세지표 결손 — 시즌 요약만으로는 여전히 출전 가능한 로테이션 자원이나 최근 신호는 하향이다.');
INSERT INTO player_evaluations VALUES(103,4,176,'C+ — DM 72 ovr(FC27 09-10, FC26과 OVR 동일). 26/27 ATM 소속 실측은 여전히 0건(R1 명단 미포함 유지) — 09-02 이후 신규 관측 없음. 25/26 세비야 시절 12경기 739분 평점 6.82만 보유.','⛔ 26/27 ATM 역할 서술 없음(변동 없음). squad_entries fit_role dm_dlp/Roaming(fit_sim 0.746, 세비야 실측 기준 — grid_club=Sevilla).','25/26 세비야 duels won% 97%ile로 몸싸움은 최상위지만 chances created 18%ile·xG 18%ile·aerials won 13%ile로 공격 기여는 낮다 — 수비형 DM 프로필.','FC27(09-10): OVR72 유지, pac74→73·pas66→67 소폭 변동, playstyles 신규 공개(Technical) 1개뿐으로 여전히 얇다. 25/26: 12경기 739분 평점 6.82(어시스트 1, 상세지표는 세비야 소속 기준).','판단 근거 부족 — 상세지표 결손.','판단 근거 부족 — 상세지표 결손.','판단 근거 부족 — 상세지표 결손.','player_duties(CDM, R1 명단 미포함 명시); fotmob_season_stats 25/26; squad_entries DM(fit_sim 0.746); player_market_values 26-09 7.68M€ | 2026-09-11 확인: player_game_stats(FC27, 2026-09-10) OVR·PlayStyles 갱신 확인하되 변화 미미; fotmob_detail_stats 25/26 LaLiga(세비야, duels won% 97%ile 등) 신규 조회; 26/27 ATM 실측 0건 유지; player_duties·prescriptions(regime=4) 09-02 이후 갱신 없음','젊은 선수, 데뷔 시즌 수준 표본 유지. 26/27 ATM 실측이 전무해 09-02 대비 판단 변화 없음 — 등급 보수적으로 유지한다.','2026-09-11','FotMob 상세지표 결손 — 시즌 요약(평점 6.82)만으로는 무난한 로테이션 신인급.');
INSERT INTO player_evaluations VALUES(104,4,183,'데이터 없음 — 스쿼드 등재만 확인. 2026-09-11 재확인: FC27/FC26 player_game_stats·fotmob_detail_stats·player_duties·player_status·player_market_values 전부 신규 행 0건. 실측·FotMob·서사 전부 결손 유지.','결손 — 2026-09-11 재확인해도 변화 없음.','결손.','결손 — player_game_stats(FC27 전체 roster_date, FC26) 조회 결과 0행, fotmob_detail_stats 0행.','판단 근거 부족 — 데이터 없음.','판단 근거 부족 — 데이터 없음.','판단 근거 부족 — 데이터 없음.','player_duties(GK, R1 명단 미포함 명시); squad_entries GK(rate_basis=none) | 2026-09-11 갱신: player_game_stats(name_kr=''알바로 모레노'' 전체 조회, 0행) · fotmob_detail_stats(0행) · player_duties/player_status/player_market_values(변화 없음) 재확인 — 신규 데이터 없음 확정','데이터 지어내지 않음. 유스급 추정, GK 3번 서열(squad_entries rate_note 기준).','2026-09-11','결손.');
INSERT INTO player_evaluations VALUES(105,4,184,'C — CB. FC26(2026-07-23)·FC27(08-22/08-31/09-10) 4스냅샷 전부 OVR67로 동일, 변화 없음. 25/26 ATM 현 시즌 2경기 46분 평점 6.29로 표본 극히 얇고 26/27 R1 명단 미포함 유지. 별도 시즌(2024/2025 LaLiga2, 소속·리그가 현재와 달라 팀 축 혼입 주의 — 불변규칙 7) 상세지표 30건(2026-08-21 수집, 직전 평가 09-02 누락)을 참고하면 수비 액션·공중 경합 관여가 활발한 프로필이 확인되나 이는 ATM 26/27 실측이 아니다.','⛔ 26/27 역할 서술 없음(R1 명단 미포함, FotMob positionIdsDesc 기반 추정 배정, pos_only NULL — 좌우 근거 0). 참고용 2024/2025 LaLiga2 상세지표(별도 시즌·소속 불명확, 30건)로 보면 수비 액션 9.20/90(91%ile)·공중 경합 승 2.39/90(89%ile)·인터셉트 1.10/90(83%ile)·태클 1.22/90(78%ile)로 적극적 수비형이나 파울 1.31/90(6%ile)·경고 10장(4%ile)로 규율 리스크도 동반 — 어느 팀·시즌 소속인지 DB에 명시돼 있지 않아 현재 체제 판단에 직접 반영하지 않는다.','참고용 2024/2025 LaLiga2(별도 시즌, 30지표): 슛 25회(97%ile)·유효슛 7회(92%ile)로 이례적으로 높은 공격 가담, 수비 액션 308회(91%ile)·공중경합승 80회(89%ile)·클린시트 11회(87%ile)·인터셉트 37회(83%ile)로 수비 관여 자체는 왕성. ATM 현 시즌 실측(2경기 46분)은 표본 부족으로 강점 판정 불가.','참고용 2024/2025 LaLiga2 약점: 파울 44회(6%ile)·경고 10장(4%ile)로 리그 최하위권 규율, 출전 중 실점 47회(6%ile). FC26·FC27 4스냅샷 전부 OVR67·PAC64~67·SHO41·PAS53·DRI50·DEF66~67·PHY73로 완전히 안정 — 변화 없음. ATM 25/26 현 시즌: 2경기 46분 평점 6.29(상세지표 없음, R1 명단 미포함).','판단 근거 부족 — 데이터 최소, 유스급.','판단 근거 부족 — 데이터 최소, 유스급.','판단 근거 부족 — 데이터 최소, 유스급.','player_duties(CB, R1 명단 미포함 명시); fotmob_season_stats 25/26; squad_entries CB(rate_basis=none); player_market_values 26-09 0.93M€ | 2026-09-11 갱신: player_game_stats(FC26 2026-07-23, FC27 2026-08-22/08-31/09-10 4스냅샷, OVR 전부 67 동일) · fotmob_detail_stats(2024/2025 LaLiga2, 30지표, pulled 2026-08-21 — 직전 평가 누락분, 소속·시즌 불명확이라 참고용으로만 반영·팀 축 혼입 경고 명기) · player_duties/player_status/player_market_values/fotmob_season_stats(25/26 ATM, 2경기) 재확인, 변화 없음','FC27 스탯은 4스냅샷 완전 일치로 안정적. LaLiga2 30지표는 소속·시즌이 현재 ATM 26/27 체제와 다르다는 것만 확인되고 어느 팀 임대인지는 DB에 없어 불변규칙 7에 따라 참고용으로 한정했다. 현재 체제 실측 표본은 여전히 2경기 46분으로 매우 얇다.','2026-09-11','표본 46분뿐 — 결론 도출 불가.');
INSERT INTO player_evaluations VALUES(106,4,185,'데이터 없음 — 스쿼드 등재만 확인. 2026-09-11 재확인: FC27/FC26 player_game_stats·fotmob_detail_stats·player_duties·player_status·player_market_values 전부 신규 행 0건. 실측·FotMob·서사 전부 결손 유지.','결손 — 2026-09-11 재확인해도 변화 없음.','결손.','결손 — player_game_stats(FC27 전체 roster_date, FC26) 조회 결과 0행, fotmob_detail_stats 0행.','판단 근거 부족 — 데이터 없음.','판단 근거 부족 — 데이터 없음.','판단 근거 부족 — 데이터 없음.','player_duties(LM, R1 명단 미포함 명시); squad_entries WM(rate_basis=none) | 2026-09-11 갱신: player_game_stats(name_kr=''호르헤 라하도'' 전체 조회, 0행) · fotmob_detail_stats(0행) · player_duties/player_status/player_market_values(변화 없음) 재확인 — 신규 데이터 없음 확정','데이터 지어내지 않음. 유스 승격 자원(squad_entries rate_note 기준), LW/LM 추정.','2026-09-11','결손.');
INSERT INTO player_evaluations VALUES(107,4,198,'B — ST. FC27(roster 2026-08-31) OVR80·PAC79·SHO79·PAS71·DRI79·DEF38·PHY73(높은 슈팅·페이스·드리블, 수비 기여도는 스쿼드 최하위권인 38로 EA도 non-pressing형 스트라이커로 평가) — FC26 스냅샷은 없음(ATM 합류가 이적 마감 시점이라 FC26 로스터에는 미등재). ATM 실측 0(이적 초기, 임대 합류)이나 유벤투스 25/26(35경기 1782분 6G4A, 평점 6.6~6.7) + 릴 시절 서사가 매우 두텁다. squad_entries rate_v 6.45(juve2526, 표본 6경기)·fit_sim 0.673(st_false9/Attack). L''Ultimo Uomo의 진단대로 ''공간형·트랜지션형'' 스트라이커가 세리에A의 밀집 수비에서 고전했고, ATM/시메오네 체제에서 재활 가능성이 서사상 제기된다(가설, 실측 아님).','유벤투스 기준: 순수 9번으로 기용됐으나 실제 수행은 연계형(chances created 91~94%ile)에 가까웠고 득점 전환은 실패(xG 8.19 대비 실제 득점 크게 언더퍼폼). 릴 시절(타 체제)엔 배후 침투+하강형 임무를 반복 수행. ATM에서는 가설상 알바레스와 투톱 또는 원톱, 혹은 처진 공격형까지 거론되나 실측 0.','유벤투스 25/26 상대 박스 터치 105회(15.7%)·xA 0.22/90(상위 17%)로 연계 능력 확인. 릴 시절 압박 강도(92~93%ile)도 강점이었으나 유벤투스에서는 수비 액션이 16~23%ile로 떨어졌다. 약점: 유벤투스 슈팅 시도 20%ile·공중 듀얼 10~11%ile로 최하위권, xG 대비 큰 폭 언더퍼폼(xG 8.19 vs 실제 득점).','유벤투스 25/26 세리에A 35경기(~16선발) 1782분 6G4A, 슛 41(유효 16, 39.0%)=2.07/90, 전대회 xG 8.19/npxG 7.40/xGOT 6.39로 대폭 언더퍼폼. 터치 667·상대 박스터치 105(15.7%)·키패스 1.66/경기·xA 0.22/90(상위 17%). 세리에A 공격수 대비 퍼센타일: 터치 76~79%·슈팅시도 20%·득점 47%·찬스창출 91~94%·공중듀얼 10~11%·수비액션 16~23%. UCL 6경기 253분 2골. 릴 24/25(타 체제) 리그1 32경기 16골5도움. 대표팀 캐나다 82경기 42골(역대 최다), WC2026 본선 3골. FC27(roster_date 2026-08-31, ATM 이적 직후 반영): OVR80·PAC79·SHO79·PAS71·DRI79·DEF38·PHY73 — 6대 스탯 중 DEF만 30%대로 극단적으로 낮아 유벤투스 실측(수비 액션 16~23%ile)과 방향이 일치한다.','MEDIUM — 에메리는 연계형 9번 활용이 가능하나 유벤투스에서 확인된 마무리 언더퍼폼(xG 대비)이 리스크(교차 투영, 실측 아님).','HIGH — 알론소 체제의 처진 연계형 9번/false9 활용과 데이비드의 chances created 강점이 정확히 부합(교차 투영, 실측 아님) — 단 릴 시절 자기규정(''나는 피봇형이 아니다'')과는 상충 가능.','MEDIUM — 이라올라의 트랜지션 축구는 릴 시절 배후침투형 임무와 일부 부합하나, 유벤투스에서 확인된 밀집 수비 대응력 저하가 우려(교차 투영, 실측 아님).','player_duties(ST, 2건 — 체제 분리 서술: 유벤투스 25/26·릴 2020~25·ATM 26/27 가설); fotmob 유벤투스 25/26 세리에A 상세지표; squad_entries ST(rate_v 6.45, rate_basis=juve2526, 표본 6경기, fit_sim 0.673); 서사(이탈리아어 L''Ultimo Uomo, 프랑스어 L''Équipe/So Foot, 스페인어 Telemadrid/El Rincón Atlético 등 4개 언어권 — 불변규칙 10 준수, sample_note에 상세 기록) | 2026-09-11 갱신: player_game_stats(FC27 roster_date 2026-08-31, OVR80·6대스탯 확인 — FC26 스냅샷은 ATM 합류 전이라 존재하지 않음, height/weight 미기입) · player_duties/fotmob_detail_stats/squad_entries/player_market_values 재확인, 09-02 이후 신규 행 없음(변화 없음 확정)','ATM 실측 0 — 전부 이적 전 체제(유벤투스·릴) 교차 투영. 불변규칙 7 유의: 이 선수의 유벤투스/릴 데이터는 ATM·시메오네 체제 것이 아니다. FC27 6대 스탯(DEF38)은 EA 자체 산정이나 유벤투스 실측 수비 퍼센타일과 방향이 일치해 교차검증 신호로 볼 수 있다. Marca·AS·Relevo 등 스페인 대형지는 직접 히트 0이라 하위 매체로 대체 확보했다는 한계가 DB sample_note에 명시돼 있다.','2026-09-11','FotMob 유벤투스 25/26 지표만 보면 ''연계형 트리거''(chances created 91~94%ile)와 ''피니셔 실패''(슈팅시도 20%ile, xG 대비 대폭 언더퍼폼)가 공존하는 이례적 프로필. 릴 시절 자료는 별도 체제라 이 평가에서 분리했다.');
INSERT INTO player_evaluations VALUES(108,2,67,'C+ — 35세 베테랑 백업 9번. 알론소 체제 실측 표본은 프리시즌 밀란전 58분(평점 6.5)뿐이고 squad_entries 커널 최적은 CAM 슬롯 cam_playmaker/Balanced .66이나 duties 판정 포지션은 ST이고 game_role_implication은 st_advanced/Support .570로 서사가 제시한 st_false9(폴스나인) 가설은 반증됐다. prescriptions 행 없음(최적 스쿼드 11인에 미편입). 25/26 PL(마레스카 체제) 37경기(26선발) 13골로 득점력은 살아있으나 이는 알론소 체제 실측이 아니다. ⭐[2026-09-12 갱신] C+ → B- 상향. 첼시 소속 공식전 실측이 생겼고 득점으로 답했다 — EFL컵 2경기 163분 3골 평균 7.7(08-27 루턴 73분 7.5 ⚽1 데뷔골·09-09 리즈 90분 7.9 ⚽2 멀티골), PL은 09-06 아스날 8분(6.4, hp 2 무효)뿐. 컵 로테이션 표본이라 리그 서열은 주앙 페드루 우위(duties#35 D+2)이고 prescriptions 변경은 보류(obs#606). 알론소 「접근법을 크게 바꾸지 않고도 투입할 수 있는 경험 있는 대안」 프레이밍 — 백업 9번 지위는 유지되나 「살아있는 득점력」이 알론소 체제에서 확인된 점이 상향 근거.','베테랑 백업 9번. 서사: 데제르비 체제에서는 폴스나인, 휘르첼러 체제 24/25부터는 순수 센터포워드로 회귀. 핵심 움직임은 내려받기(짧게 떨어져 CB를 끌어내 배후를 여는 것). 알론소 체제 유일한 실측(밀란전 58분)에서 avg_x 63.4로 같은 경기 João Pedro(74.3)보다 10.9 낮아 서사와 정합하나 hp=18로 그리드 유효 문턱(15)을 겨우 넘는 경계 표본이다. ⭐[2026-09-12] PlayStyles: FC25 출시(2024-09-13) 없음 → FC26 출시(2025-09-12) Enforcer → FC27 출시(2026-09-10) Tiki Taka·Press Proven·Enforcer(+2). Press Proven은 서사 「등지고 받아 연결·프레스 기준점」(duties#35)과, Tiki Taka는 패스 정확도 79.4%(FW군 백분위90, 25/26)와 정합. 그러나 첼시 실측 2골 경기의 성격은 채널 침투·박스 안 마무리형(CFC Online 「Ran the channels tirelessly」·하셀바인크 「on the end of things」, obs#606)이라 Poacher 계열 PS가 없는 점이 갭. 커널도 st_false9/Attack(루턴 .861·리즈 .703)으로 서사와 어긋나 재검증 항목. AcceleRATE Lengthy.','FC27 OVR80(ST) — 슈팅82·결정력84·볼컨트롤81·헤딩정확도80 등 마무리 능력치가 스쿼드 최상위권. 약점은 가속/질주54, 수비 관련 전 항목 40대. AcceleRATE Lengthy. fotmob_traits(공격수군) 득점 백분위69로 준수하나 공중볼16·슛시도21로 낮다. ⭐[2026-09-12] OVR 궤적: FC25 출시 76 ST(PAC54/SHO76/PAS70/DRI76/DEF42/PHY71) → FC26 출시 78(60/78/74/77/45/77, Δ+2 vs FC25 출시) → FC26 시즌말(07-23) 80 POT80(60/81/74/77/45/77, Δ+2 vs FC26 출시, SHO +3) → FC27 출시(09-10, Chelsea) 80(54/82/73/77/45/77, Δ0 vs FC26 시즌말; vs FC26 출시 SHO +4·PAC −6). attrs FC26 출시→FC27: 결정력 81→84·공격위치 83→84·슈팅력 81→83·중거리 70→77·발리 75→80·헤딩 78→80 상승 / 가속·질주 60→54·점프 83→81 하락. FC25→FC26 출시: 결정력 78→81·프리킥 62→79·힘 73→81. 강점: 마무리(결정력84)·PHY77. 약점: PAC54(36세 곡선)·DEF45·공중볼 승률 33.9%(백분위29).','FotMob PL 25/26(마레스카 체제) 37경기 2263분 13골 1도움 평점6.79 — 백업치고 준수한 득점 생산. 포지션군(공격수) 백분위: 득점69·터치38·기회창출40·공중볼16·슛시도21·수비행동59. 이 시즌 스탯 전량이 마레스카·로즈니어 체제 값이며 알론소 체제 실측은 프리시즌 밀란전 1경기(58분, 평점6.5)뿐이다(불변규칙 7 유의). ⭐[2026-09-12] 최신 FotMob 시즌 PL 25/26 브라이턴(2263분): 13골(백분위86)·xG 12.44(86)·유효슛 28(84)·패스 정확도 79.4%(90)·인터셉트 9(94)·주행거리(92) ↔ 듀얼 승률 36%(33)·공중볼 승률 33.9%(29)·최고속도 32.1km/h(14). 26/27 FotMob 미수집. 09-02 이후 첼시 실측: 09-06 아스날 87'' 교체 8분 6.4(hp 2 무효, 리포트 34), 09-09 리즈 ST 90분 7.9·65''·90+4'' 멀티골·터치 30·hp 42(리포트 36; 65'' 골은 상대 GK 실책 요인, 90+4''는 바르코 빗맞은 슛을 헤더 방향 전환, obs#600). 26/27 EFL컵 2경기 3골 평균 7.7. 시장가치 2026-08-01 €3.03m. 계약 2028-06-30.','MEDIUM — (교차 투영 — 실측 아님) 에메리 체제는 정교한 침투·마무리형 9번을 선호하는데 웰벡의 결정력84·마무리력은 부합하나, 35세 체력·기동성(가속54)이 에메리의 높은 활동량 요구와는 어긋난다.','MEDIUM — 실측 근거: 알론소 체제 유일 표본(밀란전 CAM/드롭9 58분 6.5, cam_playmaker/Balanced fit_sim .66)과 duties 커널(ST 포지션, st_advanced/Support .570)이 서로 다른 슬롯을 가리켜 확정 역할이 불명확하다. 표본 자체도 hp=18 경계선이라 신뢰도가 낮다. prescriptions 행이 없어(비선발) 뎁스 자원으로 판정된다. ⭐[2026-09-12] MEDIUM 유지. 첼시 소속 실측 hp≥15 경기 3개(밀란 58분 ST st_advanced/Support .570·루턴 73분 st_false9/Attack .861·리즈 90분 st_false9/Attack .703)가 역할을 한 곳으로 모으지 못한다 — 커널은 false9를, 4소스 서사·실제 골 장면은 채널 러너/포처를 가리킨다(obs#595·#606). squad_entries CAM cam_playmaker .66과 duties ST 라벨 불일치도 미해소. prescriptions 행 없음(최적 11 밖) 유지. 리그 선발 표본이 붙으면 st_poacher/st_advanced 계열 재계산 대상(D+3 이월). 알론소 체제 득점 3골은 적합이 아니라 「투입 가능성」의 근거.','LOW-MEDIUM — (교차 투영 — 실측 아님) 이라올라의 고강도 압박·침투형 9번 요구는 웰벡의 낮은 가속(54)·체력(68)과 맞지 않는다. 다만 결정력·박스 안 마무리는 부합한다.','player_game_stats FC27(OVR80,ST); fotmob_season_stats PL 25/26(37경기 13골); fotmob_traits(공격수군 6지표); player_duties ST(밀란전 hp=18); squad_entries CAM(rate_v 6.5, cam_playmaker/Balanced .66) | 2026-09-12 갱신: player_game_stats FC25 2024-09-13(#761)·FC26 2025-09-12(#762)·2026-07-23(#548)·FC27 2026-09-10(#601) / player_matches#4102·#4329·#4356 / match_player_reports 27·34·36 / player_duties#35(09-10·09-11 추가) / obs#595·#600·#606 / fotmob_detail_stats PL 2025/2026 / fotmob_traits(FW군) / v_player_season_stats 2026-27 / player_market_values 2026-08-01 / player_status 2026-08-21','알론소 체제 실측 1경기(58분)뿐이고 hp=18로 그리드 신뢰 문턱 경계. duties(ST 포지션)와 squad_entries(CAM 슬롯) 라벨이 어긋나 역할이 확정되지 않았다. prescriptions 0행 — 선발 라인업 밖 뎁스 자원. 25/26 스탯은 마레스카 체제 값으로 알론소 귀속 금지. ⚠️ 2026-09-12: 첼시 실측 유효 표본은 컵 2경기(루턴·리즈)이고 PL은 8분 1회 — 리그 강도에서의 재현 미검증. 리즈전 2골 모두 우연 요인(GK 실책·빗맞은 슛) 기록. 25/26 FotMob 지표 전량은 브라이턴(휘르첼러 체제) 값(불변규칙 7). 커널 fit(false9) ↔ 서사(포처) 충돌 미해소. FC26 시즌말 행은 attrs·PS 미수집이라 세부속성 Δ는 FC26 출시→FC27 출시로만 계산.','2026-09-12','FotMob 지표(공격수군 백분위) 기준: 득점69·터치38·기회창출40·슛시도21·공중볼16·수비행동59. 슛 시도 대비 골 전환이 높은(득점 백분위가 슛시도 백분위를 크게 상회) 효율형 마무리 프로필로 읽힌다. 다만 포지션군 대비 관여량(터치·슛시도) 자체는 낮아 팀 내 볼 순환의 중심이라기보다 마무리 국면에 집중된 백업 9번 성격이 뚜렷하다.');
INSERT INTO player_evaluations VALUES(109,2,140,'B- — 유벤투스전 교체(24분 6.9)·조호르전 선발 풀타임(90분 6.7, 주장완장, 터치93·패스75/69성공·태클4)으로 카이세도·라비아 뒤 3~4번째 피벗으로 자리잡았다. squad_entries 커널 cm_holding/Defend fit_sim .705로 홀딩형 6번 적합. 25/26 시즌은 대퇴 수술로 사실상 아웃이었고(직전 시즌 표본 없음), 알론소의 직접 언급 자료는 확인되지 않는다.','피벗. 백4(유벤투스)에서는 후반 교체 투입, 백3(조호르)에서는 RCM 선발+주장으로 니콜-자줄리와 더블 피벗을 구성. 서사상 볼 회수·1v1 수비가 강점, 볼 유지·찬스창출은 약점이나 실측(조호르전)은 오히려 터치93·패스93%로 팀 내 최다 볼 관여를 기록했다.','FC27 OVR75 CDM — 수비74·피지컬76·가속72로 밸런스형. AcceleRATE Controlled. fotmob_traits(미드필더군) 기회창출88·터치92 백분위로 매우 높으나 표본이 시즌 3경기 26분뿐이라 통계적 신뢰도는 낮다.','fotmob_season_stats 표본이 3경기 26분(평점6.67)에 불과해 시즌 스탯으로는 해석 불가. 알론소 체제 실측 조호르전(90분)이 훨씬 유의미한 표본 — 터치93·패스75/69성공(92%)·태클4·경합11승13패로 이 경기 팀 내 최다 볼 관여였다.','MEDIUM — (교차 투영 — 실측 아님) 에메리는 압박 저항+라인 브레이크 패스가 가능한 피벗을 선호한다. 조호르전 실측 패스 성공률(92%)·태클 활동은 부합하나 표본 1경기로 판단 근거가 얇다.','MEDIUM — 실측 근거: squad_entries CM 슬롯 cm_holding/Defend fit_sim .705(조호르전 90분 6.7). 좌표 tool_x60.1이 RCM 앵커(x=55)와 Δ+5.1로 근접. 다만 상대(조호르) 수준이 낮아 볼 관여량이 부풀려졌을 가능성이 있고, 알론소의 직접 언급 자료는 확인되지 않는다.','LOW-MEDIUM — (교차 투영 — 실측 아님) 이라올라의 고강도 카운터프레스 체제는 활동량 많은 피벗을 요구하는데, 24분 짧은 표본(유벤투스전 교체)만으로는 판단 불가하다.','player_game_stats FC27(OVR75,CDM); fotmob_season_stats(3경기 26분); fotmob_traits(미드필더군); player_duties RCM+CM(유벤투스·조호르, id병합 103→140); squad_entries CM(rate_v6.7, cm_holding/Defend .705)','⛔ 좌표는 CM 행에만 있고 RCM 행은 결손(첼시 공식 매치리포트 표기, 같은 경기의 다른 회차). 25/26은 대퇴 수술로 사실상 시즌 아웃이라 직전 시즌 표본이 없다. 알론소 직접 언급 자료 확인 실패, 검색된 자료 대부분이 마레스카 체제 발언이다.','2026-09-02','데이터 부족(시즌 3경기 26분) — FotMob 시즌 지표만으로는 신뢰할 만한 프로필 서술이 어렵다. fotmob_traits 자체가 미수집이라 포지션군 대비 백분위 비교도 불가능하다.');
INSERT INTO player_evaluations VALUES(110,2,95,'B+ — 신규 영입 시즌 초반. 조호르전 RM/우측 윙백 90분 7.2(경고)로 3경기 중 최고 평점. squad_entries 커널 wm_wideplm/Attack fit_sim .804로 첼시 스쿼드 내에서도 상위권 적합. 백4에서는 우측 미드필더, 백3에서는 우측 윙백으로 전환하는 이력(스포르팅 시절 이미 경험)이 있다. 다만 좌표(avg_x/avg_y) 실측이 3경기 전부 결손이라 위치·전진도는 정성 근거뿐이다. ⭐[2026-09-12 갱신] B+ 유지(판단 보류 성격). 게임·FotMob 프로필은 그대로지만 알론소 공식전 표본이 풀럼전 8분(LAM, hp6·평가 불가) 하나뿐이고 이후 루턴(08-27)·브라이턴(08-30)·아스날(09-06)·리즈(09-09) 4경기 연속 player_matches 행이 없다(미출전, 사유는 DB 미수집). 09-02 판단 근거였던 조호르전 평점은 소스가 갈린다 — match_player_reports(FotMob) 7.2 vs player_matches(SofaScore 정본) 6.9. 3-4-2-1에 윙어 슬롯이 없다는 구조 모순(obs#61)과 퀜다는 2025 선합의 영입이라 알론소 취향으로 귀속 금지(obs#177)라는 점을 등급 상한 근거로 둔다.','폭 담당 우측 아웃렛. 백4일 때 우측 미드필더(유벤투스전 기텐스와 좌우 대칭 윙어), 백3일 때 우측 윙백(밀란전 네투의 자리를 인계, 조호르전 선발). 스포르팅에서 이미 윙어→윙백 개조 이력이 있다. Fulham전은 로저스 대신 LAM 8분 교체 출전(평가 불가 표본). ⭐[2026-09-12] PlayStyles 궤적: FC25 출시판(2024-09-13, 스포르팅) 없음 → FC26 출시판(2025-09-12) Incisive Pass·Whipped Pass·Inventive·Technical → FC27 09-10판(첼시) Incisive Pass·Whipped Pass·Inventive(Technical 탈락). AcceleRATE Controlled(FC25) → Explosive(FC26 출시판). 패스·크로스 계열 PS 3종은 FotMob 25/26 Liga Portugal 조력 프로필(도움 5, 백분위 86·per90 98; xA 2.49 per90 백분위 93)과 정합한다. 왼발(FC25·FC26 출시판 preferred_foot 왼쪽) — 09-02 미해소였던 「Sky 왼발잡이」 서사와 게임 데이터가 일치한다.','FC27 OVR76 RM — 가속86·드리블79로 스피드형 윙어. 수비41·피지컬68은 약점. Liga Portugal 20경기(7선발) 2골5도움 평점6.97로 생산성 준수. fotmob_traits(공격형MF/윙어군) 득점 백분위75·기회창출62로 상위권, 공중볼14는 최하위권. ⭐[2026-09-12] OVR 궤적: FC25 출시판 67(RW, PAC77/SHO62/PAS61/DRI72/DEF21/PHY52) → FC26 출시판 76(RM, 85/62/71/79/41/67, Δ+9) → FC26 시즌말 라이브(2026-07-23) 76(85/64/73/79/41/67, best_pos CAM) → FC27 출시판(2026-09-10) 76(RM, 86/64/72/79/41/68). FC27 vs FC26 출시판: OVR 0·PAC+1·SHO+2·PAS+1·PHY+1; vs FC26 라이브: PAC+1·PAS−1·PHY+1. 세부(FC26 출시판 attrs): 가속87·질주83·볼컨트롤81·드리블80·짧은패스74·크로스71 강점, 차단40·스탠딩태클40·헤딩35 약점. 강점 갱신: 24/25 Liga Portugal 기회창출 53(백분위98)·드리블 성공 38(100)·빅찬스 12(100). 약점 갱신: 공중볼 승률 16.7%(25/26 백분위8).','Liga Portugal 25/26 20경기 873분 2골5도움 평점6.97 — 선발 7회뿐인데도 도움 생산(5개)이 높아 조력형 윙어 프로필. fotmob_traits 득점75·기회창출62·터치70 백분위로 공격 기여도가 높다. 단 이 스탯은 스포르팅 소속 시절 값으로 첼시·알론소 체제 스탯이 아니다(불변규칙 7). ⭐[2026-09-12] fotmob_detail_stats 25/26 Liga Portugal(스포르팅, 873분): 도움 5(백분위86·per90 98), xA 2.49(67·per90 93), 기회창출 19(per90 1.96·백분위84), 회수 per90 5.67(96), 터치 per90 64.7(90), 성공패스 per90 32.8(89), 수비행동 per90 3.40(74) — per90 기준 공수 관여 상위권, 합계 백분위가 낮은 것은 선발 7회의 출전량 탓. 패스 성공률 77.6%(45), 공중볼 승률 16.7%(8). 26/27 FotMob 시즌·상세 미수집. 알론소 체제 실측(player_matches n=4, 175분, 평균 6.9): 유벤투스 45분 6.9·밀란 32분 6.9·조호르 90분 6.9·풀럼 8분 무평점. 09-02 이후 경기 리포트 없음(4경기 연속 미출전).','MEDIUM — (교차 투영 — 실측 아님) 에메리의 우측 윙어는 폭+크로스+수비 복귀를 동시에 요구하는데, 퀜다의 스피드·드리블은 부합하나 낮은 수비 관여(41)는 우려 요인이다.','MEDIUM-HIGH — 실측 근거: squad_entries WM 슬롯 wm_wideplm/Attack fit_sim .804(조호르전 90분 평점7.2)로 스쿼드 상위 적합. 백3 전환 시 우측 윙백(fb_att_wb 계열) 겸업 가능성이 duties에서 시사되나 좌표 실측이 3경기 전부 0이라 fit 산출은 squad_entries 값에 의존한다. 조호르전 현지 평가는 ''수비 규율 부족''을 지적해 완전한 확신은 아니다. ⭐[2026-09-12] MEDIUM-HIGH → MEDIUM 하향. 첼시 소속 실측 우선: squad_entries WM wm_wideplm/Attack .804(조호르 1경기 90분, 툴x 83.0)는 유효하나 공식전 표본이 8분(풀럼 LAM)뿐이고 이후 4경기 미출전이라 알론소가 우측 폭 슬롯에 그를 쓴다는 실측이 없다. 09-02 「좌표 3경기 전부 결손」 캐비앗은 현재 DB 기준 해소 — 유벤투스(hp28, 툴x 85.5)·밀란(hp19, 32분)·조호르(hp47, 툴x 83.0) avg_x/avg_y 존재. 백3 우측 최외곽(WM x=79)에 정합하는 위치는 확인되나 밀란·풀럼 행은 45분 미만·hp15 미달로 집계 제외. 스포르팅 25/26 FotMob 값은 아모림 3-4-2-1 체제 값이라 알론소 적합 근거로 직접 쓰지 않는다(불변규칙 7).','MEDIUM — (교차 투영 — 실측 아님) 이라올라의 고압박 요구에 부합할 스피드는 있으나 수비 복귀 습관(41 백분위)이 검증되지 않았다.','fotmob_season_stats Liga Portugal(20경기 2G5A); fotmob_traits(공격형MF/윙어군); player_duties RM+LAM(유벤투스·밀란·조호르·Fulham); squad_entries WM(rate_v6.9, wm_wideplm/Attack .804) | 2026-09-12 갱신: player_game_stats FC25(2024-09-13)·FC26(2025-09-12·2026-07-23)·FC27(2026-08-22·08-31·09-10); fotmob_detail_stats Liga Portugal 2024/2025·2025/2026; fotmob_season_stats 2025/2026; player_matches 26/27 n=4(유벤투스·밀란·조호르·풀럼); v_player_profile; squad_entries WM; player_market_values 2026-08-01 €36.1m; player_status contract_end 2034-06-30; obs#61·#109·#177','⛔ 좌표 3경기 전부 결손(SofaScore 403 + FotMob 친선 미제공) — game_role_implication은 시사 단계이고 처방 신설 금지 상태. TFA(라이트백/윙백) vs Sky(왼발잡이) 소스 상충 미해소. 스포르팅 자료 혼입 위험. ⚠️ 2026-09-12: 알론소 공식전 표본 8분(무평점). 08-27~09-09 4경기 미출전 사유(부상·명단외) DB 미수집 — player_status에 injury 행 없음. 조호르전 평점 소스 상충(FotMob 7.2 vs SofaScore 6.9). prescriptions 행 없음(미수집). FC26 라이브·FC27 행은 attrs 결손이라 세부속성 Δ는 FC25→FC26 출시판 구간만 산출 가능. 26/27 FotMob 시즌·상세 미수집.','2026-09-12','Liga Portugal 시절(스포르팅) fotmob_traits 기준: 득점75·기회창출62·터치70 백분위로 공격형 미드필더/윙어군 중 상위권 생산성을 보인다. 공중볼14·수비행동37은 하위권으로 전형적인 스피드·드리블 기반 윙어 프로필이며 첼시 이적 후 데이터는 아직 얇다.');
INSERT INTO player_evaluations VALUES(111,2,97,'B — 좌측 윙어/윙백 겸업 후보. 조호르전 좌 윙백 87분 7.1(PK 유도)로 준수했으나 유벤투스전 좌 미드필더 65분 6.0(팀 최저권)으로 편차가 크고 두 경기 상대 수준 차(조호르 vs 유벤투스)가 통제되지 않았다. squad_entries 커널 wm_winger/Attack fit_sim .816로 스쿼드 내 상위 적합. 본인은 스스로를 ''윙어''로 규정하는데 알론소는 윙백으로 배치한 바 있어 서사-배치 충돌이 존재한다. ⭐[2026-09-12 갱신] B 유지. 알론소 공식전 PL 3경기(풀럼·브라이턴·아스날) 출전 0 — 3-4-2-1에 윙어 슬롯이 없다는 구조 모순(obs#61)이 실측으로 이어지고 있다. 출전은 EFL컵 2경기 55분(루턴 10분 6.6 · 리즈 선발 45분 6.6)만이고 리즈전은 알론소 레퍼토리 밖 컵 전용 4-3-3의 LW였다(report 36). 게임 카드는 FC27에서 OVR 78→77 하락(FC26 라이브 대비). 등급을 내리지 않는 이유는 리즈전 LW 단일 경기 fit .890(w_wideplm/Build-Up)과 스피드 속성(PAC92)이 유지돼 백4 전환 시 가치가 남기 때문이다.','좌측 폭 담당. 백4(유벤투스)에서는 좌 미드필더/윙어, 백3(조호르)에서는 좌 윙백. 본인 인터뷰에서 ''지난 시즌도 두 윙어를 쓰는 4-3-3''이었다고 자기규정 — 알론소의 실제 배치(윙백)와 어긋나는 드문 사례다. ⭐[2026-09-12] PlayStyles 궤적: FC25 출시판(2024-09-13, 도르트문트) Rapid·Flair·Quick Step → FC26 출시판(2025-09-09, 첼시) Rapid·Quick Step(Flair 탈락) → FC27 09-10판 Rapid·Quick Step(변동 없음). AcceleRATE Explosive 유지, 오른발. 스피드 PS 2종은 FotMob PL 25/26 드리블 성공 per90 2.39(백분위89)·볼 뺏김 적음(91)·경합 승률 54.2%(95)와 정합. 반면 득점 0(백분위0)·xG 0.82(18)이라 마무리 PS가 없는 것도 실측과 일치. 수비행동 per90 5.33(백분위18)로 윙백 겸업 서사를 지표가 지지하지 않는다.','FC27 OVR77 LM — 가속92 최상위권 스피드, 드리블82. 수비27·피지컬55는 뚜렷한 약점. PL 25/26 16경기(5선발) 490분 2도움 평점6.52. fotmob_traits 기회창출48·수비행동48 중간, 득점8은 최하위권. ⭐[2026-09-12] OVR 궤적: FC25 출시판 75(LM, PAC90/SHO66/PAS62/DRI82/DEF26/PHY55) → FC26 출시판 78(92/73/66/84/27/59, Δ+3) → FC26 시즌말 라이브(2026-07-23) 78(동일) → FC27 출시판(09-10) 77(92/72/66/82/27/55). FC27 vs FC26 라이브(=출시판): OVR−1·SHO−1·DRI−2·PHY−4. 세부(FC26 출시판 attrs): 가속94·질주90·민첩90·균형87·드리블87·슈팅력79 강점, 스탠딩태클22·수비위치26·차단29·긴패스57 약점. 강점 갱신: 경합 승률 54.2%(PL 25/26 백분위95), 리즈전 45분 회수 4. 약점 갱신: PL 25/26 0골, 26/27 PL 0분.','PL 25/26 16경기 490분 평점6.52 2도움 0골 — 짧은 출전시간(경기당 평균 30분)에서의 조력형 기여. fotmob_traits(공격형MF/윙어군) 백분위: 기회창출48·수비행동48·터치35·공중볼31·득점8. 이 시즌은 도르트문트→첼시 이적 시즌이라 체제가 혼재할 수 있다. ⭐[2026-09-12] fotmob_detail_stats PL 25/26(첼시, 마레스카·로즈니어 체제, 490분): 도움 2(per90 백분위95), 드리블 성공 13(per90 2.39·89), 경합 승률 54.2%(95), 볼 뺏김 4(91), 기회창출 9(per90 69), xA 0.93(per90 69), 득점 0(0)·xG 0.82(18), 수비행동 29(12·per90 18), 터치 per90 46.8(35), 패스 성공률 79.2%(39). 26/27 FotMob 미수집. 알론소 실측(player_matches n=7, 327분, 평균 6.52): 유벤투스 65분 6.4·조호르 87분 6.9·소시에다드 14분 6.1·루턴 10분 6.6(패스 8/8, 골포스트)·리즈 45분 6.6(키패스 1, 경합 3승7패, 회수 4). 09-02 이후 리포트: 리즈 EFL컵(report 36) 선발 LW, 46분 팔머 교체.','LOW-MEDIUM — (교차 투영 — 실측 아님) 에메리 체제는 윙어의 수비 복귀·압박 참여를 중시하는데 기텐스의 수비 관련 수치(27)는 최하위권이라 부합도가 낮다.','MEDIUM — 실측 근거: squad_entries WM 슬롯 wm_winger/Attack fit_sim .816(조호르전 87분 7.1). 좌표 tool_x16.16으로 WM 앵커(x=15)와 거의 일치. 다만 duties는 로저스(£117m 영입, 좌측 어태커)와 슬롯이 겹쳐 ''좌측 윙백은 임시 해법일 가능성''을 시사하고, 좌표 결손으로 fit 산출은 squad_entries 단일 표본에 의존한다. ⭐[2026-09-12] MEDIUM 유지. 첼시 실측 우선: squad_entries WM wm_winger/Attack .816(조호르 87분, 툴x 16.2)은 여전히 프리시즌 1경기 표본. 공식전 실측은 리즈전 45분(4-3-3 LW, 툴x 20.2·툴y 54.7, hp36) 단일 경기 fit w_wideplm/Build-Up .890 — 높지만 45분·컵 전용 편성이라 시즌 정본 승격 불가. 09-02 「좌표 2경기 결손」은 DB 기준 해소(유벤투스 hp29 툴x 19.5·조호르 hp53 툴x 16.2). 부정 근거: PL 3경기 출전 0, 알론소 정본 3-4-2-1의 폭 담당은 윙백이라 슬롯 자체가 없다(obs#61). 도르트문트·마레스카 체제 수치는 참고만(불변규칙 7).','LOW-MEDIUM — (교차 투영 — 실측 아님) 스피드(92)는 이라올라의 카운터프레스에 적합할 수 있으나 수비 관여(27)가 낮아 고강도 압박 체제 부담이 크다.','fotmob_season_stats PL 25/26(16경기 2A); fotmob_traits(공격형MF/윙어군); player_duties LM(유벤투스·조호르); squad_entries WM(rate_v6.9, wm_winger/Attack .816) | 2026-09-12 갱신: player_game_stats FC25(2024-09-13)·FC26(2025-09-09·2026-07-23)·FC27(2026-08-22·08-31·09-10); fotmob_detail_stats Bundesliga 2024/2025·Premier League 2025/2026; fotmob_season_stats PL 2025/2026; player_matches 26/27 n=7; match_player_reports 27·36; v_player_season_stats(EFL컵 2G 55분); squad_entries WM; player_market_values 2026-08-01 €42.0m; player_status contract_end 2032-06-30; obs#61','⛔ 좌표 2경기 전부 결손. 도르트문트 시절 자료 혼입 위험 큼. 25/26 PL 27경기(12선발) 서사 자료 대부분이 마레스카·로즈니어 체제 값. 다수 매체가 ''윙백 징후 없음 — 일관되게 윙어''로 서술하지만 조호르전 실제 배치는 좌 윙백 — 서사-배치 충돌 미해소. ⚠️ 2026-09-12: 공식전 표본 55분(EFL컵 2경기, 45분 이상 1경기). PL 0분 — 미출전 사유(전술 선택/부상) DB 미수집. 리즈전 fit .890은 45분 표본·컵 전용 4-3-3이라 처방 근거 금지. FC26 라이브·FC27 행 attrs 결손으로 세부속성 Δ는 FC25→FC26 출시판만. 26/27 FotMob 시즌·상세 미수집. 서사-배치 충돌(윙어 자기규정 vs 윙백 배치)은 공식전 윙백 기용 0으로 미검증.','2026-09-12','FotMob 지표(공격형MF/윙어군 백분위) 기준: 기회창출48·수비행동48이 중간, 득점8·공중볼31·슛시도44·터치35는 하위~중하위권이다. 짧은 출전시간 대비 두드러진 생산 지표가 없어 아직 데이터로는 ''완성형 윙어''라기보다 스피드에 의존하는 미완성 프로필로 읽힌다.');
INSERT INTO player_evaluations VALUES(112,2,63,'B+ — 백3 우측(RCB) 선발 확정급. 밀란전 90분 7.6·Fulham전(개막 공식전) 90분 7.32로 안정적인 데뷔 초반. prescriptions fc26:opt:RCB(starter=1, cb_bpd/Aggressive fit_sim .635)로 최적 스쿼드 편입. 다만 RB/RCB 슬롯 판별이 실측상 Δ.003으로 거의 구별 불가능한 하이브리드 포지션이다. ⭐[2026-09-12 갱신] B+ → B 하향(잠정). 「RCB 선발 확정급」 전제가 흔들렸다 — 아스날전 선발은 콜윌 컨디션 문제에 따른 대체였고(obs#526, 알론소 회견) 「전진형 우측 CB」 임무는 슬롯 귀속·사람 가변으로 판정됐다. 26/27 PL 3경기 평균 6.44(풀럼 7.32·브라이턴 22분 6.3·아스날 5.7), EFL컵 2경기 평균 7.5(루턴 7.9·리즈 RB 7.1). 아스날전 cb_bpd/Aggressive 0.4556은 경기 최저 적합(리포트 34). 다만 공식전 5경기 중 4경기 선발(RCB 3·RB 1)로 출전 비중 자체는 스쿼드 상위 — 등급은 B, 뎁스 가치는 RCB/RB 겸용에서 나온다.','우측 볼전진 수비수. 서사상 본직 라이트 CB이며 백3 우측·백4 RB·인버티드 FB·DM까지 소화하는 다역. 밀란전 실측(tool_x75.6)은 RCB(66)·RB(86) 사이 정중앙에 위치해 하이브리드 성격을 실측으로도 확인했다. ⭐[2026-09-12] PlayStyles: FC26 출시(2025-09-12)·FC26 라이브(07-23)·FC27 출시(09-10) 전부 부여 없음(playstyles NULL) — 미수집이 아니라 게임상 무PS 카드. FC25 출시판 행 미수집(FC25 미수록 가능). AcceleRATE Lengthy(FC26 출시·FC27 동일). 실측 프로필은 아스날전에서 「넓게 서다 접히는 CB」 서사를 뒤집고 전진형 우측 CB(avg_x 50.0, CB 둘보다 11.7 높음, 네투 언더랩·오버랩 런, obs#520·#564)로, 무공에서는 촐리스 담당 우측 풀백(4-4-2 접힘)이었다. 리즈전은 백4 RB 90분. ⇒ 게임상 무PS·DEF 75는 이 전진 성향(드리블 성공 11 백분위96, 25/26)을 반영하지 못한다.','FC27 OVR75 CB — 수비75·피지컬73·가속75로 밸런스형 어린 수비수. AcceleRATE Lengthy. PL 25/26 17경기(8선발) 663분 1골 평점6.64. fotmob_traits(CB군) 기회창출91·득점93으로 공격 기여 백분위가 매우 높고 공중볼19·수비행동4는 낮다(표본 663분으로 작음 유의). ⭐[2026-09-12] OVR 궤적: FC25 출시 미수집 → FC26 출시(2025-09-12) 70 RB(PAC76/SHO50/PAS65/DRI69/DEF66/PHY73) → FC26 시즌말(2026-07-23) 74 POT85 CB(76/50/66/69/74/73, Δ+4 vs FC26 출시, DEF +8) → FC27 출시(09-10) 75 CB(75/50/67/69/75/73, Δ+1 vs FC26 시즌말·Δ+5 vs FC26 출시). attrs FC26 출시→FC27: 차단 65→75·수비위치 66→77·스탠딩태클 67→75·슬라이딩 65→75·반응 67→75·헤딩 65→71·점프 80→83·짧은패스 69→72·긴패스 64→68, 가속 75→74. 강점: 수비 기본기 전반 상승·PAC75 유지·패스 정확도(92.1% 백분위88, 25/26). 약점: 롱볼 정확도 22.2%(백분위2)·공중볼 승 11(백분위11)·클리어 20(백분위8) — FC27 긴패스 68이 이를 반영.','PL 25/26 17경기 663분 1골 평점6.64 — 백업급 출전량에서의 안정적 지표. fotmob_traits 백분위가 공격지표(기회창출91·득점93·슛시도72)에서 유독 높고 전통 수비지표(공중볼19·수비행동4)에서 낮은 것은 표본(663분)이 작아 왜곡됐을 가능성이 있다. ⭐[2026-09-12] 최신 FotMob 시즌은 PL 25/26(663분): 패스 정확도 92.1%(백분위88)·드리블 성공 11(96)·최고속도 33.8km/h(82) ↔ 수비행동 44(12)·클리어 20(8)·공중볼 승 11(11)·롱볼 정확도 22.2%(2). 26/27 FotMob 미수집. 09-02 이후 실측: 09-06 아스날 RCB 90분 5.7·터치 21·hp 28(전진 위치로 볼 회로 밖, obs#520), 09-09 리즈 RB 90분 7.1·hp 84·fb_wingback/Balanced .838(리포트 36, 팀 내 수비수 최고 평점이나 CFC Online 5/10 「전환 공격에 시종 흔들림」 — 원인은 중앙 2인 차단 실패 선행, obs#602). v_player_profile n=10 평균 6.76·599분. 시장가치 2026-08-01 €23.9m(06-01 €29.5m에서 하락). 계약 2029-06-30.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 에메리의 3백은 볼 전진 가능한 우측 CB를 요구하는데 아체암퐁의 넓게 서다 안으로 접는 실측 패턴(avg_x43.0, tool_x75.6)이 부합한다.','HIGH — 실측 근거: prescriptions fc26:opt:RCB(starter=1, cb_bpd/Aggressive .635), squad_entries CB rate_v7.6. 밀란전 실측 tool_x75.6이 RCB 앵커에 Δ+0.6로 근접해 최적 스쿼드 편입 근거가 됐다(적합값 자체는 라크루아 .844보다 낮지만 소시에다드전 기준 우선순위에서 밀란전 표본이 채택됐다). ⭐[2026-09-12] HIGH → MEDIUM 하향. 첼시 소속 공식전 실측 4경기(hp≥15)가 슬롯을 서로 다르게 가리킨다 — 풀럼 RCB(7.32)·루턴 RCB cb_bpd/Aggressive .740 ↔ 아스날 RCB cb_bpd .4556(FB .695/CB .704/WM .706이 Δ0.011 안에 몰려 시즌 measured 보류, 리포트 34) ↔ 리즈 RB fb_wingback/Balanced .838. prescriptions fc26:opt:RCB(starter=1, .635)와 squad_entries CB .635는 밀란전 프리시즌 1경기 기반이라 갱신 필요. 임무(전진형 우측 CB)가 슬롯 귀속이라(obs#526) 개인 적합으로 고정하지 않는다 — 다음 백3 경기에서 RCB vs RB 재판정.','MEDIUM — (교차 투영 — 실측 아님) 이라올라의 하이라인·전진형 백라인에 아체암퐁의 볼 전진 능력은 맞으나 공중볼 대응(19백분위)이 약점으로 지적될 수 있다.','fotmob_season_stats PL 25/26(17경기); fotmob_traits(CB군); player_duties RB+RCB(밀란·Fulham); prescriptions fc26:opt:RCB(starter1, cb_bpd/Aggressive .635); squad_entries CB(rate_v7.6, .635) | 2026-09-12 갱신: player_game_stats FC26 2025-09-12(#757)·2026-07-23(#133)·FC27 2026-09-10(#619) / player_matches#4060·#4092·#4082·#4319·#4350 / match_player_reports 25·26·27·34·36 / player_duties#32(09-08~09-10 추가)·#178 / obs#520·#526·#564·#602 / fotmob_detail_stats PL 2025/2026 / fotmob_traits(CB군) / v_player_profile / player_market_values 2026-08-01 / player_status 2026-08-21','1경기 표본(밀란전)이고 RB vs RCB 슬롯 적합차가 Δ.003로 구별 불가 — 하이브리드 포지션 자체가 낮은 격차의 원인. 신장(185cm vs 1.90m) 소스 충돌, 알론소 체제 선발 지위도 소스 충돌(''untouchable'' vs ''두 형태 모두 선발 예상 안 됨''). ⚠️ 2026-09-12: FC25 출시판 행 없음(미수집). PlayStyles는 전 버전 NULL — 결손인지 무PS인지 fut.gg 09-10 정본 기준 무PS로 읽었다. 슬롯 판정은 4경기 실측이 갈려 미확정. 아스날전 5.7·리즈전 「흔들림」 서술은 각각 단일경기·3티어 평점 기사라 개인 능력 하향 근거로 과대 해석 금지(구조 원인 선행 — obs#521·#602). 26/27 FotMob 미수집.','2026-09-12','FotMob 지표(CB군 백분위) 기준 기회창출91·득점93·슛시도72로 CB치고 이례적으로 높은 공격 관여가 눈에 띈다. 다만 공중볼19·수비행동4로 전통적 수비 지표는 하위권이라, 표본(663분) 규모를 감안하면 ''공격 가담형''이라는 인상이 소표본 효과일 가능성을 배제할 수 없다.');
INSERT INTO player_evaluations VALUES(113,2,131,'B+ — 백3 좌측(LCB) 선발 확정급. 소시에다드전 76분 6.6·Fulham전(개막) 90분 6.67로 위치 실측(tool_x23.1)이 LCB 앵커(25)와 Δ−1.9로 정합. prescriptions fc26:opt:LCB(starter=1, cb_bpd/Aggressive .72). ⭐[2026-09-12 갱신] B+ → B 하향(잠정). 알론소 공식전 실측 3경기(풀럼 LCB 90분 6.67 · 브라이턴 LCB 72분 6.3 · 리즈 LCB 76분 6.3; v_player_season_stats PL 2G 6.48·EFL컵 1G 6.3)가 전부 6.7 이하이고, 브라이턴전 패스 21회 중 13회 성공(62%, 8회 실패)으로 팀 패스 정확도 하락의 최대 기여자(report 26). 아스날전(09-06) 결장 — 알론소 1차 발언 「Levi had a little thing during the week」(obs#526)로 컨디션 사유, 아체암퐁이 대체. 루턴전 행 없음(사유 미수집). 유지 근거: FC27 OVR80(CB 2위), 시장가치 €58.2m(2026-08-01, 5명 중 최고), 브라이턴전 주장.','백3 좌측. 소시에다드전에서 좌측 윙백(팔레스트라) 뒤를 덮는 형태로 배치, 볼 소유 시 전진 없이 배급형 좌 CB. 패스 57/57(100%)로 완결적 배급이나 경합 0승3패로 듀얼에서 전패했다. ⭐[2026-09-12] PlayStyles 궤적: FC25 출시판(2024-09-13) Long Ball Pass·Block·Aerial → FC26 출시판(2025-09-09) Block(2종 탈락) → FC27 09-10판 Pinged Pass·Block(Pinged Pass 추가). AcceleRATE Lengthy 유지, 왼발. Pinged Pass 추가는 FotMob PL 25/26 성공패스 per90 69.2(백분위93)·패스 성공률 90.1%(80)·터치 per90 91.6(94)의 배급형 프로필과 정합하나, 정확한 롱볼 3(백분위4)이라 Long Ball Pass 탈락도 실측과 맞는다. 첼시 실측에서는 브라이턴전 그리드가 LCB .590 < LB .785로 윙백형(report 26), 리즈전(백4) cb_bpd/Aggressive .935로 경기 형태에 따라 성격이 달라진다.','FC27 OVR80 CB — 수비81·피지컬78로 스쿼드 상위권 CB. AcceleRATE Lengthy. PL 25/26 3경기(2선발) 225분 평점6.72로 부상 복귀 초반 출전량 관리 구간. fotmob_traits(CB군) 터치87 최상위, 득점0·수비행동27은 표본이 작아 해석 유의. ⭐[2026-09-12] OVR 궤적: FC25 출시판 77(CB/LB, PAC69/SHO40/PAS68/DRI68/DEF77/PHY77) → FC26 출시판 80(70/43/71/72/81/80, Δ+3) → FC26 시즌말 라이브(2026-07-23) 80(동일) → FC27 출시판(09-10) 80(68/43/71/71/81/78). FC27 vs FC26 라이브(=출시판): OVR 0·PAC−2·DRI−1·PHY−4(체력 77→69, 질주 73→70). 세부(FC27 attrs): 공격성84·점프84·차단81·수비위치81·스탠딩태클81·슬라이딩80·짧은패스79·침착79·헤딩79·볼컨트롤77·시야73 강점, 가속66·민첩60·균형60 약점. 강점 갱신: 경합 승률 64.7%(PL 25/26 백분위76), 브라이턴전 듀얼 5승2패. 약점 갱신: 압박 노출 시 패스 실패(브라이턴 8회), 체력 속성 −8.','PL 25/26 3경기 225분 평점6.72 — 표본이 작아(2선발) 시즌 평가 근거로는 제한적이다. fotmob_traits 터치87 백분위는 볼 관여도가 높음을 시사하나 나머지 수비지표(공중볼51·수비행동27)는 중하위권으로 소표본 영향이 크다. ⭐[2026-09-12] fotmob_detail_stats PL 25/26(첼시, 225분·소표본): 성공패스 per90 69.2(per90 백분위93), 패스 성공률 90.1%(80), 터치 per90 91.6(94), 인터셉트 per90 2.0(93), 수비행동 per90 10.0(72), 경합 승률 64.7%(76), 정확한 롱볼 3(4), 공중볼 승 6(7·per90 44). 24/25 PL 상세 40지표 보유(tenure 38경기 6.97). 26/27 FotMob 미수집. 알론소 실측(player_matches n=6, 421분, 평균 6.47): 소시에다드 76분 6.6 · 풀럼 90분 6.67(패스 27/29, 툴x 24.5) · 브라이턴 72분 6.3(패스 13/21, 듀얼 5승2패, 클리어 6, 툴x 24.5) · 리즈 76분 6.3(4-3-3, 툴x 34.8, 76분 포파나 교체). 09-02 이후: 아스날 결장(obs#526), 리즈 report 36.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 에메리의 좌측 볼플레잉 CB 요구에 콜윌의 100% 패스 성공(소시에다드전)과 배급형 프로필이 부합한다.','HIGH — 실측 근거: prescriptions fc26:opt:LCB(starter=1, cb_bpd/Aggressive .72), squad_entries CB rate_v6.6. 소시에다드전 실측 tool_x23.1이 LCB 앵커(25)와 Δ−1.9로 거의 정확히 일치 — 3-4-2-1 좌 CB 1순위다. 단 밀란전에는 하토가 같은 자리(tool_x26.2)를 맡아 좌측 CB는 로테이션 대상이다. ⭐[2026-09-12] HIGH 유지(슬롯 우선순위 축). 첼시 실측 우선: prescriptions fc26:opt:LCB cb_bpd/Aggressive .72(starter=1) — 공식전 툴x 풀럼 24.5·브라이턴 24.5로 LCB 앵커(25)와 Δ0.5 이내 정합(09-02 소시에다드 23.1과 일관). 아체암퐁 선발은 전술 선택이 아니라 콜윌 컨디션 대체라는 감독 1차 발언(obs#526)이 1순위 지위를 지지한다. 단 역할 정합은 흔들린다: 브라이턴전 단일 경기 LCB fit .590(26% 점유 왜곡, LB .785가 더 높음) vs 리즈전 백4 LCB .935. 좌 CB 로테이션(하토·아체암퐁)은 유지되며 밀란전 하토 툴x 26.2 사례도 그대로다.','MEDIUM — (교차 투영 — 실측 아님) 이라올라의 하이라인 체제에서 좌 CB의 커버 스피드가 중요한데 콜윌의 실측 경합 성적(0승3패, 소표본)만으로는 판단 근거가 부족하다.','fotmob_season_stats PL 25/26(3경기); fotmob_traits(CB군); player_duties LCB(소시에다드·Fulham); prescriptions fc26:opt:LCB(starter1, .72); squad_entries CB(rate_v6.6, .72) | 2026-09-12 갱신: player_game_stats FC25(2024-09-13)·FC26(2025-09-09·2026-07-23)·FC27(2026-08-22·08-31·09-10); fotmob_detail_stats PL 2024/2025·2025/2026; fotmob_season_stats PL 2025/2026; player_matches 26/27 n=6; match_player_reports 5·17·18·25·26·36; v_player_season_stats(PL 2G 6.48·EFL컵 1G 6.3); prescriptions fc26:opt:LCB; squad_entries CB; player_market_values 2026-08-01 €58.2m; player_status contract_end 2029-06-30; obs#526','1경기(소시에다드전) 표본. 경합 0승3패는 표본 3회로 성향 판정 불가. 좌측 CB는 하토와 로테이션(밀란전 하토 기용)이라 콜윌 단독 확정 아니다. ⚠️ 2026-09-12: 공식전 3경기(238분) 표본. 브라이턴전 fit .590은 점유 26% 왜곡으로 시즌 근거 금지(report 26). 아스날 결장 사유는 감독 발언(HIGH)이나 부상명·기간은 player_status에 없음(미수집). 루턴전 미출전 사유 미수집. 26/27 FotMob 미수집. FC26 라이브 행 attrs 결손 — 세부 Δ는 FC26 출시판↔FC27만. 리즈전 .935는 컵 전용 4-3-3 백4 값이라 3-4-2-1 LCB 근거로 직접 쓰지 않는다.','2026-09-12','FotMob 지표(CB군 백분위) 기준 터치87로 볼 관여도가 매우 높고 공중볼51은 평균 수준이다. 표본(225분)이 작아 득점0·수비행동27 등 낮은 값은 실제 약점이라기보다 부상 복귀 초반 제한된 출전량의 산물일 가능성이 크다.');
INSERT INTO player_evaluations VALUES(114,2,105,'B — 조호르전 90분 평점9.0(PK 2골)로 수집 표본 중 최고 평점을 기록했으나 우리 DB 실측은 이 1경기뿐이고 좌표·map25가 전무해 커널 적합 자체를 산출할 수 없다. 외부 실측(Opta, 입스위치 24/25)은 배후침투46.1%·전방압박976회·홀드업80+회로 명확한 ''고압박 저점유 유일 출구형'' 9번을 가리키는데, 이는 첼시(마레스카) 고점유 체제와 정면 충돌했고 25/26 PL 28경기 1골(npxG/90 0.24)로 생산성이 붕괴됐다. 알론소 체제 조호르전에서는 딜랍이 9번, 잭슨이 그 왼쪽으로 배치돼 두 선수가 정반대 프로필이라는 서사·실측이 수렴한다.','입스위치(맥케나)에서는 저점유 직접축구의 유일한 전방 출구로 배후침투+홀드업+전방압박 3중 부하를 혼자 졌고(팀 36골 중 12골), 첼시(마레스카)에서는 연결형 9번을 요구받아 프로필과 충돌, 알론소 체제에서는 조호르전 3-4-3 최전방 9번(잭슨이 왼쪽/뒤)으로 배치됐다.','FC27 OVR77 ST — 슈팅77·피지컬79로 파워형 스트라이커, 수비30은 예상대로 낮다. AcceleRATE Lengthy. 외부 Opta(입스위치24/25) 기준 배후침투46.1%(잭슨28%)·홀드업80+회(PL ST 4위 이내)·슛전환율17.7%(잭슨13.2%)·12골/9.3xG(+2.7)로 리그 최상위권 침투형 9번 지표를 보였다. 반면 25/26 PL(첼시) 28경기 1골로 생산성은 크게 떨어졌다.','우리 실측은 조호르전 1경기(90분, 평점9.0, PK2골)뿐이라 좌표·터치·듀얼 데이터가 전무하다. fotmob_season_stats PL 25/26(마레스카 체제) 28경기 1102분 1골 평점6.3으로 낮은 생산성을 보였고 fotmob_traits(공격수군) 득점10·기회창출17 백분위로 하위권 — 이는 시스템 부적합 진단(Squawka·Opta·PL 공통)과 일치한다. 외부 Opta 수치(입스위치 시절)는 체제가 달라 첼시 알론소 평가에 직접 대입할 수 없다.','MEDIUM — (교차 투영 — 실측 아님) 에메리 체제의 조직적 침투 요구는 딜랍의 배후침투 능력(외부 실측 46.1%)과 부합하나, 첼시 고점유 체제에서 이미 한 차례 부적합이 확인된 프로필이라 신뢰도는 낮다.','MEDIUM — squad_entries 커널값은 st_false9/Attack fit_sim .818(조호르전 90분 평점7.7 기준)이나, duties의 game_role_implication은 외부 실측(배후침투46.1%·압박976회·홀드업80+)을 근거로 st_false9를 명확히 반증하고 st_advanced 계열을 가리킨다 — 두 판정이 서로 모순돼 fit_alonso를 단일 값으로 확정하기 어렵다. 조호르전 라인업(딜랍9번-잭슨왼쪽)은 딜랍을 전형적 최전방 침투형으로 쓰겠다는 신호로 읽힌다.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 이라올라의 고강도 카운터프레스+배후공간 침투 요구는 딜랍의 입스위치 시절 프로필(압박976회·배후침투46.1%)과 구조적으로 가장 가깝다. 다만 이는 다른 팀·다른 체제(입스위치) 자료의 교차 투영이라 첼시 실사용 근거는 아니다.','fotmob_season_stats PL 25/26(28경기 1골); fotmob_traits(공격수군); player_duties ST(조호르 실측 + Opta 외부 2025-06-25 입스위치24/25); squad_entries ST(rate_v7.7, st_false9/Attack .818)','⚠️ 최대 한계: 우리 알론소 체제 실측이 1경기·PK2골이고 좌표·map25가 0이다. 정량 내용 대부분이 외부(입스위치 시절) 인용이며 팀 축 혼입 위험이 크다(점유율 40%↔60%대로 정반대 체제). squad_entries(kernel st_false9)와 duties(st_false9 반증, st_advanced 시사)가 상충 — 재판정 필요. 알론소 직접 발언 확인 실패, 전부 기자 해석. 25/26 출전 기록도 PL 28경기1골 vs 전대회 41경기2골4도움으로 소스 충돌.','2026-09-02','FotMob 지표(공격수군 백분위) 기준 득점10·기회창출17·슛시도69로 슛은 많이 시도하나 득점 전환이 낮은 프로필로 나타난다. 이는 마레스카 체제(고점유·연결형 9번 요구) 부적합 진단과 일치하며, 슛 시도(69백분위)와 실제 득점(10백분위) 사이의 큰 격차가 시스템-프로필 불일치를 수치로 뒷받침한다.');
INSERT INTO player_evaluations VALUES(115,2,96,'C+ (데이터 부족) — 유스 자원. FC26/27 game_stats·fotmob 상세지표 전무. 유벤투스전(66분6.9)·조호르전(90분6.2) 두 프리시즌 경기에서 실측 tool_x41.3·tool_y45.4로 CAM 앵커(x=68)보다 훨씬 안쪽이라 ''10번보다 중앙 미드에 가까운 위치''로 판정됐다. squad_entries 커널은 cam_playmaker/Build-Up fit_sim .438로 스쿼드 내 낮은 편이나, 이는 슬롯 배정(x=68) 문제이며 실측 위치 자체는 LAM(x=35)에 더 근접(Δ6.3)한다. ⭐[2026-09-12 갱신] C+(데이터 부족) 유지. 갱신 근거가 늘지 않았다 — 게임스탯 카드는 FC25 출시판·FC26 출시판·FC26 라이브·FC27 어느 버전에도 없고(확정 결손, 게임 미수록), 알론소 공식전(풀럼~리즈 5경기) 출전 0. 실측은 프리시즌 4경기(player_matches n=4, 244분, 평점 있는 2경기 평균 6.75)로 09-02와 동일. 2026-09-12 수집 fotmob_season_stats U18 26/27 행은 Goals 1·Matches 0·Minutes 0으로 내부 불일치(경기 없이 득점) — 소스 갱신 지연으로 보고 근거로 쓰지 않는다.','중앙 공격형 미드필더. 유벤투스전(4-4-2)·조호르전(3-4-3) 모두 90분 가까이 선발한 유스 자원으로 두 경기 모두 중앙 밴드에 머물렀다. 에수구의 duties에서 조호르전에 니콜-자줄리와 더블 피벗을 구성했다는 언급이 있어, 실제로는 CAM보다 낮은 위치에서도 뛰는 것으로 보인다. ⭐[2026-09-12] 게임 PlayStyles·특성 전 버전 카드 없음(결손) — FC25→FC27 대조 불가. fotmob_traits 미수집. 실측 프로필만 존재: 유벤투스전(4-4-2, 66분) avg 52.4/60.2 → 툴x 39.8·툴y 52.4, 조호르전(3-4-3, 90분) 툴x 41.3·툴y 45.4 — 두 경기 모두 LCM(x=45)~LAM(x=35) 사이 중앙 밴드. match_player_reports 포지션도 두 경기 LCM. 유벤투스전 태클 3·인터셉트 3·경합 3승4패(66분)로 수비 관여가 있는 중앙 미드 프로필.','FC26/27 game_stats 미수집, fotmob_traits 미수집 — 능력치·PlayStyles 기반 평가가 불가능하다. fotmob_season_stats는 Premier League 2(U21) 2경기 117분 평점6.92(1선발)뿐이라 1군급 데이터가 없다. ⭐[2026-09-12] OVR 궤적: FC25 출시판·FC26 출시판·FC26 시즌말(07-23)·FC27 출시판(09-10) 전부 해당 버전 카드 없음(결손). 6종합·세부속성 산출 불가. 실측 강점: 유벤투스전 SofaScore 7.3(선발 66분, 터치 55) — 프리시즌 첼시 출전자 중 준수한 값. 약점: 공식전 0분, PL2 25/26 2경기 117분이 유일한 리그 표본. 시장가치·계약(player_market_values·player_status) 미수집.','데이터 부족. Premier League 2(U21) 2경기 117분 평점6.92 외 시즌 스탯이 없다. 알론소 체제 실측은 프리시즌 2경기 합산(156분) tool_x41.3·tool_y45.4뿐이며 포메이션이 다른 두 경기(4-4-2/3-4-3)를 합친 값이라 docs/30의 포지션-순수 원칙에서 벗어난다. ⭐[2026-09-12] fotmob_detail_stats 없음. fotmob_season_stats: PL2 25/26 2경기 117분 1선발 평점 6.92(변동 없음), U18 26/27(2026-09-12 pulled) Goals 1·Matches 0(불일치). 알론소 실측 player_matches: 웨스턴시드니 44분·토트넘 44분(원천 수치 없음), 유벤투스 66분 7.3(SofaScore; FotMob 6.5), 조호르 90분 6.2(SofaScore; FotMob 7.0) — 두 소스 평점이 경기마다 역방향으로 갈려 평균(6.75)의 신뢰도가 낮다. 09-02 이후 첼시 공식전 리포트에 등장 없음.','LOW-MEDIUM — (교차 투영 — 실측 아님) 데이터 부족으로 판단 근거가 매우 얇다. 에메리의 정교한 10번 요구에 부합하는지 판정할 실측이 없다.','LOW-MEDIUM — 실측 근거: squad_entries CAM rate_v6.2, cam_playmaker/Build-Up fit_sim .438로 스쿼드 내 낮은 축에 속하나, 이는 저장된 슬롯(RAM x=68) 기준값이고 실측 위치(tool_x41.3)는 LAM(x=35)에 더 가깝다(Δ6.3) — LAM은 로저스(£117m, pos_only=LAM)가 점유해 이 선수는 현재 뎁스로만 기록된다. duties도 ''뎁스 후보로만 쓰고 선발 근거로 쓰지 말 것''을 명시한다. ⭐[2026-09-12] LOW-MEDIUM 유지. 첼시 실측: squad_entries CAM cam_playmaker/Build-Up .438(RAM x=68 기준, 조호르 1경기)·슬롯군 argmax LAM .662 — 실측 툴x 41.3은 LAM(35) Δ6.3으로 LAM 성격이나 LAM은 로저스(pos_only)가 점유(obs#316 오탐 정리에서 사이드 고정 판정 유지). 알론소 공식전 5경기 출전 0으로 뎁스 이하. 프리시즌 두 경기가 4-4-2·3-4-3으로 포메이션이 달라 포지션-순수 집계 조건(docs/30)을 충족하지 못한다.','LOW — (교차 투영 — 실측 아님) 데이터가 얇아 판단 근거가 부족하다.','fotmob_season_stats PL2/U21(2경기); player_duties CAM(유벤투스·조호르 합산 156분); squad_entries CAM(rate_v6.2, cam_playmaker/Build-Up .438, RAM/LAM 사이드고정 캐비앗) | 2026-09-12 갱신: player_game_stats 전 버전 조회(행 없음 확인: FC25 2024-09-13·FC26 2025-09-xx·2026-07-23·FC27 2026-09-10); fotmob_season_stats PL2 2025/2026·U18 2026/2027(2026-09-12); player_matches 26/27 n=4; match_player_reports 6·7·17·18; v_player_profile; squad_entries CAM; player_duties CAM(id124)','⚠️ 데이터 부족 — FC26/27 game_stats·fotmob_detail_stats·fotmob_traits 전무. 실측도 프리시즌 친선 2경기(포메이션 혼합 집계)뿐이라 표본 신뢰도가 낮다. squad_entries 저장값(RAM 커널 .438)과 실측 위치(LAM에 더 근접)가 불일치하는 것으로 별도 캐비앗이 기록돼 있다. ⚠️ 2026-09-12: 게임스탯 카드 전 버전 부재(게임 미수록 — 수집 결손 아님). fotmob_detail_stats·fotmob_traits·player_market_values·player_status 전부 미수집. 실측 평점 소스 상충(SofaScore 7.3/6.2 vs FotMob 6.5/7.0). U18 26/27 행 내부 불일치. 공식전 0분 — 표본은 프리시즌 친선 4경기(그중 2경기 원천 수치 없음)가 전부.','2026-09-12','데이터 부족 — fotmob_traits(포지션군 백분위 지표) 자체가 수집되지 않아 FotMob 기반 독립 서술이 불가능하다. Premier League 2 시즌 스탯(2경기 117분)만으로는 유의미한 평가를 내릴 표본이 되지 못한다.');
INSERT INTO player_evaluations VALUES(116,2,66,'A- — 백3 좌측 윙백(LM 슬롯) 유력 주전. 밀란전 90분 평점6.8, 2경기 합산 평점6.75로 준수하고 squad_entries·prescriptions fc26:opt:LM 모두 wm_winger/Balanced fit_sim .908로 스쿼드 전체에서 최상위권 적합. Serie A(임대) 25/26 37경기(34선발) 3084분 1골4도움 평점7.03로 풀타임급 검증도 마쳤다. 단 서사는 본직을 우측 윙백/CB로 규정하는데 실측 배치는 좌측 최외곽이라 서사-배치가 정반대로 갈렸다. ⭐[2026-09-12 갱신] A- → B 하향(잠정). 「좌측 윙백 유력 주전」 전제가 실측으로 깨졌다 — 첼시 공식전 5경기(08-24 풀럼~09-09 리즈) player_matches 0행, 마지막 출전은 08-15 소시에다드(프리시즌). 그 사이 LM 슬롯 선발은 하토(풀럼·브라이턴·아스날)·차바리아(루턴)였다. 결장 사유는 DB 미수집(player_status 부상 행 없음 — 계약 행만 존재). 반면 게임 가치는 급등: FC27 출시 OVR78(FC26 출시 61 대비 Δ+17, FC26 시즌말 75 대비 Δ+3)·PAC90. ⇒ 실측 공백이 해소될 때까지 등급을 실측 기준 B로 내리고 prescriptions fc26:opt:LM(starter=1)은 재검토 대상.','매우 높고 넓은 공격형 윙백. 서사상 본직은 라이트 백/윙백이며 양측면·백3 3번째 CB·인버티드 FB까지 소화하는 다역 유니콘 유형, 1v1 고립을 의도적으로 부여받는 유형이다. 그러나 알론소 체제 실측(밀란전 tool_x16.1·avg_x65.9)은 좌측 최외곽+매우 높은 전진도로 서사와 반대 측면에서 뛰었다. ⭐[2026-09-12] PlayStyles: FC25 출시판 행 미수집 → FC26 출시(2025-09-13, Bergamo Calcio) 없음 → FC26 시즌말(07-23, 칼리아리 임대) 미수집 → FC27 출시(09-10, Chelsea RB) Rapid. Rapid 단일 PS는 가속·질주 90(FC26 출시 67·66에서 +23·+24)의 스피드형 표기이고, 실측 프로필의 핵심인 드리블(세리에A 25/26 성공 70회 백분위100)·듀얼(248 백분위100)·파울 유도(108 백분위100)·크로스(27 백분위90)는 PS로 표현되지 않았다(Technical·Whipped Pass 없음). 좌측 배치는 프리시즌 3경기 연속(밀란·조호르·소시에다드)이었으나 공식전 표본 0 — 좌우 판정도 프리시즌 한정.','FC27 OVR78 RB — 가속90·드리블80으로 스피드형 풀백/윙백. AcceleRATE Controlled. Serie A(임대) 37경기 3084분 1골4도움 평점7.03로 검증된 생산성. fotmob_traits(미드필더군) 기회창출51은 준수하나 공중볼19·수비행동19·득점17은 낮다. ⭐[2026-09-12] OVR 궤적: FC25 출시 미수집 → FC26 출시(2025-09-13) 61 RM(PAC66/SHO51/PAS57/DRI62/DEF47/PHY56) → FC26 시즌말(2026-07-23) 75 POT84 RM(86/62/69/78/67/72, Δ+14 vs FC26 출시 — 칼리아리 임대 37경기 3084분 반영) → FC27 출시(09-10) 78 RB(90/65/69/80/70/81, Δ+3 vs FC26 시즌말·Δ+17 vs FC26 출시). attrs FC26 출시→FC27: 가속 67→90·질주 66→90·드리블 61→82·볼컨 66→81·민첩 56→82·크로스 59→74·스탠딩태클 43→76·점프 62→88·체력 51→85·힘 60→81. 강점: PAC90·DRI80·PHY81(체력85). 약점: SHO65·PAS69·수비위치 68, 공중볼 승률 40.5%(백분위37).','Serie A 25/26(임대 소속) 37경기 3084분 평점7.03·1골4도움으로 풀타임급 검증을 마쳤다. fotmob_traits 기회창출51 백분위가 상대적으로 높아 공격 기여형 풀백/윙백 프로필을 뒷받침한다. 단 이 스탯은 임대 클럽(세리에A) 소속 값이며 첼시·알론소 체제 스탯이 아니다(불변규칙 7 유의). ⭐[2026-09-12] 최신 FotMob 시즌은 Serie A 25/26 칼리아리 임대(3084분): 드리블 성공 70(백분위100)·듀얼 승 248(100)·파울 유도 108(100)·박스 터치 80(94)·어시스트 4(90)·xA 3.55(90)·기회창출 32(85) ↔ 재적 시 실점 46·xGA 47.35(백분위2 — 팀 요인)·공중볼 승률 40.5%(37). 첼시·알론소 체제 FotMob 미수집. 09-02 이후 첼시 경기 평점·리포트 없음(공식전 미출전, match_player_reports 마지막은 08-16 소시에다드 76분 6.6). v_player_profile n=5 평균 6.83·337분 전부 프리시즌. 시장가치 2026-08-01 €12.4m(이적료 £43m, obs#177). 계약 2033-06-30.','MEDIUM — (교차 투영 — 실측 아님) 에메리의 윙백은 폭+오버래핑+크로스를 요구하는데 팔레스트라의 스피드·드리블은 부합하나 수비 관여(수비행동19백분위)는 우려된다.','HIGH — 실측 근거: prescriptions fc26:opt:LM(starter=1, wm_winger/Balanced .908), squad_entries WM(2경기 166분 rate_v6.75, .908)로 스쿼드 내 최상위 적합 중 하나다. 실측 tool_x16.1이 LM 앵커(x=14)에 거의 정확히 위치. 다만 wm_widemid/Build-Up(.888)과의 격차가 Δ.017로 노이즈 구간이라 docs/30 기준 서사(세리에A 성공탈압박2위·오픈플레이크로스9위·코너획득3위·의도적1v1고립)를 근거로 wm_winger를 채택한 가설적 결정이다. ⭐[2026-09-12] HIGH → MEDIUM 하향. 커널값 자체(prescriptions fc26:opt:LM wm_winger/Balanced .908, squad_entries WM .908)는 스쿼드 최상위이나 근거가 전부 프리시즌 2경기(밀란 90분 6.8·소시에다드 76분 6.6, 실측 그리드는 밀란전 1경기)다. 첼시 공식전 실측 0경기라 알론소 공식전 체제에서의 좌측 윙백 배치·전진도(avg_x 65.9)가 재현되는지 미검증이며, 그 슬롯을 하토(LM 3경기 7.08·7.0·7.1)가 채우고 있다. 서사 본직(우측)과 실측(좌측) 충돌도 미해소. 첫 공식전 45분+ 표본이 나오면 재판정.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 이라올라의 하이라인·오버래핑 풀백 요구에 팔레스트라의 높은 전진도(avg_x65.9)·스피드는 부합한다.','fotmob_season_stats Serie A(임대, 37경기 4A); fotmob_traits(미드필더군); player_duties LM(밀란전 실측); prescriptions fc26:opt:LM(starter1, wm_winger/Balanced .908); squad_entries WM(2경기166분, rate_v6.75, .908) | 2026-09-12 갱신: player_game_stats FC26 2025-09-13(#760)·2026-07-23(#547)·FC27 2026-09-10(#611) / player_matches(26/27 5행, 마지막 08-15) / match_player_reports 2·5·6·17·18 / player_duties#34 / prescriptions#448 / squad_entries#80 / obs#172·#177·#209·#217·#255·#257 / fotmob_detail_stats Serie A 2025/2026 / fotmob_traits(MF군) / player_market_values 2026-08-01 / player_status 2026-08-21','1경기(밀란전) 좌표 실측, 2경기 합산 평점. 서사(우측 윙백 예측)와 실측(좌측 배치)이 정반대로 갈려 위치 판정은 실측이 우선하나 기능적 서사(드리블·크로스)는 그리드 밖 층이라 가설로만 유지한다. 소스 내부 모순 다수(공중볼 강점/약점 소스 상충, 피지컬·리스크 성향도 소스간 정반대). ⚠️ 2026-09-12: ⚠️ 첼시 공식전 5경기 결장 사유 DB 미수집(부상·선발 제외·명단 제외 불명) — 등급 하향은 「실측 부재」에 근거한 잠정 판정이며 원인이 확인되면 재판정. FC25 출시판 행 없음. FC26 시즌말 행은 attrs·PS 미수집이라 세부속성 Δ는 FC26 출시→FC27 출시로만 계산. 세리에A 백분위는 임대 클럽·타 리그 값(불변규칙 7). 좌우 배치·wm_winger 채택은 프리시즌 1경기 그리드 + 노이즈 구간(Δ.017) 서사 타이브레이크의 가설.','2026-09-12','FotMob 지표(미드필더군 백분위, 세리에A 임대 시즌) 기준 기회창출51로 준수한 공격 기여를 보이나 공중볼19·수비행동19·득점17은 하위권이다. 풀타임급(3084분) 표본에서 나온 값이라 신뢰도는 있으나, 순수 수비형 풀백이라기보다 공격 가담에 특화된 윙백/윙어 하이브리드 프로필로 읽힌다.');
INSERT INTO player_evaluations VALUES(117,2,130,'A- — 백3 중앙(CCB) 신규 충원 1순위. 소시에다드 데뷔전 62분 평점6.6·Fulham전(개막) 90분 평점8(수비수를 벗기고 로저스 골 어시스트)로 강한 임팩트를 남겼다. prescriptions fc26:opt:CCB가 아다라비오요 CONFIRMED 이적(토트넘) 직후(2026-09-02) 공백을 메우기 위해 신규 산출됐고, cb_bpd/Aggressive fit_sim .844로 백3 CB 중 최고 적합값(콜윌.720·아체암퐁.635보다 높음)이다. 실제 Fulham전 백3(콜윌LCB·라크루아CCB·아체암퐁RCB) 조합과도 독립적으로 일치한다. ⭐[2026-09-12 갱신] A- → B+ 하향(잠정). 유지 근거: 알론소 공식전 5경기 전부 선발 90분(450분) — 전 경기 풀타임 CB이고 FC27 OVR82로 첼시 CB 최고. 하향 근거(실측>서사): 평점이 풀럼 8.0 → 루턴 7.4 → 브라이턴 6.2 → 아스날 6.6 → 리즈 6.1로 하락하고, 아스날전 25분 하베르츠 동점골 장면 지목(report 34; obs#562 사슬에서 라크루아+네투 흡인), 리즈전 48분·75분 실점 모두 개인 책임 특정(obs#598, SI 1차 분석). PL 3경기 평균 6.93·EFL컵 2경기 6.75(v_player_season_stats).','백3 중앙. 소시에다드전 첼시 데뷔전에서 백3 중앙(콜윌 좌·포파나 우)을 맡아 전진 없이 배급형으로 남는 형태였다. Fulham전에서는 박스까지 올라가 수비수를 벗기고 어시스트를 기록해 데뷔전보다 공격 관여도가 높았다. ⭐[2026-09-12] PlayStyles 궤적: FC25 출시판(2024-09-13, 볼프스부르크) 없음 → FC26 출시판(2025-09-12, 팰리스) Long Ball Pass·Jockey → FC27 09-10판(첼시) Long Ball Pass·Jockey·Intercept·Aerial Fortress(2종 추가). AcceleRATE Lengthy 전 버전 유지, 오른발. Aerial Fortress·Intercept 추가는 FotMob PL 25/26 공중볼 승 119(백분위94)·인터셉트 45(94)·클리어 252(97)와 정합. Long Ball Pass는 정확한 롱볼 84(88)와 일치. 첼시 실측에서는 배급형(루턴 패스 85/82 96%·아스날 48회 90%)과 대인형(리즈 RCB cb_stopper .790)이 경기별로 갈린다 — obs#175 「BPD 2명 사이의 힘 있는 수비수 1명」 원형과 대조 필요.','FC27 OVR82 CB — 스쿼드 CB 중 최고 종합능력치, 수비83·피지컬82·가속86으로 스피드형 파워 CB다. AcceleRATE Lengthy. PL 25/26(전 소속 추정) 35경기(35선발) 3087분 1골2도움 평점7.04로 풀타임 검증 완료. fotmob_traits(CB군) 공중볼86·수비행동82 상위권으로 전통적 CB 지표가 강하다. ⭐[2026-09-12] OVR 궤적: FC25 출시판 76(CB, PAC88/SHO41/PAS55/DRI67/DEF76/PHY77) → FC26 출시판 79(88/40/57/67/80/82, Δ+3) → FC26 시즌말 라이브(2026-07-23) 81(88/41/57/67/81/82, 시즌 내 +2) → FC27 출시판(09-10) 82(86/45/61/67/83/82). FC27 vs FC26 출시판 +3(fut.gg 표기 Δ+3과 일치), vs FC26 라이브 +1·PAC−2·SHO+4·PAS+4·DEF+2. 세부(FC27 attrs): 질주93·스탠딩태클84·차단84·공격성83·점프83·힘83·수비위치82·반응82·헤딩79·긴패스73 강점, 가속78(FC26 출시판 82에서 −4)·민첩63·균형56 약점. 강점 갱신: 풀럼전 도움(xA .20). 약점 갱신: 몸싸움에 밀린 실점(리즈 48분)·박스 마킹 실패(75분).','PL 25/26 35경기(전 경기 선발) 3087분 평점7.04·1골2도움으로 풀시즌 주전급 생산성이 검증됐다. fotmob_traits 공중볼86·수비행동82·슛시도66 백분위로 수비·제공권 모두 상위권이나 기회창출17은 낮아 빌드업 관여보다 순수 수비형에 가깝다. 단 이 스탯은 이적 전 소속 클럽 값이며 첼시·알론소 체제 스탯이 아니다(불변규칙 7 유의). ⭐[2026-09-12] fotmob_detail_stats PL 25/26(팰리스, 3087분): 클리어 252(백분위97), 수비행동 375(97·per90 10.93/86), 공중볼 승 119(94, 승률 61.3%/61), 인터셉트 45(94), 정확한 롱볼 84(88), 터치 2224(86), 성공패스 1460(81), 패스 성공률 88.2%(60), xG 2.38(84), 경합 승률 61.3%(57). 26/27 FotMob 미수집. 알론소 공식전 실측(player_matches): 풀럼 CCB 90분 8.0(도움 1·xA .20·태클 5·경합 7승10패·툴x 49.1) · 루턴 LCB 90분 7.4(4-2-3-1·hp105·툴x 46.9) · 브라이턴 CCB 90분 6.2(점유 26%·툴x 56.4) · 아스날 CCB 90분 6.6(경합 5승3패·경고·툴x 62.0) · 리즈 RCB 90분 6.1(4-3-3·툴x 58.1). v_player_profile n=6(소시에다드 포함) 평균 6.83·512분.','HIGH — (교차 투영 — 실측 아님) 에메리의 3백 중앙은 공중볼 지배력+안정적 배급을 요구하는데 라크루아의 공중볼86 백분위와 소시에다드전 패스 100%(56/56)가 이를 뒷받침한다.','HIGH — 실측 근거: prescriptions fc26:opt:CCB(starter=1, cb_bpd/Aggressive .844, 백3 CB 중 최고값), squad_entries CB(rate_v6.7). 소시에다드전 실측 tool_x57.5가 CCB 앵커(57)와 Δ0.5로 거의 정확히 일치 — 위치·적합 양쪽 모두 최상위다. 아다라비오요 CONFIRMED 이적(2026-09-01/02) 직후 백3 재계산에서도 콜윌LCB+라크루아CCB+아체암퐁RCB 조합이 최댓값이었고 이는 실제 Fulham전 선발과 정확히 일치한다(독립 수렴). ⭐[2026-09-12] HIGH 유지(기용 축) / 역할은 재판정 필요. 첼시 실측 우선: prescriptions fc26:opt:CCB cb_bpd/Aggressive .844(starter=1)은 소시에다드 1경기 값이고, 공식전 단일 경기 fit은 브라이턴 CCB .769 · 루턴 LCB .734 · 아스날 CCB .7065(2위 cb_stopper .539) · 리즈 RCB cb_stopper/Aggressive .790으로 전부 .70 이상이나 역할이 bpd↔stopper로 갈린다. 26/27 포지션이 CCB 3·LCB 1·RCB 1로 갈려 포지션-순수 집계 불가(report 34). 알론소가 5경기 전부 선발한 사실과 obs#175(CCB=힘 있는 수비수) 원형은 HIGH를 지지하고, 실점 책임 2경기(obs#562·#598)는 fit이 아니라 폼 축으로 분리해 기록한다.','MEDIUM-HIGH — (교차 투영 — 실측 아님) 이라올라의 하이라인 체제는 스피드 있는 CB를 요구하는데 라크루아의 가속86은 스쿼드 CB 중 최고 수준이라 부합도가 높다.','fotmob_season_stats PL 25/26(35경기 1G2A); fotmob_traits(CB군); player_duties CCB(소시에다드·Fulham); prescriptions fc26:opt:CCB(starter1, cb_bpd/Aggressive .844, 2026-09-02 아다라비오요 이적 후 충원); squad_entries CB(rate_v6.7, .844) | 2026-09-12 갱신: player_game_stats FC25(2024-09-13)·FC26(2025-09-12·2026-07-23)·FC27(2026-08-21·08-22·08-31·09-10); fotmob_detail_stats PL 2024/2025·2025/2026; fotmob_season_stats PL 2025/2026; player_matches 26/27 n=6; match_player_reports 5·25·26·27·34·36; v_player_season_stats(PL 3G 6.93·EFL컵 2G 6.75); prescriptions fc26:opt:CCB; squad_entries CB; player_market_values 2026-08-01 €41.8m; player_status contract_end 2032-06-30; obs#175·#177·#324·#562·#598','소시에다드전 1경기(62분) 표본에 기반한 커널값이고, 등번호 미배정 상태(첼시 공식 스쿼드 페이지, 2026-08-21 기준 확인)였다. 알론소 공식전(Fulham전) 데이터는 duties execution에만 기록돼 있고 squad_entries·prescriptions는 프리시즌 표본 기준임에 유의. ⚠️ 2026-09-12: 공식전 5경기 표본이나 포지션 3종 혼재로 시즌 처방 재산출 미실행(.844는 여전히 프리시즌 1경기 값). 평점 하락 추세는 5경기 표본이고 브라이턴전(26% 점유)·리즈전(컵 로테이션)은 팀 요인이 큼. 실점 책임은 아스날전 프랑스어 매체·리즈전 SI 단일 1차 분석 기반(MEDIUM-HIGH). 26/27 FotMob 미수집. FC26 라이브 행 attrs 결손 — 세부 Δ는 FC26 출시판↔FC27만 산출.','2026-09-12','FotMob 지표(CB군 백분위, 이적 전 소속) 기준 공중볼86·수비행동82·터치45로 수비 지표 전반이 상위권이고, 기회창출17로 빌드업 관여는 낮은 전형적 수비형 CB 프로필이다. 3087분(풀시즌급) 표본이라 신뢰도가 다른 CB 대비 높다.');
INSERT INTO player_evaluations VALUES(118,2,65,'A- — 밀란전 90분 평점7.7(첼시 입단 후 첫 90분 완주)로 알론소 체제 실측이 가장 두터운 선수 중 하나다. duties 커널 dm_dlp(딥라잉 플레이메이커)/Roaming fit_sim .913로 강한 정합을 보였다. squad_entries CM cm_holding/Defend fit_sim.831도 상위권. 부상 이력(24/25 선발10회, 26-07 햄스트링)이 최대 리스크다. ⭐[2026-09-12 갱신] A- 유지. 첼시 공식전 실측이 가장 두터운 축에 든다 — 26/27 PL 3경기 전부 선발(풀럼 65분 7.31·브라이턴 68분 7.5 ⚽1·아스날 60분 6.8), 평균 7.2(193분), EFL컵 루턴 22분 6.6. prescriptions#483 measured LDM 3경기 포지션-순수 cm_dlp/Build-Up .746·평균 7.33·218분(09-07 재집계). 아스날전은 cm_b2b/Ball-Winning .8709로 필드 최고 적합(리포트 34). 리스크는 부상보다 「60~68분 교체 3경기 연속」의 부하 관리 패턴 — 60분 교체는 개인 부진 아닌 중원 통제 회복 패키지(obs#526). 26/27 player_status에 부상 행 없음.','백라인 앞 딥 스크린. 단독 6번 또는 더블 피벗의 한 축이며 압박 저항이 최대 강점으로 반복 지명된다. 밀란전에서 모드리치 대인 마킹 임무를 수행했고, 카이세도가 파괴자 역할을 분담한다는 본인 발언이 있다. ⭐[2026-09-12] PlayStyles: FC25 출시(2024-09-13) 없음 → FC26 출시(2025-09-09) Technical → FC27 출시(2026-09-10) Pinged Pass(Technical 소멸). Pinged Pass 부여는 실측 프로필과 강정합 — PL 25/26 라인브레이킹 패스 10.27/90(백분위93)·롱볼 정확도 85.7%(백분위100)·패스 정확도 92.6%(96). 서사 「압박 저항 딥 스크린」(duties#33)은 PS로 표현되지 않았다(Press Proven 없음). AcceleRATE Controlled 유지. 첼시 실측은 시즌 집계 cm_dlp/Build-Up(.746) ↔ 아스날 단일경기 cm_b2b/Ball-Winning(.871)로 갈려 「배급형 6번」과 「볼 회수 피벗」 두 얼굴이 공존.','FC27 OVR78 CDM — 수비77·패스74·드리블78로 밸런스형 6번. AcceleRATE Controlled. PL 25/26 12경기(4선발) 377분 평점6.41로 부상 관리 구간의 제한된 출전량. fotmob_traits(미드필더군) 터치91 최상위, 득점0·수비행동13·기회창출17은 6번 역할 특성상 낮게 나온다. ⭐[2026-09-12] OVR 궤적: FC25 출시 75 CDM(PAC67/SHO50/PAS70/DRI75/DEF73/PHY73) → FC26 출시 78(69/52/72/77/77/75, Δ+3 vs FC25 출시) → FC26 시즌말(07-23) 78 POT85(69/52/74/78/77/74) → FC27 출시 78(66/52/74/78/77/72, Δ0 vs FC26 시즌말; vs FC26 출시 PAC −3·PHY −3·PAS +2·DRI +1). attrs FC26 출시→FC27: 시야 75→80·짧은패스 79→81·볼컨 78→80·침착 78→81 상승 / 가속 71→67·질주 68→66·체력 65→56·점프 80→77 하락. 체력 56은 실측 「60~68분 교체 3연속」과 정합. FC25→FC26 출시에서 차단·수비위치 73→78로 이미 수비축 정착. 강점: 배급(PAS74·시야80)·DEF77. 약점: 체력·스피드 하향.','PL 25/26 12경기 377분 평점6.41로 출전 자체가 제한적이었다(부상 관리). 반면 알론소 체제 밀란전 실측(90분7.7)은 터치68·리커버리8·듀얼4/6·패스60중58성공(96.7%)로 외부 보도 수치(68터치·8리커버리·97%)와 독립 일치해 신뢰도가 높다. 라인 사이 패스 성공 4.57/90(PL 미드필더 1위)·볼 상실 5.75/90(3번째로 적음, 24/25 시즌)도 인용된다. ⭐[2026-09-12] 최신 FotMob 시즌 PL 25/26(377분, 소표본): 패스 정확도 92.6%(백분위96)·롱볼 정확도 85.7%(100)·라인브레이킹 43회 10.27/90(93)·공중볼 승률 75%(96)·터치 82.8/90(91)·듀얼 승률 57.9%(81) ↔ 기회창출 1(4)·xG 0.20(12). 26/27 FotMob 미수집. 09-02 이후 실측: 09-06 아스날 RCM 60분 6.8·태클 1·인터셉트 1·터치 37·hp 46(리포트 34). 26/27 PL 3경기 193분 1골 평균 7.2(v_player_season_stats). 시장가치 2026-08-01 €29.5m(06-01 €36.4m에서 하락). 계약 2030-06-30.','HIGH — (교차 투영 — 실측 아님) 에메리 체제의 압박 저항형 피벗 요구에 라비아의 딥라잉 플레이메이커 프로필(패스 성공률96.7%, 라인 사이 패스 1위)이 정확히 부합한다.','HIGH — 실측 근거: duties 커널 dm_dlp/Roaming fit_sim .913(2위 dm_dlp/Build-Up .798, Δ.115로 노이즈 구간 밖)이 서사(딥스크린+압박저항+라인사이배급)와 강정합. squad_entries CM cm_holding/Defend fit_sim .831도 상위권. 밀란전 90분 완주는 알론소 체제 첫 90분 완주 기록이라는 점에서 신뢰 지위가 다른 선수보다 높다. ⭐[2026-09-12] HIGH 유지. 첼시 소속 실측이 근거 — prescriptions#483 measured(regime 2, 3경기 218분) cm_dlp/Build-Up .746, 아스날전 단일 cm_b2b/Ball-Winning .8709(필드 최고), 브라이턴전 cm_b2b/BW .651(점유 26% 왜곡 경기). squad_entries CM cm_holding/Defend .831·duties#33 dm_dlp/Roaming .913은 밀란전 프리시즌 1경기 기반이라 시즌 measured(.746)가 우선 근거로 교체된다. 시즌 dlp ↔ 단일 b2b 갈림은 상대(아스날 고압박)에 따른 국면 차이로 읽히며 처방 변경 근거는 아직 아님. 3경기 연속 60분대 교체는 적합이 아닌 부하 관리 변수.','MEDIUM — (교차 투영 — 실측 아님) 이라올라의 고강도 볼 회수 요구에 라비아의 딥스크린형 배급 스타일은 부분적으로만 부합한다 — 활동반경보다 정적 배급에 특화된 프로필이라 완전한 매치는 아니다.','fotmob_season_stats PL 25/26(12경기); fotmob_traits(미드필더군); player_duties LDM+LCM(밀란·Fulham); squad_entries CM(rate_v7.7, cm_holding/Defend .831) | 2026-09-12 갱신: player_game_stats FC25 2024-09-13(#758)·FC26 2025-09-09(#759)·2026-07-23(#546)·FC27 2026-09-10(#610) / prescriptions#483(measured 2026-09-07) / player_matches#4065·#4081·#4104·#4322 / match_player_reports 25·26·27·34 / player_duties#33·#181 / obs#526 / fotmob_detail_stats PL 2025/2026 / fotmob_traits(MF군) / v_player_season_stats 2026-27 / player_market_values 2026-08-01 / player_status 2026-08-21','부상 이력이 지배적 캐비앗(24/25 선발10회, 26-07 햄스트링). PFF 등급은 404 경유 스니펫이라 저신뢰. 피벗 구성 서사도 소스 충돌(카이세도+엔소 예상 vs 실제 카이세도+라비아 선발). ⚠️ 2026-09-12: 첼시 공식전 4경기 중 90분 완주 0회(65·68·60·22분) — 시즌 measured n=3은 전부 부분 출전 표본. 25/26 FotMob 백분위는 377분 소표본(per90 백분위와 합계 백분위가 크게 갈림, 예 successful_passes 12↔94). 26/27 FotMob 미수집. FC26 시즌말(sofifa 07-23) 행은 attrs·PS 미수집이라 세부속성 Δ는 FC26 출시(fut.gg)→FC27 출시(fut.gg)로만 계산했다.','2026-09-12','FotMob 지표(미드필더군 백분위) 기준 터치91로 볼 관여도가 매우 높고 나머지(득점0·기회창출17·수비행동13)는 낮다 — 이는 약점이라기보다 6번(딥스크린) 역할 특성상 자연스러운 프로필이다. 압박 저항·배급형 미드필더의 전형적인 지표 분포로 읽힌다.');
INSERT INTO player_evaluations VALUES(119,2,94,'⚠️ CONFIRMED 이적 완료(2026-09-01, 첼시→토트넘 완전이적 £7m+애드온, 5년계약) — 이 평가는 첼시 소속 마지막 시점 기준 회고적 기록이다. prescriptions fc26:opt:CCB 행의 starter는 이적 확정으로 0으로 해제되고 후임 라크루아로 대체됐다(2026-09-02 rationale). 조호르전 CCB 90분 평점6.2(경고)가 알론소 체제 유일 실측이며 좌표 결손으로 정성 평가만 존재하고, 조호르전 현지 평가는 부정적(역습대응·빌드업 곤란)이었다.','백4일 때(유벤투스) LCB, 백3일 때(조호르) CCB — 수불로예·안셀미노 사이 가장 낮은 꼭짓점. 알론소 서사(볼플레잉 CB 2명 사이 파워 CB 1명 구조)에서 중앙 파워 CB 역할의 실제 배치 사례를 제공했으나(obs#175/#198 참조), 표본 1경기·평점6.2·부정적 정성 평가·이후 CONFIRMED 이적으로 obs#198의 ''CCB 미정'' 판정을 뒤집지 못했다.','FC27 OVR77 CB — 수비77·피지컬78로 준수한 종합능력치. AcceleRATE Lengthy. PL 25/26(마레스카·로즈니어 체제) 16경기(8선발) 789분 평점6.69. fotmob_traits(CB군) 공중볼95·터치99 최상위권, 득점86도 높다.','PL 25/26 16경기 789분 평점6.69(마레스카·로즈니어 체제 값, 알론소 귀속 금지). fotmob_traits 공중볼95·터치99·수비행동75로 CB 지표 전반이 상위권이나, 이는 알론소 체제 이전 데이터다. 알론소 체제 실측은 조호르전 1경기(90분6.2)뿐이다.','MEDIUM — (교차 투영 — 실측 아님, 회고적) 에메리의 3백 중앙 파워 CB 요구에 부합할 신체 조건은 있으나 조호르전 정성 평가(빌드업 곤란)가 부정적이었다.','LOW-MEDIUM — 실측 근거: squad_entries CB rate_v6.6, cb_bpd/Aggressive fit_sim .891(수치상 라크루아 .844보다 높음)이나 실측 위치 tool_x48.0이 CCB 앵커(57)와 Δ−9.0로 어긋나 있어 ''적합값은 높지만 자리 정합은 낮은'' 모순 사례로 별도 기록돼 있다. 좌표·정성 평가 모두 결손·부정적이었고 최종적으로 CONFIRMED 이적(2026-09-01)으로 알론소 체제 편입이 종료됐다.','LOW-MEDIUM — (교차 투영 — 실측 아님, 회고적) 이라올라의 하이라인 체제에 필요한 커버 스피드·리커버리가 서사상 약점으로 지목됐다.','fotmob_season_stats PL 25/26(16경기); fotmob_traits(CB군); player_duties CCB(유벤투스·조호르); prescriptions fc26:opt:CCB(2026-09-02 starter 해제, 후임 라크루아); squad_entries CB(rate_v6.6, cb_bpd/Aggressive .891); transfer_outgoing(CONFIRMED, Tottenham, 2026-09-01)','⚠️⚠️ [2026-09-02] CONFIRMED 이적 완료(토트넘, £7m+애드온, 5년계약) — 이 평가는 첼시 이탈 시점의 회고적 기록이며 향후 알론소 체제 실측 축적이 없다. 좌표·map25 0으로 fit_sim(.891)과 실측 위치(Δ−9.0)가 상충하는 모순이 별도로 기록돼 있다. 풀럼 시절(마르쿠 실바) 서술이 스카우트 자료 다수, 25/26 PL 스탯은 마레스카·로즈니어 체제 값이다.','2026-09-02','FotMob 지표(CB군 백분위, 마레스카 체제) 기준 공중볼95·터치99·수비행동75·득점86으로 종합 지표가 매우 높다. 다만 이 지표는 알론소 체제 이전 값이고 선수 본인도 이적이 확정돼 알론소 체제에서의 검증 기회 자체가 사라졌다는 점을 감안해야 한다.');
INSERT INTO player_evaluations VALUES(120,2,1,'B — 첼시 GK 1선 즉시 교체(2026-08-30 £7.5m 영입, 발표 당일 브라이턴전 선발·산체스 제외)로 지위는 확정적이지만 알론소 체제 표본은 1경기(4-3 승, 3실점)뿐이라 첼시 축 등급은 잠정이다. AVL 25/26 시즌 실측(64경기, 평점 7.06, 선방률 70.9%·백분위 85)이 여전히 판단의 실질 근거다. ⭐[2026-09-12 갱신] B 유지(상향 대기). 첼시 실측이 1→2경기로 늘었고 둘 다 상위 평점이다 — 08-30 브라이턴 8.1(세이브 4), 09-06 아스날 8.4(세이브 8, 리포트 34 「실질 MOM」), 26/27 PL 2경기 평균 8.25(v_player_season_stats). 09-09 리즈(EFL컵)는 펜더스 출전으로 미출전. 아스날 동점골 책임은 소수(니어포스트 비판 3소스) 대 다수(세이브 산출 우호)로 정리됐고 1차 전술 분석은 피벗 보호 결손을 지목한다(obs#563) — GK 개인 등급을 내릴 근거 아님. 표본 2경기라 B 이상 확정은 보류.','짧은 빌드업 개시 GK — 골라인 고정형(평균 x~10.1~10.5), 좌우 폭 전체를 얕게 커버. 스위핑은 상시가 아니라 상황부(player_duties#1). 33세(1992-09생)·3년 계약. ⭐[2026-09-12] PlayStyles 궤적: FC25 출시(2024-09-10) Footwork·Rush Out+ → FC26 출시(2025-09-09) Footwork·Rush Out(+ 소멸) → FC26 시즌말 sofifa(2026-06-30) 긴패스·돌진 블로킹 → FC27 출시(2026-09-10) Long Ball Pass·Rush Out·Far Reach+. Footwork가 빠지고 Long Ball Pass가 들어온 방향은 첼시 실측과 정합 — 브라이턴전 패스 38/16(42%)·롱패스 14성공(리포트 26 「설계된 롱 분배」), 아스날전 롱볼 18/49(37%)(duties#193). 골라인 고정형(avg_x 9.85·10.48)은 빌라 시절과 동일. Far Reach+ 신설은 세이브 8회 경기와 방향 일치하나 EA 부여 근거는 미수집.','하이볼 처리·선방 효율은 AVL 25/26 리그 상위(하이볼 48회 백분위 100, 선방으로 막은 실점 +3.52 백분위 92). 배급 볼륨도 상위(성공 패스 893회 백분위 87). 약점은 실책→실점 3회(하위 5%)와 실점 39골(백분위 26) — 막는 능력은 상위, 사고 빈도는 하위라는 양면이 공존한다. 첼시 이적 후 이 프로필이 그대로 재현될지는 미검증. ⭐[2026-09-12] OVR 궤적: FC25 출시 87(DIV84/HAN82/KIC83/REF86/SPD56/POS87) → FC26 출시 85(83/82/82/85/56/85, Δ−2 vs FC25 출시) → FC26 시즌말 85(83/81/82/85/56/85, HAN −1 vs FC26 출시) → FC27 출시 85(83/81/82/85/50/85, Δ0 vs FC26 시즌말·출시). 유일한 유의 변화는 SPD 56→50(FC26 출시 대비 −6; attrs 가속 55→50·질주 57→49). 반응력은 FC25 84→FC26 출시 81→FC27 79로 완만 하락(34세 노화 곡선). 강점(POS85·REF85·DIV83) 유지, 약점은 스피드·스위핑 범위 축소 — 실측 골라인 고정형이라 게임상 손실은 제한적.','AVL 25/26 Fotmob 20지표(2835분): 클린시트 7·실점 39·평점 7.07(팀 자체 산정). CHE 이적 후 표본은 2026-08-30 브라이턴전 1경기(SofaScore 평점 8.1, 90분, 선방 4, 클리어런스 1, 패스 38/성공률 저조 16, xA 0.014)뿐이라 첼시 리그 백분위는 아직 산출 불가. ⭐[2026-09-12] 26/27 첼시 FotMob 시즌·백분위 미수집(fotmob_detail_stats 최신 시즌은 AVL 25/26: 선방률 70.9% 백분위85·goals_prevented +3.52 백분위92·하이클레임 48 백분위95·성공패스 893 백분위92·실책→실점 3 백분위5). 09-02 이후 첼시 실측: 09-06 아스날 원정 90분 8.4·세이브 8·터치 49·리커버리 8·hp 58(player_matches#4317, 리포트 34). 26/27 PL 2경기 평균 8.25(180분, 무실점 0). 시장가치 2026-08-01 €16.76m(AVL 표기, 06-01 €20.69m에서 하락). 계약 2029-06-30(player_status 08-21).','HIGH(실측) — AVL 체제 원 데이터(player_evaluations id=?, regime_id=1)와 동일. 에메리의 빌드업 요구(풀백·CB 배급 고정)와 실측 정합이 이미 확인됐다. 단 그는 이미 이적했다 — 회고적 참고값.','LOW confidence(가설) — squad_entries의 CHE 커널 적합(gk_goalkeeper/Defend 0.961)은 AVL 그리드를 그대로 이관해 재산출한 값이라 첼시에서 관측된 위치가 아니다(불변규칙 7). 알론소 체제 GK 빌드업 관여 요구를 밝힌 1차 발언·서사가 0건이고 실측도 1경기뿐이라 적합도를 등급으로 단정하지 않는다. player_duties#193 참조 — 3경기 이상 쌓이면 재판정 예정. ⭐[2026-09-12] LOW 유지(가설 지위 — 「적합도 판정 불가」의 뜻). ⑴ 첼시 소속 실측 2경기(브라이턴·아스날) 단일경기 fit gk_goalkeeper/Defend 0.9388(아스날, 2위 Balanced 0.931)로 정본 유지에 이견 없음(리포트 34). ⑵ 그러나 GK 커널은 판별력이 없고(squad_entries#133 캐비앗), 알론소 체제 GK 빌드업 관여 서술은 D+3까지 전 언어권 0건 — 오히려 「골키퍼에서 길게 갈 의향」 서술 + 롱볼 37%가 반대 방향(duties#193). ⑶ squad_entries map25는 여전히 AVL 25/26 이관본(불변규칙 7). ⇒ 첼시 실측 avg_x·롱볼 비율이 3경기+ 쌓이면 gk_goalkeeper/Defend 확정 후보.','교차 투영 — 실측 아님. AVL·CHE 두 체제 실측만 있고 리버풀 이적 시나리오는 근거가 없다. 이라올라의 고압박·하이라인 체제는 배후 스위핑 GK를 선호하나 마르티네스의 실측 발자국은 골라인 고정형이라 적합도는 낮게 잡는다(참고: player_evaluations regime_id=1의 동일 판단).','player_duties id=193(regime_id=2) · squad_entries id=133(CHE, CONFIRMED, map25 AVL 이관) · transfer_targets(team_code=CHE, player_id=1, CONFIRMED) · player_matches id=4076(2026-08-30 브라이턴전) · fotmob_season_stats(AVL 2025/2026, 8행) · player_evaluations id 기존행(regime_id=1, AVL 원 평가) 대조 | 2026-09-12 갱신: player_game_stats FC25 2024-09-10(#736)·FC26 2025-09-09(#737)·FC26 2026-06-30(#1)·2026-07-23(#83)·FC27 2026-09-10(#593) / player_matches#4076·#4317 / match_player_reports 26·34 / player_duties#193(09-08·09-09 추가) / obs#563 / fotmob_detail_stats AVL 2025/2026 / player_market_values 2026-08-01 / player_status 2026-08-21 / v_player_season_stats 2026-27','첼시 축 표본이 1경기뿐이라 이 평가의 CHE 고유 결론(strengths 재현 여부·fit_alonso)은 전부 잠정이다. AVL 축 수치(stat_eval 대부분)는 이적 전 팀 데이터이므로 회고적 참고로만 쓸 것 — 불변규칙 7. 다음 정기 수집에서 CHE 표본 3경기 이상 확보 후 재작성 필요(player_duties#193과 동일 유보). ⚠️ 2026-09-12: 첼시 실측 2경기(둘 다 PL, 컵 미출전)로 여전히 소표본. 26/27 FotMob 지표·백분위 미수집. FC25·FC26 출시판은 fut.gg base 아이템(MEDIUM-HIGH)이고 FC26 시즌말은 sofifa라 소스가 다르다 — Δ는 표기한 기준 시점 대비로만 읽을 것(obs#249). 아스날 동점골 책임은 소스 분산(ES 4 · football.london 5 ↔ SI 7.5 · Foot Mercato 8.0) 충돌 기록.','2026-09-12','AVL 소속 시절 Fotmob 지표(25/26 PL)로 본 서술형 평가: 클린시트 7·실점 39·평점 7.07의 시즌 성적. 첼시 이적 후 아직 Fotmob 시즌 통계가 별도 집계되지 않아 이 서술은 이적 전 팀 소속 데이터에 근거한다.');
INSERT INTO player_evaluations VALUES(121,3,207,'B(잠정) — 2024-25 프랑크푸르트 시즌 st_advanced/Support 코사인 .712(measured:season, n=46). 리버풀 데뷔 시즌(2025-26) 팀 내 최다골(17골/45경기)이나 2026-04 아킬레스건 파열로 Iraola 체제 실전 표본 0.','하이브리드 9번 — 배후 침투 본능 + 좌측 폭 연계/드리블. 분데스리가 캐리발 슈팅 1위(Opta).','침투 타이밍·1대1 돌파·연계 플레이. 약점: 순수 포처형 마무리 안정성은 상대적으로 낮음(TFA 대조 평가).','FC27(2026-09-10) 신규 게임 스탯: OVR85 · PAC86/SHO83/PAS72/DRI84/DEF33/PHY73, 키189cm·몸무게70kg, PlayStyles Finesse Shot·Chip Shot·Technical. ⚠️ FC26 카드 자체가 없다(신규 합류 이후 최초 수집) — 세대 간 변화 비교 불가, 절대치만 참고. Fotmob 2026-09-10 재수집(41지표, 2025/26 프리미어리그 29경기 1810분): 드리블 38회(96백분위)·xA 2.67(96)·어시스트 4(90)·기회 창출 21(84)·패스 정확도 76.8%(86)로 연계형 수치가 최상위권이나 파울 35회(18, 하위권)·볼 탈취당함 26회(33)로 볼 관리 규율은 약점. 2024-25 분데스리가(프랑크푸르트) 33경기 15골·8도움 평균7.27과 비교하면 리버풀 이적 첫 시즌(PL 29경기 11골·4도움 평균6.92)은 골 기여가 소폭 하락하고 연계 비중이 커졌다. Iraola 체제(2026-27) 실전은 여전히 0경기(아킬레스건 파열 재활) — player_matches·v_player_season_stats에 2026-27 행 없음.','LOW — 에메리 체제 실측·duties 없음(교차 투영 아님, AVL 소속 경력 없음).','MEDIUM — 알론소 CHE는 ST 최종라인 침투형을 선호(Emegha duties 참고) — 유사 성향이나 직접 교차 데이터 없음(추정).','MEDIUM — Iraola 체제 실전 표본 0(부상 지속, 2026-09-11 기준 재활 중). FC27 PlayStyles(Finesse/Chip/Technical)는 페널티박스 가장자리 마무리형 프로필을 지지하나, Iraola의 고강도 수직 프레스에 필요한 DEF33·PHY73은 낮아 압박 가담은 파트너 의존적일 개연성(팬매체 추정, 미검증). player_duties #obs 신규 관찰 없음.','core.aggregate/core.kernel(measured:season) · 서브에이전트 서사 조사(프랑스어·독일어·영어) · fotmob_season_stats | stat_eval 2026-09-11 갱신: player_game_stats(FC27, roster_date=2026-09-10) · fotmob_detail_stats(재수집 2026-09-10, PL 2025/26 41지표 + Bundesliga 2024/25) · v_player_season_stats','MEDIUM — FC27 신규 스탯 확보로 게임 프로필은 보강됐으나 Iraola 체제 실전 표본은 여전히 0, 비교용 FC26 카드 부재','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(122,3,208,'B−(잠정) — 2024-25 파르마 시즌 cb_bpd/Aggressive 코사인 .799(measured:season, n=17). 리버풀 공식전 1경기 후 ACL 파열, 2026-27 실전 표본 0.','빌드업형 센터백 — 백3 우측 주 포지션(86%), 높은 라인·예측형 1대1(블록 84th pct).','공중볼 대응·전진 패스 잠재력. 약점: 세리에A 기준 빌드업 관여도(전진패스·드리블)는 평균 이하로 평가됨.','FC27(2026-09-10) 신규 게임 스탯: OVR71 · PAC57/SHO30/PAS54/DRI58/DEF72/PHY68, 키193cm·몸무게79kg, PlayStyles 없음. ⚠️ FC26 카드 자체가 없다(신규 합류 이후 최초 수집) — 세대 간 비교 불가. Fotmob 2026-09-10 재수집(2024-25 세리에A, 파르마): 드리블 성공률 100%(100, n=3 소표본 왜곡 주의)·듀얼 승률 60.6%(70)·공중 경합 승률 63.0%(68)로 1대1·공중 대응은 상위권이나 볼 리커버리 34회(29)·듀얼 승 43회(27)는 세리에A 평균 이하 — 기존 duties의 ''빌드업 관여 평균 이하'' 평가와 정합. 2025-26 리버풀 이적 후 Premier League 1경기(v_player_season_stats)·EFL Cup 1경기(81분, 평점7.1)뿐이고 그 직후 ACL 파열. 2026-27 Iraola 체제 실전은 0경기.','LOW — 에메리 체제 실측·duties 없음.','LOW — 알론소 CHE 실측·duties 없음, 이적 후보 아닌 LIV 소속.','MEDIUM — Iraola의 강도·수직성과 피지컬(193cm)·듀얼/공중 경합 상위권(각 70·68백분위)이 부합할 것이라는 분석가 전망은 유지되나 여전히 실전 미검증. FC27 DEF72는 포지션 대비 평범한 수준으로, ''수비형 잠재력이 매우 높다''는 서사보다는 보수적으로 읽어야 한다.','core.aggregate/core.kernel(measured:season) · 서브에이전트 서사 조사(이탈리아어·영어) | stat_eval 2026-09-11 갱신: player_game_stats(FC27, roster_date=2026-09-10) · fotmob_detail_stats(재수집 2026-09-10, Serie A 2024/25) · v_player_season_stats','LOW — 20세 미만, 실전 표본 극히 얇고(세리에A 위주) FC26 비교 불가, ACL 재활로 Iraola 체제 실전 0','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(123,3,209,'B+ — 2025-26시즌(Slot 말기) fb_att_wb/Support 코사인 .918(measured:season, n=28). 리버풀 정규 로테이션 라이트백이나 2026-01 무릎 중상으로 Iraola 체제 실전 표본 0.','인버티드 아닌 폭 유지형 오버래핑 라이트백. 카운터프레싱 볼탈취 다수(경기당 9.6회, Klopp 시절 분석).','1대1 수비(태클), 전진 오버랩 타이밍. 약점: TAA 대비 빌드업 인사이드 진입 빈도 낮음(둘의 역할 상반).','FC27(2026-09-10) 신규 게임 스탯: OVR79 · PAC79/SHO62/PAS71/DRI75/DEF76/PHY73, 키181cm·몸무게75kg, PlayStyles 없음. FC26 카드 없음(신규 수집 대상 아니었음) — 세대 간 비교 불가. Fotmob 2026-09-10 재수집: 2025-26 PL(16경기 932분) 파울 획득 20회(57)·패스 정확도 83.9%(55)는 준수하나 드리블 성공률 31.8%(15)·롱볼 정확도 25.0%(10)·듀얼 승률 44.9%(12)로 전진 국면 생산성은 리그 라이트백 대비 하위권 — 2024-25 PL 표본(25경기, xA 1.42·상대 박스 터치 45회 75백분위)보다 오히려 낮아진 흐름. v_player_season_stats 확인 결과 2025-26 PL 16경기 932분 평균6.63(2024-25 25경기 평균6.81 대비 소폭 하락)이 마지막 기록이고 이후 2026-01 무릎 수술로 2026-27 시즌 행 자체가 없다 — Iraola 체제 실전 여전히 0.','LOW — 에메리 체제 실측·duties 없음.','LOW — 알론소 CHE 실측·duties 없음, 이적 후보 아닌 LIV 소속.','HIGH — Iraola 본인이 ''건강하면 우리 라이트백''이라 반복 명시(신규 영입 배제 근거로 직접 인용, player_duties regime_id=3 행). 다만 마지막 실측 시즌(2025-26 PL)의 전진 생산성 지표(드리블 성공률 15백분위·롱볼 정확도 10백분위)가 직전 시즌보다 하락한 채로 부상에 들어갔다는 점은 복귀 초기 폼 리스크로 남는다. 전술 세부는 부상으로 여전히 미검증.','core.aggregate/core.kernel(measured:season) · 서브에이전트 서사 조사(영어) | stat_eval 2026-09-11 갱신: player_game_stats(FC27, roster_date=2026-09-10) · fotmob_detail_stats(재수집 2026-09-10, PL 2025/26 + 2024/25) · v_player_season_stats','MEDIUM — Iraola의 신뢰 발언은 1차 소스로 강하나, 마지막 실측 시즌 지표 하락 추세 + FC26 비교 불가 + 전술 적용 실측 공백','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(124,2,210,'B(잠정) — 실측 그리드·적합값 미산출(CHE 슬롯 테이블에 DM 전용 슬롯 부재 — LCM/RCM 매핑 보류). 2024-25 아약스(Farioli) 시즌 단일 6번 전환 실측 근거는 있으나 2025-26 브렌트포드 시즌 서사 조사는 이번 회차에서 수행하지 못함(브리핑 오류). [2026-09-10 갱신] CHE Alonso 4-2-3-1 Wide 슬롯에 DM(LDM/RDM) 신설 — 브렌트포드 2025-26 PL 실측(22경기)을 투영한 결과 RDM 적합 .816(dm_dlp/Roaming), LDM .737. 등급 B(잠정)→B(실측 근거 보강, 단 CHE 체제 자체 출전 0은 그대로).','딥라잉 피벗/6번 — 리버풀 시절 8번에서 아약스에서 단일 홀딩으로 전환, 리더십·문화적 영향력이 전술과 별도로 두드러짐.','패스 순환·경기 조율·경험. 약점: 35세 활동량·커버리지 한계 — 본인도 인지.','fotmob_season_stats(2025-26 PL, 32경기 1골3도움 평점6.7) · player_tenures 확인. [2026-09-10] core.kernel best_fit_slot 재계산 — map25 0000122358278X73779502331, CHE regime RDM(x60,y42) 대조 필요.','LOW — 에메리 체제 실측·duties 없음.','MEDIUM — Alonso 본인이 2019년부터 관찰한 리더십·압박강도 조절 능력을 영입 근거로 직접 언급. 전술 포지션(딥 미드필더 vs 로테이션)은 아직 유동적으로 서술됨. [2026-09-10] 실측 적합값 산출: RDM(우측 더블피벗) dm_dlp/Roaming .816 — Alonso가 언급한 「리더십·압박강도 조절」 서사와 별개로, 온볼 위치·패스 패턴은 우측 딥라잉 플레이메이커에 가깝다. prescriptions(kind=measured:season, RDM) 참고.','LOW — 이라올라 체제 실측·duties 없음, 이적 후보 아닌 CHE 소속.','chelseafc.com(Alonso·Henderson 1차 인터뷰) · NOS.nl(아약스 시절) · fotmob_season_stats + prescriptions(player_id=210, regime_id=2, RDM, fit .816, 2026-09-10)','MEDIUM — 실측 그리드·CHE 슬롯 적합값 산출 완료(RDM .816). 단 2026-27시즌 CHE 체제 실전 출전은 여전히 0.','2026-09-10',NULL);
INSERT INTO player_evaluations VALUES(125,2,211,'B(잠정) — 2025-26 스트라스부르 시즌 st_advanced/Support 코사인 .654(measured:season, n=9, 표본 얇음). Alonso 본인이 최종라인 침투형으로 직접 규정했으나, CHE 실전 표본은 여전히 0분이다(2026-08-27 EFL컵 루턴전 벤치 등록, 미출전). FC27(2026-09-10) OVR78·PAC88로 스쿼드 내 최상위권 스피드형 스트라이커임이 게임 능치로 확정됐지만 실측은 정지 상태.','지능적 포지셔닝 중심 침투형 9번 — 니어포스트 견제로 파트너 공간 창출, 장거리 스피드 강점. FC27(roster_date 2026-09-10) OVR78: PAC88·SHO76·PAS60·DRI69·DEF31·PHY78, 195cm/82kg. PlayStyles: Low Driven Shot·Enforcer·Game Changer(FC26 행이 DB에 없어 변화폭 비교 불가). 195cm 신장과 PAC88의 속도 결합이 게임 능치로도 침투형 프로필을 뒷받침한다.','특장점: 배후 침투·박스 안 마무리, PAC88의 스피드가 게임 스탯으로도 확인. 약점: 항공볼/롱볼 수신·홀드업이 코치진 개발 영역으로 명시됨(TFA) — FC27 PAS60·DRI69도 낮아 연계·홀드업 약점과 정합. CHE 공식전 여전히 0경기(2026-08-27 EFL컵 루턴전 벤치 대기 후 미출전).','player_matches n=9(2025-26 리그1, 스트라스부르) map25 15X9327468148341133502621, avg_rating 7.22. 2026-09-11 갱신: fotmob_detail_stats(Ligue 1 2025/2026, 34지표)로 축 보강 — 10경기(≈490분) 골 4·어시스트 2·xG 3.90(90분당 0.799, 동포지션 90분당 백분위 100)·유효슛 90분당 백분위 89로 마무리 산출은 상위권이나, 볼 탈취당함 90분당 백분위 97(불리한 쪽)·수비 액션 90분당 백분위 20으로 비소유 기여는 낮다. 표본이 10경기 내외로 여전히 얇고, 이 fotmob 데이터와 player_matches 모두 스트라스부르(Rosenior) 소속 기록이며 첼시·알론소 체제 실측이 아니다(불변규칙 7).','LOW — 에메리 체제 실측·duties 없음.','HIGH — Alonso 본인 기자회견 직접 인용: ''최종 라인에서 공간을 받는 위협형으로 본다''. 임대 이탈 요구를 직접 차단하며 잔류·기회 확대 의사 명시. 2026-09-11 확인: 2026-08-27 EFL컵 루턴전에 벤치 등록됐으나 미출전(0분) — 발언 이후에도 실전 기회는 아직 없다.','LOW — 이라올라 체제 실측·duties 없음, 이적 후보 아닌 CHE 소속.','core.aggregate/core.kernel(measured:season) · teamtalk.com(Alonso 1차 인용) · TotalFootballAnalysis(2026-01-17) · Alsa''Sports(Rosenior 1차 인용) · NOS.nl | 2026-09-11 갱신: player_game_stats FC27(roster_date 2026-09-10, OVR78·PAC88·PlayStyles Low Driven Shot/Enforcer/Game Changer, FC26 비교 데이터 없음) · fotmob_detail_stats(Ligue 1 2025/2026, 34지표) · player_matches(EFL Cup 2026-08-27 vs Luton, 0분 벤치)','MEDIUM — 현 체제 1차 발언은 확보됐으나 실전 표본은 사실상 0(EFL컵 벤치 포함해도 출전 0분). FC27 스탯은 이번이 첫 반영이라 시계열 비교는 불가.','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(126,3,212,'B−(잠정) — 2025-26 아약스 임대 시즌 gk_goalkeeper/Defend 코사인 .961(measured:season, n=32, 2026-02 부상 전까지). 리버풀 3옵션 키퍼로 등록, 2026-27 실전 표본 0.','현대적 스위퍼 키퍼 — 골문 밖 과감한 전진, 패스 타이밍 지연으로 미드필드 수적우위 창출.','배급 범위·미드필드 지원. 약점: 고공볼 대응·중거리슛 포지셔닝(아약스 10월 이후 베테랑에게 자리 내준 원인).','FC27(2026-09-10) 신규 게임 스탯: OVR72 · PAC72/SHO70/PAS71/DRI73/DEF39/PHY71, 키190cm·몸무게88kg, PlayStyles 없음. FC26 카드 없음 — 세대 간 비교 불가. Fotmob 2026-09-10 재수집(2025-26 에레디비시, 아약스 임대): 실책→실점 0(100)·패스 정확도 72.5%(85)·실점 방지 +4.67(82)로 배급·기본 안정성은 상위권이나 PK 실점 3회(8, 하위권)·스위퍼 클리어 3회(31)로 스위핑 반경은 제한적 — 기존 duties의 ''고공볼·중거리슛 대응이 약점'' 평가와 정합. v_player_season_stats 확인 결과 2025-26 에레디비시 23경기(1710분, 평균7.27)가 마지막이고 2026-02 부상 이후·리버풀 복귀 후 2026-27 행 없음 — Iraola 체제 실전 0경기 유지.','LOW — 에메리 체제 실측·duties 없음.','LOW — 알론소 CHE 실측·duties 없음, 이적 후보 아닌 LIV 소속.','LOW — 여전히 Iraola의 개인 지목 발언 미확인. FC27 DEF39는 스쿼드 GK 중에서도 낮은 편으로, ''현대적 스위퍼 키퍼'' 서사가 FC27 카드에도 반영되지 않았다(비교: 알리송은 def50, Rush Out+ 보유). 3옵션 GK로 실전 기회 자체가 제한적이라 체제 적합 검증이 당분간 어려울 전망.','core.aggregate/core.kernel(measured:season) · fcupdate.nl · footballtransfers.com/nl · thisisanfield.com · footballclub.cz(체코어) | stat_eval 2026-09-11 갱신: player_game_stats(FC27, roster_date=2026-09-10) · fotmob_detail_stats(재수집 2026-09-10, Eredivisie 2025/26) · v_player_season_stats','LOW — 3옵션 백업, FC26 비교 불가, Iraola 체제 실전 표본 0 유지','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(127,1,190,'B+ — 2026-08-27 바이에른 뮌헨에서 자유이적 합류 확정(31세). squad_entries에 CAM(cam_playmaker/Build-Up .861, n=6)과 DM(dm_dlp/Roaming .807, n=6) 두 슬롯 실측 보유, 둘 다 바이에른 그리드 기준(콤파니 체제, 불변규칙 7 — 에메리 체제 아님). FC27(2026-09-10) 수집 목록에서 누락되어 FC26(2026-07-23)이 최신 게임 스탯 — OVR81·PAC76·SHO78·PAS79·DRI79·DEF80·PHY80, PlayStyle 5종(파워슛·프리시전 헤딩·예리한패스·에어리얼 포트리스·브루저)으로 필드 최상위권 능치. AVL 실측은 아직 0경기(아스날전 명단 제외, 헐전 미출전).','서사 축은 「6번(딥라잉 배급) vs 8번(박스 도착형)」으로 갈린다. player_duties(#162, season 2025-26)는 바이에른 25/26 정본 슬롯이 콤파니 체제에서 8번이 아니라 6번이었다고 명시 — 파블로비치가 키미히 옆을 차지한 뒤 고레츠카는 "깊은 배급+순환 연결점"으로 재배치됐다(LIGABlatt Stagnation 판정). 반면 영어권 프리뷰·UTV 유튜브 전사는 "박스 도착형 8번" 서사를 반복한다 — 실측(스크리닝 지표 전부 하위)이 이를 지지하지 않아 긴장 상태로 남긴다. 커널 argmax인 CAM(cam_playmaker/Build-Up .861 > LDM dm_dlp/Roaming .807)도 보도 근거 0건인 가설 행이다.','FC26 능치 기준 6대 스탯이 스쿼드 최상위권(SHO78·PAS79·DRI79·PHY80)이고 PlayStyle 5종도 스쿼드 내 최다 수준 — 파워슛·프리시전 헤딩·예리한패스·에어리얼 포트리스·브루저로 슈팅·공중볼·패스 전방위 커버. 189cm 신장의 세트피스 양면 위협. 약점: FC27(09-10) 수집에서 누락돼 최신 게임 밸런스 반영 여부 불명, 31세로 신체 능력 하락 곡선 진입 가능. 공중볼 경합 승률이 24/25 53.4%(백분위 70)에서 25/26 37.3%(16%)로 급락 — 같은 클럽·감독 체제 내 하락이라 시스템 탓으로 돌릴 수 없다.','FotMob/Opta 분데스리가 25/26 41지표(1954분, 31경기 25선발 평점 7.29 — v_player_profile n=10은 클럽 공식전 일부만 반영, 786분/6.95)에서 깊은 배급자로서 실행은 최상위다 — 성공 패스 1479(백분위 93)·패스 정확도 91.4%(94)·롱볼 정확도 68.5%(89, 24/25 55.3%에서 급등)·터치 1897(91). 공격 관여도 6번으로 내려와도 유지 — xG 4.80(93)·슛 35(87)·유효슛 11(84)·상대 박스 터치 41(73)·골 5(89)·xA 3.81(83)·기회창출 21(71). 반면 스크리닝은 전부 하위 — 태클 1.34/90(18)·수비적 행동 4.84/90(43)·지상 듀얼 승률 48.8%(34)·공중볼 승률 37.3%(16). 즉 "깊게 서지만 전진해 때리는 6번"이며 앞을 막는 6번은 아니다. Understat 교차확인: 67슛/33경기·xG 8.33(전 대회)·헤더 11·평균 슛거리 18.1m. FC27(09-10) 게임스탯 수집 결측으로 최신 능치 검증 불가 — FC26(07-23) OVR81이 현재 참조 가능한 유일 값이다.','MEDIUM(잠정) — 에메리 체제 요구 임무는 미확정(2026-08-27 이적 발표까지 빌라 출전 0). fit_sim 상 CAM(.861)이 DM(.807)보다 높지만 서사·바이에른 정본 슬롯은 6번(DM)을 가리키는 반대 방향 신호라 실측 후 재판정 필요. 오나나(ACL) 공백 커버 + CL 로테이션 자원으로 영입됐다는 것이 매체 공통 관측(Tanswell: "피지컬이 뛰어나다 — 오나나 이후 빌라가 보강 필요하다고 느낀 영역").',NULL,NULL,'squad_entries CAM(fit_sim .861, n=6)·DM(fit_sim .807, n=6) 2행, grid_club=Bayern München(콤파니 체제); prescriptions measured:season:full2526·fc26:opt:CAM·fc26:opt:LDM 3행; player_duties 2025-26(CDM, 바이에른 6번 재배치)·2026-27(LDM 가설)·2026-27(CAM 가설, 근거 0건) 3행; v_player_profile n=10(786분); v_player_season_stats(25/26 분데스리가 8선발+국가대표); FC26(roster_date 2026-07-23, OVR81 PlayStyle 5종) — FC27 09-10 수집 목록 누락 확인; fotmob_detail_stats(Bundesliga 2025/2026, 41지표) · Understat(player 335) · LIGABlatt·Bundesliga.com·Eurosport.de·1874 팟캐스트(Brassell) 서사; obs#287·#288·#289','n=10(786분) 실측은 바이에른 그리드 기준(에메리 체제 아님, 교차 검증 필요) — 불변규칙 7 위반 방지 위해 team_code 교차 명시. FC27 미수집으로 게임 스탯은 FC26 07-23 값만 존재해 시의성 캐비앗 있음. CAM/DM 두 슬롯 실측이 서로 다른 방향(argmax vs 보도)을 가리켜 배치 논쟁 미해소 — 실측 축적 시까지 등급·핏은 잠정 등급(MEDIUM)으로 유지. 알론소·이라올라 핏은 데이터 없어 비워둠.','2026-09-11',NULL);
INSERT INTO player_evaluations VALUES(128,1,178,'B+ — 이적 CONFIRMED(2026-09-01 구단 공식), squad_entries 승격 완료. RCB 슬롯 fit_sim 0.899(n=38, 챔피언십 25/26 풀시즌)·rate_v 7.47로 수치상 높으나 ⚠️ 이 그리드는 챔피언십(2부) 표본이라 PL 고라인 투영이 아니다(prescriptions rationale 명시 경고). FC27(09-10) 수집에서 누락돼 FC26이 최신 게임 스탯 — OVR74(pac65·sho36·pas62·dri66·def74·phy78, PlayStyle 「긴패스;블로킹」).','우측 볼 플레잉 CB — 「우측 파우 토레스」로 구단 내부가 직접 규정(Tanswell/1874, 2026-09-07: 정제 가능한 우측 파우 토레스로 본다, 전진 패스 우수). 세트피스 위협이 강점 축(25/26 챔피언십 7골, 헤더슛 백분위100). FC26 PlayStyle 「긴패스;블로킹」이 전진 배급·수비 개입 겸장과 정합.','v_player_profile n=60·4503분·평균평점 7.37로 6명 중 표본·평점 모두 최상급(단 레벨은 챔피언십). 25/26 챔피언십 47경기 43선발 3900분 7골2도움 평점7.37, 26/27 챔피언십 데뷔 90분 평점7.2·EFL컵 90분 평점8.1로 초반 폼 양호. 약점: 공중볼 승률이 두 체제(맨시티 아카데미·마틴)에서 공통으로 약함(FotMob 백분위 37, 58.4%Champ/55.8%PL) — 188cm치고 낮다는 지적이 Bains(2026-08-30)와 기존 서사에서 겹친다. 1v1·후진 스텝(Tanswell: 1v1 상황 스텝 패턴이 어색하다)도 반복 지적.','FC27 미수집(09-10 목록 누락 확인) — FC26(2026-07-23 roster) OVR74가 최신 게임 능치다: pac65·sho36·pas62·dri66·def74·phy78. 실측은 squad_entries·prescriptions에 CONFIRMED로 반영됐다 — RCB grid centroid tool_x68.75(AVL RCB 슬롯 x=63 대비 +5.75, 슬롯보다 넓게 선다는 뜻) fit_sim0.899(cb_bpd/Aggressive, n=38). Bains(2026-08-30) 실측: 챔피언십 전진패스 12.23/90(최상위 백분위), PL 표본 파이널서드·전진패스(4.93/90)도 상위권, 공중볼 51-54% 승률이 약점으로 재확인.','HIGH(방향) — cb_bpd 계열 배정의 구단 내부 근거가 확보됐다(「우측 파우 토레스」, 1차 소스). 신규 발견(2026-09-07 player_duties): 실측 표본 시즌(25/26 사우샘프턴)이 이미 인포제션 3-2-5+RB인버트/드롭+맨오리엔티드 하이프레스+고라인 구조였다 — 에메리 하이라인 결합이 신규 학습이 아니라 기존 경험의 연장. 단 아직 AVL 공식전 출전 0경기(등록 후 데뷔 대기).',NULL,NULL,'squad_entries CB CONFIRMED cb_bpd(fit_sim 0.899, rate_v 7.47, RCB, 2026-09-01 구단 공식 확인 승격); prescriptions measured:season:full2526·fc26:opt:RCB(n=38, cb_bpd/Aggressive 0.899, rt7.47, grid_club=Southampton ⚠️2부리그); player_duties 2025-26·2026-27(Bains Analysis 2026-08-30, 1874/Tanswell 2026-09-07, BTL·TFA·WhoScored 등); v_player_profile n=60(4503분, 평균평점7.37); v_player_season_stats(챔피언십 25/26 47경기43선발 3900분 7골2도움 평점7.37, 26/27 챔피언십1경기90분7.2·EFL컵1경기90분8.1); FC26(OVR74, 긴패스;블로킹, roster 2026-07-23) — FC27 09-10 수집 누락 확인 | stat_eval 2026-09-11 신규 작성','표본은 크지만(n=60) 전부 챔피언십(2부)·아직 AVL PL 공식전 0경기 — 구단 CONFIRMED·프리시즌 판단이며 PL 고라인 투영은 미검증(불변규칙7 경고 그대로 승계). FC27 스탯 결손(누락)이라 FC26을 근거로 썼다. 알론소·이라올라 핏은 비워둔다(투영 근거 없음).','2026-09-11',NULL);
